        public DocTab(string title, OfficeAppMode mode, bool active = false, bool isModified = false)
        {
            Title = title;
            Mode = mode;
            Active = active;
            IsModified = isModified;
            FilePath = "";
            ActiveRibbonTab = 0;
            ActiveSlideIndex = 0;
            SlideZoomLevel = 1.0f;
            SlideCanvasScrollX = 0;
            SlideCanvasScrollY = 0;

            WriterCursorPosition = 0;
            WriterSelectionStart = 0;
            WriterSelectionEnd = 0;
            WriterZoomLevel = 1.0f;
            WriterScrollY = 0f;
            WriterViewMode = 1;
            WriterParagraphAlignments = new Dictionary<int, int>();
            WriterParagraphBottomBorders = new Dictionary<int, Color>();
            WriterTablePageX = new Dictionary<int, int>();
            WriterTablePageY = new Dictionary<int, int>();
            WriterTableWrapModes = new Dictionary<int, int>();
            WriterTableCustomSizes = new Dictionary<int, Size>();
            WriterTableColWidths = new Dictionary<int, List<int>>();
            WriterTableRowHeights = new Dictionary<int, List<int>>();
            WriterDocumentTables = new List<DocTableObject>();
            WriterParagraphBorders = new Dictionary<int, ParagraphBorderInfo>();
            WriterTextBorders = new List<TextBorderRange>();
            WriterParagraphLineSpacings = new Dictionary<int, float>();
            WriterParagraphSpacingsBefore = new Dictionary<int, float>();
            WriterParagraphSpacingsAfter = new Dictionary<int, float>();
            WriterHeaderText = "";
            WriterFooterText = "";
            WriterCurrentHeaderPreset = HeaderFooterPreset.None;
            WriterCurrentFooterPreset = HeaderFooterPreset.None;
            WriterIsEditingHeaderFooter = false;
            WriterHeaderTitleText = "";
            WriterThreeColHeaderLeft = "";
            WriterThreeColHeaderCenter = "";
            WriterThreeColHeaderRight = "";
            WriterThreeColFooterLeft = "";
            WriterThreeColFooterCenter = "";
            WriterThreeColFooterRight = "";
            WriterShowPageNumbers = false;
            WriterFooterAlignment = 1;
            WriterDifferentOddEvenPages = false;
            WriterFooterEvenAlignment = 0;
            WriterFooterEvenText = "";
            WriterHeaderAlignment = 0;
            WriterHeaderEvenAlignment = 0;
            WriterHeaderEvenText = "";
            WriterTableFixPositions = new Dictionary<int, bool>();
            WriterParagraphFirstLineIndents = new Dictionary<int, float>();
            WriterParagraphLeftIndents = new Dictionary<int, float>();
            WriterParagraphRightIndents = new Dictionary<int, float>();
            WriterParagraphHangingIndents = new Dictionary<int, float>();
            WriterPaperWidthInches = 8.27f;
            WriterPaperHeightInches = 11.69f;
            WriterMarginMode = 0;
            WriterCustomLeftMargin = 1.0f;
            WriterCustomRightMargin = 1.0f;
            WriterCustomTopMargin = 1.0f;
            WriterCustomBottomMargin = 1.0f;

            CalcActiveSheetIndex = 0;
            CalcSelectedRow = 1;
            CalcSelectedCol = 1;
            CalcSelEndRow = 1;
            CalcSelEndCol = 1;
            CalcScrollRow = 1;
            CalcScrollCol = 1;
            CalcColWidths = new Dictionary<uint, int>();
            CalcRowHeights = new Dictionary<uint, int>();

            PdfActivePageIndex = 0;
            PdfZoomLevel = 1.0f;
            PdfScrollY = 0f;
            PdfSelectedTool = 0;

            if (mode == OfficeAppMode.Slides)
            {
                PresentationData = new PresentationRoot();
            }
            else if (mode == OfficeAppMode.Writer)
            {
                WriterPieceTable = new PieceTable();
                WriterFormattedRuns = new List<FormattedRun>();
                WriterShapes = new List<DocShapeObject>();
                WriterCharts = new List<DocChartObject>();
                WriterUndoStack = new Stack<WriterUndoSnapshot>();
                WriterRedoStack = new Stack<WriterUndoSnapshot>();
            }
            else if (mode == OfficeAppMode.Calc)
            {
                CalcSheets = new List<SparseMatrix> { new SparseMatrix() };
                CalcSheetNames = new List<string> { "Sheet1" };
            }
            else if (mode == OfficeAppMode.Pdf)
            {
                PdfData = new PdfDocument(title);
            }
            else if (mode == OfficeAppMode.Photo)
            {
                PhotoData = new PhotoDocument(1920, 1080, title);
            }
        }
