        public Rectangle ActiveDropdownBounds = Rectangle.Empty;
        public ContextMenuStrip ActiveOpenMenu = null;

        public void UpdateHover(int x, int y)
        {
            HoverX = x;
            HoverY = y;
        }

        public bool IsHovering(Rectangle rect)
        {
            if (!ActiveDropdownBounds.IsEmpty)
            {
                return ActiveDropdownBounds.IntersectsWith(rect);
            }
            return rect.Contains(HoverX, HoverY);
        }

        public void ShowRibbonDropdown(ContextMenuStrip menu, Form parentForm, Point screenPt, Rectangle buttonBounds)
        {
            if (ActiveOpenMenu != null && ActiveOpenMenu != menu)
            {
                try { ActiveOpenMenu.Close(); } catch { }
            }
            ActiveOpenMenu = menu;
            ActiveDropdownBounds = buttonBounds;
            UpdateHover(buttonBounds.X + buttonBounds.Width / 2, buttonBounds.Y + buttonBounds.Height / 2);

            menu.Closed += (s, e) =>
            {
                if (ActiveOpenMenu == menu)
                {
                    ActiveOpenMenu = null;
                    ActiveDropdownBounds = Rectangle.Empty;
                }
                if (parentForm != null && !parentForm.IsDisposed)
                {
                    try
                    {
                        Point cur = parentForm.PointToClient(Cursor.Position);
                        UpdateHover(cur.X, cur.Y);
                        parentForm.Invalidate();
                    }
                    catch { }
                }
            };
            if (parentForm != null && !parentForm.IsDisposed)
            {
                parentForm.Invalidate();
            }
            menu.Show(screenPt);
        }

        public void SaveTabState(int index, SlidesView slidesView, WriterView writerView, CalcView calcView, PdfView pdfView = null, PhotoView photoView = null)
        {
            if (index < 0 || index >= DocTabs.Count) return;
            DocTab tab = DocTabs[index];
            tab.ActiveRibbonTab = ActiveRibbonTab;
            if (tab.Mode == OfficeAppMode.Pdf && tab.ActiveRibbonTab >= 6)
            {
                tab.ActiveRibbonTab = 0;
            }
            if (tab.Mode == OfficeAppMode.Slides && slidesView != null)
            {
                slidesView.HideSearchBox();
                tab.PresentationData = slidesView.Presentation;
                tab.ActiveSlideIndex = slidesView.ActiveSlideIndex;
                tab.SlideZoomLevel = slidesView.ZoomLevel;
                tab.SlideCanvasScrollX = slidesView.CanvasScrollX;
                tab.SlideCanvasScrollY = slidesView.CanvasScrollY;
                tab.TargetCanvasScrollX = slidesView.TargetCanvasScrollX;
                tab.TargetCanvasScrollY = slidesView.TargetCanvasScrollY;
                tab.SlideIsSidebarOpen = slidesView.IsSidebarOpen;
                tab.SlideSidebarPanel = slidesView.SidebarPanel;
                tab.SlideIsElementsDrawerOpen = slidesView.IsElementsDrawerOpen;
                tab.SlideIsElementsDrawerCollapsed = slidesView.IsElementsDrawerCollapsed;
                tab.SlideElementsDrawerSelectedTab = slidesView.ElementsDrawerSelectedTab;
                tab.SlideThumbScrollY = slidesView.ThumbScrollY;
                tab.SlideTargetThumbScrollY = slidesView.TargetThumbScrollY;
                tab.SlideBottomThumbScrollX = slidesView.BottomThumbScrollX;
                tab.SlideTargetBottomThumbScrollX = slidesView.TargetBottomThumbScrollX;
                tab.SlideViewMode = slidesView.ViewMode;
                tab.SlideUndoStack = new List<PresentationRoot>(slidesView.UndoStack);
                tab.SlideRedoStack = new List<PresentationRoot>(slidesView.RedoStack);
                try
                {
                    if (SlideAudioPlayerManager.Instance.IsPlaying)
                    {
                        SlideAudioPlayerManager.Instance.Stop();
                    }
                    if (SlideVideoPlayerManager.Instance.IsPlaying)
                    {
                        SlideVideoPlayerManager.Instance.Stop();
                    }
                }
                catch { }
            }
            else if (tab.Mode == OfficeAppMode.Writer && writerView != null)
            {
                tab.WriterPieceTable = writerView.PieceTable;
                tab.WriterFormattedRuns = writerView.FormattedRuns;
                tab.WriterShapes = writerView.DocumentShapes;
                tab.WriterCharts = writerView.DocumentCharts;
                tab.WriterCursorPosition = writerView.CursorPosition;
                tab.WriterSelectionStart = writerView.SelectionStart;
                tab.WriterSelectionEnd = writerView.SelectionEnd;
                tab.WriterZoomLevel = writerView.ZoomLevel;
                tab.WriterScrollY = writerView.SmoothScrollY;
                tab.WriterViewMode = writerView.ViewMode;
                tab.WriterParagraphAlignments = writerView.ParagraphAlignments;
                tab.WriterParagraphBottomBorders = writerView.ParagraphBottomBorders;
                tab.WriterTablePageX = writerView.TablePageX;
                tab.WriterTablePageY = writerView.TablePageY;
                tab.WriterTableWrapModes = writerView.TableWrapModes;
                tab.WriterTableCustomSizes = writerView.TableCustomSizes;
                tab.WriterTableColWidths = writerView.TableColWidths;
                tab.WriterTableRowHeights = writerView.TableRowHeights;
                tab.WriterDocumentTables = writerView.DocumentTables != null ? new List<DocTableObject>(writerView.DocumentTables) : new List<DocTableObject>();
                tab.WriterParagraphBorders = writerView.ParagraphBorders != null ? new Dictionary<int, ParagraphBorderInfo>(writerView.ParagraphBorders) : new Dictionary<int, ParagraphBorderInfo>();
                tab.WriterTextBorders = writerView.TextBorders != null ? WriterUndoSnapshot.CloneTextBorders(writerView.TextBorders) : new List<TextBorderRange>();
                tab.WriterParagraphLineSpacings = writerView.ParagraphLineSpacings != null ? new Dictionary<int, float>(writerView.ParagraphLineSpacings) : new Dictionary<int, float>();
                tab.WriterParagraphSpacingsBefore = writerView.ParagraphSpacingsBefore != null ? new Dictionary<int, float>(writerView.ParagraphSpacingsBefore) : new Dictionary<int, float>();
                tab.WriterParagraphSpacingsAfter = writerView.ParagraphSpacingsAfter != null ? new Dictionary<int, float>(writerView.ParagraphSpacingsAfter) : new Dictionary<int, float>();
                tab.WriterHeaderText = writerView.HeaderText;
                tab.WriterFooterText = writerView.FooterText;
                tab.WriterCurrentHeaderPreset = writerView.CurrentHeaderPreset;
                tab.WriterCurrentFooterPreset = writerView.CurrentFooterPreset;
                tab.WriterIsEditingHeaderFooter = writerView.IsEditingHeaderFooter;
                tab.WriterHeaderTitleText = writerView.HeaderTitleText;
                tab.WriterThreeColHeaderLeft = writerView.ThreeColHeaderLeft;
                tab.WriterThreeColHeaderCenter = writerView.ThreeColHeaderCenter;
                tab.WriterThreeColHeaderRight = writerView.ThreeColHeaderRight;
                tab.WriterThreeColFooterLeft = writerView.ThreeColFooterLeft;
                tab.WriterThreeColFooterCenter = writerView.ThreeColFooterCenter;
                tab.WriterThreeColFooterRight = writerView.ThreeColFooterRight;
                tab.WriterShowPageNumbers = writerView.ShowPageNumbers;
                tab.WriterFooterAlignment = writerView.FooterAlignment;
                tab.WriterDifferentOddEvenPages = writerView.DifferentOddEvenPages;
                tab.WriterFooterEvenAlignment = writerView.FooterEvenAlignment;
                tab.WriterFooterEvenText = writerView.FooterEvenText;
                tab.WriterHeaderAlignment = writerView.HeaderAlignment;
                tab.WriterHeaderEvenAlignment = writerView.HeaderEvenAlignment;
                tab.WriterHeaderEvenText = writerView.HeaderEvenText;
                tab.WriterTableFixPositions = writerView.TableFixPositions != null ? new Dictionary<int, bool>(writerView.TableFixPositions) : new Dictionary<int, bool>();
                tab.WriterParagraphFirstLineIndents = writerView.ParagraphFirstLineIndents != null ? new Dictionary<int, float>(writerView.ParagraphFirstLineIndents) : new Dictionary<int, float>();
                tab.WriterParagraphLeftIndents = writerView.ParagraphLeftIndents != null ? new Dictionary<int, float>(writerView.ParagraphLeftIndents) : new Dictionary<int, float>();
                tab.WriterParagraphRightIndents = writerView.ParagraphRightIndents != null ? new Dictionary<int, float>(writerView.ParagraphRightIndents) : new Dictionary<int, float>();
                tab.WriterParagraphHangingIndents = writerView.ParagraphHangingIndents != null ? new Dictionary<int, float>(writerView.ParagraphHangingIndents) : new Dictionary<int, float>();
                tab.WriterPaperWidthInches = PaperWidthInches;
                tab.WriterPaperHeightInches = PaperHeightInches;
                tab.WriterMarginMode = MarginMode;
                tab.WriterCustomLeftMargin = CustomLeftMargin;
                tab.WriterCustomRightMargin = CustomRightMargin;
                tab.WriterCustomTopMargin = CustomTopMargin;
                tab.WriterCustomBottomMargin = CustomBottomMargin;
                tab.WriterUndoStack = writerView.GetUndoStack();
                tab.WriterRedoStack = writerView.GetRedoStack();
            }
            else if (tab.Mode == OfficeAppMode.Calc && calcView != null)
            {
                tab.CalcSheets = calcView.Sheets;
