        public void AddDocTab(string title, OfficeAppMode mode, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null, PhotoView photoView = null)
        {
            SaveTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView, photoView);

            foreach (var tab in DocTabs) tab.Active = false;
            DocTab newTab = new DocTab(title, mode, true, false);

            if (mode == OfficeAppMode.Slides)
            {
                newTab.PresentationData = new PresentationRoot();
                newTab.PresentationData.Slides.Clear();
                SlideNode blankSlide = new SlideNode
                {
                    Title = "Trang 1",
                    Layout = SlideLayoutType.Blank,
                    BgColor = 0xFFFFFF,
                    Shapes = new List<ShapeNode>(),
                    Transition = TransitionType.None,
                    TransitionDuration = 0f
                };
                newTab.PresentationData.Slides.Add(blankSlide);
            }
            else if (mode == OfficeAppMode.Writer)
            {
                newTab.WriterPieceTable = new PieceTable("");
                newTab.WriterFormattedRuns = new List<FormattedRun>();
                newTab.WriterShapes = new List<DocShapeObject>();
                newTab.WriterCharts = new List<DocChartObject>();
                newTab.WriterDocumentTables = new List<DocTableObject>();
                newTab.WriterCursorPosition = 0;
                newTab.WriterUndoStack = new Stack<WriterUndoSnapshot>();
                newTab.WriterRedoStack = new Stack<WriterUndoSnapshot>();
            }
            else if (mode == OfficeAppMode.Calc)
            {
                newTab.CalcSheets = new List<SparseMatrix> { new SparseMatrix(), new SparseMatrix(), new SparseMatrix() };
                newTab.CalcSheetNames = new List<string> { "Sheet1", "Sheet2", "Sheet3" };
                newTab.CalcColWidths = new Dictionary<uint, int>();
                newTab.CalcRowHeights = new Dictionary<uint, int>();
                if (calcView != null)
                {
                    calcView.CustomColWidths.Clear();
                    calcView.CustomRowHeights.Clear();
                }
            }
            else if (mode == OfficeAppMode.Pdf)
            {
                newTab.PdfData = new PdfDocument(title);
                newTab.PdfActivePageIndex = 0;
                newTab.PdfZoomLevel = 1.0f;
                newTab.PdfScrollY = 0f;
                newTab.PdfSelectedTool = 0;
                if (pdfView != null)
                {
                    pdfView.Document = newTab.PdfData;
                    pdfView.ActivePageIndex = 0;
                    pdfView.ZoomLevel = 1.0f;
                    pdfView.ScrollY = 0f;
                }
            }
            else if (mode == OfficeAppMode.Photo)
            {
                newTab.PhotoData = new PhotoDocument(1920, 1080, title);
                if (photoView != null)
                {
                    photoView.Document = newTab.PhotoData;
                    photoView.SelectedTool = PhotoTool.Move;
                }
            }

            DocTabs.Add(newTab);
            ActiveDocIndex = DocTabs.Count - 1;
            CurrentMode = mode;
            EnsureActiveTabVisible();

            LoadTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView, photoView);
        }

        public void SwitchDocTab(int index, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null, PhotoView photoView = null)
        {
            AppForm app = HostAppForm ?? (Parent as AppForm);
            if (app != null && app.BackstageView != null && app.BackstageView.IsOpen)
            {
                app.CloseBackstageView();
            }

            if (pdfView != null)
            {
                pdfView.SelectedText = null;
                if (pdfView.EditingText != null) pdfView.CommitInlineEdit();
            }

            if (index >= 0 && index < DocTabs.Count)
            {
                if (index == ActiveDocIndex && DocTabs[index].Active) return;

                SaveTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView, photoView);

                for (int i = 0; i < DocTabs.Count; i++)
                {
                    DocTabs[i].Active = (i == index);
                }
                ActiveDocIndex = index;
                CurrentMode = DocTabs[index].Mode;
                EnsureActiveTabVisible();

                if (DocTabs[index].NeedsLazyLoad)
                {
                    DocTabs[index].NeedsLazyLoad = false;
                    LazyLoadTab(index, slidesView, writerView, calcView, pdfView, photoView);
                }
                else
                {
                    LoadTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView, photoView);
                }
            }
        }

        public void LazyLoadTab(int index, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null, PhotoView photoView = null)
        {
            if (index < 0 || index >= DocTabs.Count) return;
            DocTab tab = DocTabs[index];

            string autoSaveDir = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "GenOffice", "autosave");
            string draftPath = !string.IsNullOrEmpty(tab.DraftFile) ? System.IO.Path.Combine(autoSaveDir, tab.DraftFile) : "";
            bool hasDraft = !string.IsNullOrEmpty(draftPath) && System.IO.File.Exists(draftPath);
            bool hasFile = !string.IsNullOrEmpty(tab.FilePath) && System.IO.File.Exists(tab.FilePath);

            try
            {
                if (tab.Mode == OfficeAppMode.Writer && writerView != null)
                {
                    string origTitle = tab.Title;
                    string origPath = tab.FilePath;
                    bool origMod = tab.IsModified;
                    bool loaded = false;

                    if (origMod && hasDraft)
                    {
                        bool preferOriginal = false;
                        if (hasFile && System.IO.File.Exists(tab.FilePath))
                        {
                            try
                            {
                                var fInfoOrig = new System.IO.FileInfo(tab.FilePath);
                                var fInfoDraft = new System.IO.FileInfo(draftPath);
                                if (fInfoOrig.LastWriteTimeUtc >= fInfoDraft.LastWriteTimeUtc)
                                {
                                    preferOriginal = true;
                                }
                            }
                            catch { }
                        }

                        if (!preferOriginal)
                        {
                            string ext = System.IO.Path.GetExtension(draftPath).ToLower();
                            if (ext == ".docx")
                            {
                                loaded = writerView.LoadDocumentFile(draftPath, this);
                            }
                            else if (ext == ".txt")
                            {
                                string draftText = System.IO.File.ReadAllText(draftPath, System.Text.Encoding.UTF8);
                                if (!string.IsNullOrEmpty(draftText))
                                {
                                    writerView.PieceTable.SetInitialText(draftText);
                                    writerView.InvalidateLayoutAndTextCache();
                                    writerView.CursorPosition = draftText.Length;
                                    loaded = true;
                                }
                            }
                        }
                    }

                    if (!loaded && hasFile)
                    {
                        loaded = writerView.LoadDocumentFile(tab.FilePath, this);
                        if (loaded)
                        {
                            origMod = false;
                        }
                    }

                    if (!loaded && hasDraft)
                    {
                        string ext = System.IO.Path.GetExtension(draftPath).ToLower();
                        if (ext == ".docx")
                        {
                            loaded = writerView.LoadDocumentFile(draftPath, this);
                        }
                        else if (ext == ".txt")
                        {
                            string draftText = System.IO.File.ReadAllText(draftPath, System.Text.Encoding.UTF8);
                            if (!string.IsNullOrEmpty(draftText))
                            {
                                writerView.PieceTable.SetInitialText(draftText);
                                writerView.InvalidateLayoutAndTextCache();
                                writerView.CursorPosition = draftText.Length;
                                loaded = true;
                            }
                        }
                    }

                    if (loaded)
                    {
                        writerView.CurrentFilePath = origPath ?? "";
                        tab.FilePath = origPath ?? "";
                        if (!string.IsNullOrEmpty(origTitle)) tab.Title = origTitle;
                        tab.IsModified = origMod;
                    }
                    SaveTabState(index, slidesView, writerView, calcView, pdfView);
                }
                else if (tab.Mode == OfficeAppMode.Slides && slidesView != null)
                {
                    string target = hasFile ? tab.FilePath : (hasDraft ? draftPath : null);
                    if (!string.IsNullOrEmpty(target) && System.IO.File.Exists(target))
                    {
                        slidesView.Presentation = Format.PptxHandler.LoadPptx(target);
                        tab.PresentationData = slidesView.Presentation;
                        slidesView.ActiveSlideIndex = Math.Max(0, Math.Min(slidesView.Presentation.Slides.Count - 1, tab.ActiveSlideIndex));
                        D2DGraphics.ClearFontCache();
                        if (target == tab.FilePath) tab.IsModified = false;
                    }
                    SaveTabState(index, slidesView, writerView, calcView, pdfView);
                }
                else if (tab.Mode == OfficeAppMode.Calc && calcView != null)
                {
                    string target = hasFile ? tab.FilePath : (hasDraft ? draftPath : null);
                    if (!string.IsNullOrEmpty(target) && System.IO.File.Exists(target))
                    {
                        Format.XlsxHandler.LoadXlsxOrCsv(target, calcView);
                        calcView.ActiveSheetIndex = Math.Max(0, Math.Min(calcView.Sheets.Count - 1, tab.CalcActiveSheetIndex));
                        if (target == tab.FilePath) tab.IsModified = false;
                    }
                    SaveTabState(index, slidesView, writerView, calcView, pdfView);
                }
                else if (tab.Mode == OfficeAppMode.Pdf && pdfView != null)
                {
                    if (hasFile)
                    {
                        pdfView.Document = Format.PdfHandler.LoadPdf(tab.FilePath);
                        pdfView.ActivePageIndex = Math.Max(0, Math.Min(pdfView.Document.Pages.Count - 1, tab.PdfActivePageIndex));
                    }
                    SaveTabState(index, slidesView, writerView, calcView, pdfView, photoView);
                }
                else if (tab.Mode == OfficeAppMode.Photo && photoView != null)
                {
                    if (hasFile)
                    {
                        photoView.Document = PhotoDocument.LoadFromFile(tab.FilePath);
                        tab.PhotoData = photoView.Document;
                    }
                    SaveTabState(index, slidesView, writerView, calcView, pdfView, photoView);
                }
            }
            catch { }

            LoadTabState(index, slidesView, writerView, calcView, pdfView, photoView);
        }

        public bool CloseDocTab(int index, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null, PhotoView photoView = null)
        {
            if (index < 0 || index >= DocTabs.Count) return false;
            DocTab tab = DocTabs[index];

            if (tab.Mode == OfficeAppMode.Home) return false;

            if (tab.IsModified)
            {
                DialogResult result = MessageBox.Show(
                    "Tài liệu '" + tab.Title + "' có những thay đổi chưa được lưu.\n\nBạn có muốn LƯU tài liệu trước khi đóng không?",
                    "Cảnh báo chưa lưu - ZENQ OFFICE",
                    MessageBoxButtons.YesNoCancel,
                    MessageBoxIcon.Warning,
                    MessageBoxDefaultButton.Button1
                );

                if (result == DialogResult.Yes)
                {
                    tab.IsModified = false;
                }
                else if (result == DialogResult.No)
                {
                }
                else
                {
                    return false;
                }
            }

            bool wasActive = (index == ActiveDocIndex);
            if (!wasActive)
            {
                SaveTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView, photoView);
            }

            // Clean up any autosave draft file on disk
            if (!string.IsNullOrEmpty(tab.DraftFile))
            {
                try
                {
                    string autoSaveDir = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "GenOffice", "autosave");
                    string dfPath = System.IO.Path.Combine(autoSaveDir, tab.DraftFile);
                    if (System.IO.File.Exists(dfPath)) System.IO.File.Delete(dfPath);
                }
                catch { }
            }

            DocTabs.RemoveAt(index);
            if (tab.WriterUndoStack != null) tab.WriterUndoStack.Clear();
            if (tab.WriterRedoStack != null) tab.WriterRedoStack.Clear();

            if (index < ActiveDocIndex)
            {
                ActiveDocIndex--;
            }
            else if (ActiveDocIndex >= DocTabs.Count)
            {
                ActiveDocIndex = DocTabs.Count - 1;
            }

            for (int i = 0; i < DocTabs.Count; i++)
            {
                DocTabs[i].Active = (i == ActiveDocIndex);
            }
            if (ActiveDocIndex >= 0 && ActiveDocIndex < DocTabs.Count)
            {
                CurrentMode = DocTabs[ActiveDocIndex].Mode;
                LoadTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView, photoView);
            }
            return true;
        }

        private GraphicsPath CreateRoundedRectanglePath(Rectangle rect, int radius)
        {
            GraphicsPath path = new GraphicsPath();
            int d = radius * 2;
            if (d > rect.Width) d = rect.Width;
            if (d > rect.Height) d = rect.Height;

            path.AddArc(rect.X, rect.Y, d, d, 180, 90);
            path.AddArc(rect.Right - d, rect.Y, d, d, 270, 90);
            path.AddArc(rect.Right - d, rect.Bottom - d, d, d, 0, 90);
            path.AddArc(rect.X, rect.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }

        private void FillRoundedRectangle(Graphics g, Brush brush, Rectangle rect, int radius)
        {
            using (GraphicsPath path = CreateRoundedRectanglePath(rect, radius))
            {
                g.FillPath(brush, path);
            }
        }

        private void DrawRoundedRectangle(Graphics g, Pen pen, Rectangle rect, int radius)
        {
            using (GraphicsPath path = CreateRoundedRectanglePath(rect, radius))
            {
                g.DrawPath(pen, path);
            }
        }

        private void DrawInteractiveButton(Graphics g, Rectangle rect, bool isActive, int radius = 2)
        {
            if (!ActiveDropdownBounds.IsEmpty && ActiveDropdownBounds.IntersectsWith(rect))
            {
                isActive = true;
            }
            bool isHover = IsHovering(rect);
            if (isActive && isHover)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(215, 218, 223)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(155, 158, 164), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
            else if (isActive)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(226, 228, 232)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(175, 178, 184), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
            else if (isHover)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(238, 240, 243)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(205, 208, 214), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
        }

        private void DrawAlignmentIcon(Graphics g, int x, int y, int alignType, Color color)
        {
            using (Pen pen = new Pen(Color.FromArgb(89, 89, 89), 1.0f))
            {
                pen.StartCap = LineCap.Flat;
                pen.EndCap = LineCap.Flat;

                float ox = x + 4f;
                float oy = y + 5.5f;
                float w = 13f;
                float gap = 3.2f;

                if (alignType == 0) // Align Left
                {
                    g.DrawLine(pen, ox, oy, ox + w, oy);
                    g.DrawLine(pen, ox, oy + gap, ox + 8f, oy + gap);
                    g.DrawLine(pen, ox, oy + gap * 2, ox + w, oy + gap * 2);
                    g.DrawLine(pen, ox, oy + gap * 3, ox + 10f, oy + gap * 3);
                }
                else if (alignType == 1) // Center
                {
                    g.DrawLine(pen, ox, oy, ox + w, oy);
                    g.DrawLine(pen, ox + 2.5f, oy + gap, ox + w - 2.5f, oy + gap);
                    g.DrawLine(pen, ox, oy + gap * 2, ox + w, oy + gap * 2);
                    g.DrawLine(pen, ox + 1.5f, oy + gap * 3, ox + w - 1.5f, oy + gap * 3);
                }
                else if (alignType == 2) // Align Right
                {
                    g.DrawLine(pen, ox, oy, ox + w, oy);
                    g.DrawLine(pen, ox + 5f, oy + gap, ox + w, oy + gap);
                    g.DrawLine(pen, ox, oy + gap * 2, ox + w, oy + gap * 2);
                    g.DrawLine(pen, ox + 3f, oy + gap * 3, ox + w, oy + gap * 3);
                }
                else if (alignType == 3) // Justify
                {
                    g.DrawLine(pen, ox, oy, ox + w, oy);
                    g.DrawLine(pen, ox, oy + gap, ox + w, oy + gap);
                    g.DrawLine(pen, ox, oy + gap * 2, ox + w, oy + gap * 2);
                    g.DrawLine(pen, ox, oy + gap * 3, ox + w, oy + gap * 3);
                }
            }
        }

        private void DrawOpenIconLarge(Graphics g, float x, float y)
        {
            // Sleek Office Fluent Folder Monoline
            Color slate = Color.FromArgb(51, 65, 85);
            Color blue = Color.FromArgb(16, 110, 190);
            using (Pen folderPen = new Pen(slate, 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
            using (Pen paperPen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            using (Pen bluePen = new Pen(blue, 1.2f))
            using (SolidBrush paperBg = new SolidBrush(Color.White))
            using (SolidBrush folderBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
            {
                // Back folder tab and body
                using (GraphicsPath bp = new GraphicsPath())
                {
                    bp.AddLine(x + 5, y + 8, x + 11, y + 8);
                    bp.AddLine(x + 11, y + 8, x + 14, y + 11);
                    bp.AddLine(x + 14, y + 11, x + 27, y + 11);
                    bp.AddLine(x + 27, y + 11, x + 27, y + 26);
                    bp.AddLine(x + 27, y + 26, x + 5, y + 26);
                    bp.CloseFigure();
                    g.FillPath(folderBg, bp);
                    g.DrawPath(folderPen, bp);
                }
                // Paper sheet inside with subtle blue accent
                RectangleF paper = new RectangleF(x + 9, y + 5, 14, 15);
                g.FillRectangle(paperBg, paper);
                g.DrawRectangle(paperPen, paper.X, paper.Y, paper.Width, paper.Height);
                g.DrawLine(bluePen, x + 12, y + 9, x + 19, y + 9);
                g.DrawLine(paperPen, x + 12, y + 13, x + 18, y + 13);

                // Front flap outline
                PointF[] flap = new PointF[] {
                    new PointF(x + 4, y + 15),
                    new PointF(x + 26, y + 15),
                    new PointF(x + 23, y + 26),
                    new PointF(x + 3, y + 26)
                };
                g.FillPolygon(paperBg, flap);
                g.DrawPolygon(folderPen, flap);
            }
        }

        private void DrawSaveIconLarge(Graphics g, float x, float y)
        {
            // Sleek Office Fluent Save/Floppy Monoline
            Color slate = Color.FromArgb(51, 65, 85);
            Color blue = Color.FromArgb(16, 110, 190);
            using (Pen diskPen = new Pen(slate, 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            using (SolidBrush paperBg = new SolidBrush(Color.White))
            using (SolidBrush blueBrush = new SolidBrush(blue))
            {
                // Floppy Disk Body
                using (GraphicsPath dp = new GraphicsPath())
                {
                    dp.AddLine(x + 5, y + 4, x + 21, y + 4);
                    dp.AddLine(x + 21, y + 4, x + 26, y + 9);
                    dp.AddLine(x + 26, y + 9, x + 26, y + 26);
                    dp.AddLine(x + 26, y + 26, x + 5, y + 26);
                    dp.CloseFigure();
                    g.FillPath(paperBg, dp);
                    g.DrawPath(diskPen, dp);
