        private string TransformCase(string text, int mode)
        {
            if (string.IsNullOrEmpty(text)) return text;
            switch (mode)
            {
                case 0: // Sentence case
                    char[] chars = text.ToLower().ToCharArray();
                    bool newSentence = true;
                    for (int i = 0; i < chars.Length; i++)
                    {
                        if (char.IsLetter(chars[i]))
                        {
                            if (newSentence) { chars[i] = char.ToUpper(chars[i]); newSentence = false; }
                        }
                        else if (chars[i] == '.' || chars[i] == '!' || chars[i] == '?' || chars[i] == '\n')
                        {
                            newSentence = true;
                        }
                    }
                    return new string(chars);
                case 1: // Lowercase
                    return text.ToLower();
                case 2: // Uppercase
                    return text.ToUpper();
                case 3: // Capitalize Each Word
                    return System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(text.ToLower());
                case 4: // Toggle case
                    char[] tc = text.ToCharArray();
                    for (int i = 0; i < tc.Length; i++)
                    {
                        if (char.IsUpper(tc[i])) tc[i] = char.ToLower(tc[i]);
                        else if (char.IsLower(tc[i])) tc[i] = char.ToUpper(tc[i]);
                    }
                    return new string(tc);
                default:
                    return text;
            }
        }

