                    for (int s = 0; s < numStyleCards; s++)
                    {
                        string curStyle = styleNames[sStart + s];
                        Rectangle cardRect = new Rectangle(styleX + s * cardW, 68, cardW, 56);
                        bool isActiveStyle = (ActiveStyle == curStyle);
                        bool isHover = IsHovering(cardRect);

                        if (isActiveStyle)
                        {
                            // Selected style card: rectangular crisp border, subtle background like Image 2 (¶ Normal)
                            using (SolidBrush ab = new SolidBrush(Color.FromArgb(248, 249, 250)))
                            using (Pen ap = new Pen(Color.FromArgb(170, 175, 180), 1.0f))
                            {
                                Rectangle selR = new Rectangle(cardRect.X + 1, cardRect.Y + 1, cardRect.Width - 2, cardRect.Height - 2);
                                g.FillRectangle(ab, selR);
                                g.DrawRectangle(ap, selR);
                            }
                        }
                        else if (isHover)
                        {
                            using (SolidBrush hb = new SolidBrush(Color.FromArgb(243, 246, 251)))
                            using (Pen hp = new Pen(Color.FromArgb(205, 218, 235), 1.0f))
                            {
                                Rectangle hovR = new Rectangle(cardRect.X + 1, cardRect.Y + 1, cardRect.Width - 2, cardRect.Height - 2);
                                g.FillRectangle(hb, hovR);
                                g.DrawRectangle(hp, hovR);
                            }
                        }

                        // Draw card typography preview
                        Color sampleCol = (curStyle.StartsWith("Heading") ? Color.FromArgb(43, 87, 154) : (curStyle == "Subtitle" ? Color.FromArgb(100, 116, 139) : Color.FromArgb(20, 20, 20)));
                        using (SolidBrush sampleBrush = new SolidBrush(sampleCol))
                        using (Font sampleFont = new Font("Segoe UI", (curStyle == "Title") ? 9.5f : 8.0f, (curStyle != "Normal" && curStyle != "No Spacing") ? (curStyle == "Subtitle" ? FontStyle.Italic : FontStyle.Bold) : FontStyle.Regular))
                        {
                            string sampleText = (curStyle == "Title") ? "AaBb" : "AaBbCcD";
                            g.DrawString(sampleText, sampleFont, sampleBrush, cardRect.X + 4, 72);
                        }

                        string displayName = (curStyle == "Normal") ? "¶ Normal" : curStyle;
                        g.DrawString(displayName, labelFont, Brushes.Gray, cardRect.X + 3, 103);
                    }

                    // 3-Button Strip on right edge of gallery
                    int stripX = styleX + numStyleCards * cardW;
                    bool canScrollUp = (sStart > 0);
                    bool canScrollDown = (sStart < maxOffset);
                    DrawGalleryScrollButtons(g, stripX, 68, 16, 56, canScrollUp, canScrollDown, true);
                }

                int styleDividerX = stylesGalleryRect.Right + 8;
                g.DrawString("Kiểu hiển thị", labelFont, Brushes.Gray, stylesGalleryRect.X + stylesGalleryRect.Width / 2 - 28, 137);
                g.DrawLine(Pens.LightGray, styleDividerX, 68, styleDividerX, 148);

                // ==================== Group 5: Editing (Chỉnh sửa) ====================
                int editX = styleDividerX + 8;
                Rectangle searchBox = new Rectangle(editX, 68, 108, 20);
                DrawInteractiveButton(g, searchBox, false, 3);
                DrawLucideSearch(g, editX + 3, 70, Color.FromArgb(51, 65, 85));
                g.DrawString("Tìm kiếm ▾", btnFont, Brushes.Black, editX + 24, 70);

                Rectangle replaceBox = new Rectangle(editX, 89, 108, 20);
                DrawInteractiveButton(g, replaceBox, false, 3);
                DrawLucideReplace(g, editX + 3, 91, Color.FromArgb(51, 65, 85));
                g.DrawString("Thay thế", btnFont, Brushes.Black, editX + 24, 91);

                Rectangle selectBox = new Rectangle(editX, 110, 108, 20);
                DrawInteractiveButton(g, selectBox, false, 3);
                DrawLucideSelectPointer(g, editX + 3, 112, Color.FromArgb(51, 65, 85));
                g.DrawString("Chọn vùng ▾", btnFont, Brushes.Black, editX + 24, 112);

                g.DrawString("Chỉnh sửa", labelFont, Brushes.Gray, editX + 24, 137);
            }
        }

        private void DrawTabChen(Graphics g, int width)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
                int curX = 14;
                Color slate = Color.FromArgb(51, 65, 85);
                Color blue = Color.FromArgb(16, 110, 190);
                Color dimLine = Color.FromArgb(148, 163, 184);

                // 1. Nhóm Trang (Pages)
                DrawVectorBtn(g, curX, 68, 92, 20, (g1, x1, y1) => { // Trang bìa
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen p = new Pen(slate, 1.2f))
                    using (SolidBrush bTop = new SolidBrush(blue))
                    using (Pen pLine = new Pen(dimLine, 1.0f))
                    {
                        g1.FillRectangle(bg, x1, y1, 11, 14);
                        g1.DrawRectangle(p, x1, y1, 11, 14);
                        g1.FillRectangle(bTop, x1 + 1, y1 + 1, 9, 3.5f);
                        g1.DrawLine(pLine, x1 + 2.5f, y1 + 7.5f, x1 + 8.5f, y1 + 7.5f);
                        g1.DrawLine(pLine, x1 + 2.5f, y1 + 10.5f, x1 + 6.5f, y1 + 10.5f);
                    }
                }, "Trang bìa");

                DrawVectorBtn(g, curX, 88, 92, 20, (g1, x1, y1) => { // Trang trắng
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen p = new Pen(slate, 1.2f) { LineJoin = LineJoin.Round })
                    {
                        PointF[] pagePts = new PointF[] {
                            new PointF(x1, y1),
                            new PointF(x1 + 7, y1),
                            new PointF(x1 + 11, y1 + 4),
                            new PointF(x1 + 11, y1 + 14),
                            new PointF(x1, y1 + 14)
                        };
                        g1.FillPolygon(bg, pagePts);
                        g1.DrawPolygon(p, pagePts);
                        PointF[] foldPts = new PointF[] {
                            new PointF(x1 + 7, y1),
                            new PointF(x1 + 11, y1 + 4),
                            new PointF(x1 + 7, y1 + 4)
                        };
                        g1.FillPolygon(bg, foldPts);
                        g1.DrawPolygon(p, foldPts);
                    }
                }, "Trang trắng");

                DrawVectorBtn(g, curX, 108, 92, 20, (g1, x1, y1) => { // Ngắt trang
                    using (Pen p = new Pen(slate, 1.2f))
                    using (Pen dashPen = new Pen(blue, 1.1f) { DashStyle = DashStyle.Dash })
                    {
                        // Top bracket
                        g1.DrawLine(p, x1, y1 + 4.5f, x1, y1);
                        g1.DrawLine(p, x1, y1, x1 + 11, y1);
                        g1.DrawLine(p, x1 + 11, y1, x1 + 11, y1 + 4.5f);
                        // Blue dash line
                        g1.DrawLine(dashPen, x1 - 1, y1 + 7, x1 + 12, y1 + 7);
                        // Bottom bracket
                        g1.DrawLine(p, x1, y1 + 9.5f, x1, y1 + 14);
                        g1.DrawLine(p, x1, y1 + 14, x1 + 11, y1 + 14);
                        g1.DrawLine(p, x1 + 11, y1 + 14, x1 + 11, y1 + 9.5f);
                    }
                }, "Ngắt trang");
                curX += 96;
                g.DrawString("Trang", labelFont, Brushes.Gray, curX - 65, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // 2. Nhóm Bảng (Tables)
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => { // Bảng
                    using (Pen borderPen = new Pen(slate, 1.3f))
                    using (Pen innerPen = new Pen(slate, 1.0f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    {
                        g1.FillRectangle(bg, x1, y1 + 1, 20, 18);
                        g1.DrawRectangle(borderPen, x1, y1 + 1, 20, 18);
                        g1.DrawLine(innerPen, x1 + 6.6f, y1 + 1, x1 + 6.6f, y1 + 19);
                        g1.DrawLine(innerPen, x1 + 13.3f, y1 + 1, x1 + 13.3f, y1 + 19);
                        g1.DrawLine(innerPen, x1, y1 + 7, x1 + 20, y1 + 7);
                        g1.DrawLine(innerPen, x1, y1 + 13, x1 + 20, y1 + 13);
                    }
                }, "Bảng");
                curX += 68;
                g.DrawString("Bảng", labelFont, Brushes.Gray, curX - 50, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // 3. Nhóm Minh họa (Illustrations)
                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => { // Hình ảnh
                    using (Pen framePen = new Pen(slate, 1.3f))
                    using (Pen sunPen = new Pen(slate, 1.2f))
