        private void DrawVectorBtn(Graphics g, int x, int y, int w, int h, Action<Graphics, int, int> drawIcon, string title = "", bool isActive = false)
        {
            Rectangle box = new Rectangle(x, y, w, h);
            DrawInteractiveButton(g, box, isActive, 2);
            SmoothingMode prevSmooth = g.SmoothingMode;
            PixelOffsetMode prevOffset = g.PixelOffsetMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            drawIcon(g, x + 5, y + (h - 14) / 2);
            g.SmoothingMode = prevSmooth;
            g.PixelOffsetMode = prevOffset;
            if (!string.IsNullOrEmpty(title))
            {
                using (Font txtFont = new Font("Segoe UI", 7.8f, FontStyle.Regular))
                using (SolidBrush tb = new SolidBrush(isActive ? Color.FromArgb(16, 110, 190) : Color.FromArgb(50, 49, 48)))
                {
                    g.DrawString(title, txtFont, tb, x + 24, y + (h - 14) / 2 - 1);
                }
            }
        }

        private void DrawVectorToolBtnLarge(Graphics g, int x, int y, int w, int h, Action<Graphics, int, int> drawIcon, string title, bool isActive = false)
        {
            Rectangle box = new Rectangle(x, y, w, h);
            DrawInteractiveButton(g, box, isActive, 4);
            SmoothingMode prevSmooth = g.SmoothingMode;
            PixelOffsetMode prevOffset = g.PixelOffsetMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            drawIcon(g, x + (w - 20) / 2, y + 8);
            g.SmoothingMode = prevSmooth;
            g.PixelOffsetMode = prevOffset;
            using (Font txtFont = new Font("Segoe UI", 7.8f, FontStyle.Regular))
            using (SolidBrush tb = new SolidBrush(isActive ? Color.FromArgb(16, 110, 190) : Color.FromArgb(50, 49, 48)))
            using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
            {
                g.DrawString(title, txtFont, tb, new RectangleF(x, y + 36, w, h - 38), sf);
            }
        }

        private void DrawTabHeaderFooter(Graphics g, int width)
        {
            using (Font labelFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 9.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 16;

                // 1. Nhóm Đầu trang & Chân trang
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 16, 16);
                    g1.FillRectangle(Brushes.SteelBlue, x1, y1, 16, 5);
                }, "Đầu trang");
                curX += 68;

                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 16, 16);
                    g1.FillRectangle(Brushes.SteelBlue, x1, y1 + 11, 16, 5);
                }, "Chân trang");
                curX += 68;

                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 5, y1, x1 + 5, y1 + 16); g1.DrawLine(iconPen, x1 + 11, y1, x1 + 11, y1 + 16);
                    g1.DrawLine(iconPen, x1, y1 + 5, x1 + 16, y1 + 5); g1.DrawLine(iconPen, x1, y1 + 11, x1 + 16, y1 + 11);
                }, "Số trang");
                curX += 72;
                g.DrawString("Đầu trang & Chân trang", labelFont, Brushes.Gray, curX - 185, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Chèn
                DrawVectorBtn(g, curX, 68, 125, 20, (g1, x1, y1) => {
                    g1.DrawEllipse(iconPen, x1, y1, 13, 13);
                    g1.DrawLine(iconPen, x1 + 6, y1 + 3, x1 + 6, y1 + 6); g1.DrawLine(iconPen, x1 + 6, y1 + 6, x1 + 9, y1 + 6);
                }, "Ngày & Giờ");
                DrawVectorBtn(g, curX, 88, 125, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 12, 14);
                    g1.DrawLine(iconPen, x1 + 3, y1 + 4, x1 + 9, y1 + 4);
                }, "Thông tin tài liệu");
                DrawVectorBtn(g, curX, 108, 125, 20, (g1, x1, y1) => {
                    PointF[] zap = new PointF[] { new PointF(x1 + 6, y1), new PointF(x1 + 1, y1 + 7), new PointF(x1 + 6, y1 + 7), new PointF(x1 + 4, y1 + 14), new PointF(x1 + 10, y1 + 6), new PointF(x1 + 5, y1 + 6) };
                    g1.DrawPolygon(iconPen, zap);
                }, "Phần nhanh");
                curX += 132;

                DrawVectorBtn(g, curX, 68, 110, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 14, 11);
                }, "Hình ảnh");
                DrawVectorBtn(g, curX, 88, 110, 20, (g1, x1, y1) => {
                    g1.DrawEllipse(iconPen, x1, y1, 13, 13);
                }, "Ảnh trực tuyến");
                curX += 118;
                g.DrawString("Chèn", labelFont, Brushes.Gray, curX - 135, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Điều hướng
                DrawVectorBtn(g, curX, 68, 118, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 6, y1 + 12, x1 + 6, y1 + 2);
                }, "Đến Đầu trang");
                DrawVectorBtn(g, curX, 88, 118, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 6, y1 + 2, x1 + 6, y1 + 12);
                }, "Đến Chân trang");
                DrawVectorBtn(g, curX, 108, 118, 20, (g1, x1, y1) => {
                    g1.DrawEllipse(iconPen, x1, y1 + 2, 8, 8);
                }, "Liên kết Trước");
                curX += 128;
                g.DrawString("Điều hướng", labelFont, Brushes.Gray, curX - 95, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 4. Nhóm Tùy chọn
                g.DrawString((DifferentFirstPage ? "☑" : "☐") + " Trang đầu khác biệt", btnFont, Brushes.Black, curX, 70);
                g.DrawString((DifferentOddEven ? "☑" : "☐") + " Trang chẵn & lẻ khác nhau", btnFont, Brushes.Black, curX, 90);
                g.DrawString("☑ Hiện văn bản tài liệu", btnFont, Brushes.Black, curX, 110);
                curX += 175;
                g.DrawString("Tùy chọn", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 5. Nhóm Vị trí
                g.DrawString("Đầu trang Trên: 0.5\"", btnFont, Brushes.Black, curX, 75);
                g.DrawString("Chân trang Dưới: 0.5\"", btnFont, Brushes.Black, curX, 100);
                curX += 145;
                g.DrawString("Vị trí", labelFont, Brushes.Gray, curX - 90, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // 6. Nhóm Đóng (Nút màu đỏ sang trọng rộng rãi)
                Rectangle closeBox = new Rectangle(curX, 68, 135, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 58, 73, curX + 76, 91);
                    g.DrawLine(redPen, curX + 76, 73, curX + 58, 91);
                }
                g.DrawString("Đóng Đầu trang\nvà Chân trang", boldFont, Brushes.White, curX + 16, 94);
            }
        }

        private void DrawTabChartDesign(Graphics g, int width)
        {
            using (Font labelFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 16;

                // 1. Nhóm Bố cục Biểu đồ
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 16, 16);
                    g1.DrawLine(iconPen, x1 + 8, y1 + 3, x1 + 8, y1 + 13);
                    g1.DrawLine(iconPen, x1 + 3, y1 + 8, x1 + 13, y1 + 8);
                }, "Thành phần");
                curX += 78;

                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 16, 16);
                    g1.DrawLine(iconPen, x1 + 4, y1 + 4, x1 + 12, y1 + 4);
                    g1.DrawLine(iconPen, x1 + 4, y1 + 8, x1 + 12, y1 + 8);
                }, "Bố cục");
                curX += 78;

                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    Color[] c4 = new Color[] { Color.FromArgb(68, 114, 196), Color.FromArgb(237, 125, 49), Color.FromArgb(165, 165, 165), Color.FromArgb(255, 192, 0) };
                    for (int k = 0; k < 4; k++)
                    {
                        using (SolidBrush b = new SolidBrush(c4[k])) g1.FillRectangle(b, x1 + (k % 2) * 8, y1 + (k / 2) * 8, 7, 7);
                    }
                }, "Đổi màu");
                curX += 78;
                g.DrawString("Bố cục Biểu đồ", labelFont, Brushes.Gray, curX - 190, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Kiểu Biểu đồ Gallery
                string[] styles = new string[] { "Sáng", "Nền tối", "Xám" };
                for (int s = 0; s < 3; s++)
                {
                    Rectangle sBox = new Rectangle(curX, 68, 62, 60);
                    DrawInteractiveButton(g, sBox, false, 3);
                    Color sBg = s == 1 ? Color.FromArgb(30, 41, 59) : (s == 2 ? Color.FromArgb(245, 247, 250) : Color.White);
                    using (SolidBrush sb = new SolidBrush(sBg)) g.FillRectangle(sb, sBox.X + 4, sBox.Y + 4, sBox.Width - 8, 30);
                    g.FillRectangle(Brushes.SteelBlue, sBox.X + 8, sBox.Y + 16, 8, 14);
                    g.FillRectangle(Brushes.DarkOrange, sBox.X + 18, sBox.Y + 10, 8, 20);
                    g.FillRectangle(Brushes.Gray, sBox.X + 28, sBox.Y + 14, 8, 16);
                    using (Font sf = new Font("Segoe UI", 7.5f))
                    {
                        g.DrawString(styles[s], sf, Brushes.Black, sBox.X + 10, sBox.Y + 38);
                    }
                    curX += 68;
                }
                g.DrawString("Kiểu Biểu đồ", labelFont, Brushes.Gray, curX - 165, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Bảng Dữ liệu
                DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 16, 16);
                    g1.DrawLine(iconPen, x1 + 4, y1 + 8, x1 + 12, y1 + 8);
                }, "Hàng/Cột");
                curX += 82;

                DrawVectorToolBtnLarge(g, curX, 68, 92, 60, (g1, x1, y1) => {
                    using (SolidBrush exB = new SolidBrush(Color.FromArgb(16, 124, 65)))
                    {
                        g1.FillRectangle(exB, x1, y1, 18, 16);
                        using (Pen wP = new Pen(Color.White, 1.2f))
                        {
                            g1.DrawRectangle(wP, x1 + 2, y1 + 2, 14, 12);
                            g1.DrawLine(wP, x1 + 7, y1 + 2, x1 + 7, y1 + 14);
                            g1.DrawLine(wP, x1 + 2, y1 + 7, x1 + 16, y1 + 7);
                        }
                    }
                }, "Sửa dữ liệu 📊");
                curX += 98;

                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    g1.DrawArc(iconPen, x1, y1, 16, 16, 45, 270);
                }, "Làm mới");
                curX += 74;
                g.DrawString("Bảng dữ liệu", labelFont, Brushes.Gray, curX - 200, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 4. Nhóm Loại Biểu đồ
                DrawVectorToolBtnLarge(g, curX, 68, 86, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 18, 16);
                    g1.FillRectangle(Brushes.SteelBlue, x1 + 3, y1 + 6, 4, 8);
                    g1.FillRectangle(Brushes.DarkOrange, x1 + 9, y1 + 3, 4, 11);
                }, "Đổi loại 📈");
                curX += 92;
                g.DrawString("Loại Biểu đồ", labelFont, Brushes.Gray, curX - 84, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // 5. Nhóm Đóng
                Rectangle closeBox = new Rectangle(curX, 68, 110, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 46, 73, curX + 64, 91);
                    g.DrawLine(redPen, curX + 64, 73, curX + 46, 91);
                }
                g.DrawString("Đóng Biểu đồ", boldFont, Brushes.White, curX + 14, 96);
            }
        }

        private void DrawTabSmartArtDesign(Graphics g, int width, WriterView writerView)
        {
            using (Font labelFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Font miniFont = new Font("Segoe UI", 6.5f, FontStyle.Regular))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // 1. Nhóm Tạo Đồ họa (Create Graphic)
                // Cột 1: Thêm hình, Thêm đầu dòng, Ngăn văn bản
                DrawVectorBtn(g, curX, 68, 102, 20, (g1, x1, y1) => {
                    using (Pen gp = new Pen(Color.FromArgb(16, 124, 65), 1.6f))
                    {
                        g1.DrawRectangle(gp, x1, y1 + 1, 12, 10);
                        g1.DrawLine(gp, x1 + 6, y1 - 1, x1 + 6, y1 + 5);
                        g1.DrawLine(gp, x1 + 3, y1 + 2, x1 + 9, y1 + 2);
                    }
                }, "Thêm hình ▾");

                DrawVectorBtn(g, curX, 89, 102, 20, (g1, x1, y1) => {
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(45, 55, 72)))
                    {
                        g1.FillEllipse(b, x1 + 1, y1 + 2, 3, 3);
                        g1.FillEllipse(b, x1 + 1, y1 + 7, 3, 3);
                    }
                    g1.DrawLine(iconPen, x1 + 6, y1 + 3, x1 + 13, y1 + 3);
                    g1.DrawLine(iconPen, x1 + 6, y1 + 8, x1 + 13, y1 + 8);
                }, "Thêm Đầu dòng");

                DrawVectorBtn(g, curX, 110, 102, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 13, 11);
                    g1.DrawLine(iconPen, x1 + 4, y1 + 1, x1 + 4, y1 + 12);
                    using (Pen p = new Pen(Color.FromArgb(45, 55, 72), 1f))
                    {
                        g1.DrawLine(p, x1 + 6, y1 + 4, x1 + 11, y1 + 4);
                        g1.DrawLine(p, x1 + 6, y1 + 8, x1 + 11, y1 + 8);
                    }
                }, "Ngăn Văn bản");
                curX += 106;

                // Cột 2: Nâng cấp, Hạ cấp, Phải sang Trái
                DrawVectorBtn(g, curX, 68, 98, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 12, y1 + 6, x1 + 2, y1 + 6);
                    g1.DrawLine(iconPen, x1 + 6, y1 + 2, x1 + 2, y1 + 6);
                    g1.DrawLine(iconPen, x1 + 6, y1 + 10, x1 + 2, y1 + 6);
                }, "Nâng cấp ←");

                DrawVectorBtn(g, curX, 89, 98, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 2, y1 + 6, x1 + 12, y1 + 6);
                    g1.DrawLine(iconPen, x1 + 8, y1 + 2, x1 + 12, y1 + 6);
                    g1.DrawLine(iconPen, x1 + 8, y1 + 10, x1 + 12, y1 + 6);
                }, "Hạ cấp →");

                DrawVectorBtn(g, curX, 110, 98, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 1, y1 + 4, x1 + 12, y1 + 4);
                    g1.DrawLine(iconPen, x1 + 9, y1 + 2, x1 + 12, y1 + 4);
                    g1.DrawLine(iconPen, x1 + 12, y1 + 9, x1 + 1, y1 + 9);
                    g1.DrawLine(iconPen, x1 + 4, y1 + 11, x1 + 1, y1 + 9);
                }, "Phải sang Trái ⇄");
                curX += 102;

                // Cột 3: Lên, Xuống, Bố cục nhánh
                DrawVectorBtn(g, curX, 68, 86, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 6, y1 + 11, x1 + 6, y1 + 2);
                    g1.DrawLine(iconPen, x1 + 2, y1 + 6, x1 + 6, y1 + 2);
                    g1.DrawLine(iconPen, x1 + 10, y1 + 6, x1 + 6, y1 + 2);
                }, "Lên ↑");

                DrawVectorBtn(g, curX, 89, 86, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1 + 6, y1 + 2, x1 + 6, y1 + 11);
                    g1.DrawLine(iconPen, x1 + 2, y1 + 7, x1 + 6, y1 + 11);
                    g1.DrawLine(iconPen, x1 + 10, y1 + 7, x1 + 6, y1 + 11);
                }, "Xuống ↓");

                DrawVectorBtn(g, curX, 110, 86, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1 + 4, y1 + 1, 6, 4);
                    g1.DrawLine(iconPen, x1 + 7, y1 + 5, x1 + 7, y1 + 8);
                    g1.DrawLine(iconPen, x1 + 2, y1 + 8, x1 + 12, y1 + 8);
                    g1.DrawRectangle(iconPen, x1 + 1, y1 + 8, 4, 3);
                    g1.DrawRectangle(iconPen, x1 + 9, y1 + 8, 4, 3);
                }, "Bố cục ▾");
                curX += 90;

                g.DrawString("Tạo Đồ họa", labelFont, Brushes.Gray, curX - 200, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Bố cục (Layouts)
                string[] sampleLayouts = new string[] { "Cycle_Radial", "Cycle_Basic", "Process_BasicChevron", "List_BasicBlock", "Hierarchy_Tree", "Matrix_Grid" };
                string[] sampleNames = new string[] { "Hướng tâm", "Chu kỳ", "Quy trình", "Danh sách", "Phân cấp", "Ma trận" };

                for (int li = 0; li < sampleLayouts.Length; li++)
                {
                    Rectangle lBox = new Rectangle(curX + li * 44, 68, 40, 60);
                    bool isCurrent = (writerView != null && writerView.ActiveShape != null && writerView.ActiveShape.SmartArtType == sampleLayouts[li]);
                    DrawInteractiveButton(g, lBox, isCurrent, 2);

                    int cx = lBox.X + 20;
                    int cy = lBox.Y + 18;

                    using (Pen pPen = new Pen(Color.FromArgb(43, 87, 154), 1.2f))
                    using (SolidBrush pBr = new SolidBrush(Color.FromArgb(220, 235, 252)))
                    {
                        if (li == 0) // Cycle_Radial
                        {
                            g.DrawLine(pPen, cx, cy, cx - 11, cy - 9);
                            g.DrawLine(pPen, cx, cy, cx + 11, cy - 9);
                            g.DrawLine(pPen, cx, cy, cx - 11, cy + 9);
                            g.DrawLine(pPen, cx, cy, cx + 11, cy + 9);
                            g.FillEllipse(pBr, cx - 5, cy - 5, 10, 10);
                            g.DrawEllipse(pPen, cx - 5, cy - 5, 10, 10);
                            g.FillEllipse(pBr, cx - 14, cy - 12, 7, 7);
                            g.DrawEllipse(pPen, cx - 14, cy - 12, 7, 7);
                            g.FillEllipse(pBr, cx + 7, cy - 12, 7, 7);
                            g.DrawEllipse(pPen, cx + 7, cy - 12, 7, 7);
                            g.FillEllipse(pBr, cx - 14, cy + 6, 7, 7);
                            g.DrawEllipse(pPen, cx - 14, cy + 6, 7, 7);
                            g.FillEllipse(pBr, cx + 7, cy + 6, 7, 7);
                            g.DrawEllipse(pPen, cx + 7, cy + 6, 7, 7);
                        }
                        else if (li == 1) // Cycle_Basic
                        {
                            g.DrawEllipse(pPen, cx - 11, cy - 11, 22, 22);
                            g.FillEllipse(pBr, cx - 15, cy - 4, 8, 8);
                            g.DrawEllipse(pPen, cx - 15, cy - 4, 8, 8);
                            g.FillEllipse(pBr, cx + 7, cy - 4, 8, 8);
                            g.DrawEllipse(pPen, cx + 7, cy - 4, 8, 8);
                            g.FillEllipse(pBr, cx - 4, cy - 15, 8, 8);
                            g.DrawEllipse(pPen, cx - 4, cy - 15, 8, 8);
                            g.FillEllipse(pBr, cx - 4, cy + 7, 8, 8);
                            g.DrawEllipse(pPen, cx - 4, cy + 7, 8, 8);
                        }
                        else if (li == 2) // Process_BasicChevron
                        {
                            for (int ci = 0; ci < 3; ci++)
                            {
                                int bx = cx - 14 + ci * 10;
                                PointF[] pts = new PointF[] {
                                    new PointF(bx, cy - 8),
                                    new PointF(bx + 7, cy - 8),
                                    new PointF(bx + 11, cy),
                                    new PointF(bx + 7, cy + 8),
                                    new PointF(bx, cy + 8),
                                    new PointF(bx + 4, cy)
                                };
                                g.FillPolygon(pBr, pts);
                                g.DrawPolygon(pPen, pts);
                            }
                        }
                        else if (li == 3) // List_BasicBlock
                        {
                            for (int bi = 0; bi < 3; bi++)
                            {
                                Rectangle bRect = new Rectangle(cx - 14, cy - 11 + bi * 8, 28, 6);
                                g.FillRectangle(pBr, bRect);
                                g.DrawRectangle(pPen, bRect);
                            }
                        }
                        else if (li == 4) // Hierarchy_Tree
                        {
                            Rectangle rootR = new Rectangle(cx - 7, cy - 12, 14, 7);
                            g.FillRectangle(pBr, rootR);
                            g.DrawRectangle(pPen, rootR);
                            g.DrawLine(pPen, cx, cy - 5, cx, cy - 1);
                            g.DrawLine(pPen, cx - 10, cy - 1, cx + 10, cy - 1);
                            g.DrawLine(pPen, cx - 10, cy - 1, cx - 10, cy + 3);
                            g.DrawLine(pPen, cx + 10, cy - 1, cx + 10, cy + 3);
                            Rectangle c1 = new Rectangle(cx - 15, cy + 3, 10, 7);
                            Rectangle c2 = new Rectangle(cx + 5, cy + 3, 10, 7);
                            g.FillRectangle(pBr, c1); g.DrawRectangle(pPen, c1);
                            g.FillRectangle(pBr, c2); g.DrawRectangle(pPen, c2);
                        }
                        else // Matrix_Grid
                        {
                            Rectangle q1 = new Rectangle(cx - 11, cy - 11, 10, 10);
                            Rectangle q2 = new Rectangle(cx + 1, cy - 11, 10, 10);
                            Rectangle q3 = new Rectangle(cx - 11, cy + 1, 10, 10);
                            Rectangle q4 = new Rectangle(cx + 1, cy + 1, 10, 10);
                            g.FillRectangle(pBr, q1); g.DrawRectangle(pPen, q1);
                            g.FillRectangle(pBr, q2); g.DrawRectangle(pPen, q2);
                            g.FillRectangle(pBr, q3); g.DrawRectangle(pPen, q3);
                            g.FillRectangle(pBr, q4); g.DrawRectangle(pPen, q4);
                        }
                    }

                    using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center })
                    {
                        g.DrawString(sampleNames[li], miniFont, Brushes.DimGray, new RectangleF(lBox.X, lBox.Y + 41, lBox.Width, 16), sf);
                    }
                }
                curX += sampleLayouts.Length * 44;

                DrawVectorToolBtnLarge(g, curX, 68, 80, 60, (g1, x1, y1) => {
                    using (Pen p = new Pen(Color.FromArgb(43, 87, 154), 1.5f))
                    {
                        g1.DrawRectangle(p, x1, y1, 14, 14);
                        g1.DrawLine(p, x1 + 7, y1, x1 + 7, y1 + 14);
                        g1.DrawLine(p, x1 + 7, y1 + 7, x1 + 14, y1 + 7);
                        g1.DrawLine(p, x1 + 17, y1 + 5, x1 + 20, y1 + 8);
                        g1.DrawLine(p, x1 + 20, y1 + 8, x1 + 23, y1 + 5);
                    }
                }, "Bố cục khác... ▾");
                curX += 84;

                g.DrawString("Bố cục", labelFont, Brushes.Gray, curX - 210, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Kiểu SmartArt (SmartArt Styles)
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen p = new Pen(Color.FromArgb(50, 70, 100), 1.5f))
                    {
                        g1.DrawEllipse(p, x1, y1, 18, 16);
                        g1.FillEllipse(Brushes.Crimson, x1 + 4, y1 + 3, 4, 4);
                        g1.FillEllipse(Brushes.Goldenrod, x1 + 10, y1 + 3, 4, 4);
                        g1.FillEllipse(Brushes.DodgerBlue, x1 + 4, y1 + 9, 4, 4);
                        g1.FillEllipse(Brushes.ForestGreen, x1 + 10, y1 + 9, 4, 4);
                    }
                }, "Đổi Màu ▾");
                curX += 72;

                string[] stNames = new string[] { "Phẳng", "Dải màu", "Nổi 3D", "Thủy tinh", "Viền mảnh" };
                for (int si = 0; si < 5; si++)
                {
                    Rectangle sBox = new Rectangle(curX + si * 46, 68, 42, 60);
                    DrawInteractiveButton(g, sBox, false, 2);

                    int sx = sBox.X + 21;
                    int sy = sBox.Y + 20;

                    using (Pen p = new Pen(Color.FromArgb(43, 87, 154), (si == 4 ? 2.0f : 1.2f)))
                    using (SolidBrush b = new SolidBrush(si == 4 ? Color.White : Color.FromArgb(43, 87, 154)))
                    {
                        if (si == 2) // 3D shadow
                        {
                            using (SolidBrush shBr = new SolidBrush(Color.FromArgb(80, 0, 0, 0)))
                            {
                                g.FillEllipse(shBr, sx - 9, sy - 5, 18, 14);
                            }
                        }
                        g.FillEllipse(b, sx - 11, sy - 8, 18, 14);
                        g.DrawEllipse(p, sx - 11, sy - 8, 18, 14);

                        if (si == 3) // Glass highlight
                        {
                            using (SolidBrush glBr = new SolidBrush(Color.FromArgb(160, 255, 255, 255)))
                            {
                                g.FillEllipse(glBr, sx - 9, sy - 7, 14, 6);
                            }
                        }
                        else if (si == 1) // Gradient
                        {
                            using (SolidBrush grBr = new SolidBrush(Color.FromArgb(90, 255, 255, 255)))
                            {
                                g.FillRectangle(grBr, sx - 10, sy - 8, 16, 6);
                            }
                        }
                    }

                    using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center })
                    {
                        g.DrawString(stNames[si], miniFont, Brushes.DimGray, new RectangleF(sBox.X, sBox.Y + 41, sBox.Width, 16), sf);
                    }
                }
                curX += 5 * 46 + 4;

                g.DrawString("Kiểu SmartArt", labelFont, Brushes.Gray, curX - 210, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 4. Nhóm Đặt lại (Reset)
                DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                    using (Pen p = new Pen(Color.FromArgb(16, 124, 65), 1.6f))
                    {
                        g1.DrawRectangle(p, x1, y1 + 3, 16, 12);
                        g1.DrawLine(p, x1 + 5, y1 + 3, x1 + 5, y1 + 15);
                    }
                    using (Pen up = new Pen(Color.FromArgb(0, 120, 215), 1.8f))
                    {
                        g1.DrawArc(up, x1 + 8, y1 - 2, 12, 12, 180, 210);
                        g1.DrawLine(up, x1 + 8, y1 + 3, x1 + 4, y1 + 3);
                        g1.DrawLine(up, x1 + 8, y1 + 3, x1 + 8, y1 - 1);
                    }
                }, "Đặt lại");
                curX += 80;

                g.DrawString("Đặt lại", labelFont, Brushes.Gray, curX - 60, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // 5. Nhóm Đóng (Close)
                Rectangle closeBox = new Rectangle(curX, 68, 92, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 37, 73, curX + 55, 91);
                    g.DrawLine(redPen, curX + 55, 73, curX + 37, 91);
                }
                g.DrawString("Bỏ chọn", boldFont, Brushes.White, curX + 18, 96);
            }
        }

        private void DrawTabSmartArtFormat(Graphics g, int width, WriterView writerView)
        {
            using (Font labelFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Font abcFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font miniFont = new Font("Segoe UI", 6.5f, FontStyle.Regular))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // 1. Nhóm Hình dạng (Shapes)
                DrawVectorBtn(g, curX, 68, 102, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 12, 10);
                    g1.DrawPolygon(iconPen, new PointF[] { new PointF(x1 + 8, y1 + 8), new PointF(x1 + 14, y1 + 8), new PointF(x1 + 11, y1 + 13) });
                }, "Đổi hình dạng ▾");

                DrawVectorBtn(g, curX, 89, 102, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1 + 1, y1 + 2, 12, 10);
                    g1.DrawLine(iconPen, x1 + 10, y1 + 5, x1 + 14, y1 + 1);
                    g1.DrawLine(iconPen, x1 + 11, y1 + 1, x1 + 14, y1 + 1);
                    g1.DrawLine(iconPen, x1 + 14, y1 + 1, x1 + 14, y1 + 4);
                }, "Lớn hơn ⭷");

                DrawVectorBtn(g, curX, 110, 102, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1 + 1, y1 + 2, 12, 10);
                    g1.DrawLine(iconPen, x1 + 14, y1 + 1, x1 + 10, y1 + 5);
                    g1.DrawLine(iconPen, x1 + 10, y1 + 2, x1 + 10, y1 + 5);
                    g1.DrawLine(iconPen, x1 + 10, y1 + 5, x1 + 13, y1 + 5);
                }, "Nhỏ hơn ⭸");
                curX += 106;

                g.DrawString("Hình dạng", labelFont, Brushes.Gray, curX - 85, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Kiểu Hình dạng (Shape Styles)
                Color[] pFills = new Color[] {
                    Color.FromArgb(43, 87, 154),  // Theme Blue
                    Color.FromArgb(31, 41, 55),   // Slate/Dark
                    Color.White,                  // Minimalist White
                    Color.FromArgb(5, 150, 105),  // Emerald Green
                    Color.FromArgb(217, 119, 6),  // Amber / Orange
                    Color.FromArgb(124, 58, 237)  // Violet / Purple
                };
                Color[] pLines = new Color[] {
                    Color.FromArgb(30, 60, 110),
                    Color.FromArgb(17, 24, 39),
                    Color.FromArgb(55, 65, 81),
                    Color.FromArgb(4, 120, 87),
                    Color.FromArgb(180, 83, 9),
                    Color.FromArgb(109, 40, 217)
                };

                for (int sp = 0; sp < 6; sp++)
                {
                    Rectangle spBox = new Rectangle(curX + sp * 44, 68, 40, 60);
                    DrawInteractiveButton(g, spBox, false, 2);

                    Rectangle innerR = new Rectangle(spBox.X + 4, spBox.Y + 8, 32, 26);
                    using (SolidBrush sb = new SolidBrush(pFills[sp]))
                    {
                        FillRoundedRectangle(g, sb, innerR, 4);
                    }
                    using (Pen spP = new Pen(pLines[sp], 1.2f))
                    {
                        DrawRoundedRectangle(g, spP, innerR, 4);
                    }
                    using (SolidBrush txtBr = new SolidBrush(sp == 2 ? Color.FromArgb(43, 87, 154) : Color.White))
                    using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                    {
                        g.DrawString("Abc", abcFont, txtBr, innerR, sf);
                    }
                }
                curX += 6 * 44 + 4;

                // Cột nút Tô Hình dạng, Viền ngoài, Hiệu ứng
                Color curFill = Color.FromArgb(43, 87, 154);
                if (writerView != null && writerView.ActiveShape != null)
                {
                    var ash = writerView.ActiveShape;
                    if (ash.SelectedNodeIndex >= 0 && ash.NodeColors.ContainsKey(ash.SelectedNodeIndex))
                        curFill = ash.NodeColors[ash.SelectedNodeIndex];
                    else
                        curFill = ash.FillColor;
                }

                DrawVectorBtn(g, curX, 68, 120, 20, (g1, x1, y1) => {
                    using (SolidBrush b = new SolidBrush(curFill))
                    {
                        g1.FillRectangle(b, x1, y1 + 1, 14, 11);
                    }
                    g1.DrawRectangle(Pens.Gray, x1, y1 + 1, 14, 11);
                }, "Tô Hình dạng ▾");

                DrawVectorBtn(g, curX, 89, 120, 20, (g1, x1, y1) => {
                    using (Pen p = new Pen(writerView != null && writerView.ActiveShape != null ? writerView.ActiveShape.OutlineColor : Color.Navy, 2.5f))
                    {
                        g1.DrawLine(p, x1, y1 + 7, x1 + 14, y1 + 7);
                    }
                }, "Viền ngoài ▾");

                DrawVectorBtn(g, curX, 110, 120, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 12, 11);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(80, 0, 120, 215)))
                    {
                        g1.FillRectangle(b, x1 + 4, y1 + 4, 11, 10);
                    }
                }, "Hiệu ứng ✨ ▾");
                curX += 124;

                g.DrawString("Kiểu Hình dạng", labelFont, Brushes.Gray, curX - 250, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Kiểu WordArt (WordArt Styles)
                Color[] waColors = new Color[] { Color.Black, Color.FromArgb(43, 87, 154), Color.FromArgb(217, 119, 6) };
                for (int wi = 0; wi < 3; wi++)
                {
                    Rectangle wBox = new Rectangle(curX + wi * 44, 68, 40, 60);
                    DrawInteractiveButton(g, wBox, false, 2);

                    using (Font wFont = new Font("Georgia", 15.0f, FontStyle.Bold))
                    using (SolidBrush wb = new SolidBrush(waColors[wi]))
                    using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                    {
                        if (wi == 2)
                        {
                            using (Pen wp = new Pen(waColors[wi], 1.5f))
                            using (GraphicsPath pth = new GraphicsPath())
                            {
                                pth.AddString("A", new FontFamily("Georgia"), (int)FontStyle.Bold, 20f, new PointF(wBox.X + 11, wBox.Y + 10), sf);
                                g.DrawPath(wp, pth);
                            }
                        }
                        else
                        {
                            g.DrawString("A", wFont, wb, new RectangleF(wBox.X, wBox.Y + 6, wBox.Width, 32), sf);
                        }
                    }
                }
                curX += 3 * 44 + 4;

                DrawVectorBtn(g, curX, 68, 115, 20, (g1, x1, y1) => {
                    using (Font tf = new Font("Segoe UI", 8f, FontStyle.Bold))
                    {
                        g1.DrawString("A", tf, Brushes.Black, x1 + 2, y1 - 2);
                    }
                    using (SolidBrush b = new SolidBrush(writerView != null && writerView.ActiveShape != null ? writerView.ActiveShape.TextColor : Color.Black))
                    {
                        g1.FillRectangle(b, x1 + 1, y1 + 10, 12, 3);
                    }
                }, "Tô Màu Chữ ▾");

                DrawVectorBtn(g, curX, 89, 115, 20, (g1, x1, y1) => {
                    using (Font tf = new Font("Segoe UI", 8f, FontStyle.Bold))
                    {
                        g1.DrawString("A", tf, Brushes.DarkBlue, x1 + 2, y1 - 2);
                    }
                    g1.DrawLine(iconPen, x1 + 1, y1 + 11, x1 + 13, y1 + 11);
                }, "Viền Chữ ▾");

                DrawVectorBtn(g, curX, 110, 115, 20, (g1, x1, y1) => {
                    using (Font tf = new Font("Segoe UI", 8f, FontStyle.Bold))
                    {
                        g1.DrawString("A", tf, Brushes.RoyalBlue, x1 + 2, y1 - 2);
                    }
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(100, 0, 120, 215)))
                    {
                        g1.FillEllipse(b, x1 + 8, y1 + 3, 6, 6);
                    }
                }, "Hiệu ứng Chữ ▾");
                curX += 119;

                g.DrawString("Kiểu WordArt", labelFont, Brushes.Gray, curX - 160, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 4. Nhóm Sắp xếp (Arrange)
                DrawVectorBtn(g, curX, 68, 102, 20, (g1, x1, y1) => {
                    g1.DrawArc(iconPen, x1 + 1, y1 + 1, 12, 10, 180, 180);
                    g1.DrawLine(iconPen, x1 + 1, y1 + 10, x1 + 13, y1 + 10);
                }, "Ngắt dòng ▾");

                DrawVectorBtn(g, curX, 89, 102, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1 + 1, y1 + 1, 10, 10);
                    g1.FillRectangle(Brushes.DodgerBlue, x1 + 3, y1 + 4, 8, 8);
                }, "Lên trước ⭡");

                DrawVectorBtn(g, curX, 110, 102, 20, (g1, x1, y1) => {
                    g1.FillRectangle(Brushes.DodgerBlue, x1 + 1, y1 + 1, 8, 8);
                    g1.DrawRectangle(iconPen, x1 + 3, y1 + 4, 10, 10);
                }, "Về sau ⭣");
                curX += 106;

                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, curX - 70, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 5. Nhóm Kích cỡ (Size)
                int shW = writerView != null && writerView.ActiveShape != null ? (writerView.ActiveShape.BaseWidth + writerView.ActiveShape.WidthDelta) : 440;
                int shH = writerView != null && writerView.ActiveShape != null ? (writerView.ActiveShape.BaseHeight + writerView.ActiveShape.HeightDelta) : 220;
                double hCm = Math.Round(shH * 0.0264583333, 1);
                double wCm = Math.Round(shW * 0.0264583333, 1);

                g.DrawString("↕ Cao: " + hCm + " cm", boldFont, Brushes.Black, curX, 75);
                g.DrawString("↔ Rộng: " + wCm + " cm", boldFont, Brushes.Black, curX, 100);
                curX += 105;

                g.DrawString("Kích cỡ", labelFont, Brushes.Gray, curX - 70, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // 6. Nhóm Đóng (Close)
                Rectangle closeBox = new Rectangle(curX, 68, 90, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 36, 73, curX + 54, 91);
                    g.DrawLine(redPen, curX + 54, 73, curX + 36, 91);
                }
                g.DrawString("Bỏ chọn", boldFont, Brushes.White, curX + 17, 96);
            }
        }

        private void DrawTabShapeFormat(Graphics g, int width, WriterView writerView)
        {
            using (Font labelFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 16;

                // 1. Nhóm Chèn hình dạng (Insert Shapes)
                int palW = 75;
                Rectangle palBox = new Rectangle(curX, 68, palW, 60);
                DrawInteractiveButton(g, palBox, false, 3);
                string[] qTypes = new string[] { "TextBox", "Line", "ArrowLine", "Rectangle", "Oval", "Triangle", "RightArrow", "Star5", "Cloud" };
                for (int qi = 0; qi < qTypes.Length; qi++)
                {
                    int qr = qi / 3; int qc = qi % 3;
                    Rectangle qRect = new Rectangle(curX + 6 + qc * 22, 70 + qr * 18, 18, 14);
                    using (Pen qp = new Pen(Color.FromArgb(50, 70, 100), 1.2f))
                    {
                        if (qTypes[qi] == "TextBox")
                        {
                            g.DrawRectangle(qp, qRect);
                            using (Font tf = new Font("Segoe UI", 6.5f, FontStyle.Bold)) g.DrawString("A", tf, Brushes.DarkBlue, qRect.X + 2, qRect.Y - 1);
                        }
                        else if (qTypes[qi] == "Line") g.DrawLine(qp, qRect.Left, qRect.Bottom, qRect.Right, qRect.Top);
                        else if (qTypes[qi] == "ArrowLine") { qp.CustomEndCap = new AdjustableArrowCap(2, 2); g.DrawLine(qp, qRect.Left, qRect.Bottom, qRect.Right, qRect.Top); }
                        else
                        {
                            using (GraphicsPath p = ShapeRenderer.CreateShapePath(qTypes[qi], qRect)) g.DrawPath(qp, p);
                        }
                    }
                }
                curX += palW + 4;

                DrawVectorToolBtnLarge(g, curX, 68, 80, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 16, 16);
                    g1.DrawPolygon(iconPen, new PointF[] { new PointF(x1 + 10, y1 + 10), new PointF(x1 + 18, y1 + 10), new PointF(x1 + 14, y1 + 17) });
                }, "Đổi hình");
                curX += 86;
                g.DrawString("Chèn hình dạng", labelFont, Brushes.Gray, curX - 165, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Kiểu hình dạng (Shape Styles)
                Color[] pFills = new Color[] { Color.FromArgb(43, 87, 154), Color.FromArgb(31, 41, 55), Color.White, Color.FromArgb(5, 150, 105), Color.FromArgb(217, 119, 6), Color.FromArgb(124, 58, 237) };
                Color[] pLines = new Color[] { Color.FromArgb(30, 60, 110), Color.FromArgb(17, 24, 39), Color.FromArgb(55, 65, 81), Color.FromArgb(4, 120, 87), Color.FromArgb(180, 83, 9), Color.FromArgb(109, 40, 217) };
                string[] pNames = new string[] { "Xanh", "Đen", "Trắng", "Lá", "Cam", "Tím" };

                for (int sp = 0; sp < 6; sp++)
                {
                    Rectangle spBox = new Rectangle(curX, 68, 38, 60);
                    DrawInteractiveButton(g, spBox, false, 2);
                    Rectangle spInner = new Rectangle(curX + 4, 72, 30, 26);
                    using (SolidBrush sb = new SolidBrush(pFills[sp])) g.FillRectangle(sb, spInner);
                    using (Pen spP = new Pen(pLines[sp], 1.2f)) g.DrawRectangle(spP, spInner);
                    using (Font spf = new Font("Segoe UI", 7.0f)) g.DrawString(pNames[sp], spf, Brushes.DimGray, curX + 6, 105);
                    curX += 42;
                }
                curX += 4;

                DrawVectorBtn(g, curX, 68, 110, 20, (g1, x1, y1) => {
                    using (SolidBrush b = new SolidBrush(writerView != null && writerView.ActiveShape != null ? writerView.ActiveShape.FillColor : Color.FromArgb(43, 87, 154)))
                        g1.FillRectangle(b, x1, y1 + 1, 14, 12);
                    g1.DrawRectangle(Pens.Gray, x1, y1 + 1, 14, 12);
                }, "Đổ màu nền ▾");
                DrawVectorBtn(g, curX, 88, 110, 20, (g1, x1, y1) => {
                    using (Pen p = new Pen(writerView != null && writerView.ActiveShape != null ? writerView.ActiveShape.OutlineColor : Color.Navy, 2.5f))
                        g1.DrawLine(p, x1, y1 + 7, x1 + 14, y1 + 7);
                }, "Viền hình ▾");
                DrawVectorBtn(g, curX, 108, 110, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 12, 12);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(80, 0, 120, 215))) g1.FillRectangle(b, x1 + 4, y1 + 5, 12, 12);
                }, "Hiệu ứng ✨ ▾");
                curX += 118;
                g.DrawString("Kiểu hình dạng", labelFont, Brushes.Gray, curX - 220, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Sắp xếp (Arrange)
                DrawVectorToolBtnLarge(g, curX, 68, 75, 60, (g1, x1, y1) => {
                    g1.DrawArc(iconPen, x1 + 2, y1 + 2, 16, 12, 180, 180);
                    g1.DrawLine(iconPen, x1 + 2, y1 + 12, x1 + 18, y1 + 12);
                }, "Ngắt dòng ▾");
                curX += 81;

                DrawVectorBtn(g, curX, 68, 115, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 12, 12);
                    g1.FillRectangle(Brushes.DodgerBlue, x1 + 3, y1 + 4, 10, 10);
                }, "Lên trước ⭡");
                DrawVectorBtn(g, curX, 88, 115, 20, (g1, x1, y1) => {
                    g1.FillRectangle(Brushes.DodgerBlue, x1, y1 + 1, 10, 10);
                    g1.DrawRectangle(iconPen, x1 + 3, y1 + 4, 12, 12);
                }, "Về sau ⭣");
                DrawVectorBtn(g, curX, 108, 115, 20, (g1, x1, y1) => {
                    g1.DrawArc(iconPen, x1 + 1, y1 + 1, 13, 13, 45, 270);
                }, "Xoay hình ↻");
                curX += 123;
                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 4. Nhóm Kích cỡ (Size)
                int shW = writerView != null && writerView.ActiveShape != null ? (writerView.ActiveShape.BaseWidth + writerView.ActiveShape.WidthDelta) : 180;
                int shH = writerView != null && writerView.ActiveShape != null ? (writerView.ActiveShape.BaseHeight + writerView.ActiveShape.HeightDelta) : 110;
                double hCm = Math.Round(shH * 0.0264583333, 1);
                double wCm = Math.Round(shW * 0.0264583333, 1);

                g.DrawString("↕ Cao: " + hCm + " cm", boldFont, Brushes.Black, curX, 75);
                g.DrawString("↔ Rộng: " + wCm + " cm", boldFont, Brushes.Black, curX, 100);
                curX += 115;
                g.DrawString("Kích cỡ", labelFont, Brushes.Gray, curX - 80, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // 5. Nhóm Đóng Định dạng Hình dạng
                Rectangle closeBox = new Rectangle(curX, 68, 110, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 46, 73, curX + 64, 91);
                    g.DrawLine(redPen, curX + 64, 73, curX + 46, 91);
                }
                g.DrawString("Bỏ chọn Hình", boldFont, Brushes.White, curX + 12, 96);
            }
        }

        private void DrawTabPictureFormat(Graphics g, int width, WriterView writerView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.6f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // 1. Nhóm Điều chỉnh (Adjust) (X: 14 -> 264)
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 18, 14);
                    using (Pen redP = new Pen(Color.FromArgb(239, 68, 68), 2f))
                    {
                        g1.DrawLine(redP, x1 + 10, y1 + 3, x1 + 18, y1 + 11);
                        g1.DrawLine(redP, x1 + 18, y1 + 3, x1 + 10, y1 + 11);
                    }
                }, "Xóa nền");
                curX += 68;

                DrawVectorBtn(g, curX, 68, 86, 20, (g1, x1, y1) => {
                    using (SolidBrush sunB = new SolidBrush(Color.FromArgb(217, 119, 6))) g1.FillEllipse(sunB, x1 + 2, y1 + 2, 10, 10);
                }, "Chỉnh sửa ▾");
                DrawVectorBtn(g, curX, 88, 86, 20, (g1, x1, y1) => {
                    g1.FillRectangle(Brushes.SteelBlue, x1 + 1, y1 + 2, 5, 5);
                    g1.FillRectangle(Brushes.SeaGreen, x1 + 7, y1 + 2, 5, 5);
                    g1.FillRectangle(Brushes.Coral, x1 + 1, y1 + 8, 5, 5);
                    g1.FillRectangle(Brushes.MediumPurple, x1 + 7, y1 + 8, 5, 5);
                }, "Màu sắc ▾");
                DrawVectorBtn(g, curX, 108, 86, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1 + 1, y1 + 2, 11, 11);
                    g1.DrawLine(iconPen, x1 + 2, y1 + 10, x1 + 5, y1 + 4);
                    g1.DrawLine(iconPen, x1 + 5, y1 + 4, x1 + 9, y1 + 10);
