                // 2. Nhóm Kiểu hình ảnh (Picture Styles) (X: 276 -> 646)
                string[] pStyleNames = new string[] { "Mỏng", "Khung đen", "Bóng gương", "Bo góc", "3D Kim loại", "Bầu dục" };
                for (int ps = 0; ps < 6; ps++)
                {
                    Rectangle psBox = new Rectangle(curX, 68, 44, 60);
                    DrawInteractiveButton(g, psBox, false, 2);
                    Rectangle psInner = new Rectangle(curX + 4, 72, 36, 26);

                    if (ps == 0) // Mỏng
                    {
                        g.FillRectangle(Brushes.LightSkyBlue, psInner);
                        g.DrawRectangle(Pens.LightGray, psInner);
                    }
                    else if (ps == 1) // Khung đen
                    {
                        g.FillRectangle(Brushes.LightSkyBlue, psInner);
                        using (Pen bp = new Pen(Color.FromArgb(20, 20, 20), 2f)) g.DrawRectangle(bp, psInner);
                    }
                    else if (ps == 2) // Bóng gương
                    {
                        g.FillRectangle(Brushes.LightSkyBlue, psInner);
                        g.FillRectangle(Brushes.LightSteelBlue, psInner.X, psInner.Bottom + 1, psInner.Width, 3);
                    }
                    else if (ps == 3) // Bo góc
                    {
                        using (GraphicsPath rp = ShapeRenderer.CreateShapePath("RoundedRectangle", psInner))
                        {
                            g.FillPath(Brushes.LightSkyBlue, rp);
                            g.DrawPath(Pens.SteelBlue, rp);
                        }
                    }
                    else if (ps == 4) // 3D Kim loại
                    {
                        using (LinearGradientBrush met = new LinearGradientBrush(psInner, Color.White, Color.Silver, 45f))
                        {
                            g.FillRectangle(met, psInner);
                        }
                        g.DrawRectangle(Pens.Gray, psInner);
                    }
                    else if (ps == 5) // Bầu dục
                    {
                        g.FillEllipse(Brushes.LightSkyBlue, psInner);
                        g.DrawEllipse(Pens.SteelBlue, psInner);
                    }

                    using (Font spf = new Font("Segoe UI", 6.6f, FontStyle.Regular))
                    {
                        SizeF nsz = g.MeasureString(pStyleNames[ps], spf);
                        g.DrawString(pStyleNames[ps], spf, Brushes.DimGray, curX + (44 - nsz.Width) / 2, 106);
                    }
                    curX += 46;
                }
                curX += 4;

                DrawVectorBtn(g, curX, 68, 92, 20, (g1, x1, y1) => {
                    using (Pen p = new Pen(writerView != null && writerView.ActiveShape != null ? writerView.ActiveShape.OutlineColor : Color.Navy, 2.5f))
