        private void DrawWatermarkRibbonIcon(Graphics g, int x, int y)
        {
            // Word Watermark icon: White page with folded corner + slanted red/coral outline 'A'
            Rectangle pRect = new Rectangle(x + 1, y, 19, 24);

            // Drop shadow
            using (SolidBrush sb = new SolidBrush(Color.FromArgb(220, 224, 230)))
            {
                g.FillRectangle(sb, pRect.X + 2, pRect.Y + 2, pRect.Width, pRect.Height);
            }

            // Paper base with folded top-right corner
            int fold = 6;
            using (SolidBrush pb = new SolidBrush(Color.White))
            using (Pen pp = new Pen(Color.FromArgb(100, 110, 125), 1.0f))
            {
                PointF[] pts = new PointF[] {
                    new PointF(pRect.X, pRect.Y),
                    new PointF(pRect.Right - fold, pRect.Y),
                    new PointF(pRect.Right, pRect.Y + fold),
                    new PointF(pRect.Right, pRect.Bottom),
                    new PointF(pRect.X, pRect.Bottom)
                };
                g.FillPolygon(pb, pts);
                g.DrawPolygon(pp, pts);

                // Fold flap
                PointF[] flap = new PointF[] {
                    new PointF(pRect.Right - fold, pRect.Y),
                    new PointF(pRect.Right - fold, pRect.Y + fold),
                    new PointF(pRect.Right, pRect.Y + fold)
                };
                using (SolidBrush fb = new SolidBrush(Color.FromArgb(238, 242, 246)))
                {
                    g.FillPolygon(fb, flap);
                }
                g.DrawPolygon(pp, flap);
            }

            // Slanted red/coral watermark outline letter 'A'
            GraphicsState gs = g.Save();
            g.TranslateTransform(pRect.X + pRect.Width / 2f - 0.5f, pRect.Y + pRect.Height / 2f + 1f);
            g.RotateTransform(-32f);
            using (Font wf = new Font("Segoe UI", 12.5f, FontStyle.Bold))
            using (SolidBrush redFill = new SolidBrush(Color.FromArgb(30, 235, 70, 70)))
            using (Pen redPen = new Pen(Color.FromArgb(216, 59, 1), 1.25f))
            {
                StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                GraphicsPath path = new GraphicsPath();
                path.AddString("A", wf.FontFamily, (int)wf.Style, 13.5f, new PointF(0, 0), sf);
                g.FillPath(redFill, path);
                g.DrawPath(redPen, path);
            }
            g.Restore(gs);
        }

        private void DrawPageColorRibbonIcon(Graphics g, int x, int y)
        {
            // Word Page Color icon: Paper with folded corner + tilted bucket pouring blue paint
            Rectangle pRect = new Rectangle(x + 1, y, 19, 24);

            // Drop shadow
            using (SolidBrush sb = new SolidBrush(Color.FromArgb(220, 224, 230)))
            {
                g.FillRectangle(sb, pRect.X + 2, pRect.Y + 2, pRect.Width, pRect.Height);
            }

            // Paper base
            int fold = 6;
            using (SolidBrush pb = new SolidBrush(Color.White))
            using (Pen pp = new Pen(Color.FromArgb(100, 110, 125), 1.0f))
            {
                PointF[] pts = new PointF[] {
                    new PointF(pRect.X, pRect.Y),
                    new PointF(pRect.Right - fold, pRect.Y),
                    new PointF(pRect.Right, pRect.Y + fold),
                    new PointF(pRect.Right, pRect.Bottom),
                    new PointF(pRect.X, pRect.Bottom)
                };
                g.FillPolygon(pb, pts);
                g.DrawPolygon(pp, pts);

                PointF[] flap = new PointF[] {
                    new PointF(pRect.Right - fold, pRect.Y),
                    new PointF(pRect.Right - fold, pRect.Y + fold),
                    new PointF(pRect.Right, pRect.Y + fold)
                };
                using (SolidBrush fb = new SolidBrush(Color.FromArgb(238, 242, 246)))
                {
                    g.FillPolygon(fb, flap);
                }
                g.DrawPolygon(pp, flap);
            }

            // Spilled blue paint puddle and wave on page
            using (SolidBrush blueBrush = new SolidBrush(Color.FromArgb(0, 120, 212)))
            {
                GraphicsPath paintPath = new GraphicsPath();
                paintPath.AddEllipse(pRect.X + 3, pRect.Y + 12, 11, 8);
                paintPath.AddEllipse(pRect.X + 7, pRect.Y + 9, 8, 8);
                g.FillPath(blueBrush, paintPath);
            }

            // Tilted bucket at upper-right pouring paint
            GraphicsState gs = g.Save();
            g.TranslateTransform(x + 14, y + 4);
            g.RotateTransform(42f);
            using (LinearGradientBrush bGrad = new LinearGradientBrush(new Rectangle(-4, -5, 9, 10), Color.FromArgb(240, 243, 246), Color.FromArgb(156, 163, 175), 45f))
            using (Pen bPen = new Pen(Color.FromArgb(55, 65, 81), 0.9f))
            using (SolidBrush blueLiquid = new SolidBrush(Color.FromArgb(0, 120, 212)))
            {
                PointF[] bkt = new PointF[] {
                    new PointF(-4, -5),
                    new PointF(4, -5),
                    new PointF(3, 4),
                    new PointF(-3, 4)
                };
                g.FillPolygon(bGrad, bkt);
                g.DrawPolygon(bPen, bkt);

                // Handle
                g.DrawArc(bPen, -4, -8, 8, 6, 180, 180);

                // Paint lip
                g.FillEllipse(blueLiquid, -3, 3, 6, 3);
            }
            g.Restore(gs);

            // Pour stream connecting bucket to puddle
            using (SolidBrush streamBrush = new SolidBrush(Color.FromArgb(0, 120, 212)))
            {
                PointF[] strm = new PointF[] {
                    new PointF(x + 13, y + 8),
                    new PointF(x + 15, y + 10),
                    new PointF(x + 11, y + 16),
                    new PointF(x + 9, y + 15)
                };
                g.FillPolygon(streamBrush, strm);
            }
        }

