        private void DrawThemesRibbonIcon(Graphics g, int x, int y)
        {
            // Word Themes icon: Clean bordered card with bold navy 'A', slate 'a', and 4 theme swatches
            Rectangle tile = new Rectangle(x - 2, y - 2, 26, 26);
            using (SolidBrush wb = new SolidBrush(Color.White))
            using (Pen bp = new Pen(Color.FromArgb(175, 185, 198), 1.0f))
            {
                g.FillRectangle(wb, tile);
                g.DrawRectangle(bp, tile);
            }

            using (Font fA = new Font("Segoe UI", 12f, FontStyle.Bold))
            using (Font fa = new Font("Segoe UI", 10f, FontStyle.Bold))
            using (SolidBrush bA = new SolidBrush(Color.FromArgb(31, 78, 121)))
            using (SolidBrush ba = new SolidBrush(Color.FromArgb(75, 85, 99)))
            {
                g.DrawString("A", fA, bA, x - 1, y - 4);
                g.DrawString("a", fa, ba, x + 11, y - 2);
            }

            Color[] swatches = new Color[] {
                Color.FromArgb(68, 114, 196),  // Primary Blue
                Color.FromArgb(237, 125, 49),  // Orange
                Color.FromArgb(165, 165, 165),  // Medium Gray
                Color.FromArgb(255, 192, 0)    // Gold
            };

            for (int k = 0; k < 4; k++)
            {
                int sx = x + k * 5 - 1;
                int sy = y + 15;
                using (SolidBrush sb = new SolidBrush(swatches[k]))
                {
                    g.FillRectangle(sb, sx, sy, 4, 4);
                }
                using (Pen sp = new Pen(Color.FromArgb(140, 145, 155), 0.5f))
                {
                    g.DrawRectangle(sp, sx, sy, 4, 4);
                }
            }
        }

        private void DrawColorsRibbonIcon(Graphics g, int x, int y)
        {
            // 2x2 grid of 4 colored rectangles in Word theme palette
            Color c0 = (ThemeColorPalette != null && ThemeColorPalette.Length > 0) ? ThemeColorPalette[0] : Color.FromArgb(47, 85, 151);
            Color c1 = (ThemeColorPalette != null && ThemeColorPalette.Length > 1) ? ThemeColorPalette[1] : Color.FromArgb(217, 217, 217);
            Color c2 = (ThemeColorPalette != null && ThemeColorPalette.Length > 2) ? ThemeColorPalette[2] : Color.FromArgb(91, 155, 213);
            Color c3 = (ThemeColorPalette != null && ThemeColorPalette.Length > 3) ? ThemeColorPalette[3] : Color.FromArgb(197, 90, 17);

            Color[] colors = new Color[] { c0, c1, c2, c3 };
            int sz = 7;
            for (int k = 0; k < 4; k++)
            {
                int cx = x + (k % 2) * (sz + 1);
                int cy = y + (k / 2) * (sz + 1);
                using (SolidBrush b = new SolidBrush(colors[k]))
                {
                    g.FillRectangle(b, cx, cy, sz, sz);
                }
            }
            using (Pen p = new Pen(Color.FromArgb(170, 175, 185), 0.8f))
            {
                g.DrawRectangle(p, x - 1, y - 1, sz * 2 + 2, sz * 2 + 2);
            }
        }

