        private void DrawTabThietKe(Graphics g, int width)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.8f, FontStyle.Bold))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                int curX = 14;

                // ==================== 1. NHOM CHU DE (THEMES) ====================
                BtnThemesBounds = new Rectangle(curX, 68, 54, 62);
                DrawVectorToolBtnLarge(g, BtnThemesBounds.X, BtnThemesBounds.Y, BtnThemesBounds.Width, BtnThemesBounds.Height, (g1, x1, y1) => {
                    DrawThemesRibbonIcon(g1, x1, y1);
                }, "Ch\u1ee7 \u0111\u1ec1 \u25be");
                curX += 60;

                // Divider line after Themes
                g.DrawLine(Pens.LightGray, curX, 68, curX, 146);
                curX += 10;

                // ==================== 2. NHOM DINH DANG TAI LIEU (DOCUMENT FORMATTING) ====================
                int docFmtStartX = curX;

                // Definitions of all 11 Word style sets
                Color thAccent = (ThemeColorPalette != null && ThemeColorPalette.Length > 0) ? ThemeColorPalette[0] : Color.FromArgb(68, 114, 196);
                StyleSetItemDefinition[] allStyles = new StyleSetItemDefinition[] {
                    new StyleSetItemDefinition(0, "M\u1eb7c \u0111\u1ecbnh", "TITLE", "Heading 1", thAccent, thAccent, "Calibri Light", "Calibri") { IsAllUpperTitle = true },
                    new StyleSetItemDefinition(1, "T\u1ed1i gi\u1ea3n", "TITLE", "Heading 1", Color.FromArgb(31, 41, 55), Color.FromArgb(71, 85, 105), "Segoe UI Semibold", "Segoe UI") { IsAllUpperTitle = true },
                    new StyleSetItemDefinition(2, "Th\u00e2n m\u1eadt", "Title", "Heading 1", Color.FromArgb(37, 99, 235), Color.FromArgb(59, 130, 246), "Segoe UI", "Segoe UI") { IsSerif = true },
                    new StyleSetItemDefinition(3, "Trang nh\u00e3", "Title", "Heading 1", Color.FromArgb(17, 24, 39), Color.FromArgb(180, 83, 9), "Georgia", "Garamond") { IsSerif = true },
                    new StyleSetItemDefinition(4, "\u0110\u1eadm n\u00e9t", "TITLE", "HEADING 1", Color.Black, Color.FromArgb(17, 24, 39), "Arial", "Arial") { IsAllUpperTitle = true },
                    new StyleSetItemDefinition(5, "\u0110\u00f3ng khung", "Title", "HEADING 1", Color.FromArgb(15, 23, 42), Color.FromArgb(30, 41, 59), "Cambria", "Cambria") { HasTopBottomFrame = true },
                    new StyleSetItemDefinition(6, "\u0110\u00e1nh s\u1ed1", "Title", "1  HEADING 1", Color.FromArgb(15, 23, 42), Color.FromArgb(29, 78, 216), "Calibri", "Calibri") { HasNumberPrefix = true },
                    new StyleSetItemDefinition(7, "C\u0103n gi\u1eefa", "Title", "Heading 1", Color.FromArgb(13, 148, 136), Color.FromArgb(15, 118, 110), "Aptos Display", "Aptos") { IsCentered = true },
                    new StyleSetItemDefinition(8, "Thanh vi\u1ec1n", "TITLE", "Heading 1", Color.FromArgb(5, 150, 105), Color.FromArgb(4, 120, 87), "Trebuchet MS", "Segoe UI") { HasAccentLine = true },
                    new StyleSetItemDefinition(9, "\u0110\u01b0\u1eddng \u0111\u00f4i", "TITLE", "Heading 1", Color.FromArgb(21, 128, 61), Color.FromArgb(37, 99, 235), "Calibri", "Calibri") { HasDualLine = true },
                    new StyleSetItemDefinition(10, "Trang tr\u1ecdng", "TITLE", "Heading 1", Color.FromArgb(131, 24, 67), Color.FromArgb(157, 23, 77), "Times New Roman", "Times New Roman") { IsAllUpperTitle = true, HasAccentLine = true }
                };

                // Dynamic Gallery Layout
                int fixedRightW = 16 + 8 + 48 + 6 + 48 + 6 + 134 + 12 + 204 + 20;
                int availGalleryW = Math.Max(220, width - curX - fixedRightW);
                int cardW = 76;
                int cardH = 56;
                int cardGap = 6;
                int visibleCardCount = Math.Max(3, Math.Min(11, availGalleryW / (cardW + cardGap)));

                if (StyleSetScrollOffset < 0) StyleSetScrollOffset = 0;
                if (StyleSetScrollOffset > allStyles.Length - visibleCardCount) StyleSetScrollOffset = Math.Max(0, allStyles.Length - visibleCardCount);

                StyleGalleryCardBounds.Clear();
                StyleGalleryCardIndices.Clear();

                for (int c = 0; c < visibleCardCount; c++)
                {
                    int sIdx = StyleSetScrollOffset + c;
                    if (sIdx >= allStyles.Length) break;

                    var st = allStyles[sIdx];
                    Rectangle cardBox = new Rectangle(curX, 68, cardW, cardH);
                    StyleGalleryCardBounds.Add(cardBox);
                    StyleGalleryCardIndices.Add(sIdx);

                    bool isCur = (ActiveStyleSetIndex == sIdx);
                    bool isHov = IsHovering(cardBox);

                    // Card background & border
                    using (SolidBrush cBg = new SolidBrush(isCur ? Color.FromArgb(239, 246, 255) : (isHov ? Color.FromArgb(248, 250, 252) : Color.White)))
                    {
                        g.FillRectangle(cBg, cardBox);
                    }
                    using (Pen bPen = new Pen(isCur ? Color.FromArgb(37, 99, 235) : (isHov ? Color.FromArgb(148, 163, 184) : Color.FromArgb(215, 220, 228)), isCur ? 1.8f : 1.0f))
                    {
                        g.DrawRectangle(bPen, cardBox.X, cardBox.Y, cardBox.Width - 1, cardBox.Height - 1);
                    }

                    // Title
                    using (Font tf = new Font("Segoe UI", 6.8f, FontStyle.Bold))
                    using (SolidBrush tb = new SolidBrush(st.AccentColor))
                    {
                        if (st.IsCentered)
                        {
                            StringFormat sf = new StringFormat { Alignment = StringAlignment.Center };
                            g.DrawString(st.TitleSample, tf, tb, new RectangleF(cardBox.X + 3, cardBox.Y + 4, cardBox.Width - 6, 12), sf);
                        }
                        else
                        {
                            g.DrawString(st.TitleSample, tf, tb, cardBox.X + 5, cardBox.Y + 4);
                        }
                    }

                    // Accents
                    if (st.HasDualLine)
                    {
                        using (Pen pG = new Pen(st.AccentColor, 0.8f))
                        {
                            g.DrawLine(pG, cardBox.X + 5, cardBox.Y + 3, cardBox.Right - 5, cardBox.Y + 3);
                            g.DrawLine(pG, cardBox.X + 5, cardBox.Y + 16, cardBox.Right - 5, cardBox.Y + 16);
                        }
                    }
                    else if (st.HasAccentLine)
                    {
                        using (Pen pA = new Pen(st.AccentColor, 1.0f))
                        {
                            g.DrawLine(pA, cardBox.X + 5, cardBox.Y + 16, cardBox.Right - 5, cardBox.Y + 16);
                        }
                    }
                    else if (st.HasTopBottomFrame)
                    {
                        using (Pen pF = new Pen(Color.FromArgb(160, 160, 160), 0.7f))
                        {
                            g.DrawLine(pF, cardBox.X + 5, cardBox.Y + 16, cardBox.Right - 5, cardBox.Y + 16);
                        }
                    }

                    // Heading line
                    using (Font hf = new Font("Segoe UI", 5.5f, FontStyle.Bold))
                    using (SolidBrush hb = new SolidBrush(st.HeadingColor))
                    {
                        if (st.IsCentered)
                        {
                            StringFormat sf = new StringFormat { Alignment = StringAlignment.Center };
                            g.DrawString(st.HeadingSample, hf, hb, new RectangleF(cardBox.X + 3, cardBox.Y + 18, cardBox.Width - 6, 10), sf);
                        }
                        else
                        {
                            g.DrawString(st.HeadingSample, hf, hb, cardBox.X + 5, cardBox.Y + 18);
                        }
                    }

                    // 4 realistic paragraph text silhouette lines
                    using (Pen lp = new Pen(Color.FromArgb(195, 200, 208), 1.0f))
                    {
                        g.DrawLine(lp, cardBox.X + 5, cardBox.Y + 31, cardBox.Right - 6, cardBox.Y + 31);
                        g.DrawLine(lp, cardBox.X + 5, cardBox.Y + 37, cardBox.Right - 10, cardBox.Y + 37);
                        g.DrawLine(lp, cardBox.X + 5, cardBox.Y + 43, cardBox.Right - 7, cardBox.Y + 43);
                        g.DrawLine(lp, cardBox.X + 5, cardBox.Y + 49, cardBox.X + 32, cardBox.Y + 49);
                    }

                    curX += cardW + cardGap;
                }

                // Vertical navigation strip (Up, Down, More)
                int navX = curX;
                BtnStyleGalleryUpBounds = new Rectangle(navX, 68, 16, 18);
                BtnStyleGalleryDownBounds = new Rectangle(navX, 87, 16, 18);
                BtnStyleGalleryMoreBounds = new Rectangle(navX, 106, 16, 18);

                Action<Rectangle, int> drawNavBtn = (r, navType) => {
                    bool hov = IsHovering(r);
                    using (SolidBrush nb = new SolidBrush(hov ? Color.FromArgb(235, 240, 248) : Color.White))
                    using (Pen np = new Pen(hov ? Color.FromArgb(148, 163, 184) : Color.FromArgb(215, 220, 228), 1.0f))
                    using (SolidBrush arrBrush = new SolidBrush(Color.FromArgb(70, 80, 95)))
                    {
                        g.FillRectangle(nb, r);
                        g.DrawRectangle(np, r.X, r.Y, r.Width - 1, r.Height - 1);

                        if (navType == 0) // Up arrow
                        {
                            PointF[] tri = new PointF[] {
                                new PointF(r.X + r.Width / 2f, r.Y + 6),
                                new PointF(r.X + 4.5f, r.Y + 11.5f),
                                new PointF(r.Right - 4.5f, r.Y + 11.5f)
                            };
                            g.FillPolygon(arrBrush, tri);
                        }
                        else if (navType == 1) // Down arrow
                        {
                            PointF[] tri = new PointF[] {
                                new PointF(r.X + 4.5f, r.Y + 6.5f),
                                new PointF(r.Right - 4.5f, r.Y + 6.5f),
                                new PointF(r.X + r.Width / 2f, r.Y + 12)
                            };
                            g.FillPolygon(arrBrush, tri);
                        }
                        else if (navType == 2) // More button (bar + down arrow)
                        {
                            using (Pen barPen = new Pen(Color.FromArgb(70, 80, 95), 1.2f))
                            {
                                g.DrawLine(barPen, r.X + 4, r.Y + 5.5f, r.Right - 4, r.Y + 5.5f);
                            }
                            PointF[] tri = new PointF[] {
                                new PointF(r.X + 4.5f, r.Y + 9),
                                new PointF(r.Right - 4.5f, r.Y + 9),
                                new PointF(r.X + r.Width / 2f, r.Y + 13.5f)
                            };
                            g.FillPolygon(arrBrush, tri);
                        }
                    }
                };

                drawNavBtn(BtnStyleGalleryUpBounds, 0);
                drawNavBtn(BtnStyleGalleryDownBounds, 1);
                drawNavBtn(BtnStyleGalleryMoreBounds, 2);

                curX = navX + 22;

                // Colors & Fonts medium buttons
                BtnColorsBounds = new Rectangle(curX, 68, 48, 58);
                DrawVectorToolBtnLarge(g, BtnColorsBounds.X, BtnColorsBounds.Y, BtnColorsBounds.Width, BtnColorsBounds.Height, (g1, x1, y1) => {
                    DrawColorsRibbonIcon(g1, x1, y1);
                }, "M\u00e0u s\u1eafc \u25be");
                curX += 52;

                BtnFontsBounds = new Rectangle(curX, 68, 48, 58);
                DrawVectorToolBtnLarge(g, BtnFontsBounds.X, BtnFontsBounds.Y, BtnFontsBounds.Width, BtnFontsBounds.Height, (g1, x1, y1) => {
                    DrawFontsRibbonIcon(g1, x1, y1);
                }, "Ph\u00f4ng ch\u1eef \u25be");
                curX += 52;

                // 3 Stacked horizontal rows (Paragraph Spacing, Effects, Set as Default)
                BtnParagraphSpacingBounds = new Rectangle(curX, 68, 134, 18);
                DrawVectorBtn(g, BtnParagraphSpacingBounds.X, BtnParagraphSpacingBounds.Y, BtnParagraphSpacingBounds.Width, BtnParagraphSpacingBounds.Height, (g1, x1, y1) => {
                    DrawParagraphSpacingRibbonIcon(g1, x1, y1);
                }, "Gi\u00e3n c\u00e1ch \u0111o\u1ea1n \u25be");

                BtnEffectsBounds = new Rectangle(curX, 88, 134, 18);
                DrawVectorBtn(g, BtnEffectsBounds.X, BtnEffectsBounds.Y, BtnEffectsBounds.Width, BtnEffectsBounds.Height, (g1, x1, y1) => {
                    DrawEffectsRibbonIcon(g1, x1, y1);
                }, "Hi\u1ec7u \u1ee9ng \u25be");

                BtnSetAsDefaultBounds = new Rectangle(curX, 108, 134, 18);
                DrawVectorBtn(g, BtnSetAsDefaultBounds.X, BtnSetAsDefaultBounds.Y, BtnSetAsDefaultBounds.Width, BtnSetAsDefaultBounds.Height, (g1, x1, y1) => {
                    DrawSetAsDefaultRibbonIcon(g1, x1, y1);
                }, "\u0110\u1eb7t l\u00e0m m\u1eb7c \u0111\u1ecbnh");
                curX += 140;

                // Document Formatting group label
                int docFmtW = curX - docFmtStartX;
                using (SolidBrush lblBrush = new SolidBrush(Color.FromArgb(120, 130, 145)))
                {
                    StringFormat csf = new StringFormat { Alignment = StringAlignment.Center };
                    g.DrawString("\u0110\u1ecbnh d\u1ea1ng t\u00e0i li\u1ec7u", labelFont, lblBrush, new RectangleF(docFmtStartX, 137, docFmtW, 16), csf);
                }

                // Subgroup divider line
                g.DrawLine(Pens.LightGray, curX, 68, curX, 146);
                curX += 12;

                // ==================== 3. NHOM NEN TRANG (PAGE BACKGROUND) ====================
                int pageBgStartX = curX;

                BtnWatermarkBounds = new Rectangle(curX, 68, 68, 62);
                DrawVectorToolBtnLarge(g, BtnWatermarkBounds.X, BtnWatermarkBounds.Y, BtnWatermarkBounds.Width, BtnWatermarkBounds.Height, (g1, x1, y1) => {
                    DrawWatermarkRibbonIcon(g1, x1, y1);
                }, "H\u00ecnh m\u1edd \u25be");
                curX += 72;

                BtnPageColorBounds = new Rectangle(curX, 68, 70, 62);
                DrawVectorToolBtnLarge(g, BtnPageColorBounds.X, BtnPageColorBounds.Y, BtnPageColorBounds.Width, BtnPageColorBounds.Height, (g1, x1, y1) => {
                    DrawPageColorRibbonIcon(g1, x1, y1);
                }, "M\u00e0u trang \u25be");
                curX += 74;

                BtnPageBordersBounds = new Rectangle(curX, 68, 68, 62);
                DrawVectorToolBtnLarge(g, BtnPageBordersBounds.X, BtnPageBordersBounds.Y, BtnPageBordersBounds.Width, BtnPageBordersBounds.Height, (g1, x1, y1) => {
                    DrawPageBorderRibbonIcon(g1, x1, y1);
                }, "Vi\u1ec1n trang");
                curX += 72;

                int pageBgW = curX - pageBgStartX;
                using (SolidBrush lblBrush = new SolidBrush(Color.FromArgb(120, 130, 145)))
                {
                    StringFormat csf = new StringFormat { Alignment = StringAlignment.Center };
                    g.DrawString("N\u1ec1n trang", labelFont, lblBrush, new RectangleF(pageBgStartX, 137, pageBgW, 16), csf);
                }
            }
        }

        private void DrawTabBoTri(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font labelFontBold = new Font("Segoe UI", 7.5f, FontStyle.Bold))
            using (Font spinFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font spinArrowFont = new Font("Segoe UI", 6.0f, FontStyle.Bold))
            using (Pen spinBorder = new Pen(Color.FromArgb(180, 180, 180), 1.0f))
            using (Pen spinBtnBorder = new Pen(Color.FromArgb(210, 210, 210), 1.0f))
            {
                int curX = 14;

                // ==================== 1. NHÓM THIẾT LẬP TRANG (PAGE SETUP) ====================
                int pageSetupStartX = curX;

                // Lề trang (Margins)
                BtnMarginsBounds = new Rectangle(curX, 68, 58, 62);
                DrawVectorToolBtnLarge(g, BtnMarginsBounds.X, BtnMarginsBounds.Y, BtnMarginsBounds.Width, BtnMarginsBounds.Height, (g1, x1, y1) => DrawMarginsRibbonIcon(g1, x1, y1), "Lề ▾");
                curX += 62;

                // Hướng giấy (Orientation)
                BtnOrientationBounds = new Rectangle(curX, 68, 64, 62);
                DrawVectorToolBtnLarge(g, BtnOrientationBounds.X, BtnOrientationBounds.Y, BtnOrientationBounds.Width, BtnOrientationBounds.Height, (g1, x1, y1) => DrawOrientationRibbonIcon(g1, x1, y1), "Hướng ▾");
                curX += 68;

                // Khổ giấy (Size)
                BtnPageSizeBounds = new Rectangle(curX, 68, 66, 62);
                DrawVectorToolBtnLarge(g, BtnPageSizeBounds.X, BtnPageSizeBounds.Y, BtnPageSizeBounds.Width, BtnPageSizeBounds.Height, (g1, x1, y1) => DrawPageSizeRibbonIcon(g1, x1, y1), "Khổ giấy ▾");
                curX += 70;

                // Chia cột (Columns)
                BtnColumnsBounds = new Rectangle(curX, 68, 66, 62);
                DrawVectorToolBtnLarge(g, BtnColumnsBounds.X, BtnColumnsBounds.Y, BtnColumnsBounds.Width, BtnColumnsBounds.Height, (g1, x1, y1) => DrawColumnsRibbonIcon(g1, x1, y1), "Chia cột ▾");
                curX += 70;

                // 3 nút nhỏ xếp tầng (Breaks, Line Numbers, Hyphenation)
                BtnBreaksBounds = new Rectangle(curX, 68, 120, 20);
                DrawVectorBtn(g, BtnBreaksBounds.X, BtnBreaksBounds.Y, BtnBreaksBounds.Width, BtnBreaksBounds.Height, (g1, x1, y1) => DrawBreaksRibbonIcon(g1, x1, y1), "Ngắt trang ▾");

                BtnLineNumbersBounds = new Rectangle(curX, 89, 120, 20);
                DrawVectorBtn(g, BtnLineNumbersBounds.X, BtnLineNumbersBounds.Y, BtnLineNumbersBounds.Width, BtnLineNumbersBounds.Height, (g1, x1, y1) => DrawLineNumbersRibbonIcon(g1, x1, y1), "Số dòng ▾");

                BtnHyphenationBounds = new Rectangle(curX, 110, 120, 20);
                DrawVectorBtn(g, BtnHyphenationBounds.X, BtnHyphenationBounds.Y, BtnHyphenationBounds.Width, BtnHyphenationBounds.Height, (g1, x1, y1) => DrawHyphenationRibbonIcon(g1, x1, y1), "Dấu nối ▾");
                curX += 126;

                // Tiêu đề nhóm & Dialog launcher
                g.DrawString("Thiết lập trang", labelFont, Brushes.Gray, (pageSetupStartX + curX) / 2 - 38, 137);
                BtnPageSetupLauncherBounds = new Rectangle(curX - 16, 134, 13, 13);
                DrawDialogLauncherIcon(g, BtnPageSetupLauncherBounds.X, BtnPageSetupLauncherBounds.Y);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // ==================== 2. NHÓM ĐOẠN VĂN (PARAGRAPH) ====================
                int paraStartX = curX;

                // Cột Thụt lề (Indent)
                g.DrawString("Thụt lề", labelFontBold, Brushes.DimGray, curX, 70);

                // Trái (Left Indent)
                DrawIndentLeftRibbonIcon(g, curX, 89);
                g.DrawString("Trái:", labelFont, Brushes.Black, curX + 18, 89);
                Rectangle spinLeftBox = new Rectangle(curX + 50, 87, 72, 20);
                g.FillRectangle(Brushes.White, spinLeftBox);
                g.DrawRectangle(spinBorder, spinLeftBox);
                g.DrawString(ParagraphIndentLeft.ToString("0.#") + "\"", spinFont, Brushes.Black, spinLeftBox.X + 4, spinLeftBox.Y + 3);
                SpinIndentLeftUpBounds = new Rectangle(spinLeftBox.Right - 16, spinLeftBox.Y, 16, 10);
                SpinIndentLeftDownBounds = new Rectangle(spinLeftBox.Right - 16, spinLeftBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinIndentLeftUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinIndentLeftDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinIndentLeftUpBounds.X + 2, SpinIndentLeftUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinIndentLeftDownBounds.X + 2, SpinIndentLeftDownBounds.Y - 1);

                // Phải (Right Indent)
                DrawIndentRightRibbonIcon(g, curX, 110);
                g.DrawString("Phải:", labelFont, Brushes.Black, curX + 18, 110);
                Rectangle spinRightBox = new Rectangle(curX + 50, 108, 72, 20);
                g.FillRectangle(Brushes.White, spinRightBox);
                g.DrawRectangle(spinBorder, spinRightBox);
                g.DrawString(ParagraphIndentRight.ToString("0.#") + "\"", spinFont, Brushes.Black, spinRightBox.X + 4, spinRightBox.Y + 3);
                SpinIndentRightUpBounds = new Rectangle(spinRightBox.Right - 16, spinRightBox.Y, 16, 10);
                SpinIndentRightDownBounds = new Rectangle(spinRightBox.Right - 16, spinRightBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinIndentRightUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinIndentRightDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinIndentRightUpBounds.X + 2, SpinIndentRightUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinIndentRightDownBounds.X + 2, SpinIndentRightDownBounds.Y - 1);
                curX += 134;

                // Cột Giãn cách (Spacing)
                g.DrawString("Giãn cách", labelFontBold, Brushes.DimGray, curX, 70);

                // Trước (Spacing Before)
                DrawSpacingBeforeRibbonIcon(g, curX, 89);
                g.DrawString("Trước:", labelFont, Brushes.Black, curX + 18, 89);
                Rectangle spinBeforeBox = new Rectangle(curX + 56, 87, 68, 20);
                g.FillRectangle(Brushes.White, spinBeforeBox);
                g.DrawRectangle(spinBorder, spinBeforeBox);
                g.DrawString(((int)ParagraphSpacingBefore).ToString() + " pt", spinFont, Brushes.Black, spinBeforeBox.X + 4, spinBeforeBox.Y + 3);
                SpinSpacingBeforeUpBounds = new Rectangle(spinBeforeBox.Right - 16, spinBeforeBox.Y, 16, 10);
                SpinSpacingBeforeDownBounds = new Rectangle(spinBeforeBox.Right - 16, spinBeforeBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinSpacingBeforeUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinSpacingBeforeDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinSpacingBeforeUpBounds.X + 2, SpinSpacingBeforeUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinSpacingBeforeDownBounds.X + 2, SpinSpacingBeforeDownBounds.Y - 1);

                // Sau (Spacing After)
                DrawSpacingAfterRibbonIcon(g, curX, 110);
                g.DrawString("Sau:", labelFont, Brushes.Black, curX + 18, 110);
                Rectangle spinAfterBox = new Rectangle(curX + 56, 108, 68, 20);
                g.FillRectangle(Brushes.White, spinAfterBox);
                g.DrawRectangle(spinBorder, spinAfterBox);
                g.DrawString(((int)ParagraphSpacingAfter).ToString() + " pt", spinFont, Brushes.Black, spinAfterBox.X + 4, spinAfterBox.Y + 3);
                SpinSpacingAfterUpBounds = new Rectangle(spinAfterBox.Right - 16, spinAfterBox.Y, 16, 10);
                SpinSpacingAfterDownBounds = new Rectangle(spinAfterBox.Right - 16, spinAfterBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinSpacingAfterUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinSpacingAfterDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinSpacingAfterUpBounds.X + 2, SpinSpacingAfterUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinSpacingAfterDownBounds.X + 2, SpinSpacingAfterDownBounds.Y - 1);
                curX += 136;

                // Tiêu đề nhóm & Dialog launcher
                g.DrawString("Đoạn văn", labelFont, Brushes.Gray, (paraStartX + curX) / 2 - 25, 137);
                BtnParagraphLauncherBounds = new Rectangle(curX - 16, 134, 13, 13);
                DrawDialogLauncherIcon(g, BtnParagraphLauncherBounds.X, BtnParagraphLauncherBounds.Y);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // ==================== 3. NHÓM SẮP XẾP (ARRANGE) ====================
                int arrStartX = curX;

                // Vị trí (Position)
                BtnPositionBounds = new Rectangle(curX, 68, 58, 62);
                DrawVectorToolBtnLarge(g, BtnPositionBounds.X, BtnPositionBounds.Y, BtnPositionBounds.Width, BtnPositionBounds.Height, (g1, x1, y1) => DrawPositionRibbonIcon(g1, x1, y1), "Vị trí ▾");
                curX += 62;

                // Ngắt dòng (Wrap Text)
                BtnWrapTextBounds = new Rectangle(curX, 68, 70, 62);
                DrawVectorToolBtnLarge(g, BtnWrapTextBounds.X, BtnWrapTextBounds.Y, BtnWrapTextBounds.Width, BtnWrapTextBounds.Height, (g1, x1, y1) => DrawWrapTextRibbonIcon(g1, x1, y1), "Ngắt dòng ▾");
                curX += 74;

                // Lên trước (Bring Forward)
                BtnBringForwardBounds = new Rectangle(curX, 68, 70, 62);
                DrawVectorToolBtnLarge(g, BtnBringForwardBounds.X, BtnBringForwardBounds.Y, BtnBringForwardBounds.Width, BtnBringForwardBounds.Height, (g1, x1, y1) => DrawBringForwardRibbonIcon(g1, x1, y1), "Lên trước ▾");
                curX += 74;

                // Về sau (Send Backward)
                BtnSendBackwardBounds = new Rectangle(curX, 68, 68, 62);
                DrawVectorToolBtnLarge(g, BtnSendBackwardBounds.X, BtnSendBackwardBounds.Y, BtnSendBackwardBounds.Width, BtnSendBackwardBounds.Height, (g1, x1, y1) => DrawSendBackwardRibbonIcon(g1, x1, y1), "Về sau ▾");
                curX += 72;

                // Ngăn Lựa chọn (Selection Pane) - Khung vàng cam sáng khi kích hoạt giống Microsoft Word
                bool isSelPaneOpen = (writerView != null && writerView.ShowSelectionPane);
                BtnSelectionPaneBounds = new Rectangle(curX, 68, 78, 62);

                if (isSelPaneOpen)
                {
                    using (SolidBrush goldBg = new SolidBrush(Color.FromArgb(255, 237, 213))) // Tailwind amber-100
                    using (Pen goldBorder = new Pen(Color.FromArgb(217, 119, 6), 1.3f))
                    {
                        FillRoundedRectangle(g, goldBg, BtnSelectionPaneBounds, 4);
                        DrawRoundedRectangle(g, goldBorder, BtnSelectionPaneBounds, 4);
                    }
                }
                else
                {
                    DrawInteractiveButton(g, BtnSelectionPaneBounds, false, 4);
                }

                DrawSelectionPaneRibbonIcon(g, BtnSelectionPaneBounds.X + (BtnSelectionPaneBounds.Width - 20) / 2, 72);
                using (Font txtFont = new Font("Segoe UI", 7.8f, FontStyle.Bold))
                using (SolidBrush tb = new SolidBrush(isSelPaneOpen ? Color.FromArgb(180, 83, 9) : Color.FromArgb(30, 41, 59)))
                using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                {
                    g.DrawString("Ngăn chọn", txtFont, tb, new RectangleF(BtnSelectionPaneBounds.X, 104, BtnSelectionPaneBounds.Width, 22), sf);
                }
                curX += 84;

                // 3 nút nhỏ xếp tầng (Align, Group, Rotate)
                BtnAlignBounds = new Rectangle(curX, 68, 114, 20);
                DrawVectorBtn(g, BtnAlignBounds.X, BtnAlignBounds.Y, BtnAlignBounds.Width, BtnAlignBounds.Height, (g1, x1, y1) => DrawAlignRibbonIcon(g1, x1, y1), "Căn chỉnh ▾");

                BtnGroupBounds = new Rectangle(curX, 89, 114, 20);
                DrawVectorBtn(g, BtnGroupBounds.X, BtnGroupBounds.Y, BtnGroupBounds.Width, BtnGroupBounds.Height, (g1, x1, y1) => DrawGroupRibbonIcon(g1, x1, y1), "Nhóm ▾");

                BtnRotateBounds = new Rectangle(curX, 110, 114, 20);
                DrawVectorBtn(g, BtnRotateBounds.X, BtnRotateBounds.Y, BtnRotateBounds.Width, BtnRotateBounds.Height, (g1, x1, y1) => DrawRotateRibbonIcon(g1, x1, y1), "Xoay hình ▾");
                curX += 120;

                // Tiêu đề nhóm Sắp xếp
                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, (arrStartX + curX) / 2 - 25, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            }
        }

