        private void DrawColumnsRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color slate = Color.FromArgb(51, 65, 85);
            using (GraphicsPath col1 = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 1, y + 1, 9, 22)))
            using (GraphicsPath col2 = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 13, y + 1, 9, 22)))
            {
                using (SolidBrush bg = new SolidBrush(Color.White))
                {
                    g.FillPath(bg, col1);
                    g.FillPath(bg, col2);
                }
                using (Pen p = new Pen(slate, 1.2f))
                {
                    g.DrawPath(p, col1);
                    g.DrawPath(p, col2);
                }
            }
            using (Pen lp = new Pen(Color.FromArgb(148, 163, 184), 1.1f))
            {
                for (int i = 0; i < 4; i++)
                {
                    g.DrawLine(lp, x + 3, y + 6 + i * 4.5f, x + 8, y + 6 + i * 4.5f);
                    g.DrawLine(lp, x + 15, y + 6 + i * 4.5f, x + 20, y + 6 + i * 4.5f);
                }
            }
        }

