        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Pen p = new Pen(Color.FromArgb(51, 65, 85), 1.2f))
            {
                g.DrawLine(p, x, y + 4.5f, x, y);
                g.DrawLine(p, x, y, x + 13, y);
                g.DrawLine(p, x + 13, y, x + 13, y + 4.5f);

                g.DrawLine(p, x, y + 9.5f, x, y + 14);
                g.DrawLine(p, x, y + 14, x + 13, y + 14);
                g.DrawLine(p, x + 13, y + 14, x + 13, y + 9.5f);
            }
            using (Pen breakPen = new Pen(Color.FromArgb(16, 110, 190), 1.1f) { DashStyle = DashStyle.Dash })
            {
                g.DrawLine(breakPen, x - 1, y + 7, x + 14, y + 7);
            }
        }

