        private void DrawPositionRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color slate = Color.FromArgb(51, 65, 85);
            Color blue = Color.FromArgb(16, 110, 190);
            Color dimLine = Color.FromArgb(148, 163, 184);

            Rectangle page = new Rectangle(x + 1, y, 19, 23);
            using (SolidBrush bg = new SolidBrush(Color.White))
                g.FillRectangle(bg, page);
            using (Pen p = new Pen(slate, 1.3f) { LineJoin = LineJoin.Round })
                g.DrawRectangle(p, page);

            // Subtle text lines
            using (Pen lp = new Pen(dimLine, 1.1f))
            {
                g.DrawLine(lp, x + 4, y + 4, x + 17, y + 4);
                g.DrawLine(lp, x + 4, y + 17, x + 17, y + 17);
                g.DrawLine(lp, x + 4, y + 20, x + 13, y + 20);
            }

            // Clean floating object box with blue accent
            Rectangle obj = new Rectangle(x + 5, y + 7, 11, 8);
            using (SolidBrush ob = new SolidBrush(Color.FromArgb(239, 246, 255)))
                g.FillRectangle(ob, obj);
            using (Pen op = new Pen(blue, 1.3f))
                g.DrawRectangle(op, obj);
        }

