        private void DrawSelectionPaneRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color slate = Color.FromArgb(51, 65, 85);
            Color blue = Color.FromArgb(16, 110, 190);
            Color dimLine = Color.FromArgb(148, 163, 184);

            // Back card
            Rectangle back = new Rectangle(x + 1, y + 4, 15, 17);
            using (SolidBrush bg = new SolidBrush(Color.White))
                g.FillRectangle(bg, back);
            using (Pen p = new Pen(dimLine, 1.1f) { LineJoin = LineJoin.Round })
                g.DrawRectangle(p, back);

            // Front card
            Rectangle front = new Rectangle(x + 6, y + 1, 15, 17);
            using (SolidBrush bg = new SolidBrush(Color.White))
                g.FillRectangle(bg, front);
            using (Pen p = new Pen(slate, 1.3f) { LineJoin = LineJoin.Round })
                g.DrawRectangle(p, front);
            using (SolidBrush hb = new SolidBrush(blue))
                g.FillRectangle(hb, x + 6, y + 1, 15, 4);

            // Pointer arrow
            Point[] cursorPoly = new Point[]
            {
                new Point(x + 14, y + 9),
                new Point(x + 20, y + 15),
                new Point(x + 17, y + 16),
                new Point(x + 20, y + 21),
                new Point(x + 18, y + 22),
                new Point(x + 15, y + 17),
                new Point(x + 12, y + 19)
            };
            using (SolidBrush cb = new SolidBrush(Color.White))
                g.FillPolygon(cb, cursorPoly);
            using (Pen cp = new Pen(slate, 1.2f) { LineJoin = LineJoin.Round })
                g.DrawPolygon(cp, cursorPoly);
        }

        private void DrawAlignRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color slate = Color.FromArgb(51, 65, 85);
            Color blue = Color.FromArgb(16, 110, 190);

            // Alignment vertical guide line
            using (Pen p = new Pen(blue, 1.4f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                g.DrawLine(p, x + 2, y + 1, x + 2, y + 15);

            // Two aligned horizontal rectangular bars
            using (SolidBrush b = new SolidBrush(Color.FromArgb(241, 245, 249)))
            using (Pen p = new Pen(slate, 1.2f) { LineJoin = LineJoin.Round })
            {
                Rectangle r1 = new Rectangle(x + 4, y + 3, 11, 4);
                g.FillRectangle(b, r1);
                g.DrawRectangle(p, r1);

                Rectangle r2 = new Rectangle(x + 4, y + 9, 7, 4);
                g.FillRectangle(b, r2);
                g.DrawRectangle(p, r2);
            }
        }

        private void DrawGroupRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color slate = Color.FromArgb(51, 65, 85);
            Color blue = Color.FromArgb(16, 110, 190);

            // Dotted grouping frame
            using (Pen dashPen = new Pen(Color.FromArgb(148, 163, 184), 1.0f) { DashStyle = DashStyle.Dash })
                g.DrawRectangle(dashPen, x, y, 15, 15);

            // Two wireframe objects
            using (SolidBrush bg = new SolidBrush(Color.White))
            using (Pen p1 = new Pen(slate, 1.2f))
            using (Pen p2 = new Pen(blue, 1.3f))
            {
                Rectangle r1 = new Rectangle(x + 2, y + 2, 5, 5);
                g.FillRectangle(bg, r1);
                g.DrawRectangle(p1, r1);

                Rectangle r2 = new Rectangle(x + 8, y + 8, 5, 5);
                g.FillRectangle(bg, r2);
                g.DrawRectangle(p2, r2);
            }
        }

        private void DrawRotateRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color blue = Color.FromArgb(16, 110, 190);
            using (Pen p = new Pen(blue, 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
            {
                g.DrawArc(p, x + 1, y + 1, 13, 13, 40, 280);
                // Arrow head at top right
                g.DrawLine(p, x + 12, y + 3, x + 14, y);
                g.DrawLine(p, x + 12, y + 3, x + 15, y + 5);
            }
        }

        #region POPUP MENUS CHO TAB BỐ TRÍ (LAYOUT)
        private Bitmap CreateMenuVectorIcon(int w, int h, Action<Graphics, int, int> draw)
        {
            Bitmap bmp = new Bitmap(w, h);
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                draw(g, 0, 0);
            }
            return bmp;
        }

        private void ShowAlignPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Căn lề trái (Align Left)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 2, y + 1, x + 2, y + 15);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 4, y + 3, 10, 4);
                    g.FillRectangle(b, x + 4, y + 9, 6, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Left", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Căn giữa ngang (Align Center)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f) { DashStyle = DashStyle.Dash }) g.DrawLine(p, x + 8, y + 1, x + 8, y + 15);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 3, 10, 4);
                    g.FillRectangle(b, x + 5, y + 9, 6, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Center", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Căn lề phải (Align Right)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 14, y + 1, x + 14, y + 15);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 2, y + 3, 10, 4);
                    g.FillRectangle(b, x + 6, y + 9, 6, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Right", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add(new ToolStripSeparator());

            menu.Items.Add("Căn lề trên (Align Top)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 1, y + 2, x + 15, y + 2);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 4, 4, 10);
