            ToolStripMenuItem mRegroup = new ToolStripMenuItem("Nhóm lại (Regroup)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f)) g.DrawArc(p, x + 2, y + 2, 12, 12, 45, 270);
