        private void ShowPositionPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            PositionDropDownForm posDlg = new PositionDropDownForm(screenPos, 0);
            posDlg.OnPreviewPosition += delegate(int pIdx) {
                if (writerView != null)
                {
                    writerView.PreviewPositionShape(pIdx, this);
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            posDlg.OnCancelPreview += delegate() {
                if (writerView != null)
                {
                    writerView.CancelShapeLivePreview();
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            posDlg.OnPositionSelected += delegate(int posIdx) {
                if (writerView != null)
                {
                    writerView.CommitShapeLivePreview();
                    if (posIdx == 0)
                    {
                        if (writerView.ActiveShape != null) writerView.ActiveShape.WrapMode = 0;
                    }
                    else
                    {
                        writerView.PositionShape(posIdx - 1, this);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            posDlg.OnMoreLayoutOptionsClicked += delegate() {
                if (writerView != null)
                {
                    using (LayoutOptionsDialogForm layoutDlg = new LayoutOptionsDialogForm(writerView.ActiveShape, 0))
                    {
                        if (layoutDlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (writerView.ActiveShape != null)
                            {
                                writerView.ActiveShape.WrapMode = layoutDlg.WrapMode;
                                writerView.ActiveShape.RotationAngle = layoutDlg.RotationAngle;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                }
            };
            posDlg.Show();
        }

        private void ShowWrapTextPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            int curWrap = (writerView != null && writerView.ActiveShape != null) ? writerView.ActiveShape.WrapMode : 1;
            WrapTextDropDownForm wrapDlg = new WrapTextDropDownForm(screenPos, curWrap);
            wrapDlg.OnPreviewWrapMode += delegate(int mode) {
                if (writerView != null)
                {
                    writerView.PreviewWrapMode(mode);
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            wrapDlg.OnCancelPreview += delegate() {
                if (writerView != null)
                {
                    writerView.CancelShapeLivePreview();
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            wrapDlg.OnWrapModeSelected += delegate(int mode) {
                if (writerView != null)
                {
                    writerView.CommitShapeLivePreview();
                    if (writerView.ActiveShape != null) writerView.ActiveShape.WrapMode = mode;
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            wrapDlg.OnMoreLayoutOptionsClicked += delegate() {
                if (writerView != null)
                {
                    using (LayoutOptionsDialogForm layoutDlg = new LayoutOptionsDialogForm(writerView.ActiveShape, 1))
                    {
                        if (layoutDlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (writerView.ActiveShape != null)
                            {
                                writerView.ActiveShape.WrapMode = layoutDlg.WrapMode;
                                writerView.ActiveShape.RotationAngle = layoutDlg.RotationAngle;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                }
            };
            wrapDlg.Show();
        }

        private void ShowBringForwardPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Lên trước 1 lớp (Bring Forward)", null, delegate(object s, EventArgs e) {
                if (writerView != null)
                {
                    if (writerView.ActiveShape != null) writerView.MoveShapeUp(writerView.ActiveShape);
                    else if (writerView.ActiveChart != null) writerView.MoveChartUp(writerView.ActiveChart);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Lên trên cùng (Bring to Front)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.DocumentShapes.Remove(writerView.ActiveShape);
                    writerView.DocumentShapes.Add(writerView.ActiveShape);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Lên trước văn bản (Bring in Front of Text)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.ActiveShape.WrapMode = 6;
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Show(screenPos);
        }

        private void ShowSendBackwardPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Về sau 1 lớp (Send Backward)", null, delegate(object s, EventArgs e) {
                if (writerView != null)
                {
                    if (writerView.ActiveShape != null) writerView.MoveShapeDown(writerView.ActiveShape);
                    else if (writerView.ActiveChart != null) writerView.MoveChartDown(writerView.ActiveChart);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Xuống dưới cùng (Send to Back)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.DocumentShapes.Remove(writerView.ActiveShape);
                    writerView.DocumentShapes.Insert(0, writerView.ActiveShape);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Xuống sau văn bản (Send Behind Text)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.ActiveShape.WrapMode = 5;
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Show(screenPos);
        }

