        private void DrawTabThamChieu(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;
                Color slate = Color.FromArgb(51, 65, 85);
                Color blue = Color.FromArgb(16, 110, 190);
                Color dimLine = Color.FromArgb(148, 163, 184);

                // ==========================================
                // 1. NHÓM: MỤC LỤC (Table of Contents)
                // ==========================================
                // 1.1 Mục lục tự động (Large)
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.2f))
                    using (Pen pDot = new Pen(dimLine, 1.0f) { DashStyle = DashStyle.Dot })
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (SolidBrush hdr = new SolidBrush(blue))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 1, 16, 18);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 1, 16, 18);
                        // Header band
                        g1.FillRectangle(hdr, x1 + 3, y1 + 3, 12, 2.5f);
                        // TOC bullet rows
                        // Level 1
                        g1.DrawLine(pBlue, x1 + 3, y1 + 8, x1 + 7, y1 + 8);
                        g1.DrawLine(pDot, x1 + 8, y1 + 8, x1 + 12, y1 + 8);
                        g1.DrawLine(pSlate, x1 + 13, y1 + 8, x1 + 15, y1 + 8);
                        // Level 2 (indented)
                        g1.DrawLine(pSlate, x1 + 5, y1 + 11.5f, x1 + 8, y1 + 11.5f);
                        g1.DrawLine(pDot, x1 + 9, y1 + 11.5f, x1 + 12, y1 + 11.5f);
                        g1.DrawLine(pSlate, x1 + 13, y1 + 11.5f, x1 + 15, y1 + 11.5f);
                        // Level 1
                        g1.DrawLine(pBlue, x1 + 3, y1 + 15, x1 + 7, y1 + 15);
                        g1.DrawLine(pDot, x1 + 8, y1 + 15, x1 + 12, y1 + 15);
                        g1.DrawLine(pSlate, x1 + 13, y1 + 15, x1 + 15, y1 + 15);
                    }
                }, "Mục lục ▾");
                curX += 72;

                // 1.2 Thêm văn bản (Add Text Level) & Cập nhật mục lục (Update TOC)
                DrawVectorBtn(g, curX, 68, 128, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pPlus = new Pen(blue, 1.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen pLine = new Pen(dimLine, 1.0f))
                    {
                        g1.FillRectangle(bg, x1, y1 + 1, 14, 13);
                        g1.DrawRectangle(pSlate, x1, y1 + 1, 14, 13);
                        g1.DrawLine(pLine, x1 + 2, y1 + 4, x1 + 8, y1 + 4);
                        g1.DrawLine(pLine, x1 + 4, y1 + 7, x1 + 9, y1 + 7);
                        // Plus glyph badge in blue
                        g1.DrawEllipse(pPlus, x1 + 7.5f, y1 + 6.5f, 6.5f, 6.5f);
                        g1.DrawLine(pPlus, x1 + 10.7f, y1 + 8, x1 + 10.7f, y1 + 11.5f);
                        g1.DrawLine(pPlus, x1 + 9, y1 + 9.7f, x1 + 12.5f, y1 + 9.7f);
                    }
                }, "Thêm văn bản ▾");
                DrawVectorBtn(g, curX, 98, 128, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen pBlue = new Pen(blue, 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                    {
                        g1.FillRectangle(bg, x1, y1 + 1, 14, 13);
                        g1.DrawRectangle(pSlate, x1, y1 + 1, 14, 13);
                        g1.DrawArc(pBlue, x1 + 3, y1 + 3.5f, 8, 8, 30, 270);
                        g1.DrawLine(pBlue, x1 + 9, y1 + 4, x1 + 11, y1 + 6);
                        g1.DrawLine(pBlue, x1 + 9, y1 + 8, x1 + 11, y1 + 6);
                    }
                }, "Cập nhật bảng");
                curX += 134;

                g.DrawString("Mục lục", labelFont, Brushes.Gray, curX - 125, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 2. NHÓM: CHÚ THÍCH (Footnotes & Endnotes)
                // ==========================================
                // 2.1 Chèn Chú thích Footnote (AB¹)
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    using (Font abF = new Font("Segoe UI", 9.5f, FontStyle.Bold))
                    using (Font supF = new Font("Segoe UI", 7.5f, FontStyle.Bold))
                    using (Pen pSep = new Pen(blue, 1.3f))
                    using (SolidBrush bSlate = new SolidBrush(slate))
                    using (SolidBrush bBlue = new SolidBrush(blue))
                    using (Pen linePen = new Pen(dimLine, 1.0f))
                    {
                        g1.DrawString("AB", abF, bSlate, x1 - 1, y1 - 2);
                        g1.DrawString("¹", supF, bBlue, x1 + 14, y1 - 4);
                        g1.DrawLine(pSep, x1 - 1, y1 + 15, x1 + 19, y1 + 15);
                        g1.DrawString("¹", new Font("Segoe UI", 6.0f, FontStyle.Bold), bBlue, x1 - 2, y1 + 14);
                        g1.DrawLine(linePen, x1 + 5, y1 + 18, x1 + 18, y1 + 18);
                    }
                }, "Chèn Footnote");
                curX += 76;

                // 2.2 Chèn Endnote & Chú thích tiếp theo
                DrawVectorBtn(g, curX, 68, 124, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Font supF = new Font("Segoe UI", 7.5f, FontStyle.Bold))
                    using (SolidBrush bBlue = new SolidBrush(blue))
                    using (Pen linePen = new Pen(dimLine, 1.0f))
                    {
                        g1.FillRectangle(bg, x1, y1 + 1, 13, 14);
                        g1.DrawRectangle(pSlate, x1, y1 + 1, 13, 14);
                        g1.DrawString("i", supF, bBlue, x1 + 7, y1 - 1);
                        g1.DrawLine(linePen, x1 + 2, y1 + 11, x1 + 10, y1 + 11);
                    }
                }, "Chèn Endnote");
                DrawVectorBtn(g, curX, 98, 124, 28, (g1, x1, y1) => {
                    using (Pen pBlue = new Pen(blue, 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                    using (SolidBrush dotBrush = new SolidBrush(blue))
                    {
                        g1.DrawLine(pBlue, x1 + 1, y1 + 7, x1 + 10, y1 + 7);
                        g1.DrawLine(pBlue, x1 + 7, y1 + 4, x1 + 10, y1 + 7);
                        g1.DrawLine(pBlue, x1 + 7, y1 + 10, x1 + 10, y1 + 7);
                        g1.FillEllipse(dotBrush, x1 + 12, y1 + 5.5f, 3, 3);
                    }
                }, "Chú thích tiếp ▾");
                curX += 128;

                // 2.3 Hiện danh sách chú thích (Show Notes Pane)
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen linePen = new Pen(dimLine, 1.0f))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawLine(linePen, x1 + 3, y1 + 4, x1 + 13, y1 + 4);
                        g1.DrawLine(linePen, x1 + 3, y1 + 7, x1 + 11, y1 + 7);
                        g1.DrawLine(pBlue, x1 + 1, y1 + 11, x1 + 17, y1 + 11);
                        g1.DrawLine(pBlue, x1 + 3, y1 + 14, x1 + 12, y1 + 14);
                    }
                }, "Hiện chú thích");
                curX += 74;

                g.DrawString("Chú thích", labelFont, Brushes.Gray, curX - 160, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 3. NHÓM: TRÍCH DẪN & TÀI LIỆU THAM KHẢO
                // ==========================================
                // 3.1 Chèn Trích dẫn (Insert Citation)
                DrawVectorToolBtnLarge(g, curX, 68, 74, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Font qFont = new Font("Georgia", 9.0f, FontStyle.Bold))
                    using (SolidBrush bBlue = new SolidBrush(blue))
                    {
                        PointF[] leftPage = new PointF[] { new PointF(x1 + 1, y1 + 3), new PointF(x1 + 9, y1 + 1), new PointF(x1 + 9, y1 + 17), new PointF(x1 + 1, y1 + 18) };
                        PointF[] rightPage = new PointF[] { new PointF(x1 + 9, y1 + 1), new PointF(x1 + 17, y1 + 3), new PointF(x1 + 17, y1 + 18), new PointF(x1 + 9, y1 + 17) };
                        g1.FillPolygon(bg, leftPage);
                        g1.DrawPolygon(pSlate, leftPage);
                        g1.FillPolygon(bg, rightPage);
                        g1.DrawPolygon(pSlate, rightPage);
                        g1.DrawString("“", qFont, bBlue, x1 + 2, y1 + 2);
                    }
                }, "Trích dẫn ▾");
                curX += 78;

                // 3.2 Quản lý nguồn & Kiểu trích dẫn
                string activeCitStyle = (writerView != null && !string.IsNullOrEmpty(writerView.CurrentCitationStyle)) ? writerView.CurrentCitationStyle : "APA";
                DrawVectorBtn(g, curX, 68, 128, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.1f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    {
                        g1.FillRectangle(bg, x1, y1 + 2, 14, 11);
                        g1.DrawRectangle(pSlate, x1, y1 + 2, 14, 11);
                        g1.DrawLine(pBlue, x1 + 2, y1 + 5, x1 + 6, y1 + 5);
                        g1.DrawLine(pSlate, x1 + 2, y1 + 8, x1 + 12, y1 + 8);
                    }
                }, "Quản lý nguồn");
                DrawVectorBtn(g, curX, 98, 128, 28, (g1, x1, y1) => {
                    using (Font qFont = new Font("Georgia", 9.0f, FontStyle.Bold))
                    using (SolidBrush bSlate = new SolidBrush(slate))
                    {
                        g1.DrawString("“ ”", qFont, bSlate, x1 - 2, y1 - 2);
                    }
                }, "Kiểu: " + activeCitStyle + " ▾");
                curX += 134;

                // 3.3 Thư mục tài liệu tham khảo (Bibliography)
                DrawVectorToolBtnLarge(g, curX, 68, 70, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen linePen = new Pen(dimLine, 1.0f))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawLine(pBlue, x1 + 3, y1 + 4, x1 + 13, y1 + 4);
                        g1.DrawLine(linePen, x1 + 3, y1 + 7.5f, x1 + 14, y1 + 7.5f);
                        g1.DrawLine(linePen, x1 + 5, y1 + 10.5f, x1 + 13, y1 + 10.5f);
                        g1.DrawLine(linePen, x1 + 3, y1 + 13.5f, x1 + 14, y1 + 13.5f);
                    }
                }, "Thư mục ▾");
                curX += 76;

                g.DrawString("Trích dẫn & Nguồn", labelFont, Brushes.Gray, curX - 190, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 4. NHÓM: PHỤ ĐỀ & BẢNG BIỂU (Captions)
                // ==========================================
                // 4.1 Chèn Phụ đề (Insert Caption)
                DrawVectorToolBtnLarge(g, curX, 68, 70, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 1, 16, 12);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 1, 16, 12);
                        g1.DrawEllipse(pSlate, x1 + 11, y1 + 3, 3, 3);
                        PointF[] mtn = new PointF[] { new PointF(x1 + 2, y1 + 12), new PointF(x1 + 6, y1 + 6), new PointF(x1 + 10, y1 + 12) };
                        g1.DrawLines(pSlate, mtn);
                        g1.DrawLine(pBlue, x1 + 1, y1 + 16, x1 + 17, y1 + 16);
                    }
                }, "Chèn Phụ đề");
                curX += 74;

                // 4.2 Bảng hình ảnh & Cập nhật bảng hình ảnh
                DrawVectorBtn(g, curX, 68, 132, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.0f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    {
                        g1.FillRectangle(bg, x1, y1 + 2, 13, 11);
                        g1.DrawRectangle(pSlate, x1, y1 + 2, 13, 11);
                        g1.DrawLine(pBlue, x1 + 2, y1 + 5, x1 + 5, y1 + 5);
                        g1.DrawLine(pSlate, x1 + 6, y1 + 5, x1 + 11, y1 + 5);
                        g1.DrawLine(pSlate, x1 + 2, y1 + 8.5f, x1 + 11, y1 + 8.5f);
                    }
                }, "Chèn bảng hình");
                DrawVectorBtn(g, curX, 98, 132, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.2f))
                    {
                        g1.DrawRectangle(pSlate, x1, y1 + 2, 13, 11);
                        g1.DrawArc(pBlue, x1 + 3, y1 + 4, 7, 7, 30, 270);
                        g1.DrawLine(pBlue, x1 + 8, y1 + 4, x1 + 10, y1 + 6);
                    }
                }, "Cập nhật bảng hình");
                curX += 138;

                // 4.3 Tham chiếu chéo (Cross Reference)
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (Pen pBlue = new Pen(blue, 1.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 2, 9, 13);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 2, 9, 13);
                        g1.FillRectangle(bg, x1 + 8, y1 + 5, 9, 13);
                        g1.DrawRectangle(pBlue, x1 + 8, y1 + 5, 9, 13);
                    }
                }, "Tham chiếu chéo");
                curX += 78;

                g.DrawString("Phụ đề & Bảng", labelFont, Brushes.Gray, curX - 165, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 5. NHÓM: CHỈ MỤC TÀI LIỆU (Index)
                // ==========================================
                DrawVectorBtn(g, curX, 68, 122, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f) { LineJoin = LineJoin.Round })
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (SolidBrush bBlue = new SolidBrush(blue))
                    {
                        PointF[] tag = new PointF[] { new PointF(x1 + 1, y1 + 4), new PointF(x1 + 7, y1 + 4), new PointF(x1 + 12, y1 + 9), new PointF(x1 + 8, y1 + 13), new PointF(x1 + 1, y1 + 13) };
                        g1.FillPolygon(bg, tag);
                        g1.DrawPolygon(pSlate, tag);
                        g1.FillEllipse(bBlue, x1 + 3, y1 + 6, 2, 2);
                    }
                }, "Đánh dấu mục");
                DrawVectorBtn(g, curX, 98, 122, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen lp = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
                    using (Font aFont = new Font("Segoe UI", 6.0f, FontStyle.Bold))
                    using (SolidBrush bBlue = new SolidBrush(blue))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 1, 13, 13);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 1, 13, 13);
                        g1.DrawString("A", aFont, bBlue, x1 + 2, y1);
                        g1.DrawLine(lp, x1 + 8, y1 + 4, x1 + 12, y1 + 4);
                        g1.DrawLine(lp, x1 + 3, y1 + 8, x1 + 12, y1 + 8);
                        g1.DrawLine(lp, x1 + 3, y1 + 11, x1 + 10, y1 + 11);
                    }
                }, "Chèn chỉ mục");
                curX += 126;

                // 5.3 Cập nhật chỉ mục (Update Index)
                DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(slate, 1.2f))
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen pBlue = new Pen(blue, 1.3f))
                    using (Font zFont = new Font("Segoe UI", 6.5f, FontStyle.Bold))
                    using (SolidBrush bBlue = new SolidBrush(blue))
                    {
                        g1.FillRectangle(bg, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawString("Z", zFont, bBlue, x1 + 2, y1 + 1);
                        g1.DrawArc(pBlue, x1 + 5, y1 + 7, 9, 8, 30, 270);
                        g1.DrawLine(pBlue, x1 + 12, y1 + 8, x1 + 14, y1 + 10);
                    }
                }, "Cập nhật mục");
                curX += 82;

                g.DrawString("Chỉ mục", labelFont, Brushes.Gray, curX - 110, 137);
            }
        }

        private void DrawTabHienThi(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // ==========================================
                // 1. NHÓM: CHẾ ĐỘ XEM (Views)
                // ==========================================
                int viewMode = writerView != null ? writerView.ViewMode : 1;
                // 1.1 Bố trí In (Print Layout)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    PointF[] pagePts = new PointF[] {
                        new PointF(x1 + 3, y1 + 1),
                        new PointF(x1 + 14, y1 + 1),
                        new PointF(x1 + 19, y1 + 6),
                        new PointF(x1 + 19, y1 + 21),
                        new PointF(x1 + 3, y1 + 21)
                    };
                    g1.FillPolygon(Brushes.White, pagePts);
                    using (Pen p = new Pen(slate, 1.3f) { LineJoin = LineJoin.Round })
                    {
                        g1.DrawPolygon(p, pagePts);
                        g1.DrawLine(p, x1 + 14, y1 + 1, x1 + 14, y1 + 6);
                        g1.DrawLine(p, x1 + 14, y1 + 6, x1 + 19, y1 + 6);
                    }
                    using (Pen bp = new Pen(blue, 1.2f))
                    using (Pen lp = new Pen(dimLine, 1.1f))
                    {
                        g1.DrawLine(bp, x1 + 6, y1 + 9, x1 + 16, y1 + 9);
                        g1.DrawLine(lp, x1 + 6, y1 + 13, x1 + 16, y1 + 13);
                        g1.DrawLine(lp, x1 + 6, y1 + 17, x1 + 13, y1 + 17);
                    }
                }, "Bố trí In", viewMode == 1);
                curX += 70;

                // 1.2 Chế độ Đọc (Read Mode)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    using (Pen p = new Pen(slate, 1.3f) { LineJoin = LineJoin.Round, StartCap = LineCap.Round, EndCap = LineCap.Round })
                    using (Pen lp = new Pen(dimLine, 1.1f))
                    using (Pen bp = new Pen(blue, 1.2f))
                    {
                        g1.DrawLine(p, x1 + 10, y1 + 3, x1 + 10, y1 + 19);
                        g1.DrawLine(p, x1 + 1, y1 + 4, x1 + 10, y1 + 3);
                        g1.DrawLine(p, x1 + 1, y1 + 4, x1 + 1, y1 + 18);
                        g1.DrawLine(p, x1 + 1, y1 + 18, x1 + 10, y1 + 19);
                        g1.DrawLine(p, x1 + 10, y1 + 3, x1 + 19, y1 + 4);
                        g1.DrawLine(p, x1 + 19, y1 + 4, x1 + 19, y1 + 18);
                        g1.DrawLine(p, x1 + 10, y1 + 19, x1 + 19, y1 + 18);

                        g1.DrawLine(bp, x1 + 3, y1 + 7, x1 + 8, y1 + 7);
                        g1.DrawLine(lp, x1 + 3, y1 + 11, x1 + 8, y1 + 11);
                        g1.DrawLine(lp, x1 + 3, y1 + 15, x1 + 7, y1 + 15);

                        g1.DrawLine(bp, x1 + 12, y1 + 7, x1 + 17, y1 + 7);
                        g1.DrawLine(lp, x1 + 12, y1 + 11, x1 + 17, y1 + 11);
                        g1.DrawLine(lp, x1 + 12, y1 + 15, x1 + 16, y1 + 15);
                    }
                }, "Chế độ Đọc", viewMode == 0);
                curX += 70;

                // 1.3 Bố trí Web (Web Layout)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 2, 20, 17);
                    using (Pen p = new Pen(slate, 1.3f) { LineJoin = LineJoin.Round })
                    using (Pen lp = new Pen(dimLine, 1.1f))
                    using (Pen bp = new Pen(blue, 1.2f))
                    {
                        g1.DrawRectangle(p, x1 + 1, y1 + 2, 20, 17);
                        g1.DrawLine(p, x1 + 1, y1 + 7, x1 + 21, y1 + 7);
                        using (SolidBrush dotBrush = new SolidBrush(dimLine))
                        {
                            g1.FillEllipse(dotBrush, x1 + 3.5f, y1 + 4, 1.5f, 1.5f);
                            g1.FillEllipse(dotBrush, x1 + 6.5f, y1 + 4, 1.5f, 1.5f);
                            g1.FillEllipse(dotBrush, x1 + 9.5f, y1 + 4, 1.5f, 1.5f);
                        }
                        g1.DrawLine(bp, x1 + 4, y1 + 11, x1 + 18, y1 + 11);
                        g1.DrawLine(lp, x1 + 4, y1 + 15, x1 + 14, y1 + 15);
                    }
                }, "Bố trí Web", viewMode == 2);
                curX += 70;

                // 1.4 Cấu trúc (Outline) & Bản nháp (Draft)
                DrawVectorBtn(g, curX, 68, 106, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    using (Pen lp = new Pen(slate, 1.2f))
                    using (SolidBrush bb = new SolidBrush(blue))
                    using (Pen bp = new Pen(blue, 1.0f))
                    {
                        g1.FillEllipse(bb, x1 + 1, y1 + 3, 3, 3);
                        g1.DrawLine(lp, x1 + 6, y1 + 4.5f, x1 + 14, y1 + 4.5f);

                        g1.DrawEllipse(bp, x1 + 4, y1 + 8, 2.5f, 2.5f);
                        g1.DrawLine(lp, x1 + 9, y1 + 9.5f, x1 + 14, y1 + 9.5f);

                        g1.FillEllipse(bb, x1 + 1, y1 + 13, 3, 3);
                        g1.DrawLine(lp, x1 + 6, y1 + 14.5f, x1 + 14, y1 + 14.5f);
                    }
                }, "Đề cương");
                DrawVectorBtn(g, curX, 98, 106, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    g1.FillRectangle(Brushes.White, x1 + 2, y1 + 2, 11, 14);
                    using (Pen p = new Pen(slate, 1.2f) { DashStyle = DashStyle.Dash })
                    using (Pen lp = new Pen(dimLine, 1.1f))
                    using (Pen bp = new Pen(blue, 1.1f))
                    {
                        g1.DrawRectangle(p, x1 + 2, y1 + 2, 11, 14);
                        g1.DrawLine(bp, x1 + 4, y1 + 5, x1 + 11, y1 + 5);
                        g1.DrawLine(lp, x1 + 4, y1 + 8, x1 + 11, y1 + 8);
                        g1.DrawLine(lp, x1 + 4, y1 + 11, x1 + 9, y1 + 11);
                    }
                }, "Bản nháp");
                curX += 110;

                // 1.5 Tập trung (Immersive Focus Mode)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    g1.FillRectangle(Brushes.White, x1 + 2, y1 + 2, 18, 16);
                    using (Pen p = new Pen(slate, 1.2f))
                    {
                        g1.DrawRectangle(p, x1 + 2, y1 + 2, 18, 16);
                    }
                    using (Pen fp = new Pen(blue, 1.4f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        g1.DrawLine(fp, x1 + 5, y1 + 7, x1 + 5, y1 + 5);
                        g1.DrawLine(fp, x1 + 5, y1 + 5, x1 + 8, y1 + 5);

                        g1.DrawLine(fp, x1 + 14, y1 + 5, x1 + 17, y1 + 5);
                        g1.DrawLine(fp, x1 + 17, y1 + 5, x1 + 17, y1 + 7);

                        g1.DrawLine(fp, x1 + 5, y1 + 13, x1 + 5, y1 + 15);
                        g1.DrawLine(fp, x1 + 5, y1 + 15, x1 + 8, y1 + 15);

                        g1.DrawLine(fp, x1 + 14, y1 + 15, x1 + 17, y1 + 15);
                        g1.DrawLine(fp, x1 + 17, y1 + 15, x1 + 17, y1 + 13);
                    }
                }, "Tập trung");
                curX += 72;

                g.DrawString("Chế độ xem", labelFont, Brushes.Gray, curX - 250, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 2. NHÓM: HIỂN THỊ (Show)
                // ==========================================
                // 2.1 Thước kẻ (Ruler)
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color mainCol = ShowRuler ? blue : slate;
                    g1.FillRectangle(Brushes.White, x1, y1 + 5, 20, 11);
                    using (Pen p = new Pen(mainCol, 1.3f) { LineJoin = LineJoin.Round })
                    using (Pen tp = new Pen(mainCol, 1.0f))
                    {
                        g1.DrawRectangle(p, x1, y1 + 5, 20, 11);
                        g1.DrawLine(tp, x1 + 4, y1 + 5, x1 + 4, y1 + 9);
                        g1.DrawLine(tp, x1 + 8, y1 + 5, x1 + 8, y1 + 7);
                        g1.DrawLine(tp, x1 + 12, y1 + 5, x1 + 12, y1 + 9);
                        g1.DrawLine(tp, x1 + 16, y1 + 5, x1 + 16, y1 + 7);
                    }
                }, "Thước kẻ", ShowRuler);
                curX += 68;

                // 2.2 Đơn vị đo (cm / inch) & Đường lưới (Gridlines)
                string unitTag = (writerView != null && writerView.CurrentRulerUnit == RulerUnit.Inches) ? "Đơn vị: inch" : "Đơn vị: cm";
                DrawVectorBtn(g, curX, 68, 118, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    using (Font uFont = new Font("Segoe UI", 7.5f, FontStyle.Bold))
                    using (Pen borderP = new Pen(slate, 1.1f) { LineJoin = LineJoin.Round })
                    {
                        g1.FillRectangle(Brushes.White, x1 + 1, y1 + 2, 14, 13);
                        g1.DrawRectangle(borderP, x1 + 1, y1 + 2, 14, 13);
                        string tag = (writerView != null && writerView.CurrentRulerUnit == RulerUnit.Inches) ? "in" : "cm";
                        g1.DrawString(tag, uFont, new SolidBrush(blue), x1 + 1.5f, y1 + 1.5f);
                    }
                }, unitTag);
                DrawVectorBtn(g, curX, 98, 118, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    Color mainCol = ShowGridlines ? blue : slate;
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 2, 14, 13);
                    using (Pen p = new Pen(mainCol, 1.1f))
                    using (Pen gp = new Pen(ShowGridlines ? Color.FromArgb(147, 197, 253) : dimLine, 1.0f) { DashStyle = DashStyle.Dash })
                    {
                        g1.DrawRectangle(p, x1 + 1, y1 + 2, 14, 13);
                        g1.DrawLine(gp, x1 + 5.5f, y1 + 2, x1 + 5.5f, y1 + 15);
                        g1.DrawLine(gp, x1 + 10f, y1 + 2, x1 + 10f, y1 + 15);
                        g1.DrawLine(gp, x1 + 1, y1 + 6.5f, x1 + 15, y1 + 6.5f);
                        g1.DrawLine(gp, x1 + 1, y1 + 10.5f, x1 + 15, y1 + 10.5f);
                    }
                }, "Đường lưới", ShowGridlines);
                curX += 122;

                // 2.3 Ngăn Điều hướng (Navigation Pane)
                bool showNav = (writerView != null && writerView.ShowNavigationPane);
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color mainCol = showNav ? blue : slate;
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 2, 18, 16);
                    using (Pen p = new Pen(mainCol, 1.3f) { LineJoin = LineJoin.Round })
                    using (SolidBrush paneBg = new SolidBrush(showNav ? Color.FromArgb(219, 234, 254) : Color.FromArgb(241, 245, 249)))
                    using (Pen lp = new Pen(showNav ? blue : Color.FromArgb(148, 163, 184), 1.0f))
                    {
                        g1.FillRectangle(paneBg, x1 + 1, y1 + 2, 6, 16);
                        g1.DrawRectangle(p, x1 + 1, y1 + 2, 18, 16);
                        g1.DrawLine(p, x1 + 7, y1 + 2, x1 + 7, y1 + 18);
                        g1.DrawLine(lp, x1 + 3, y1 + 6, x1 + 5, y1 + 6);
                        g1.DrawLine(lp, x1 + 3, y1 + 10, x1 + 5, y1 + 10);
                    }
                }, "Điều hướng", showNav);
                curX += 72;

                g.DrawString("Hiển thị", labelFont, Brushes.Gray, curX - 180, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 3. NHÓM: THU PHÓNG (Zoom)
                // ==========================================
                // 3.1 100% Zoom
                float curZoom = writerView != null ? writerView.ZoomLevel : 1.0f;
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    using (Pen p = new Pen(slate, 1.3f))
                    using (Font zFont = new Font("Segoe UI", 6.8f, FontStyle.Bold))
                    {
                        g1.DrawEllipse(p, x1 + 1, y1 + 1, 14, 14);
                        g1.DrawLine(new Pen(slate, 2.0f) { StartCap = LineCap.Round, EndCap = LineCap.Round }, x1 + 12, y1 + 12, x1 + 18, y1 + 18);
                        g1.DrawString("100", zFont, new SolidBrush(blue), x1, y1 + 2);
                    }
                }, "100%", Math.Abs(curZoom - 1.0f) < 0.05f);
                curX += 66;

                // 3.2 Một trang & Nhiều trang
                DrawVectorBtn(g, curX, 68, 112, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    g1.FillRectangle(Brushes.White, x1 + 2, y1 + 1, 11, 15);
                    using (Pen p = new Pen(slate, 1.2f))
                    using (Pen lp = new Pen(dimLine, 1.0f))
                    {
                        g1.DrawRectangle(p, x1 + 2, y1 + 1, 11, 15);
                        g1.DrawLine(lp, x1 + 4, y1 + 4, x1 + 11, y1 + 4);
                        g1.DrawLine(lp, x1 + 4, y1 + 7, x1 + 11, y1 + 7);
                        g1.DrawLine(lp, x1 + 4, y1 + 10, x1 + 9, y1 + 10);
                    }
                }, "Một trang");
                DrawVectorBtn(g, curX, 98, 112, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    g1.FillRectangle(Brushes.White, x1 + 7, y1 + 1, 9, 13);
                    using (Pen p = new Pen(slate, 1.1f))
                    {
                        g1.DrawRectangle(p, x1 + 7, y1 + 1, 9, 13);
                    }
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 4, 9, 13);
                    using (Pen p = new Pen(slate, 1.2f))
                    {
                        g1.DrawRectangle(p, x1 + 1, y1 + 4, 9, 13);
                    }
                }, "Nhiều trang");
                curX += 116;

                // 3.3 Độ rộng trang & Thu phóng tự do
                DrawVectorBtn(g, curX, 68, 116, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    g1.FillRectangle(Brushes.White, x1 + 3, y1 + 2, 10, 14);
                    using (Pen p = new Pen(slate, 1.2f))
                    {
                        g1.DrawRectangle(p, x1 + 3, y1 + 2, 10, 14);
                    }
                    using (Pen ap = new Pen(blue, 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                    {
                        g1.DrawLine(ap, x1, y1 + 9, x1 + 16, y1 + 9);
                        g1.DrawLine(ap, x1 + 2, y1 + 7, x1, y1 + 9);
                        g1.DrawLine(ap, x1 + 2, y1 + 11, x1, y1 + 9);
                        g1.DrawLine(ap, x1 + 14, y1 + 7, x1 + 16, y1 + 9);
                        g1.DrawLine(ap, x1 + 14, y1 + 11, x1 + 16, y1 + 9);
                    }
                }, "Độ rộng trang");
                DrawVectorBtn(g, curX, 98, 116, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    using (Pen p = new Pen(slate, 1.2f))
                    using (Pen bp = new Pen(blue, 1.3f))
                    {
                        g1.DrawEllipse(p, x1 + 1, y1 + 2, 10, 10);
                        g1.DrawLine(new Pen(slate, 1.8f) { StartCap = LineCap.Round, EndCap = LineCap.Round }, x1 + 8.5f, y1 + 9.5f, x1 + 13.5f, y1 + 14.5f);
                        g1.DrawLine(bp, x1 + 6, y1 + 4.5f, x1 + 6, y1 + 9.5f);
                        g1.DrawLine(bp, x1 + 3.5f, y1 + 7, x1 + 8.5f, y1 + 7);
                    }
                }, "Thu phóng ▾");
                curX += 122;

                g.DrawString("Thu phóng", labelFont, Brushes.Gray, curX - 200, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 4. NHÓM: NỀN & MÀU TRANG (Canvas Theme)
                // ==========================================
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    g1.FillRectangle(Brushes.White, x1 + 2, y1 + 1, 18, 19);
                    using (Pen p = new Pen(slate, 1.2f) { LineJoin = LineJoin.Round })
                    {
                        g1.DrawRectangle(p, x1 + 2, y1 + 1, 18, 19);
                    }
                    g1.FillRectangle(Brushes.White, x1 + 5, y1 + 4, 5, 5);
                    g1.DrawRectangle(Pens.Gray, x1 + 5, y1 + 4, 5, 5);

                    g1.FillRectangle(new SolidBrush(Color.FromArgb(253, 246, 226)), x1 + 12, y1 + 4, 5, 5);
                    g1.DrawRectangle(new Pen(Color.FromArgb(217, 119, 6), 1.0f), x1 + 12, y1 + 4, 5, 5);

                    g1.FillRectangle(new SolidBrush(Color.FromArgb(51, 65, 85)), x1 + 5, y1 + 11, 5, 5);
                    g1.DrawRectangle(Pens.DarkSlateGray, x1 + 5, y1 + 11, 5, 5);

                    g1.FillRectangle(new SolidBrush(Color.FromArgb(30, 30, 30)), x1 + 12, y1 + 11, 5, 5);
                    g1.DrawRectangle(Pens.Black, x1 + 12, y1 + 11, 5, 5);
                }, "Màu trang ▾");
                curX += 76;

                g.DrawString("Nền trang", labelFont, Brushes.Gray, curX - 60, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 5. NHÓM: CỬA SỔ & NGĂN (Window & Panes)
                // ==========================================
                bool showSel = (writerView != null && writerView.ShowSelectionPane);
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    Color dimLine = Color.FromArgb(148, 163, 184);
                    Color mainCol = showSel ? blue : slate;
                    g1.FillRectangle(Brushes.White, x1 + 2, y1 + 1, 16, 19);
                    using (Pen p = new Pen(mainCol, 1.2f))
                    using (Pen lp = new Pen(showSel ? blue : dimLine, 1.2f))
                    {
                        g1.DrawRectangle(p, x1 + 2, y1 + 1, 16, 19);
                        g1.DrawLine(lp, x1 + 5, y1 + 5, x1 + 15, y1 + 5);
                        g1.DrawLine(lp, x1 + 5, y1 + 9, x1 + 15, y1 + 9);
                        g1.DrawLine(lp, x1 + 5, y1 + 13, x1 + 12, y1 + 13);
                        g1.FillRectangle(new SolidBrush(blue), x1 + 5, y1 + 5, 3, 2);
                    }
                }, "Lựa chọn", showSel);
                curX += 72;

                DrawVectorBtn(g, curX, 68, 110, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    g1.FillRectangle(Brushes.White, x1 + 5, y1 + 1, 10, 9);
                    using (Pen p = new Pen(slate, 1.1f))
                    {
                        g1.DrawRectangle(p, x1 + 5, y1 + 1, 10, 9);
                        g1.DrawLine(p, x1 + 5, y1 + 3.5f, x1 + 15, y1 + 3.5f);
                    }
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 5, 10, 9);
                    using (Pen p = new Pen(slate, 1.2f))
                    {
                        g1.DrawRectangle(p, x1 + 1, y1 + 5, 10, 9);
                        g1.DrawLine(new Pen(blue, 1.2f), x1 + 1, y1 + 7.5f, x1 + 11, y1 + 7.5f);
                    }
                }, "Cửa sổ mới");
                DrawVectorBtn(g, curX, 98, 110, 28, (g1, x1, y1) => {
                    Color slate = Color.FromArgb(51, 65, 85);
                    Color blue = Color.FromArgb(16, 110, 190);
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 2, 14, 14);
                    using (Pen p = new Pen(slate, 1.2f))
                    using (Pen bp = new Pen(blue, 1.4f))
                    {
                        g1.DrawRectangle(p, x1 + 1, y1 + 2, 14, 14);
                        g1.DrawLine(bp, x1 + 1, y1 + 9, x1 + 15, y1 + 9);
                    }
                }, "Chia tách");
                curX += 116;

                g.DrawString("Cửa sổ", labelFont, Brushes.Gray, curX - 110, 137);
            }
        }

        private void DrawTabEquation(Graphics g, int width, WriterView writerView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font mathSymFont = new Font("Cambria Math", 10.0f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // 1. Nhóm Công cụ (Tools)
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                    using (Font piF = new Font("Segoe UI", 13.0f, FontStyle.Bold)) g1.DrawString("π", piF, Brushes.DarkBlue, x1 + 2, y1);
                }, "Công thức ▾");
                curX += 68;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => {
                    using (Font penF = new Font("Segoe UI", 12.0f)) g1.DrawString("✎", penF, Brushes.SteelBlue, x1, y1);
                }, "Viết tay");
                curX += 66;

                g.DrawString("Công cụ", labelFont, Brushes.Gray, curX - 100, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Ký hiệu toán học (Math Symbols Palette: 2 rows of 16 buttons = 32 math symbols)
                string[] mSymbols = new string[] {
                    "±", "∞", "=", "≠", "~", "×", "÷", "!", "∝", "<", "≪", ">", "≫", "≤", "≥", "∓",
                    "≅", "≈", "≡", "∀", "∂", "∃", "∇", "∈", "∉", "∋", "∏", "∑", "√", "∛", "∫", "π"
                };

                for (int si = 0; si < mSymbols.Length; si++)
                {
                    int r = si / 16;
                    int c = si % 16;
                    int sx = curX + c * 22;
                    int sy = 70 + r * 28;
                    Rectangle sBox = new Rectangle(sx, sy, 20, 26);

                    DrawInteractiveButton(g, sBox, false, 2);
                    SizeF msz = g.MeasureString(mSymbols[si], mathSymFont);
                    g.DrawString(mSymbols[si], mathSymFont, Brushes.Navy, sx + (20 - msz.Width) / 2, sy + (26 - msz.Height) / 2);
                }
                curX += 16 * 22 + 6;

                g.DrawString("Ký hiệu toán học", labelFont, Brushes.Gray, curX - 220, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Cấu trúc công thức (Structures)
                string[] structNames = new string[] { "Phân số ▾", "Chỉ số ▾", "Căn thức ▾", "Tích phân ▾", "Toán tử ▾", "Dấu ngoặc ▾", "Hàm số ▾", "Trọng âm ▾", "Giới hạn ▾", "Ma trận ▾" };
                string[] structIcons = new string[] { "x/y", "eˣ", "√x", "∫", "∑", "{}", "sin", "ä", "lim", "[::]" };

                for (int st = 0; st < structNames.Length; st++)
                {
                    Rectangle stBox = new Rectangle(curX, 68, 54, 60);
                    DrawInteractiveButton(g, stBox, false, 3);
                    using (Font ifont = new Font("Cambria Math", 10.0f, FontStyle.Bold))
                    {
                        SizeF isz = g.MeasureString(structIcons[st], ifont);
                        g.DrawString(structIcons[st], ifont, Brushes.Navy, curX + (54 - isz.Width) / 2, 75);
                    }
                    using (Font tf = new Font("Segoe UI", 7.0f, FontStyle.Bold))
                    {
                        g.DrawString(structNames[st], tf, Brushes.Black, curX + 2, 106);
                    }
                    curX += 58;
                }

                g.DrawString("Cấu trúc công thức", labelFont, Brushes.Gray, curX - 340, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // 4. Nhóm Đóng Công thức
                Rectangle closeBox = new Rectangle(curX, 68, 115, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 48, 73, curX + 66, 91);
                    g.DrawLine(redPen, curX + 66, 73, curX + 48, 91);
                }
                g.DrawString("Đóng Công thức", boldFont, Brushes.White, curX + 10, 96);
            }
        }

        #region Writer Tab Vẽ (Draw)
        private void DrawTabVe(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            {
                int curX = 14;

                // Group 1: Công cụ (Tools)
                DrawVectorToolBtnLarge(g, curX, 68, 52, 60, (g1, x1, y1) => DrawVectorCursorIcon(g1, x1, y1), "Chọn", ActiveDrawTool == 0);
                curX += 54;

                DrawVectorToolBtnLarge(g, curX, 68, 52, 60, (g1, x1, y1) => DrawEraserRibbonIcon(g1, x1, y1), "Tẩy", ActiveDrawTool == 6);
                curX += 54;

                g.DrawString("Công cụ", labelFont, Brushes.Gray, 45, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 2: Bút vẽ (Pens)
                DrawVectorToolBtnLarge(g, curX, 68, 48, 60, (g1, x1, y1) => DrawPenRibbonIcon(g1, x1, y1, Color.Black, false), "Bút đen", ActiveDrawTool == 1);
                curX += 50;

                DrawVectorToolBtnLarge(g, curX, 68, 48, 60, (g1, x1, y1) => DrawPenRibbonIcon(g1, x1, y1, Color.FromArgb(220, 38, 38), false), "Bút đỏ", ActiveDrawTool == 2);
                curX += 50;

                DrawVectorToolBtnLarge(g, curX, 68, 48, 60, (g1, x1, y1) => DrawPenRibbonIcon(g1, x1, y1, Color.FromArgb(37, 99, 235), false), "Bút xanh", ActiveDrawTool == 3);
                curX += 50;

                DrawVectorToolBtnLarge(g, curX, 68, 56, 60, (g1, x1, y1) => DrawPenRibbonIcon(g1, x1, y1, Color.FromArgb(250, 204, 21), true), "Dạ vàng", ActiveDrawTool == 4);
                curX += 58;

