        #region Writer Tab Thiết kế Bảng (Table Design)
        private void DrawTabTableDesign(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            {
                int curX = 14;

                // Group 1: Tùy chọn kiểu bảng (Table Style Options)
                DrawTableCheckBox(g, curX, 70, "Hàng đầu", TableStyleHeaderRow, btnFont);
                DrawTableCheckBox(g, curX, 92, "Hàng tổng", TableStyleTotalRow, btnFont);
                DrawTableCheckBox(g, curX, 114, "Hàng xen kẽ", TableStyleBandedRows, btnFont);
                curX += 96;

                DrawTableCheckBox(g, curX, 70, "Cột đầu", TableStyleFirstCol, btnFont);
                DrawTableCheckBox(g, curX, 92, "Cột cuối", TableStyleLastCol, btnFont);
                DrawTableCheckBox(g, curX, 114, "Cột xen kẽ", TableStyleBandedCols, btnFont);
                curX += 98;

                g.DrawString("Tùy chọn kiểu bảng", labelFont, Brushes.Gray, curX - 160, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 2: Kiểu bảng (Styles Gallery)
                Color[] hdrCols = new Color[] {
                    Color.FromArgb(245, 245, 245),
                    Color.FromArgb(43, 87, 154),
                    Color.FromArgb(15, 118, 110),
                    Color.FromArgb(51, 65, 85),
                    Color.FromArgb(217, 119, 6),
                    Color.FromArgb(124, 58, 237)
                };
                Color[] altCols = new Color[] {
                    Color.White,
                    Color.FromArgb(240, 244, 248),
                    Color.FromArgb(240, 253, 244),
                    Color.FromArgb(248, 250, 252),
                    Color.FromArgb(255, 251, 235),
                    Color.FromArgb(250, 245, 255)
                };

                for (int p = 0; p < 6; p++)
                {
                    Rectangle pBox = new Rectangle(curX, 70, 52, 48);
                    DrawInteractiveButton(g, pBox, ActiveTableStylePreset == p, 3);
                    using (SolidBrush hB = new SolidBrush(hdrCols[p]))
                    using (SolidBrush aB = new SolidBrush(altCols[p]))
                    using (Pen bP = new Pen(Color.FromArgb(180, 190, 200), 1f))
                    {
                        g.FillRectangle(hB, curX + 4, 74, 44, 12);
                        g.FillRectangle(Brushes.White, curX + 4, 86, 44, 10);
                        g.FillRectangle(aB, curX + 4, 96, 44, 10);
                        g.FillRectangle(Brushes.White, curX + 4, 106, 44, 8);
                        g.DrawRectangle(bP, curX + 4, 74, 44, 40);
                    }
                    if (ActiveTableStylePreset == p)
                    {
                        using (Pen selP = new Pen(Color.FromArgb(37, 99, 235), 2f))
