                // Group 3: Tô màu nền (Shading)
                DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => DrawFillBucketVector(g1, x1, y1, 18, Color.FromArgb(37, 99, 235)), "Đổ màu ▾");
                curX += 60;

                g.DrawString("Tô màu nền", labelFont, Brushes.Gray, curX - 60, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 4: Viền (Borders)
