        #region Writer Tab Bố trí Bảng (Table Layout)
        private void DrawTabTableLayout(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font matrixFont = new Font("Segoe UI", 7.0f, FontStyle.Bold))
            {
                int curX = 14;

                // Group 1: Bảng (Table)
                DrawVectorToolBtnLarge(g, curX, 68, 56, 60, (g1, x1, y1) => DrawSelectTableRibbonIcon(g1, x1, y1), "Chọn ▾");
                curX += 58;

                bool isGridOn = (writerView != null && writerView.ShowTableGridlines);
                DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => DrawGridlinesRibbonIcon(g1, x1, y1, isGridOn), "Xem lưới", isGridOn);
                curX += 60;

                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => DrawTablePropertiesRibbonIcon(g1, x1, y1), "Thuộc tính");
                curX += 64;

                g.DrawString("Bảng", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 2: Hàng & Cột (Rows & Columns)
                DrawVectorToolBtnLarge(g, curX, 68, 54, 60, (g1, x1, y1) => DrawTableDeleteRowColIcon(g1, x1, y1), "Xóa ▾");
                curX += 56;

                DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => DrawTableInsertRowIcon(g1, x1, y1, true), "Chèn trên");
                curX += 60;

                DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => DrawTableInsertRowIcon(g1, x1, y1, false), "Chèn dưới");
                curX += 60;

                DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => DrawTableInsertColIcon(g1, x1, y1, true), "Chèn trái");
                curX += 60;

                DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => DrawTableInsertColIcon(g1, x1, y1, false), "Chèn phải");
                curX += 60;

                g.DrawString("Hàng & Cột", labelFont, Brushes.Gray, curX - 170, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 3: Hợp nhất (Merge)
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => DrawTableMergeCellsRibbonIcon(g1, x1, y1), "Hợp nhất");
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 56, 60, (g1, x1, y1) => DrawSplitCellsRibbonIcon(g1, x1, y1), "Tách ô");
                curX += 58;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => DrawSplitTableRibbonIcon(g1, x1, y1), "Tách bảng");
                curX += 62;

                g.DrawString("Hợp nhất", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 4: Kích cỡ ô (Cell Size)
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => DrawAutoFitRibbonIcon(g1, x1, y1), "Tự khớp ▾");
                curX += 64;

                DrawVectorBtn(g, curX, 68, 90, 28, (g1, x1, y1) => DrawDistributeRowsIcon(g1, x1, y1), "Đều hàng");
                DrawVectorBtn(g, curX, 98, 90, 28, (g1, x1, y1) => DrawDistributeColsIcon(g1, x1, y1), "Đều cột");
                curX += 96;

                g.DrawString("Kích cỡ ô", labelFont, Brushes.Gray, curX - 100, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 5: Căn chỉnh (Alignment: 3x3 matrix)
                int activeH = 0;
                int activeV = 0;
                if (writerView != null)
                {
                    writerView.GetActiveTableCellAlignment(out activeH, out activeV);
                }

                int mX = curX;
                for (int r = 0; r < 3; r++)
                {
                    for (int c = 0; c < 3; c++)
                    {
                        Rectangle mb = new Rectangle(mX + c * 22, 70 + r * 19, 20, 17);
                        bool isCellActive = (c == activeH && r == activeV);
                        DrawInteractiveButton(g, mb, isCellActive, 2);

                        // Draw miniature cell box
                        using (Pen cellOutline = new Pen(isCellActive ? Color.FromArgb(0, 120, 212) : Color.FromArgb(203, 213, 225), 1.0f))
                        using (SolidBrush cellBg = new SolidBrush(isCellActive ? Color.FromArgb(222, 239, 255) : Color.FromArgb(250, 250, 250)))
                        {
                            Rectangle innerBox = new Rectangle(mb.X + 2, mb.Y + 2, 16, 13);
                            g.FillRectangle(cellBg, innerBox);
                            g.DrawRectangle(cellOutline, innerBox);
                        }

                        // Draw miniature alignment text lines (Word 365 style)
                        Color barCol = isCellActive ? Color.FromArgb(0, 90, 158) : Color.FromArgb(71, 85, 105);
                        using (Pen linePen = new Pen(barCol, 1.4f))
                        {
                            int yOffset = (r == 0) ? mb.Y + 4 : (r == 1 ? mb.Y + 6 : mb.Y + 8);
                            int l1X = (c == 0) ? mb.X + 4 : (c == 1 ? mb.X + 6 : mb.X + 8);
                            int l2X = (c == 0) ? mb.X + 4 : (c == 1 ? mb.X + 7 : mb.X + 10);
                            int l1W = (c == 1) ? 8 : (c == 0 ? 10 : 8);
                            int l2W = (c == 1) ? 6 : (c == 0 ? 7 : 6);
                            if (c == 2)
                            {
                                l1X = mb.X + 16 - l1W;
                                l2X = mb.X + 16 - l2W;
                            }

                            g.DrawLine(linePen, l1X, yOffset, l1X + l1W, yOffset);
                            g.DrawLine(linePen, l2X, yOffset + 3, l2X + l2W, yOffset + 3);
                        }
                    }
                }
                curX += 3 * 22 + 8;

                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => DrawTextDirectionRibbonIcon(g1, x1, y1), "Hướng chữ ▾");
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 54, 60, (g1, x1, y1) => DrawCellMarginsRibbonIcon(g1, x1, y1), "Lề ô");
                curX += 56;

                g.DrawString("Căn chỉnh", labelFont, Brushes.Gray, curX - 120, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // Group 6: Dữ liệu (Data)
                bool isRepeatHeader = (writerView != null && writerView.ActiveTableIndex >= 0 && writerView.ActiveTableIndex < writerView.DocumentTables.Count && writerView.DocumentTables[writerView.ActiveTableIndex].RepeatHeaderRow);
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => DrawRepeatHeaderRibbonIcon(g1, x1, y1, isRepeatHeader), "Lặp TĐ", isRepeatHeader);
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 56, 60, (g1, x1, y1) => DrawSortRibbonIcon(g1, x1, y1), "Sắp xếp");
                curX += 58;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => DrawFormulaFxRibbonIcon(g1, x1, y1), "Công thức");
                curX += 62;

                g.DrawString("Dữ liệu", labelFont, Brushes.Gray, curX - 110, 137);
            }
        }
        #endregion

        #region New Tabs Vector Icon Helpers
        private void DrawVectorCursorIcon(Graphics g, int x, int y)
        {
            using (SolidBrush b = new SolidBrush(Color.FromArgb(43, 87, 154)))
            using (Pen p = new Pen(Color.White, 1.2f))
            {
                PointF[] cursor = new PointF[] {
                    new PointF(x + 2, y + 2),
                    new PointF(x + 2, y + 18),
                    new PointF(x + 6, y + 14),
                    new PointF(x + 10, y + 19),
                    new PointF(x + 13, y + 17),
                    new PointF(x + 9, y + 12),
                    new PointF(x + 15, y + 12)
                };
