        private void DrawPenRibbonIcon(Graphics g, int x, int y, Color penColor, bool isHighlighter)
        {
            Color slate = Color.FromArgb(50, 49, 48);
            using (Pen borderPen = new Pen(slate, 1.2f) { LineJoin = LineJoin.Round })
            using (SolidBrush barrelBrush = new SolidBrush(Color.FromArgb(248, 250, 252)))
            using (SolidBrush bandBrush = new SolidBrush(penColor))
            {
                if (isHighlighter)
                {
                    Rectangle barrel = new Rectangle(x + 6, y + 4, 9, 12);
                    g.FillRectangle(barrelBrush, barrel);
                    g.DrawRectangle(borderPen, barrel);

                    g.FillRectangle(bandBrush, x + 6, y + 12, 9, 4);
                    g.DrawRectangle(borderPen, x + 6, y + 12, 9, 4);

                    PointF[] chisel = new PointF[] {
                        new PointF(x + 7, y + 16),
                        new PointF(x + 14, y + 18),
                        new PointF(x + 12, y + 21),
                        new PointF(x + 8, y + 21)
                    };
                    g.FillPolygon(bandBrush, chisel);
                    g.DrawPolygon(borderPen, chisel);
                }
                else
                {
                    Rectangle barrel = new Rectangle(x + 7, y + 3, 7, 12);
                    g.FillRectangle(barrelBrush, barrel);
                    g.DrawRectangle(borderPen, barrel);

                    g.DrawArc(borderPen, x + 7, y + 1, 7, 5, 180, 180);

                    g.FillRectangle(bandBrush, x + 7, y + 11, 7, 4);
                    g.DrawRectangle(borderPen, x + 7, y + 11, 7, 4);

                    PointF[] nib = new PointF[] {
                        new PointF(x + 7, y + 15),
                        new PointF(x + 14, y + 15),
                        new PointF(x + 10.5f, y + 21)
                    };
                    g.FillPolygon(barrelBrush, nib);
                    g.DrawPolygon(borderPen, nib);
                    g.FillEllipse(bandBrush, x + 9.5f, y + 19.5f, 2f, 2f);
                }
            }
        }

