        private void DrawRulerRibbonIcon(Graphics g, int x, int y)
        {
            Color slate = Color.FromArgb(50, 49, 48);
            using (Pen borderPen = new Pen(slate, 1.3f))
            using (Pen tickPen = new Pen(slate, 1.0f))
            using (SolidBrush bg = new SolidBrush(Color.White))
            {
                Rectangle rBox = new Rectangle(x + 1, y + 6, 20, 10);
                g.FillRectangle(bg, rBox);
                g.DrawRectangle(borderPen, rBox);
                for (int ti = 3; ti < 19; ti += 3)
                {
                    int tH = (ti % 6 == 0) ? 5 : 3;
                    g.DrawLine(tickPen, x + 1 + ti, y + 6, x + 1 + ti, y + 6 + tH);
                }
            }
        }

