            using (Pen arcPen = new Pen(Color.FromArgb(0, 120, 212), 1.8f))
            {
                g.DrawArc(arcPen, x + 11, y + 4, 10, 10, -90, 180);
                g.DrawLine(arcPen, x + 14, y + 13, x + 16, y + 15);
                g.DrawLine(arcPen, x + 18, y + 13, x + 16, y + 15);
            }

            using (Pen linePen = new Pen(Color.FromArgb(100, 116, 139), 1.2f))
            {
                g.DrawLine(linePen, x + 3, y + 15, x + 9, y + 15);
                g.DrawLine(linePen, x + 3, y + 18, x + 7, y + 18);
            }

            g.SmoothingMode = oldMode;
        }

