        private void DrawRepeatHeaderRibbonIcon(Graphics g, int x, int y, bool isChecked = false)
        {
            SmoothingMode oldMode = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            Rectangle p1 = new Rectangle(x + 1, y + 1, 14, 17);
            Rectangle p2 = new Rectangle(x + 7, y + 4, 14, 17);

            using (SolidBrush bg = new SolidBrush(Color.White))
            using (Pen borderPen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            {
                g.FillRectangle(bg, p2);
                g.DrawRectangle(borderPen, p2);
                g.FillRectangle(bg, p1);
                g.DrawRectangle(borderPen, p1);
