        private void DrawFormulaFxRibbonIcon(Graphics g, int x, int y)
        {
            SmoothingMode oldMode = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            using (Font f = new Font("Cambria", 11.5f, FontStyle.Italic | FontStyle.Bold))
