        private void LoadMailMergeRecipients(string filePath)
        {
            try
            {
                EnsureDefaultMailMergeRecords();
                if (System.IO.File.Exists(filePath))
                {
                    string[] lines = System.IO.File.ReadAllLines(filePath, System.Text.Encoding.UTF8);
                    if (lines.Length > 1)
                    {
                        char sep = filePath.EndsWith(".csv", StringComparison.OrdinalIgnoreCase) ? ',' : '\t';
                        string[] headers = lines[0].Split(sep);
                        for (int h = 0; h < headers.Length; h++) headers[h] = headers[h].Trim('"', ' ');

                        List<Dictionary<string, string>> newRecs = new List<Dictionary<string, string>>();
                        for (int li = 1; li < lines.Length; li++)
                        {
                            if (string.IsNullOrWhiteSpace(lines[li])) continue;
                            string[] cols = lines[li].Split(sep);
                            var rec = new Dictionary<string, string>();
                            for (int ci = 0; ci < headers.Length; ci++)
                            {
                                string val = ci < cols.Length ? cols[ci].Trim('"', ' ') : "";
                                rec[headers[ci]] = val;
                            }
                            if (!rec.ContainsKey("Họ và tên") && headers.Length > 0)
                            {
                                rec["Họ và tên"] = cols.Length > 0 ? cols[0].Trim('"', ' ') : "";
                            }
                            newRecs.Add(rec);
                        }
                        if (newRecs.Count > 0)
                        {
                            MailMergeRecords = newRecs;
                        }
                    }
                }
            }
            catch {}
        }

