                if (recForm.ShowDialog(parentForm) == DialogResult.OK)
                {
                    List<Dictionary<string, string>> updated = new List<Dictionary<string, string>>();
                    for (int ri = 0; ri < grid.Rows.Count; ri++)
                    {
                        var row = grid.Rows[ri];
                        if (row.IsNewRow) continue;
                        string name = row.Cells[0].Value != null ? row.Cells[0].Value.ToString() : "";
                        if (string.IsNullOrWhiteSpace(name)) continue;

                        var rec = new Dictionary<string, string>();
                        rec["Họ và tên"] = name;
