                        rec["Số điện thoại"] = row.Cells[4].Value != null ? row.Cells[4].Value.ToString() : "";
                        rec["Email"] = row.Cells[5].Value != null ? row.Cells[5].Value.ToString() : "";
                        updated.Add(rec);
                    }
                    if (updated.Count > 0)
                    {
                        MailMergeRecords = updated;
                    }
                    if (parentForm != null) parentForm.Invalidate();
