                {
                    string kw = txtKeyword.Text.Trim();
                    if (!string.IsNullOrEmpty(kw))
                    {
                        for (int ri = 0; ri < MailMergeRecords.Count; ri++)
                        {
                            var r = MailMergeRecords[ri];
                            bool found = false;
                            foreach (var kvp in r)
                            {
                                if (kvp.Value.IndexOf(kw, StringComparison.OrdinalIgnoreCase) >= 0)
                                {
                                    found = true;
                                    break;
                                }
                            }
                            if (found)
                            {
                                CurrentMailMergeRecord = ri + 1;
                                if (parentForm != null) parentForm.Invalidate();
                                break;
                            }
                        }
                    }
                }
            }
        }

        private void PerformMailMerge(WriterView writerView)
        {
            if (writerView == null || writerView.PieceTable == null) return;
            EnsureDefaultMailMergeRecords();
            if (MailMergeRecords.Count == 0) return;

            int recIdx = Math.Max(0, Math.Min(MailMergeRecords.Count - 1, CurrentMailMergeRecord - 1));
            var rec = MailMergeRecords[recIdx];

            writerView.SaveUndoState();
            string text = writerView.PieceTable.GetText();

            string name = rec.ContainsKey("Họ và tên") ? rec["Họ và tên"] : "";
            string addr = rec.ContainsKey("Địa chỉ") ? rec["Địa chỉ"] : "";
            string co = rec.ContainsKey("Công ty") ? rec["Công ty"] : "";
            string title = rec.ContainsKey("Chức danh") ? rec["Chức danh"] : "";
            string phone = rec.ContainsKey("Số điện thoại") ? rec["Số điện thoại"] : "";
            string email = rec.ContainsKey("Email") ? rec["Email"] : "";
            string dob = rec.ContainsKey("Ngày sinh") ? rec["Ngày sinh"] : "";

            string block = name;
            if (!string.IsNullOrEmpty(title)) block += "\n" + title;
            if (!string.IsNullOrEmpty(co)) block += "\n" + co;
            if (!string.IsNullOrEmpty(addr)) block += "\n" + addr;

            string greeting = "Kính gửi Ông/Bà " + name + ",";

            text = text.Replace("«Khối_Địa_Chỉ»", block);
            text = text.Replace(" «Khối_Địa_Chỉ» ", block);
            text = text.Replace("«Kính_gửi_Họ_Tên»", greeting);
            text = text.Replace(" «Kính_gửi_Họ_Tên» ", greeting);
            text = text.Replace("«Họ và tên»", name);
            text = text.Replace(" «Họ và tên» ", name);
            text = text.Replace("«Địa chỉ»", addr);
            text = text.Replace(" «Địa chỉ» ", addr);
            text = text.Replace("«Công ty»", co);
            text = text.Replace(" «Công ty» ", co);
            text = text.Replace("«Chức danh»", title);
            text = text.Replace(" «Chức danh» ", title);
            text = text.Replace("«Số điện thoại»", phone);
            text = text.Replace(" «Số điện thoại» ", phone);
            text = text.Replace("«Email»", email);
            text = text.Replace(" «Email» ", email);
            text = text.Replace("«Ngày sinh»", dob);
            text = text.Replace(" «Ngày sinh» ", dob);

            writerView.PieceTable.Clear();
            writerView.PieceTable.Insert(0, text);
            writerView.InvalidateLayoutAndTextCache();
            if (writerView.InvalidateCallback != null) writerView.InvalidateCallback();
        }

