            {
                ContextMenuStrip cms = new ContextMenuStrip();
                cms.Items.Add("📂 Sử dụng danh sách có sẵn...", null, (s, e) =>
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Title = "Chọn danh sách người nhận";
                        ofd.Filter = "Tệp bảng tính & dữ liệu (*.xlsx;*.csv;*.txt)|*.xlsx;*.csv;*.txt|Tất cả tệp (*.*)|*.*";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            LoadMailMergeRecipients(ofd.FileName);
                            CurrentMailMergeRecord = 1;
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                });
                cms.Items.Add("✏ Nhập / Chỉnh sửa danh sách người nhận...", null, (s, e) =>
                {
                    ShowRecipientsEditor(parentForm);
                });
                cms.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 306 && x <= 376)
            {
                ShowRecipientsEditor(parentForm);
                return true;
            }

            // Group 3: Viết & Chèn trường
            if (x >= 390 && x <= 516)
            {
                if (y >= 68 && y <= 88)
                {
                    writerView.InsertText("«Khối_Địa_Chỉ»");
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 89 && y <= 109)
                {
                    writerView.InsertText("«Kính_gửi_Họ_Tên»");
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 110 && y <= 130)
                {
                    ContextMenuStrip fMenu = new ContextMenuStrip();
                    string[] fNames = new string[] { "Họ và tên", "Chức danh", "Công ty", "Địa chỉ", "Số điện thoại", "Email", "Ngày sinh" };
                    for (int fi = 0; fi < fNames.Length; fi++)
                    {
                        string fn = fNames[fi];
                        fMenu.Items.Add("«" + fn + "»", null, (s, e) =>
                        {
                            writerView.InsertText("«" + fn + "»");
                            if (parentForm != null) parentForm.Invalidate();
                        });
                    }
                    fMenu.Show(parentForm, x, 130);
                    return true;
                }
            }

            // Group 4: Xem trước kết quả
            if (x >= 530 && x <= 610)
            {
                IsPreviewResultsActive = !IsPreviewResultsActive;
                EnsureDefaultMailMergeRecords();
                if (writerView != null)
                {
                    writerView.LoadMailMergeData(MailMergeRecords);
                    if (IsPreviewResultsActive)
                    {
                        writerView.ApplyMailMergePreview(CurrentMailMergeRecord - 1);
                    }
                    else
                    {
                        writerView.ClearMailMergePreview();
                    }
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // Nav buttons (rFirst: 616..640, rPrev: 642..666, rNext: 706..730, rLast: 732..756)
            if (x >= 616 && x <= 640)
            {
                CurrentMailMergeRecord = 1;
                if (IsPreviewResultsActive && writerView != null)
                {
                    writerView.LoadMailMergeData(MailMergeRecords);
                    writerView.ApplyMailMergePreview(CurrentMailMergeRecord - 1);
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 642 && x <= 666)
            {
                CurrentMailMergeRecord = Math.Max(1, CurrentMailMergeRecord - 1);
                if (IsPreviewResultsActive && writerView != null)
                {
                    writerView.LoadMailMergeData(MailMergeRecords);
                    writerView.ApplyMailMergePreview(CurrentMailMergeRecord - 1);
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 706 && x <= 730)
            {
                int maxR = MailMergeRecords.Count > 0 ? MailMergeRecords.Count : 5;
                CurrentMailMergeRecord = Math.Min(maxR, CurrentMailMergeRecord + 1);
                if (IsPreviewResultsActive && writerView != null)
                {
                    writerView.LoadMailMergeData(MailMergeRecords);
                    writerView.ApplyMailMergePreview(CurrentMailMergeRecord - 1);
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 732 && x <= 756)
            {
                int maxR = MailMergeRecords.Count > 0 ? MailMergeRecords.Count : 5;
                CurrentMailMergeRecord = maxR;
                if (IsPreviewResultsActive && writerView != null)
                {
                    writerView.LoadMailMergeData(MailMergeRecords);
                    writerView.ApplyMailMergePreview(CurrentMailMergeRecord - 1);
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 760 && x <= 828)
            {
                ShowRecipientsSearch(parentForm);
                return true;
            }

            // Group 5: Hoàn tất (Vẽ tại curX = 844, rộng 84 -> 844..928)
            if (x >= 844 && x <= 928)
            {
                ContextMenuStrip finMenu = new ContextMenuStrip();
                finMenu.Items.Add("📄 Trộn tất cả bản ghi thành tài liệu liên tục (Merge All to Document)", null, (s, e) =>
                {
                    if (writerView != null)
                    {
                        EnsureDefaultMailMergeRecords();
                        writerView.LoadMailMergeData(MailMergeRecords);
                        string allMerged = writerView.FinishAndMergeAllRecords();
                        writerView.SaveUndoState();
                        writerView.PieceTable.Clear();
                        writerView.PieceTable.Insert(0, allMerged);
                        writerView.InvalidateLayoutAndTextCache();
                    }
                    if (parentForm != null) parentForm.Invalidate();
                });
                finMenu.Items.Add("📄 Trộn bản ghi hiện tại vào tài liệu (Merge Current Record)", null, (s, e) =>
                {
                    PerformMailMerge(writerView);
                    if (parentForm != null) parentForm.Invalidate();
                });
                finMenu.Items.Add("🖨 In tài liệu (Print Document)...", null, (s, e) =>
                {
                    using (PrintDialog pd = new PrintDialog())
                    {
                        pd.UseEXDialog = true;
                        pd.ShowDialog(parentForm);
                    }
                });
                finMenu.Items.Add(new ToolStripSeparator());
                finMenu.Items.Add("📧 Gửi thông điệp Email (Send Email Messages)...", null, (s, e) =>
                {
                    string docTitle = "Tai_Lieu_ZenQOffice";
                    string curPath = "";
                    if (writerView != null)
                    {
                        curPath = writerView.CurrentFilePath;
                        if (!string.IsNullOrEmpty(curPath))
                            docTitle = System.IO.Path.GetFileNameWithoutExtension(curPath);
                        else if (ActiveDocIndex >= 0 && ActiveDocIndex < DocTabs.Count)
                            docTitle = DocTabs[ActiveDocIndex].Title;
                    }
                    using (SendEmailDialogForm emailDlg = new SendEmailDialogForm(
                        docTitle,
                        curPath,
                        saveTempCopyAction: (tempPath) => writerView != null && writerView.SaveDocumentFile(tempPath, this, false),
                        exportPdfAction: (pdfPath) => writerView != null && writerView.ExportToPdf(pdfPath, this)))
                    {
                        emailDlg.ShowDialog(parentForm);
                    }
                });
                finMenu.Show(parentForm, x, 130);
                return true;
            }

            return false;
        }

        private bool HandleTabXemLaiClick(int x, int y, WriterView writerView, Form parentForm)
        {
            if (writerView == null) return false;

            // Group 1: Kiểm tra
            if (x >= 14 && x <= 78)
            {
                writerView.RunSpellCheck(parentForm);
                return true;
            }
            if (x >= 80 && x <= 154)
            {
                string curWord = writerView.GetWordAtCursor();
                ThesaurusDialogForm tDlg = new ThesaurusDialogForm(curWord, writerView);
                tDlg.Show(parentForm);
                return true;
            }
            if (x >= 156 && x <= 224)
            {
                writerView.ShowWordCountDialog(parentForm);
                return true;
            }

            // Group 2: Ngôn ngữ
            if (x >= 238 && x <= 298)
            {
                string sel = writerView.GetSelectedText();
                if (string.IsNullOrEmpty(sel) && writerView.PieceTable != null)
                {
                    sel = writerView.PieceTable.GetText();
                }
                ZenQOffice.Core.SpeechHelper.ToggleSpeech(sel);
                return true;
            }
            if (x >= 300 && x <= 358)
            {
                ContextMenuStrip trMenu = new ContextMenuStrip();
                trMenu.Items.Add("🌐 Dịch toàn bộ tài liệu...", null, (s, e) =>
                {
                    string docT = writerView.PieceTable != null ? writerView.PieceTable.GetText() : "";
                    using (TranslationDialogForm dlg = new TranslationDialogForm(docT, writerView))
                    {
                        dlg.ShowDialog(parentForm);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                });
                trMenu.Items.Add("📝 Dịch đoạn văn bản đã chọn...", null, (s, e) =>
                {
                    string sel = writerView.GetSelectedText();
                    if (string.IsNullOrEmpty(sel) && writerView.PieceTable != null) sel = writerView.PieceTable.GetText();
                    using (TranslationDialogForm dlg = new TranslationDialogForm(sel, writerView))
                    {
                        dlg.ShowDialog(parentForm);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                });
                trMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 360 && x <= 424)
            {
                ContextMenuStrip langMenu = new ContextMenuStrip();
                langMenu.Items.Add("✓ Tiếng Việt (Việt Nam)", null, (s, e) => { });
                langMenu.Items.Add("  English (United States)", null, (s, e) => { });
                langMenu.Items.Add("  Français (France)", null, (s, e) => { });
                langMenu.Show(parentForm, x, 130);
                return true;
            }

            // Group 3: Nhận xét
            if (x >= 438 && x <= 510)
            {
                writerView.InsertNewComment();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 512 && x <= 574)
            {
                writerView.DeleteActiveComment();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 576 && x <= 656)
            {
                if (y >= 68 && y <= 96)
                {
                    writerView.NavigatePrevComment();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 98 && y <= 126)
                {
                    writerView.NavigateNextComment();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 4: Theo dõi
            if (x >= 670 && x <= 746)
            {
                writerView.TrackChanges = !writerView.TrackChanges;
                TrackChangesActive = writerView.TrackChanges;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 748 && x <= 812)
            {
                ContextMenuStrip accMenu = new ContextMenuStrip();
                accMenu.Items.Add("✔ Chấp nhận thay đổi này (Accept Change)", null, (s, e) =>
                {
                    if (writerView != null)
                    {
                        if (!writerView.AcceptCurrentChange())
                        {
                            writerView.AcceptAllTrackedChanges();
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    }
                });
                accMenu.Items.Add("✔✔ Chấp nhận TẤT CẢ thay đổi (Accept All Changes)", null, (s, e) =>
                {
                    if (writerView != null)
                    {
                        writerView.AcceptAllTrackedChanges();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                });
                accMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 814 && x <= 876)
            {
                ContextMenuStrip rejMenu = new ContextMenuStrip();
                rejMenu.Items.Add("✖ Từ chối thay đổi này (Reject Change)", null, (s, e) =>
                {
                    if (writerView != null)
                    {
                        if (!writerView.RejectCurrentChange())
                        {
                            writerView.RejectAllTrackedChanges();
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    }
                });
                rejMenu.Items.Add("✖✖ Từ chối TẤT CẢ thay đổi (Reject All Changes)", null, (s, e) =>
                {
                    if (writerView != null)
                    {
                        writerView.RejectAllTrackedChanges();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                });
                rejMenu.Show(parentForm, x, 130);
                return true;
            }

            // Group 5: Bảo vệ (Vẽ tại curX = 904, rộng 68 -> 904..972)
            if (x >= 904 && x <= 972)
            {
                writerView.IsReadOnly = !writerView.IsReadOnly;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 6: Font & Tiếng Việt (Vẽ tại curX = 988, rộng 96 -> 988..1084)
            if (x >= 988 && x <= 1084)
            {
                OpenVietnameseFontToolkit(parentForm);
                return true;
            }

            // Group 7: So sánh (Compare) (Vẽ tại curX = 1100, rộng 68 -> 1100..1168)
            if (x >= 1100 && x <= 1168)
            {
                writerView.ShowDocumentCompareDialog(parentForm);
                return true;
            }

            return false;
        }

        public void OpenVietnameseFontToolkit(Form parentForm)
        {
            string curDocPath = null;
            AppForm appForm = (parentForm as AppForm) ?? HostAppForm ?? (Parent as AppForm);
            if (appForm != null && appForm.Ribbon != null && appForm.Ribbon.ActiveDocIndex >= 0 && appForm.Ribbon.ActiveDocIndex < appForm.Ribbon.DocTabs.Count)
            {
                curDocPath = appForm.Ribbon.DocTabs[appForm.Ribbon.ActiveDocIndex].FilePath;
            }
            using (var dlg = new VietnameseFontToolkitForm(curDocPath))
            {
                dlg.ShowDialog(parentForm);
            }
            if (parentForm != null) parentForm.Invalidate();
        }

        private bool HandleTabTableDesignClick(int x, int y, WriterView writerView, Form parentForm)
        {
            if (writerView == null) return false;
            int tblIdx = writerView.ActiveTableIndex;

            // Group 1: Tùy chọn kiểu bảng
            if (x >= 14 && x <= 106)
            {
                if (y >= 70 && y <= 88)
                {
                    TableStyleHeaderRow = !TableStyleHeaderRow;
                    writerView.ApplyTableStylePreset(tblIdx, ActiveTableStylePreset);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 92 && y <= 110)
                {
                    TableStyleTotalRow = !TableStyleTotalRow;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 114 && y <= 132)
                {
                    TableStyleBandedRows = !TableStyleBandedRows;
                    writerView.ApplyTableStylePreset(tblIdx, ActiveTableStylePreset);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            if (x >= 110 && x <= 206)
            {
                if (y >= 70 && y <= 88)
                {
                    TableStyleFirstCol = !TableStyleFirstCol;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 92 && y <= 110)
                {
                    TableStyleLastCol = !TableStyleLastCol;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 114 && y <= 132)
                {
                    TableStyleBandedCols = !TableStyleBandedCols;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 2: Kiểu bảng (Presets 0..5)
            if (x >= 222 && x <= 222 + 6 * 56)
            {
                int pIdx = (x - 222) / 56;
                if (pIdx >= 0 && pIdx <= 5)
                {
                    ActiveTableStylePreset = pIdx;
                    writerView.ApplyTableStylePreset(tblIdx, pIdx);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 3: Tô màu nền
            if (x >= 570 && x <= 628)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(x, 130)) : new Point(x, 130);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (col) =>
                {
                    writerView.SetActiveTableCellColor(col);
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Group 4: Viền
            if (x >= 642 && x <= 700)
            {
                ContextMenuStrip bMenu = new ContextMenuStrip();
                bMenu.Items.Add("▦ Tất cả viền (All Borders)", null, (s, e) => { writerView.SetTableBordersVisibility(true, false, false, false); if (parentForm != null) parentForm.Invalidate(); });
                bMenu.Items.Add("▢ Không viền (No Border)", null, (s, e) => { writerView.SetTableBordersVisibility(false, true, false, false); if (parentForm != null) parentForm.Invalidate(); });
                bMenu.Items.Add("▣ Viền ngoài (Outside Borders)", null, (s, e) => { writerView.SetTableBordersVisibility(false, false, true, false); if (parentForm != null) parentForm.Invalidate(); });
                bMenu.Items.Add("⊞ Viền trong (Inside Borders)", null, (s, e) => { writerView.SetTableBordersVisibility(false, false, false, true); if (parentForm != null) parentForm.Invalidate(); });
                bMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 702 && x <= 764)
            {
                ContextMenuStrip wMenu = new ContextMenuStrip();
                wMenu.Items.Add("1/2 pt", null, (s, e) => { writerView.SetTableBordersWidth(0.5f); if (parentForm != null) parentForm.Invalidate(); });
                wMenu.Items.Add("1 pt", null, (s, e) => { writerView.SetTableBordersWidth(1.0f); if (parentForm != null) parentForm.Invalidate(); });
                wMenu.Items.Add("1 1/2 pt", null, (s, e) => { writerView.SetTableBordersWidth(1.5f); if (parentForm != null) parentForm.Invalidate(); });
                wMenu.Items.Add("2 1/4 pt", null, (s, e) => { writerView.SetTableBordersWidth(2.25f); if (parentForm != null) parentForm.Invalidate(); });
                wMenu.Items.Add("3 pt", null, (s, e) => { writerView.SetTableBordersWidth(3.0f); if (parentForm != null) parentForm.Invalidate(); });
                wMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 766 && x <= 828)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(x, 130)) : new Point(x, 130);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (col) =>
                {
                    writerView.SetTableBordersColor(col);
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            return false;
        }

        private bool HandleTabTableLayoutClick(int x, int y, WriterView writerView, Form parentForm)
        {
            if (writerView == null) return false;

            int tblIdx, rowIdx, colIdx;
            writerView.GetCursorTableCell(out tblIdx, out rowIdx, out colIdx);

            // Group 1: Bảng
            if (x >= 14 && x <= 70)
            {
                ContextMenuStrip selMenu = new ContextMenuStrip();
                selMenu.Items.Add("Chọn ô (Select Cell)", null, (s, e) => {
                    writerView.SelectTableCell(tblIdx, rowIdx, colIdx);
                    if (parentForm != null) parentForm.Invalidate();
                });
                selMenu.Items.Add("Chọn cột " + (colIdx + 1) + " (Select Column)", null, (s, e) => {
                    writerView.SelectTableColumn(tblIdx, colIdx);
                    if (parentForm != null) parentForm.Invalidate();
                });
                selMenu.Items.Add("Chọn hàng " + (rowIdx + 1) + " (Select Row)", null, (s, e) => {
                    writerView.SelectTableRow(tblIdx, rowIdx);
                    if (parentForm != null) parentForm.Invalidate();
                });
                selMenu.Items.Add(new ToolStripSeparator());
                selMenu.Items.Add("Chọn toàn bộ bảng (Select Table)", null, (s, e) => {
                    writerView.SelectEntireTable(tblIdx);
                    if (parentForm != null) parentForm.Invalidate();
                });
                selMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 72 && x <= 130)
            {
                writerView.ToggleTableGridlines();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 132 && x <= 194)
            {
                ContextMenuStrip propMenu = new ContextMenuStrip();
                ToolStripMenuItem alignItem = new ToolStripMenuItem("Canh lề bảng (Table Alignment)");
                alignItem.DropDownItems.Add("Canh lề Trái (Left)", null, (s, e) => { writerView.SetActiveTableAlignment(0); if (parentForm != null) parentForm.Invalidate(); });
                alignItem.DropDownItems.Add("Canh lề Giữa (Center)", null, (s, e) => { writerView.SetActiveTableAlignment(1); if (parentForm != null) parentForm.Invalidate(); });
                alignItem.DropDownItems.Add("Canh lề Phải (Right)", null, (s, e) => { writerView.SetActiveTableAlignment(2); if (parentForm != null) parentForm.Invalidate(); });
                propMenu.Items.Add(alignItem);

                ToolStripMenuItem fitItem = new ToolStripMenuItem("Kích thước bảng (Size)");
                fitItem.DropDownItems.Add("Tự khớp theo nội dung", null, (s, e) => { writerView.AutoFitTableToContents(); if (parentForm != null) parentForm.Invalidate(); });
                fitItem.DropDownItems.Add("Tự khớp theo trang giấy", null, (s, e) => { writerView.AutoFitTableToWindow(); if (parentForm != null) parentForm.Invalidate(); });
                fitItem.DropDownItems.Add("Chia đều độ rộng các cột", null, (s, e) => { writerView.DistributeTableColumns(); if (parentForm != null) parentForm.Invalidate(); });
                fitItem.DropDownItems.Add("Chia đều chiều cao các hàng", null, (s, e) => { writerView.DistributeTableRows(); if (parentForm != null) parentForm.Invalidate(); });
                propMenu.Items.Add(fitItem);

                ToolStripMenuItem padItem = new ToolStripMenuItem("Lề ô mặc định (Cell Margins)");
                padItem.DropDownItems.Add("Tiêu chuẩn (4 pt)", null, (s, e) => { writerView.SetTableCellMargins(0); if (parentForm != null) parentForm.Invalidate(); });
                padItem.DropDownItems.Add("Không lề (0 pt)", null, (s, e) => { writerView.SetTableCellMargins(1); if (parentForm != null) parentForm.Invalidate(); });
                padItem.DropDownItems.Add("Rộng rãi (8 pt)", null, (s, e) => { writerView.SetTableCellMargins(2); if (parentForm != null) parentForm.Invalidate(); });
                propMenu.Items.Add(padItem);

                propMenu.Items.Add(new ToolStripSeparator());
                propMenu.Items.Add("Bật/tắt đường lưới bảng", null, (s, e) => { writerView.ToggleTableGridlines(); if (parentForm != null) parentForm.Invalidate(); });
                propMenu.Items.Add("Bật/tắt lặp hàng tiêu đề (Repeat Header Row)", null, (s, e) => { writerView.ToggleRepeatHeaderRows(); if (parentForm != null) parentForm.Invalidate(); });

                propMenu.Show(parentForm, x, 130);
                return true;
            }

            // Group 2: Hàng & Cột
            if (x >= 208 && x <= 262)
            {
                ContextMenuStrip delMenu = new ContextMenuStrip();
                delMenu.Items.Add("🗑 Xóa ô hiện tại (Delete Cell Content)", null, (s, e) => { writerView.DeleteCurrentTableCell(); if (parentForm != null) parentForm.Invalidate(); });
                delMenu.Items.Add("🗑 Xóa cột " + (colIdx + 1) + " (Delete Column)", null, (s, e) => { writerView.DeleteTableColumn(tblIdx, colIdx); if (parentForm != null) parentForm.Invalidate(); });
                delMenu.Items.Add("🗑 Xóa hàng " + (rowIdx + 1) + " (Delete Row)", null, (s, e) => { writerView.DeleteTableRow(tblIdx, rowIdx); if (parentForm != null) parentForm.Invalidate(); });
                delMenu.Items.Add(new ToolStripSeparator());
                delMenu.Items.Add("❌ Xóa toàn bộ bảng (Delete Table)", null, (s, e) => { writerView.DeleteTable(tblIdx); if (parentForm != null) parentForm.Invalidate(); });
                delMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 264 && x <= 322)
            {
                writerView.InsertTableRowAbove();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 324 && x <= 382)
            {
                writerView.InsertTableRowBelow();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 384 && x <= 442)
            {
                writerView.InsertTableColumnLeft();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 444 && x <= 502)
            {
                writerView.InsertTableColumnRight();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 3: Hợp nhất
            if (x >= 516 && x <= 580)
            {
                writerView.MergeCellsAtCursor();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 582 && x <= 638)
            {
                writerView.SplitCellsAtCursor(2);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 640 && x <= 700)
            {
                writerView.SplitTableAtCursor();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 4: Kích cỡ ô
            if (x >= 714 && x <= 776)
            {
                ContextMenuStrip fitMenu = new ContextMenuStrip();
                fitMenu.Items.Add("↔ Tự khớp nội dung", null, (s, e) => { writerView.AutoFitTableToContents(); if (parentForm != null) parentForm.Invalidate(); });
                fitMenu.Items.Add("⟷ Tự khớp độ rộng cửa sổ", null, (s, e) => { writerView.AutoFitTableToWindow(); if (parentForm != null) parentForm.Invalidate(); });
                fitMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 778 && x <= 868)
            {
                if (y >= 68 && y <= 96)
                {
                    writerView.DistributeTableRows();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 98 && y <= 126)
                {
                    writerView.DistributeTableColumns();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 5: Căn chỉnh (3x3 Matrix)
            if (x >= 882 && x <= 882 + 3 * 22 && y >= 70 && y <= 128)
            {
                int c = (x - 882) / 22;
                int r = (y - 70) / 19;
                c = Math.Max(0, Math.Min(2, c));
                r = Math.Max(0, Math.Min(2, r));
                writerView.SetTableCellAlignment(c, r);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 956 && x <= 1020)
            {
                ContextMenuStrip dirMenu = new ContextMenuStrip();
                dirMenu.Items.Add("Ngang tiêu chuẩn (Horizontal)", null, (s, e) => { writerView.SetTableCellDirection(0); if (parentForm != null) parentForm.Invalidate(); });
                dirMenu.Items.Add("Xoay dọc 90° (Rotate 90°)", null, (s, e) => { writerView.SetTableCellDirection(1); if (parentForm != null) parentForm.Invalidate(); });
                dirMenu.Items.Add("Xoay dọc 270° (Rotate 270°)", null, (s, e) => { writerView.SetTableCellDirection(2); if (parentForm != null) parentForm.Invalidate(); });
                dirMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 1022 && x <= 1076)
            {
                ContextMenuStrip mMenu = new ContextMenuStrip();
                mMenu.Items.Add("Tiêu chuẩn (4 pt)", null, (s, e) => { writerView.SetTableCellMargins(0); if (parentForm != null) parentForm.Invalidate(); });
                mMenu.Items.Add("Không lề (0 pt)", null, (s, e) => { writerView.SetTableCellMargins(1); if (parentForm != null) parentForm.Invalidate(); });
                mMenu.Items.Add("Rộng rãi (8 pt)", null, (s, e) => { writerView.SetTableCellMargins(2); if (parentForm != null) parentForm.Invalidate(); });
                mMenu.Show(parentForm, x, 130);
                return true;
            }

            // Group 6: Dữ liệu
            if (x >= 1090 && x <= 1154)
            {
                writerView.ToggleRepeatHeaderRows();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 1156 && x <= 1212)
            {
                ContextMenuStrip sortMenu = new ContextMenuStrip();
                sortMenu.Items.Add("Tăng dần (A → Z)", null, (s, e) => { writerView.SortTableRows(true); if (parentForm != null) parentForm.Invalidate(); });
                sortMenu.Items.Add("Giảm dần (Z → A)", null, (s, e) => { writerView.SortTableRows(false); if (parentForm != null) parentForm.Invalidate(); });
                sortMenu.Show(parentForm, x, 130);
                return true;
            }
            if (x >= 1214 && x <= 1274)
            {
                ContextMenuStrip fxMenu = new ContextMenuStrip();
                fxMenu.Items.Add("∑ Tính tổng các số phía trên (=SUM(ABOVE))", null, (s, e) => { writerView.CalculateAndInsertFormula("SUM"); if (parentForm != null) parentForm.Invalidate(); });
                fxMenu.Items.Add("∅ Tính trung bình (=AVERAGE(ABOVE))", null, (s, e) => { writerView.CalculateAndInsertFormula("AVERAGE"); if (parentForm != null) parentForm.Invalidate(); });
                fxMenu.Items.Add("# Đếm số lượng ô (=COUNT(ABOVE))", null, (s, e) => { writerView.CalculateAndInsertFormula("COUNT"); if (parentForm != null) parentForm.Invalidate(); });
                fxMenu.Items.Add("▲ Giá trị lớn nhất (=MAX(ABOVE))", null, (s, e) => { writerView.CalculateAndInsertFormula("MAX"); if (parentForm != null) parentForm.Invalidate(); });
                fxMenu.Items.Add("▼ Giá trị nhỏ nhất (=MIN(ABOVE))", null, (s, e) => { writerView.CalculateAndInsertFormula("MIN"); if (parentForm != null) parentForm.Invalidate(); });
                fxMenu.Show(parentForm, x, 130);
                return true;
            }

            return false;
        }
        #endregion

        private void DrawToolBtn(Graphics g, int x, int y, int w, int h, string icon, string title, string groupName)
        {
            Rectangle box = new Rectangle(x, y, w, h);
            DrawInteractiveButton(g, box, false, 4);

            using (Font iconFont = new Font("Segoe UI Emoji", 14))
            using (Font txtFont = new Font("Segoe UI", 8, FontStyle.Bold))
            {
                g.DrawString(icon, iconFont, Brushes.Navy, x + (w - 20) / 2, y + 6);
                g.DrawString(title, txtFont, Brushes.Black, x + 4, y + 36);
            }
        }

        private void DrawSmallToolBtn(Graphics g, int x, int y, int w, int h, string icon, string title)
        {
            Rectangle box = new Rectangle(x, y, w, h);
            DrawInteractiveButton(g, box, false, 2);

            using (Font iconFont = new Font("Segoe UI Emoji", 10))
            using (Font txtFont = new Font("Segoe UI", 8, FontStyle.Regular))
            {
                g.DrawString(icon, iconFont, Brushes.Navy, x + 4, y + 2);
                g.DrawString(title, txtFont, Brushes.Black, x + 24, y + 4);
            }
        }

        private void DrawExcelRibbonToolbar(Graphics g, int width, CalcView calcView = null)
        {
            ExcelTableInfo activeTbl = null;
            bool insideTable = (calcView != null && calcView.IsSelectionInsideTable(out activeTbl));

            if (insideTable && ActiveRibbonTab == 7)
            {
                DrawCalcTabTableDesign(g, width, calcView, activeTbl);
                return;
            }

            switch (ActiveRibbonTab)
            {
                case 0: DrawCalcTabHome(g, width, calcView); break;
                case 1: DrawCalcTabInsert(g, width, calcView); break;
                case 2: DrawCalcTabPageLayout(g, width, calcView); break;
                case 3: DrawCalcTabFormulas(g, width, calcView); break;
                case 4: DrawCalcTabData(g, width, calcView); break;
                case 5: DrawCalcTabReview(g, width, calcView); break;
                case 6: DrawCalcTabView(g, width, calcView); break;
                case 7:
                    if (insideTable && activeTbl != null)
                        DrawCalcTabTableDesign(g, width, calcView, activeTbl);
                    else
                        DrawCalcTabHome(g, width, calcView);
                    break;
                default: DrawCalcTabHome(g, width, calcView); break;
            }
        }

        #region Calc / Excel Ribbon Tabs (Chuẩn Microsoft Excel 2016-365)
        private void DrawCalcInteractiveButton(Graphics g, Rectangle rect, bool isActive, int radius = 2)
        {
            if (!ActiveDropdownBounds.IsEmpty && ActiveDropdownBounds.IntersectsWith(rect))
            {
                isActive = true;
            }
            bool isHover = IsHovering(rect);
            if (isActive && isHover)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(210, 214, 220)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(160, 165, 175), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
            else if (isActive)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(226, 230, 236)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(180, 185, 195), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
            else if (isHover)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 242, 245)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(215, 218, 224), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
        }

        private void DrawOrientationMini(Graphics g, float x, float y)
        {
            using (Font f = new Font("Segoe UI", 6.8f, FontStyle.Bold))
            using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                g.DrawString("ab", f, Brushes.Black, x, y + 1);
                g.DrawLine(p, x + 9, y + 10, x + 14, y + 3);
                g.DrawLine(p, x + 11, y + 3, x + 14, y + 3);
                g.DrawLine(p, x + 14, y + 6, x + 14, y + 3);
            }
        }

        private void DrawCellStylesIcon(Graphics g, float x, float y)
        {
            float w = 20, h = 18;
            using (Pen pGrid = new Pen(Color.FromArgb(148, 163, 184), 1.0f) { LineJoin = LineJoin.Round })
            using (Pen pThin = new Pen(Color.FromArgb(226, 232, 240), 1.0f))
            using (SolidBrush bBlue = new SolidBrush(Color.FromArgb(59, 130, 246)))
            using (SolidBrush bSoft = new SolidBrush(Color.FromArgb(219, 234, 254)))
            {
                g.FillRectangle(Brushes.White, x, y, w, h);
                g.FillRectangle(bSoft, x + 7, y + 6, 7, 6);
                g.FillRectangle(bBlue, x + 14, y + 6, 6, 6);

                g.DrawRectangle(pGrid, x, y, w, h);
                g.DrawLine(pThin, x + 7, y, x + 7, y + h);
                g.DrawLine(pThin, x + 14, y, x + 14, y + h);
                g.DrawLine(pThin, x, y + 6, x + w, y + 6);
                g.DrawLine(pThin, x, y + 12, x + w, y + 12);
            }
        }

        private void DrawFormatCellsIcon(Graphics g, float x, float y)
        {
            float w = 20, h = 16;
            using (Pen pGrid = new Pen(Color.FromArgb(148, 163, 184), 1.0f) { LineJoin = LineJoin.Round })
            using (Pen pThin = new Pen(Color.FromArgb(226, 232, 240), 1.0f))
            using (SolidBrush bTab = new SolidBrush(Color.FromArgb(59, 130, 246)))
            {
                g.FillRectangle(Brushes.White, x, y + 2, w, h);
                g.DrawRectangle(pGrid, x, y + 2, w, h);
                g.DrawLine(pThin, x + 7, y + 2, x + 7, y + 2 + h);
                g.DrawLine(pThin, x + 14, y + 2, x + 14, y + 2 + h);
                g.DrawLine(pThin, x, y + 2 + h / 2, x + w, y + 2 + h / 2);

                // Sizing/dimension blue bar on top
                g.FillRectangle(bTab, x + 5, y, 10, 3);
            }
        }

        private void DrawEraserIconMini(Graphics g, float x, float y)
        {
            using (Pen p = new Pen(Color.FromArgb(100, 116, 139), 1.0f) { LineJoin = LineJoin.Round })
            using (SolidBrush bPurple = new SolidBrush(Color.FromArgb(192, 132, 252)))
            using (SolidBrush bWhite = new SolidBrush(Color.White))
            {
                PointF[] pTop = new PointF[] {
                    new PointF(x + 2, y + 7),
                    new PointF(x + 7, y + 1),
                    new PointF(x + 11, y + 5),
                    new PointF(x + 6, y + 11)
                };
                g.FillPolygon(bPurple, pTop);
                g.DrawPolygon(p, pTop);

                PointF[] pBtm = new PointF[] {
                    new PointF(x + 4, y + 9),
                    new PointF(x + 6, y + 11),
                    new PointF(x + 9, y + 14),
                    new PointF(x + 7, y + 12)
                };
                g.FillPolygon(bWhite, pBtm);
            }
        }

