        private void DrawDiagonalHeaderVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                g.DrawRectangle(p, x, y, w, h);
                g.DrawLine(p, x, y, x + w, y + h);
            }
            using (SolidBrush b = new SolidBrush(col))
            using (Font f = new Font("Segoe UI", 6f, FontStyle.Bold))
            {
                g.DrawString("A", f, b, x + w - 8, y + 1);
                g.DrawString("B", f, b, x + 2, y + h - 8);
            }
        }

        #region Excel Insert Tab Vector Graphics (Chuẩn Microsoft Excel 365)
        private void DrawPivotTableVector(Graphics g, int x, int y, int w, int h)
        {
            using (SolidBrush bBg = new SolidBrush(Color.White)) g.FillRectangle(bBg, x, y, w, h);
            using (SolidBrush bHdr = new SolidBrush(Color.FromArgb(220, 225, 230)))
            {
                g.FillRectangle(bHdr, x, y, w, 5);
                g.FillRectangle(bHdr, x, y, 6, h);
            }
            using (Pen p = new Pen(Color.FromArgb(90, 100, 110), 1.0f))
            {
                g.DrawRectangle(p, x, y, w, h);
                g.DrawLine(p, x, y + 5, x + w, y + 5);
                g.DrawLine(p, x + 6, y, x + 6, y + h);
            }
            // Double-headed diagonal arrow in blue
            using (Pen pArrow = new Pen(Color.FromArgb(0, 120, 212), 1.5f))
            {
                g.DrawLine(pArrow, x + 8, y + 14, x + 18, y + 7);
                g.DrawLine(pArrow, x + 14, y + 7, x + 18, y + 7);
                g.DrawLine(pArrow, x + 18, y + 11, x + 18, y + 7);
                g.DrawLine(pArrow, x + 8, y + 11, x + 8, y + 14);
                g.DrawLine(pArrow, x + 11, y + 14, x + 8, y + 14);
            }
        }

        private void DrawRecommendedPivotTablesVector(Graphics g, int x, int y, int w, int h)
        {
            DrawPivotTableVector(g, x, y, w, h);
            using (Font qf = new Font("Segoe UI", 9f, FontStyle.Bold))
            using (SolidBrush qb = new SolidBrush(Color.FromArgb(0, 120, 212)))
            {
                g.DrawString("?", qf, qb, x + 13, y + 6);
            }
        }

        private void DrawExcelTableVector(Graphics g, int x, int y, int w, int h)
        {
            using (SolidBrush bBg = new SolidBrush(Color.White)) g.FillRectangle(bBg, x, y, w, h);
            // Blue header row
            using (SolidBrush bHdr = new SolidBrush(Color.FromArgb(31, 78, 120)))
            {
                g.FillRectangle(bHdr, x, y, w, 6);
            }
            // Alternating light blue rows
            using (SolidBrush bAlt = new SolidBrush(Color.FromArgb(222, 235, 247)))
            {
                g.FillRectangle(bAlt, x, y + 6, w, 5);
                g.FillRectangle(bAlt, x, y + 16, w, 4);
            }
            using (Pen p = new Pen(Color.FromArgb(176, 196, 222), 1.0f))
            {
                using (Pen pBorder = new Pen(Color.FromArgb(31, 78, 120), 1.2f))
                {
                    g.DrawRectangle(pBorder, x, y, w, h);
                }
                g.DrawLine(p, x + w / 3, y + 6, x + w / 3, y + h);
                g.DrawLine(p, x + (w * 2) / 3, y + 6, x + (w * 2) / 3, y + h);
                g.DrawLine(p, x, y + 11, x + w, y + 11);
                g.DrawLine(p, x, y + 16, x + w, y + 16);
            }
            // Dots in header row
            using (SolidBrush wDot = new SolidBrush(Color.White))
            {
                g.FillEllipse(wDot, x + 3, y + 2, 2, 2);
                g.FillEllipse(wDot, x + w / 3 + 3, y + 2, 2, 2);
                g.FillEllipse(wDot, x + (w * 2) / 3 + 3, y + 2, 2, 2);
            }
        }

        private void DrawIllustrationsVector(Graphics g, int x, int y, int w, int h)
        {
            // Blue rectangle
            using (SolidBrush bRect = new SolidBrush(Color.FromArgb(0, 120, 212)))
