                g.FillRectangle(bRect, x, y, 14, 14);
            }
            using (Pen p = new Pen(Color.FromArgb(16, 110, 190), 1.0f))
            {
                g.DrawRectangle(p, x, y, 14, 14);
            }
            // White/gray circle overlapping
            using (SolidBrush bCirc = new SolidBrush(Color.FromArgb(243, 244, 246)))
            {
                g.FillEllipse(bCirc, x + 7, y + 6, 13, 13);
            }
            using (Pen pCirc = new Pen(Color.FromArgb(90, 100, 110), 1.2f))
            {
                g.DrawEllipse(pCirc, x + 7, y + 6, 13, 13);
            }
        }

