        private void DrawMiniChartBtn(Graphics g, int x, int y, int chartType)
        {
            Rectangle r = new Rectangle(x, y, 25, 23);
            DrawInteractiveButton(g, r, false, 3);
            using (Pen p = new Pen(Color.FromArgb(0, 120, 212), 1.2f))
            {
                switch (chartType)
                {
                    case 0: // Column
                        using (SolidBrush b1 = new SolidBrush(Color.FromArgb(100, 160, 220))) g.FillRectangle(b1, x + 3, y + 8, 3, 10);
                        using (SolidBrush b2 = new SolidBrush(Color.FromArgb(0, 120, 212))) g.FillRectangle(b2, x + 7, y + 3, 3, 15);
                        using (SolidBrush b3 = new SolidBrush(Color.FromArgb(200, 205, 212))) g.FillRectangle(b3, x + 11, y + 11, 3, 7);
                        break;
                    case 1: // Hierarchy / Treemap
                        g.DrawRectangle(p, x + 3, y + 4, 12, 14);
                        g.DrawLine(p, x + 9, y + 4, x + 9, y + 18);
                        g.DrawLine(p, x + 3, y + 10, x + 9, y + 10);
                        break;
                    case 2: // Waterfall
                        using (SolidBrush bg = new SolidBrush(Color.FromArgb(16, 124, 65))) g.FillRectangle(bg, x + 3, y + 4, 3, 6);
                        using (SolidBrush br = new SolidBrush(Color.FromArgb(216, 59, 1))) g.FillRectangle(br, x + 7, y + 8, 3, 5);
                        using (SolidBrush bb = new SolidBrush(Color.FromArgb(0, 120, 212))) g.FillRectangle(bb, x + 11, y + 6, 3, 12);
                        break;
                    case 3: // Line
                        g.DrawLine(p, x + 3, y + 14, x + 7, y + 7);
                        g.DrawLine(p, x + 7, y + 7, x + 11, y + 11);
                        g.DrawLine(p, x + 11, y + 11, x + 15, y + 4);
                        g.FillEllipse(Brushes.Navy, x + 6, y + 6, 2, 2);
                        g.FillEllipse(Brushes.Navy, x + 10, y + 10, 2, 2);
                        break;
                    case 4: // Statistic / Histogram
                        using (SolidBrush b1 = new SolidBrush(Color.FromArgb(0, 120, 212)))
                        {
                            g.FillRectangle(b1, x + 3, y + 10, 2, 8);
                            g.FillRectangle(b1, x + 6, y + 5, 3, 13);
                            g.FillRectangle(b1, x + 10, y + 7, 3, 11);
                            g.FillRectangle(b1, x + 14, y + 12, 2, 6);
                        }
                        break;
                    case 5: // Combo
                        using (SolidBrush b1 = new SolidBrush(Color.FromArgb(100, 160, 220)))
                        {
                            g.FillRectangle(b1, x + 3, y + 9, 3, 9);
                            g.FillRectangle(b1, x + 8, y + 4, 3, 14);
                        }
                        using (Pen pLine = new Pen(Color.FromArgb(234, 88, 12), 1.4f))
                        {
                            g.DrawLine(pLine, x + 3, y + 15, x + 9, y + 7);
                            g.DrawLine(pLine, x + 9, y + 7, x + 15, y + 10);
                        }
                        break;
                    case 6: // Pie
                        using (SolidBrush b1 = new SolidBrush(Color.FromArgb(0, 120, 212))) g.FillPie(b1, x + 2, y + 3, 14, 14, 0, 240);
                        using (SolidBrush b2 = new SolidBrush(Color.FromArgb(242, 153, 0))) g.FillPie(b2, x + 2, y + 3, 14, 14, 240, 120);
                        break;
                    case 7: // Scatter
                        using (Pen pAx = new Pen(Color.Gray, 1.0f))
                        {
                            g.DrawLine(pAx, x + 3, y + 4, x + 3, y + 17);
                            g.DrawLine(pAx, x + 3, y + 17, x + 16, y + 17);
                        }
                        g.FillEllipse(Brushes.Navy, x + 5, y + 12, 2, 2);
                        g.FillEllipse(Brushes.Navy, x + 8, y + 8, 2, 2);
                        g.FillEllipse(Brushes.Navy, x + 12, y + 6, 2, 2);
                        g.FillEllipse(Brushes.Navy, x + 14, y + 13, 2, 2);
                        break;
                }
            }
            DrawMiniArrowDown(g, x + 20, y + 11, Color.FromArgb(90, 100, 110));
        }

