        private void DrawSymbolsOmegaVector(Graphics g, int x, int y, int size)
        {
            using (Font f = new Font("Segoe UI", 12.5f, FontStyle.Bold))
            using (SolidBrush b = new SolidBrush(Color.FromArgb(32, 31, 30)))
            {
