        private void DrawPhotoAlbumVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                g.DrawRectangle(p, x + 3, y, w - 3, h - 3);
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(254, 243, 199))) g.FillRectangle(sb, x, y + 3, w - 3, h - 3);
                g.DrawRectangle(p, x, y + 3, w - 3, h - 3);
                g.DrawLine(p, x + 3, y + 6, x + 3, y + h - 3);
            }
