        private void DrawIconsVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            using (SolidBrush b = new SolidBrush(col))
            {
                PointF[] pts = new PointF[] {
                    new PointF(x + w * 0.5f, y + 1),
                    new PointF(x + w * 0.62f, y + h * 0.35f),
                    new PointF(x + w - 1, y + h * 0.4f),
                    new PointF(x + w * 0.7f, y + h * 0.65f),
                    new PointF(x + w * 0.8f, y + h - 1),
                    new PointF(x + w * 0.5f, y + h * 0.8f),
                    new PointF(x + w * 0.2f, y + h - 1),
                    new PointF(x + w * 0.3f, y + h * 0.65f),
                    new PointF(x + 1, y + h * 0.4f),
                    new PointF(x + w * 0.38f, y + h * 0.35f)
                };
                g.FillPolygon(b, pts);
            }
        }

        private void Draw3DModelVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            {
                int cx = x + w / 2;
                int cy = y + h / 2;
                Point[] topPts = new Point[] { new Point(cx, y + 1), new Point(x + w - 2, y + h / 3), new Point(cx, cy), new Point(x + 2, y + h / 3) };
                g.DrawPolygon(p, topPts);
                g.DrawLine(p, cx, cy, cx, y + h - 1);
                g.DrawLine(p, x + 2, y + h / 3, x + 2, y + h * 2 / 3);
                g.DrawLine(p, x + w - 2, y + h / 3, x + w - 2, y + h * 2 / 3);
                g.DrawLine(p, x + 2, y + h * 2 / 3, cx, y + h - 1);
                g.DrawLine(p, x + w - 2, y + h * 2 / 3, cx, y + h - 1);
            }
        }

        private void DrawSmartArtVector(Graphics g, int x, int y, int w, int h)
        {
            using (SolidBrush b1 = new SolidBrush(Color.FromArgb(37, 99, 235)))
            using (SolidBrush b2 = new SolidBrush(Color.FromArgb(234, 88, 12)))
            using (SolidBrush b3 = new SolidBrush(Color.FromArgb(16, 124, 65)))
            using (Pen p = new Pen(Color.FromArgb(100, 110, 120), 1f))
            {
                g.FillRectangle(b1, x, y + 2, 7, 7);
                g.DrawRectangle(p, x, y + 2, 7, 7);
                g.FillRectangle(b2, x + 8, y + 7, 7, 7);
                g.DrawRectangle(p, x + 8, y + 7, 7, 7);
                g.FillRectangle(b3, x + 16, y + 12, 7, 7);
                g.DrawRectangle(p, x + 16, y + 12, 7, 7);
                using (Pen ap = new Pen(Color.FromArgb(70, 80, 90), 1.2f))
                {
                    g.DrawLine(ap, x + 7, y + 5, x + 8, y + 9);
                    g.DrawLine(ap, x + 15, y + 10, x + 16, y + 14);
                }
            }
        }

        private void DrawChartVector(Graphics g, int x, int y, int w, int h)
        {
            using (Pen axisP = new Pen(Color.FromArgb(100, 116, 139), 1.2f))
            using (SolidBrush b1 = new SolidBrush(Color.FromArgb(239, 68, 68)))
            using (SolidBrush b2 = new SolidBrush(Color.FromArgb(59, 130, 246)))
            using (SolidBrush b3 = new SolidBrush(Color.FromArgb(16, 185, 129)))
            {
                g.DrawLine(axisP, x + 1, y + h - 2, x + w - 1, y + h - 2);
                g.DrawLine(axisP, x + 1, y + 2, x + 1, y + h - 2);
                g.FillRectangle(b1, x + 4, y + h - 10, 4, 8);
                g.FillRectangle(b2, x + 10, y + h - 16, 4, 14);
                g.FillRectangle(b3, x + 16, y + h - 12, 4, 10);
            }
        }

        private void DrawCommentVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            using (SolidBrush bg = new SolidBrush(Color.FromArgb(240, 253, 250)))
            {
                GraphicsPath path = new GraphicsPath();
                path.AddLine(x + 2, y + 2, x + w - 2, y + 2);
                path.AddLine(x + w - 2, y + 2, x + w - 2, y + h - 7);
                path.AddLine(x + w - 2, y + h - 7, x + 10, y + h - 7);
                path.AddLine(x + 10, y + h - 7, x + 4, y + h - 1);
                path.AddLine(x + 4, y + h - 1, x + 6, y + h - 7);
                path.AddLine(x + 6, y + h - 7, x + 2, y + h - 7);
                path.CloseFigure();
                g.FillPath(bg, path);
                g.DrawPath(p, path);
                g.DrawLine(p, x + 5, y + 5, x + w - 5, y + 5);
                g.DrawLine(p, x + 5, y + 8, x + w - 8, y + 8);
            }
        }

        private void DrawTextBoxVector(Graphics g, int x, int y, int w, int h, Color col)
