        private void DrawVideoVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            using (SolidBrush b = new SolidBrush(col))
            {
                g.DrawRectangle(p, x + 1, y + 3, w - 2, h - 6);
