        private void DrawAudioVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            using (SolidBrush b = new SolidBrush(col))
            {
                Point[] spk = new Point[] {
                    new Point(x + 3, y + h / 2 - 3),
                    new Point(x + 7, y + h / 2 - 3),
                    new Point(x + 12, y + 3),
                    new Point(x + 12, y + h - 3),
                    new Point(x + 7, y + h / 2 + 3),
                    new Point(x + 3, y + h / 2 + 3)
                };
                g.FillPolygon(b, spk);
                g.DrawArc(p, x + 12, y + 4, 6, h - 8, -60, 120);
                g.DrawArc(p, x + 14, y + 1, 9, h - 2, -60, 120);
            }
        }

        private void DrawScreenRecordVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            using (SolidBrush rb = new SolidBrush(Color.FromArgb(239, 68, 68)))
            {
                g.DrawRectangle(p, x + 1, y + 2, w - 8, h - 4);
                Point[] cam = new Point[] {
                    new Point(x + w - 6, y + h / 2),
                    new Point(x + w - 1, y + 4),
                    new Point(x + w - 1, y + h - 4)
                };
                using (SolidBrush b = new SolidBrush(col)) g.FillPolygon(b, cam);
                g.FillEllipse(rb, x + 4, y + 5, 6, 6);
            }
        }
