        private void DrawInsertVectorIcon(Graphics g, int x, int y, int idx, Color col)
        {
            using (Pen p = new Pen(col, 1.5f))
            using (SolidBrush b = new SolidBrush(col))
            using (SolidBrush bg = new SolidBrush(Color.FromArgb(35, col)))
            {
                switch (idx)
                {
                    case 0: // Slide Mới
                        g.FillRectangle(bg, x + 2, y + 2, 20, 16);
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        DrawPlusVector(g, x + 12, y + 10, 10, Color.FromArgb(210, 71, 38));
                        break;
                    case 1: // Bảng biểu
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        g.DrawLine(p, x + 2, y + 7, x + 22, y + 7);
                        g.DrawLine(p, x + 2, y + 12, x + 22, y + 12);
                        g.DrawLine(p, x + 8, y + 2, x + 8, y + 18);
                        g.DrawLine(p, x + 15, y + 2, x + 15, y + 18);
                        break;
                    case 2: // Hình ảnh
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        g.FillEllipse(b, x + 6, y + 5, 4, 4);
                        Point[] mtn = new Point[] {
                            new Point(x + 3, y + 17),
                            new Point(x + 10, y + 9),
                            new Point(x + 15, y + 14),
                            new Point(x + 18, y + 11),
                            new Point(x + 21, y + 17)
                        };
                        g.DrawLines(p, mtn);
                        break;
                    case 3: // Hình vẽ
                        g.DrawRectangle(p, x + 3, y + 3, 10, 10);
                        g.DrawEllipse(p, x + 9, y + 7, 12, 12);
                        break;
                    case 4: // Hộp chữ
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        using (Font f = new Font("Segoe UI", 8.5f, FontStyle.Bold))
                        {
                            g.DrawString("A", f, b, x + 6, y + 1);
                        }
                        break;
                    case 5: // WordArt
                        using (Font f = new Font("Georgia", 11f, FontStyle.Bold | FontStyle.Italic))
                        {
                            g.DrawString("A", f, Brushes.DarkOrange, x + 6, y + 1);
                        }
                        break;
                    case 6: // Biểu đồ
                        g.FillRectangle(b, x + 4, y + 10, 4, 8);
                        g.FillRectangle(b, x + 10, y + 5, 4, 13);
                        g.FillRectangle(b, x + 16, y + 2, 4, 16);
                        break;
                    case 7: // SmartArt
                        g.DrawRectangle(p, x + 2, y + 3, 5, 14);
                        g.DrawRectangle(p, x + 9, y + 3, 5, 14);
                        g.DrawRectangle(p, x + 16, y + 3, 5, 14);
                        g.DrawLine(p, x + 7, y + 10, x + 9, y + 10);
                        g.DrawLine(p, x + 14, y + 10, x + 16, y + 10);
                        break;
                    case 8: // Liên kết
                        g.DrawArc(p, x + 3, y + 6, 10, 8, 90, 180);
                        g.DrawArc(p, x + 11, y + 6, 10, 8, 270, 180);
                        g.DrawLine(p, x + 8, y + 10, x + 16, y + 10);
                        break;
                    case 9: // Bình luận
                        g.DrawRectangle(p, x + 3, y + 3, 18, 11);
                        Point[] tail = new Point[] { new Point(x + 6, y + 14), new Point(x + 6, y + 18), new Point(x + 11, y + 14) };
                        g.FillPolygon(b, tail);
                        g.DrawLine(p, x + 6, y + 7, x + 18, y + 7);
                        g.DrawLine(p, x + 6, y + 10, x + 14, y + 10);
                        break;
                    case 10: // Công thức
                        using (Font f = new Font("Cambria Math", 11f, FontStyle.Bold))
                        {
                            g.DrawString("π", f, b, x + 6, y + 1);
                        }
                        break;
                    case 11: // Ký hiệu
                        using (Font f = new Font("Segoe UI", 11f, FontStyle.Bold))
                        {
                            g.DrawString("Ω", f, b, x + 5, y + 1);
                        }
                        break;
                    case 12: // Video
                        g.DrawRectangle(p, x + 2, y + 3, 20, 14);
                        Point[] vplay = new Point[] { new Point(x + 9, y + 6), new Point(x + 15, y + 10), new Point(x + 9, y + 14) };
                        g.FillPolygon(b, vplay);
                        break;
                    case 13: // Âm thanh
                        g.FillRectangle(b, x + 4, y + 7, 4, 6);
                        Point[] spk = new Point[] { new Point(x + 8, y + 7), new Point(x + 13, y + 3), new Point(x + 13, y + 17), new Point(x + 8, y + 13) };
                        g.FillPolygon(b, spk);
                        g.DrawArc(p, x + 14, y + 5, 5, 10, -60, 120);
                        g.DrawArc(p, x + 16, y + 2, 7, 16, -60, 120);
                        break;
                }
            }
        }

        private void DrawEditShapeIconVector(Graphics g, int x, int y, int w, int h, Color color)
        {
            using (Pen p = new Pen(color, 1.2f) { DashStyle = DashStyle.Dash })
            {
                PointF[] pts = new PointF[] {
                    new PointF(x + 2, y + 4),
                    new PointF(x + w - 3, y + 3),
                    new PointF(x + w - 2, y + h - 3),
                    new PointF(x + 3, y + h - 4)
                };
                g.DrawPolygon(p, pts);

                using (SolidBrush b = new SolidBrush(Color.FromArgb(37, 99, 235)))
                using (Pen bp = new Pen(Color.White, 0.8f))
                {
                    float s = 3.5f;
                    foreach (var pt in pts)
                    {
                        RectangleF rf = new RectangleF(pt.X - s / 2f, pt.Y - s / 2f, s, s);
                        g.FillRectangle(b, rf);
                        g.DrawRectangle(bp, rf.X, rf.Y, rf.Width, rf.Height);
                    }
                }
            }
        }

        private void DrawMergeShapesIconVector(Graphics g, int x, int y, int w, int h, Color color)
        {
            using (SolidBrush b = new SolidBrush(Color.FromArgb(160, color)))
            using (Pen p = new Pen(color, 1.2f))
            {
                float r = w * 0.58f;
                g.FillEllipse(b, x, y, r, r);
                g.DrawEllipse(p, x, y, r, r);

                g.FillEllipse(b, x + w - r, y + h - r, r, r);
                g.DrawEllipse(p, x + w - r, y + h - r, r, r);
            }
        }

        public static Image CreateMergeIcon(MergeShapeOperation op)
        {
            Bitmap bmp = new Bitmap(24, 24);
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.Clear(Color.Transparent);

                using (SolidBrush fillB = new SolidBrush(Color.FromArgb(148, 163, 184)))
                using (Pen strokeP = new Pen(Color.FromArgb(71, 85, 105), 1.2f))
                {
                    RectangleF r1 = new RectangleF(3, 3, 11, 11);
                    RectangleF r2 = new RectangleF(9, 9, 11, 11);

                    switch (op)
                    {
                        case MergeShapeOperation.Union:
                            using (GraphicsPath p = new GraphicsPath())
                            {
                                p.FillMode = FillMode.Winding;
                                p.AddEllipse(r1);
                                p.AddEllipse(r2);
                                g.FillPath(fillB, p);
                                g.DrawPath(strokeP, p);
                            }
                            break;
                        case MergeShapeOperation.Combine:
                            using (GraphicsPath p = new GraphicsPath())
                            {
                                p.FillMode = FillMode.Alternate;
                                p.AddEllipse(r1);
                                p.AddEllipse(r2);
                                g.FillPath(fillB, p);
                                g.DrawPath(strokeP, p);
                            }
                            break;
                        case MergeShapeOperation.Fragment:
                            using (GraphicsPath p1 = new GraphicsPath())
                            {
                                p1.AddEllipse(new RectangleF(2, 2, 10, 10));
                                using (Region reg1 = new Region(p1))
                                {
                                    GraphicsPath pOther = new GraphicsPath();
                                    pOther.AddEllipse(new RectangleF(9, 9, 10, 10));
                                    reg1.Exclude(pOther);
                                    g.FillRegion(fillB, reg1);
                                    g.DrawPath(strokeP, p1);
                                }
                            }
                            using (GraphicsPath p2 = new GraphicsPath())
                            {
                                p2.AddEllipse(new RectangleF(11, 11, 10, 10));
                                using (Region reg2 = new Region(p2))
                                {
                                    GraphicsPath pOther2 = new GraphicsPath();
                                    pOther2.AddEllipse(new RectangleF(2, 2, 10, 10));
                                    reg2.Exclude(pOther2);
                                    g.FillRegion(fillB, reg2);
                                    g.DrawPath(strokeP, p2);
                                }
                            }
                            using (GraphicsPath pCenter1 = new GraphicsPath())
                            {
                                pCenter1.AddEllipse(new RectangleF(2, 2, 10, 10));
                                using (Region regC = new Region(pCenter1))
                                {
                                    GraphicsPath pOther3 = new GraphicsPath();
                                    pOther3.AddEllipse(new RectangleF(11, 11, 10, 10));
                                    regC.Intersect(pOther3);
                                    g.FillRegion(fillB, regC);
                                }
                            }
                            break;
                        case MergeShapeOperation.Intersect:
                            using (GraphicsPath p1 = new GraphicsPath())
                            {
                                p1.AddEllipse(r1);
                                using (Region reg = new Region(p1))
                                {
                                    GraphicsPath p2 = new GraphicsPath();
                                    p2.AddEllipse(r2);
                                    reg.Intersect(p2);
                                    g.FillRegion(fillB, reg);
                                }
                                g.DrawEllipse(strokeP, r1);
                                g.DrawEllipse(strokeP, r2);
                            }
                            break;
                        case MergeShapeOperation.Subtract:
                            using (GraphicsPath p1 = new GraphicsPath())
                            {
                                p1.AddEllipse(r1);
                                using (Region reg = new Region(p1))
                                {
                                    GraphicsPath p2 = new GraphicsPath();
                                    p2.AddEllipse(r2);
                                    reg.Exclude(p2);
                                    g.FillRegion(fillB, reg);
                                }
                                g.DrawEllipse(strokeP, r1);
                                g.DrawEllipse(new Pen(Color.FromArgb(180, 180, 180), 1.0f) { DashStyle = DashStyle.Dot }, r2);
                            }
                            break;
                    }
                }
            }
            return bmp;
        }

        private void DrawArrangeIconVector(Graphics g, int x, int y, int w, int h)
        {
            WpfSlideIconRenderer.DrawIconCentered(g, SlideIconKind.Arrange, new Rectangle(x, y, w, h), Math.Min(w, 24), Math.Min(h, 24));
        }

        private static ShapeType ParseShapeTypeForSlides(string s)
        {
            if (string.IsNullOrEmpty(s)) return ShapeType.Rectangle;
            string key = s.Trim().ToLowerInvariant().Replace(" ", "").Replace("_", "").Replace("-", "");

            switch (key)
            {
                case "textbox": return ShapeType.TextBox;
                case "freeformshape": case "freeformscribble": case "scribble": case "freeform": case "custompath": case "curvescribble": case "vekhungtudoo": return ShapeType.CustomPath;
                case "line": case "arrowline": case "doublearrowline": case "elbowconnector": case "elbowarrowconnector": case "curvedconnector": return ShapeType.Line;
                case "rectangle": case "rect": case "flowchartprocess": case "flowchartalternateprocess": case "flowchartpredefinedprocess": case "flowchartinternalstorage": return ShapeType.Rectangle;
                case "roundedrectangle": case "roundrect": case "singlecornersnipped": case "topcornerssnipped": case "snippedandrounded":
                case "roundsinglecorner": case "roundsamesidecorner": case "rounddiagonalcorner": case "snipsamesidecorner": case "flowchartterminator": return ShapeType.RoundedRectangle;
                case "oval": case "circle": case "flowchartconnector": case "flowchartoffpageconnector": return ShapeType.Ellipse;
                case "triangle": return ShapeType.Triangle;
                case "righttriangle": return ShapeType.RightTriangle;
                case "parallelogram": case "flowchartdata": return ShapeType.Parallelogram;
                case "trapezoid": case "flowchartmanualoperation": return ShapeType.Trapezoid;
                case "diamond": case "rhombus": case "flowchartdecision": return ShapeType.Diamond;
                case "pentagon": return ShapeType.Pentagon;
                case "hexagon": case "flowchartpreparation": return ShapeType.Hexagon;
                case "octagon": return ShapeType.Octagon;
                case "decagon": return ShapeType.Octagon;
                case "cross": case "plus": return ShapeType.Cross;
                case "cylinder": case "can": return ShapeType.Can;
                case "cube": return ShapeType.Cube;
                case "donut": return ShapeType.Donut;
                case "smileface": case "smiley": return ShapeType.Smiley;
                case "heart": return ShapeType.Heart;
                case "lightning": return ShapeType.Lightning;
                case "sun": return ShapeType.Sun;
                case "moon": return ShapeType.Moon;
                case "cloud": case "calloutcloud": return ShapeType.Cloud;
                case "rightarrow": case "blockarrowright": case "arrow": return ShapeType.BlockArrowRight;
                case "leftarrow": case "blockarrowleft": return ShapeType.BlockArrowLeft;
                case "uparrow": case "blockarrowup": return ShapeType.BlockArrowUp;
                case "downarrow": case "blockarrowdown": return ShapeType.BlockArrowDown;
                case "chevron": return ShapeType.Chevron;
                case "leftrightarrow": case "updownarrow": case "quadarrow": case "bentarrow": case "uturnarrow": return ShapeType.BlockArrowRight;
                case "star": case "star4": case "star5": case "star6": case "star8": case "star10": case "star12": case "star16": case "star24": case "star32": return ShapeType.Star;
                case "explosion1": case "explosion2": return ShapeType.Starburst;
                case "banner": case "horizontalscroll": case "verticalscroll": return ShapeType.Banner;
                case "callout": case "calloutrect": case "calloutroundedrect": case "calloutoval": return ShapeType.Callout;
                case "shield": return ShapeType.Shield;
                case "leaf": return ShapeType.Leaf;
                case "clover": return ShapeType.Clover;
                case "flower": return ShapeType.Flower;
                case "sprout": return ShapeType.Sprout;
                case "gem": return ShapeType.Gem;
                case "arch": case "arc": return ShapeType.Arch;
                default: return ShapeType.Rectangle;
            }
        }

        private void ShowArrangeMenu(Form parentForm, Point screenPos, SlidesView slidesView)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.Font = new Font("Segoe UI", 9f);
            menu.ShowImageMargin = true;

            // 1. Order Objects (Thứ tự Đối tượng)
            ToolStripMenuItem miOrderHeader = new ToolStripMenuItem("Thứ tự Đối tượng (Order Objects)");
            miOrderHeader.Enabled = false;
            miOrderHeader.Font = new Font("Segoe UI", 8.5f, FontStyle.Bold);
            menu.Items.Add(miOrderHeader);

            ToolStripMenuItem miFront = new ToolStripMenuItem("Đưa lên trên cùng (Bring to Front)", SlidesView.CreateBringFrontIcon(), (s, e) => {
                slidesView.BringShapeToFront();
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miBack = new ToolStripMenuItem("Đưa về sau cùng (Send to Back)", SlidesView.CreateSendBackIcon(), (s, e) => {
                slidesView.SendShapeToBack();
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miForward = new ToolStripMenuItem("Lên trên một lớp (Bring Forward)", null, (s, e) => {
                slidesView.BringShapeForward();
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miBackward = new ToolStripMenuItem("Xuống dưới một lớp (Send Backward)", null, (s, e) => {
                slidesView.SendShapeBackward();
                if (parentForm != null) parentForm.Invalidate();
            });

            menu.Items.AddRange(new ToolStripItem[] { miFront, miBack, miForward, miBackward, new ToolStripSeparator() });

            // 2. Group Objects (Nhóm Đối tượng)
            ToolStripMenuItem miGroupHeader = new ToolStripMenuItem("Nhóm Đối tượng (Group Objects)");
            miGroupHeader.Enabled = false;
            miGroupHeader.Font = new Font("Segoe UI", 8.5f, FontStyle.Bold);
            menu.Items.Add(miGroupHeader);

            ToolStripMenuItem miGroup = new ToolStripMenuItem("Nhóm (Group)", SlidesView.CreateGroupIcon(), (s, e) => {
                slidesView.MergeShapes(MergeShapeOperation.Union);
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miUngroup = new ToolStripMenuItem("Rã nhóm (Ungroup)", null, (s, e) => {
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miRegroup = new ToolStripMenuItem("Gom nhóm lại (Regroup)", null, (s, e) => {
                if (parentForm != null) parentForm.Invalidate();
            });

            menu.Items.AddRange(new ToolStripItem[] { miGroup, miUngroup, miRegroup, new ToolStripSeparator() });

            // 3. Position Objects (Định vị Đối tượng)
            ToolStripMenuItem miPosHeader = new ToolStripMenuItem("Định vị Đối tượng (Position Objects)");
            miPosHeader.Enabled = false;
            miPosHeader.Font = new Font("Segoe UI", 8.5f, FontStyle.Bold);
            menu.Items.Add(miPosHeader);

            // Align Submenu
            ToolStripMenuItem miAlign = new ToolStripMenuItem("Căn chỉnh (Align)");
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Trái (Align Left)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Left); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Giữa ngang (Align Center)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Center); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Phải (Align Right)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Right); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Trên (Align Top)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Top); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Giữa dọc (Align Middle)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Middle); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Dưới (Align Bottom)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Bottom); if (parentForm != null) parentForm.Invalidate(); }));
            menu.Items.Add(miAlign);

            // Rotate Submenu
            ToolStripMenuItem miRotate = new ToolStripMenuItem("Xoay (Rotate)");
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Xoay Phải 90°", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.Rotation += 90f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Xoay Trái 90°", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.Rotation -= 90f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Lật Ngang (Flip Horizontal)", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.FlipHorizontal = !slidesView.SelectedShape.Transform.FlipHorizontal;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Lật Dọc (Flip Vertical)", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.FlipVertical = !slidesView.SelectedShape.Transform.FlipVertical;
                if (parentForm != null) parentForm.Invalidate();
            }));
            menu.Items.Add(miRotate);

            // Opacity Submenu
            ToolStripMenuItem miOpacity = new ToolStripMenuItem("Làm mờ / Độ trong suốt (Opacity)");
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("100% Đặc (Opaque)", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 1.0f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("80% Hơi mờ", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.8f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("60% Bán trong suốt", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.6f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("40% Mờ (Translucent)", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.4f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("20% Rất mờ", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.2f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("0% Trong suốt (Transparent)", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.0f; if (parentForm != null) parentForm.Invalidate(); }));
            menu.Items.Add(miOpacity);

            menu.Items.Add(new ToolStripSeparator());

            // 4. Selection Pane (Ngăn Lựa chọn...)
            ToolStripMenuItem miSelectionPane = new ToolStripMenuItem("Ngăn Lựa chọn (Selection Pane)...", SlidesView.CreateSelectionPaneIcon(), (s, e) => {
                slidesView.SidebarPanel = SidebarPanelType.SelectionPane;
                slidesView.IsSidebarOpen = true;
                if (parentForm != null) parentForm.Invalidate();
            });
            menu.Items.Add(miSelectionPane);

            menu.Show(parentForm != null ? parentForm.PointToScreen(screenPos) : screenPos);
        }

        private void DrawPowerPointTabHome(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font miniFont = new Font("Segoe UI", 7.2f, FontStyle.Regular))
            using (Font tinyFont = new Font("Segoe UI", 6.5f, FontStyle.Regular))
            using (SolidBrush darkBrush = new SolidBrush(Color.FromArgb(31, 41, 55)))
            {
                g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
                Color neutralIcon = Color.FromArgb(55, 65, 81);
                Color pptAccent = Color.FromArgb(210, 71, 38);
                bool hasSelection = (slidesView != null && slidesView.SelectedShape != null);
                Color disabledCol = Color.FromArgb(160, 165, 175);
                using (SolidBrush disabledBrush = new SolidBrush(disabledCol))
                {
                    // ==================== Group 1: Clipboard (Bảng tạm) (X: 14 to 204) ====================
                    Rectangle pasteBox = new Rectangle(14, 68, 52, 62);
                    DrawInteractiveButton(g, pasteBox, false, 4);
                    WpfSlideIconRenderer.DrawIconCentered(g, SlideIconKind.Paste, new Rectangle(14, 70, 52, 34), 30, neutralIcon, pptAccent);
                    g.DrawString("Dán ▾", btnFont, darkBrush, 22, 107);

                    Rectangle cutBox = new Rectangle(72, 68, 128, 20);
                    if (hasSelection) DrawInteractiveButton(g, cutBox, false, 3);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.Cut, 76, 70, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Cắt", btnFont, hasSelection ? darkBrush : disabledBrush, 98, 70);

                    Rectangle copyBox = new Rectangle(72, 89, 128, 20);
                    if (hasSelection) DrawInteractiveButton(g, copyBox, false, 3);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.Copy, 76, 91, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Chép", btnFont, hasSelection ? darkBrush : disabledBrush, 98, 91);

                    Rectangle fmtBox = new Rectangle(72, 110, 128, 20);
                    if (hasSelection) DrawInteractiveButton(g, fmtBox, false, 3);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.FormatPainter, 76, 112, 16, 16, hasSelection ? neutralIcon : disabledCol, hasSelection ? pptAccent : disabledCol);
                    g.DrawString("Chổi", btnFont, hasSelection ? darkBrush : disabledBrush, 98, 112);

                    g.DrawString("Bảng tạm", labelFont, Brushes.Gray, 72, 137);
                    BtnSlidesClipboardLauncherBounds = new Rectangle(188, 134, 14, 14);
                    DrawInteractiveButton(g, BtnSlidesClipboardLauncherBounds, false, 2);
                    DrawDialogLauncherIcon(g, BtnSlidesClipboardLauncherBounds.X + 3, BtnSlidesClipboardLauncherBounds.Y + 3);
                    g.DrawLine(Pens.LightGray, 206, 68, 206, 148);

                    // ==================== Group 2: Slides (X: 212 to 374) ====================
                    Rectangle newSlideBox = new Rectangle(212, 68, 64, 62);
                    DrawInteractiveButton(g, newSlideBox, false, 4);
                    DrawNewSlideCardVector(g, 212, 68, 64, 34);
                    g.DrawString("Slide Mới", boldFont, darkBrush, 217, 107);

                    Rectangle layoutBox = new Rectangle(280, 68, 92, 20);
                    DrawInteractiveButton(g, layoutBox, false, 3);
                    DrawSlideLayoutVector(g, 283, 72, 14, 12, neutralIcon);
                    g.DrawString("Bố cục ▾", btnFont, darkBrush, 302, 70);

                    Rectangle resetBox = new Rectangle(280, 89, 92, 20);
                    DrawInteractiveButton(g, resetBox, false, 3);
                    DrawResetVector(g, 289, 98, 5, neutralIcon);
                    g.DrawString("Đặt lại", btnFont, darkBrush, 302, 90);

                    Rectangle dupBox = new Rectangle(280, 110, 92, 20);
                    DrawInteractiveButton(g, dupBox, false, 3);
                    DrawDuplicateVector(g, 284, 114, 13, 11, neutralIcon);
                    g.DrawString("Nhân bản", btnFont, darkBrush, 302, 110);

                    g.DrawString("Trang chiếu", labelFont, Brushes.Gray, 260, 137);
                    g.DrawLine(Pens.LightGray, 378, 68, 378, 148);

                    // ==================== Group 3: Font (X: 384 to 640) ====================
                    string currFont = hasSelection ? slidesView.SelectedShape.FontName : SelectedFont;
                    float currSize = hasSelection ? slidesView.SelectedShape.FontSize : FontSize;

                    Rectangle fontCombo = new Rectangle(384, 68, 120, 24);
                    g.FillRectangle(hasSelection ? Brushes.White : Brushes.WhiteSmoke, fontCombo);
                    using (Pen pBorder = new Pen(Color.FromArgb(203, 213, 225), 1f)) g.DrawRectangle(pBorder, fontCombo);
                    if (hasSelection) DrawInteractiveButton(g, fontCombo, false, 3);
                    g.DrawString(currFont.Length > 13 ? (currFont.Substring(0, 12) + "…") : currFont, btnFont, hasSelection ? darkBrush : disabledBrush, 388, 71);
                    DrawDropdownChevron(g, 488, 78, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    Rectangle sizeCombo = new Rectangle(508, 68, 44, 24);
                    g.FillRectangle(hasSelection ? Brushes.White : Brushes.WhiteSmoke, sizeCombo);
                    using (Pen pBorder = new Pen(Color.FromArgb(203, 213, 225), 1f)) g.DrawRectangle(pBorder, sizeCombo);
                    if (hasSelection) DrawInteractiveButton(g, sizeCombo, false, 3);
                    g.DrawString(currSize.ToString("0"), btnFont, hasSelection ? darkBrush : disabledBrush, 512, 71);
                    DrawDropdownChevron(g, 536, 78, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    Rectangle aIncBox = new Rectangle(556, 68, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, aIncBox, false, 2);
                    DrawLucideAIncrease(g, 557, 70, hasSelection ? neutralIcon : disabledCol);

                    Rectangle aDecBox = new Rectangle(582, 68, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, aDecBox, false, 2);
                    DrawLucideADecrease(g, 583, 70, hasSelection ? neutralIcon : disabledCol);

                    Rectangle clearFmtBox = new Rectangle(608, 68, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, clearFmtBox, false, 2);
                    DrawLucideClearFormatting(g, 609, 70);

                    // Font style buttons row 2 (Y: 96) - Authentic Office 365 Typography Toolbar
                    bool isB = hasSelection ? slidesView.SelectedShape.Bold : IsBold;
                    bool isI = hasSelection ? slidesView.SelectedShape.Italic : IsItalic;
                    bool isU = hasSelection ? slidesView.SelectedShape.Underline : IsUnderline;
                    bool isS = hasSelection ? slidesView.SelectedShape.HasTextShadow : false;
                    bool isStrike = hasSelection ? slidesView.SelectedShape.Strikethrough : false;

                    // Force crisp text rendering for small font icons
                    var prevHint = g.TextRenderingHint;
                    g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

                    // 1. Bold (B) — Segoe UI 10.5pt Bold, absolute positioned
                    Rectangle bBox = new Rectangle(384, 96, 22, 24);
                    if (hasSelection) DrawInteractiveButton(g, bBox, isB, 2);
                    Color bCol = !hasSelection ? disabledCol : (isB ? pptAccent : neutralIcon);
                    using (Font fBold = new Font("Segoe UI", 10.5f, FontStyle.Bold))
                    using (SolidBrush brB = new SolidBrush(bCol))
                    {
                        g.DrawString("B", fBold, brB, bBox.X + 3.5f, bBox.Y + 2f);
                    }

                    // 2. Italic (I) — Georgia 11pt Italic (exact Office 365 serif I with horizontal bars)
                    Rectangle iBox = new Rectangle(407, 96, 22, 24);
                    if (hasSelection) DrawInteractiveButton(g, iBox, isI, 2);
                    Color iCol = !hasSelection ? disabledCol : (isI ? pptAccent : neutralIcon);
                    using (Font fItalic = new Font("Georgia", 11.0f, FontStyle.Italic))
                    using (SolidBrush brI = new SolidBrush(iCol))
                    {
                        g.DrawString("I", fItalic, brI, iBox.X + 5f, iBox.Y + 1.5f);
                    }

                    // 3. Underline (U) — Segoe UI 10.5pt + thin underline bar
                    Rectangle uBox = new Rectangle(430, 96, 22, 24);
                    if (hasSelection) DrawInteractiveButton(g, uBox, isU, 2);
                    Color uCol = !hasSelection ? disabledCol : (isU ? pptAccent : neutralIcon);
                    using (Font fU = new Font("Segoe UI", 10.5f, FontStyle.Regular))
                    using (SolidBrush brU = new SolidBrush(uCol))
                    using (Pen penU = new Pen(uCol, 1.1f))
                    {
                        g.DrawString("U", fU, brU, uBox.X + 4f, uBox.Y + 1f);
                        g.DrawLine(penU, uBox.X + 4f, uBox.Y + 18f, uBox.X + 16f, uBox.Y + 18f);
                    }

                    // 4. Text Shadow (S) — "S" with subtle shadow offset
                    Rectangle sBox = new Rectangle(453, 96, 22, 24);
                    if (hasSelection) DrawInteractiveButton(g, sBox, isS, 2);
                    Color sCol = !hasSelection ? disabledCol : (isS ? pptAccent : neutralIcon);
                    using (Font fS = new Font("Segoe UI", 11.0f, FontStyle.Regular))
                    using (SolidBrush brShadow = new SolidBrush(!hasSelection ? Color.FromArgb(30, 140, 150, 160) : Color.FromArgb(80, 130, 140, 150)))
                    using (SolidBrush brS = new SolidBrush(sCol))
                    {
                        g.DrawString("S", fS, brShadow, sBox.X + 4.5f, sBox.Y + 3f);
                        g.DrawString("S", fS, brS, sBox.X + 3.5f, sBox.Y + 2f);
                    }

                    // 5. Strikethrough (ab) — "ab" with horizontal line through
                    Rectangle strikeBox = new Rectangle(476, 96, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, strikeBox, isStrike, 2);
                    Color strikeCol = !hasSelection ? disabledCol : (isStrike ? pptAccent : neutralIcon);
                    using (Font fAb = new Font("Segoe UI", 9.0f, FontStyle.Regular))
                    using (SolidBrush brAb = new SolidBrush(strikeCol))
                    using (Pen penStrike = new Pen(strikeCol, 1.0f))
                    {
                        g.DrawString("ab", fAb, brAb, strikeBox.X + 2f, strikeBox.Y + 3f);
                        float strikeY = strikeBox.Y + 11.5f;
                        g.DrawLine(penStrike, strikeBox.X + 2f, strikeY, strikeBox.X + 20f, strikeY);
                    }

                    // 6. Character Spacing (AV ▾)
                    Rectangle spacingBox = new Rectangle(501, 96, 29, 24);
                    if (hasSelection) DrawInteractiveButton(g, spacingBox, false, 2);
                    DrawFluentCharacterSpacing(g, spacingBox.X, spacingBox.Y, hasSelection ? neutralIcon : disabledCol, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    // 7. Change Case (Aa ▾)
                    Rectangle caseBox = new Rectangle(531, 96, 28, 24);
                    if (hasSelection) DrawInteractiveButton(g, caseBox, false, 2);
                    DrawFluentChangeCase(g, caseBox.X, caseBox.Y, hasSelection ? neutralIcon : disabledCol, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    // 8. Vertical Divider
                    using (Pen dividerPen = new Pen(Color.FromArgb(226, 232, 240), 1f))
                    {
                        g.DrawLine(dividerPen, 563, 100, 563, 116);
                    }

                    // 9. Highlighter ▾
                    Rectangle highlightBox = new Rectangle(568, 96, 33, 24);
                    if (hasSelection) DrawInteractiveButton(g, highlightBox, false, 2);
                    Color hlColor = (hasSelection && slidesView.SelectedShape.HasHighlight && slidesView.SelectedShape.HighlightColor != 0)
                        ? Color.FromArgb(slidesView.SelectedShape.HighlightColor)
                        : Color.FromArgb(255, 235, 59);
                    DrawFluentHighlighter(g, highlightBox.X, highlightBox.Y, hasSelection ? neutralIcon : disabledCol, hasSelection ? hlColor : disabledCol, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    // 10. Font Color (A ▾)
                    Rectangle fontColorBox = new Rectangle(603, 96, 33, 24);
                    if (hasSelection) DrawInteractiveButton(g, fontColorBox, false, 2);
                    int curTc = hasSelection ? slidesView.SelectedShape.TextColor : 0;
                    Color curCol = (curTc != 0) ? Color.FromArgb((curTc >> 16) & 0xFF, (curTc >> 8) & 0xFF, curTc & 0xFF) : pptAccent;
                    DrawFluentFontColor(g, fontColorBox.X, fontColorBox.Y, hasSelection ? neutralIcon : disabledCol, hasSelection ? curCol : disabledCol, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    g.TextRenderingHint = prevHint;

                    g.DrawString("Phông chữ", labelFont, Brushes.Gray, 480, 137);
                    BtnSlidesFontLauncherBounds = new Rectangle(626, 134, 14, 14);
                    DrawInteractiveButton(g, BtnSlidesFontLauncherBounds, false, 2);
                    DrawDialogLauncherIcon(g, BtnSlidesFontLauncherBounds.X + 3, BtnSlidesFontLauncherBounds.Y + 3);
                    g.DrawLine(Pens.LightGray, 644, 68, 644, 148);

                    // ==================== Group 4: Paragraph (X: 648 to 914) ====================
                    TextAlignment currAlign = hasSelection ? slidesView.SelectedShape.Alignment : TextAlignment.Left;

                    // Subgrid 1 (Left 5 cols x 2 rows):
                    // Row 1: Bullets ▾, Numbering ▾, | , Dec Indent, Inc Indent, | , Line Spacing ▾
                    Rectangle bulletsBox = new Rectangle(648, 68, 32, 24);
                    if (hasSelection) DrawInteractiveButton(g, bulletsBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.Bullets, 650, 72, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    DrawDropdownChevron(g, 669, 78, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    Rectangle numBox = new Rectangle(682, 68, 32, 24);
                    if (hasSelection) DrawInteractiveButton(g, numBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.Numbering, 684, 72, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    DrawDropdownChevron(g, 703, 78, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    using (Pen dividerPen = new Pen(Color.FromArgb(226, 232, 240), 1f))
                    {
                        g.DrawLine(dividerPen, 717, 72, 717, 88);
                    }

                    Rectangle decIndentBox = new Rectangle(720, 68, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, decIndentBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.IndentDecrease, 724, 72, 16, 16, hasSelection ? neutralIcon : disabledCol);

                    Rectangle incIndentBox = new Rectangle(746, 68, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, incIndentBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.IndentIncrease, 750, 72, 16, 16, hasSelection ? neutralIcon : disabledCol);

                    using (Pen dividerPen = new Pen(Color.FromArgb(226, 232, 240), 1f))
                    {
                        g.DrawLine(dividerPen, 773, 72, 773, 88);
                    }

                    Rectangle lineSpacingBox = new Rectangle(776, 68, 30, 24);
                    if (hasSelection) DrawInteractiveButton(g, lineSpacingBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.LineSpacing, 778, 72, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    DrawDropdownChevron(g, 796, 78, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    // Row 2: Align Left, Align Center, Align Right, Justify, | , Columns ▾
                    Rectangle leftAlign = new Rectangle(648, 96, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, leftAlign, currAlign == TextAlignment.Left, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.AlignLeft, 652, 100, 16, 16, !hasSelection ? disabledCol : ((currAlign == TextAlignment.Left) ? pptAccent : neutralIcon));

                    Rectangle centerAlign = new Rectangle(674, 96, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, centerAlign, currAlign == TextAlignment.Center, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.AlignCenter, 678, 100, 16, 16, !hasSelection ? disabledCol : ((currAlign == TextAlignment.Center) ? pptAccent : neutralIcon));

                    Rectangle rightAlign = new Rectangle(700, 96, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, rightAlign, currAlign == TextAlignment.Right, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.AlignRight, 704, 100, 16, 16, !hasSelection ? disabledCol : ((currAlign == TextAlignment.Right) ? pptAccent : neutralIcon));

                    Rectangle justifyAlign = new Rectangle(726, 96, 24, 24);
                    if (hasSelection) DrawInteractiveButton(g, justifyAlign, currAlign == TextAlignment.Justify, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.AlignJustify, 730, 100, 16, 16, !hasSelection ? disabledCol : ((currAlign == TextAlignment.Justify) ? pptAccent : neutralIcon));

                    using (Pen dividerPen = new Pen(Color.FromArgb(226, 232, 240), 1f))
                    {
                        g.DrawLine(dividerPen, 753, 100, 753, 116);
                    }

                    Rectangle columnsBox = new Rectangle(756, 96, 30, 24);
                    if (hasSelection) DrawInteractiveButton(g, columnsBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.Columns, 758, 100, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    DrawDropdownChevron(g, 776, 106, hasSelection ? Color.FromArgb(100, 116, 139) : disabledCol);

                    // Subgrid 2 (Right 3 stacked rows): Text Direction, Align Text, Convert to SmartArt
                    Rectangle textDirBox = new Rectangle(810, 68, 104, 20);
                    if (hasSelection) DrawInteractiveButton(g, textDirBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.TextDirection, 812, 70, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Hướng chữ ▾", tinyFont, hasSelection ? darkBrush : disabledBrush, 830, 71);

                    Rectangle alignTextVertBox = new Rectangle(810, 89, 104, 20);
                    if (hasSelection) DrawInteractiveButton(g, alignTextVertBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.AlignTextVertical, 812, 91, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Căn văn bản ▾", tinyFont, hasSelection ? darkBrush : disabledBrush, 830, 92);

                    Rectangle convertSmartArtBox = new Rectangle(810, 110, 104, 20);
                    if (hasSelection) DrawInteractiveButton(g, convertSmartArtBox, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.ConvertSmartArt, 812, 112, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Sang SmartArt ▾", tinyFont, hasSelection ? darkBrush : disabledBrush, 830, 113);

                    g.DrawString("Đoạn", labelFont, Brushes.Gray, 760, 137);
                    BtnSlidesParaLauncherBounds = new Rectangle(900, 134, 14, 14);
                    DrawInteractiveButton(g, BtnSlidesParaLauncherBounds, false, 2);
                    DrawDialogLauncherIcon(g, BtnSlidesParaLauncherBounds.X + 3, BtnSlidesParaLauncherBounds.Y + 3);
                    g.DrawLine(Pens.LightGray, 918, 68, 918, 148);

                    // ==================== Group 5: Drawing (X: 922 to 1256) ====================
                    ShapeType[][] allShapeRows = new ShapeType[][] {
                        new ShapeType[] { ShapeType.TextBox, ShapeType.Line, ShapeType.Arrow, ShapeType.CustomPath, ShapeType.Rectangle, ShapeType.Ellipse },
                        new ShapeType[] { ShapeType.RoundedRectangle, ShapeType.Triangle, ShapeType.Diamond, ShapeType.RightTriangle, ShapeType.BlockArrowRight, ShapeType.Callout },
                        new ShapeType[] { ShapeType.Lightning, ShapeType.Heart, ShapeType.Star, ShapeType.Cloud, ShapeType.Sun, ShapeType.Moon },
                        new ShapeType[] { ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.Chevron, ShapeType.Cube, ShapeType.Can, ShapeType.Donut },
                        new ShapeType[] { ShapeType.Hexagon, ShapeType.Octagon, ShapeType.Pentagon, ShapeType.Cross, ShapeType.Shield, ShapeType.Banner },
                        new ShapeType[] { ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Smiley, ShapeType.Starburst, ShapeType.Arch, ShapeType.Flower }
                    };
                    int sRow = Math.Max(0, Math.Min(allShapeRows.Length - 3, slidesView.ShapeGalleryScrollRow));
                    Rectangle shapesGalleryRect = new Rectangle(922, 68, 136, 56);

                    using (SolidBrush whiteB = new SolidBrush(Color.White))
                    using (Pen borderPen = new Pen(Color.FromArgb(218, 220, 224), 1.0f))
                    {
                        g.FillRectangle(whiteB, shapesGalleryRect);
                        g.DrawRectangle(borderPen, shapesGalleryRect);

                        for (int r = 0; r < 3; r++)
                        {
                            ShapeType[] rowShapes = allShapeRows[sRow + r];
                            int cellY = (r == 0 ? 68 : (r == 1 ? 86 : 104));
                            int cellH = (r == 2 ? 20 : 18);

                            for (int s = 0; s < rowShapes.Length; s++)
                            {
                                Rectangle sRect = new Rectangle(922 + s * 20, cellY, 20, cellH);
                                bool isShapeActive = (slidesView != null && slidesView.IsDrawingShapeMode && slidesView.PendingShapeType == rowShapes[s]);
                                bool isShapeHover = IsHovering(sRect);

                                if (isShapeActive)
                                {
                                    using (SolidBrush selBg = new SolidBrush(Color.FromArgb(232, 240, 254)))
                                    using (Pen selPen = new Pen(Color.FromArgb(0, 120, 215), 1.0f))
                                    {
                                        Rectangle selR = new Rectangle(sRect.X + 1, sRect.Y + 1, sRect.Width - 2, sRect.Height - 2);
                                        g.FillRectangle(selBg, selR);
                                        g.DrawRectangle(selPen, selR);
                                    }
                                }
                                else if (isShapeHover)
                                {
                                    using (SolidBrush hovBg = new SolidBrush(Color.FromArgb(243, 246, 251)))
                                    using (Pen hovPen = new Pen(Color.FromArgb(209, 213, 219), 1.0f))
                                    {
                                        Rectangle hovR = new Rectangle(sRect.X + 1, sRect.Y + 1, sRect.Width - 2, sRect.Height - 2);
                                        g.FillRectangle(hovBg, hovR);
                                        g.DrawRectangle(hovPen, hovR);
                                    }
                                }

                                DrawShapeIconVector(g, sRect.X + 2, sRect.Y + 2, sRect.Width - 4, sRect.Height - 4, rowShapes[s], neutralIcon, isShapeActive);
                            }
                        }

                        // 3-Button Stack for Shapes Gallery (X: 1042, Y: 68, W: 16, H: 56)
                        bool canScrollUp = (sRow > 0);
                        bool canScrollDown = (sRow < allShapeRows.Length - 3);
                        DrawGalleryScrollButtons(g, 1042, 68, 16, 56, canScrollUp, canScrollDown, true);
                    }

                    // Arrange Button (X: 1062, Y: 68, W: 46, H: 54)
                    Rectangle btnArrange = new Rectangle(1062, 68, 46, 54);
                    if (hasSelection) DrawInteractiveButton(g, btnArrange, false, 3);
                    WpfSlideIconRenderer.DrawIconCentered(g, SlideIconKind.Arrange, new Rectangle(1062, 69, 46, 26), 26, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Sắp xếp ▾", labelFont, hasSelection ? darkBrush : disabledBrush, 1064, 98);

                    // Quick Styles Button (X: 1110, Y: 68, W: 46, H: 54)
                    Rectangle btnQuickStyles = new Rectangle(1110, 68, 46, 54);
                    if (hasSelection) DrawInteractiveButton(g, btnQuickStyles, false, 3);
                    WpfSlideIconRenderer.DrawIconCentered(g, SlideIconKind.QuickStyles, new Rectangle(1110, 69, 46, 26), 26, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Kiểu ▾", labelFont, hasSelection ? darkBrush : disabledBrush, 1118, 98);

                    // Format buttons 3-stack (Tô màu, Viền hình, Hiệu ứng) (X: 1158 to 1252, W: 94)
                    int curFill = hasSelection ? slidesView.SelectedShape.FillColor : 0;
                    Color fillSwatch = (curFill != 0) ? Color.FromArgb((curFill >> 16) & 0xFF, (curFill >> 8) & 0xFF, curFill & 0xFF) : Color.FromArgb(0, 120, 212);
                    int curBdr = hasSelection ? slidesView.SelectedShape.StrokeColor : 0;
                    Color bdrSwatch = (curBdr != 0) ? Color.FromArgb((curBdr >> 16) & 0xFF, (curBdr >> 8) & 0xFF, curBdr & 0xFF) : Color.FromArgb(71, 85, 105);

                    Rectangle btnFill = new Rectangle(1158, 68, 94, 20);
                    if (hasSelection) DrawInteractiveButton(g, btnFill, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.ShapeFill, 1160, 70, 16, 16, hasSelection ? neutralIcon : disabledCol, hasSelection ? fillSwatch : disabledCol);
                    g.DrawString("Tô màu ▾", miniFont, hasSelection ? darkBrush : disabledBrush, 1180, 71);

                    Rectangle btnLine = new Rectangle(1158, 89, 94, 20);
                    if (hasSelection) DrawInteractiveButton(g, btnLine, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.ShapeOutline, 1160, 91, 16, 16, hasSelection ? neutralIcon : disabledCol, hasSelection ? bdrSwatch : disabledCol);
                    g.DrawString("Viền hình ▾", miniFont, hasSelection ? darkBrush : disabledBrush, 1180, 92);

                    Rectangle btnEffects = new Rectangle(1158, 110, 94, 20);
                    if (hasSelection) DrawInteractiveButton(g, btnEffects, false, 2);
                    WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.ShapeEffects, 1160, 112, 16, 16, hasSelection ? neutralIcon : disabledCol);
                    g.DrawString("Hiệu ứng ▾", miniFont, hasSelection ? darkBrush : disabledBrush, 1180, 113);

                    g.DrawString("Vẽ", labelFont, Brushes.Gray, 1085, 137);
                    BtnSlidesDrawingLauncherBounds = new Rectangle(1238, 134, 14, 14);
                    DrawInteractiveButton(g, BtnSlidesDrawingLauncherBounds, false, 2);
                    DrawDialogLauncherIcon(g, BtnSlidesDrawingLauncherBounds.X + 3, BtnSlidesDrawingLauncherBounds.Y + 3);
                    g.DrawLine(Pens.LightGray, 1256, 68, 1256, 148);

                    // ==================== Group 6: Fullscreen Presentation (X: 1262 to 1340) ====================
                    Rectangle btnF5 = new Rectangle(1262, 68, 76, 62);
                    DrawInteractiveButton(g, btnF5, false, 4);
                    WpfSlideIconRenderer.DrawIconCentered(g, SlideIconKind.SlideShowFromBeginning, new Rectangle(1262, 72, 76, 24), 26, neutralIcon);
                    g.DrawString("Trình chiếu", boldFont, darkBrush, 1266, 98);
                    g.DrawString("(Từ đầu F5)", labelFont, Brushes.Gray, 1269, 112);

                    g.DrawString("Trình chiếu", labelFont, Brushes.Gray, 1276, 137);
                    g.DrawLine(Pens.LightGray, 1344, 68, 1344, 148);
                }
            }
        }

