        private void DrawPptUploadVector(Graphics g, int x, int y, int w, int h)
        {
            int cx = x + w / 2;
            int cy = y + h / 2;
            using (Pen pCloud = new Pen(Color.FromArgb(2, 132, 199), 1.5f))
            using (Pen pArrow = new Pen(Color.FromArgb(2, 132, 199), 1.8f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                g.DrawArc(pCloud, cx - 10, cy - 4, 8, 8, 140, 180);
                g.DrawArc(pCloud, cx - 5, cy - 8, 10, 10, 180, 180);
                g.DrawArc(pCloud, cx + 2, cy - 4, 8, 8, 220, 180);
                g.DrawLine(pCloud, cx - 9, cy + 4, cx + 9, cy + 4);
                g.DrawLine(pArrow, cx, cy + 6, cx, cy - 1);
                g.DrawLine(pArrow, cx - 3, cy + 2, cx, cy - 1);
                g.DrawLine(pArrow, cx + 3, cy + 2, cx, cy - 1);
            }
        }

