            using (Pen pBrush = new Pen(Color.FromArgb(13, 148, 136), 1.8f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                g.DrawLine(pPen, cx - 8, cy + 8, cx + 8, cy - 8);
                g.DrawLine(pPen, cx + 6, cy - 9, cx + 9, cy - 6);
                g.DrawLine(pBrush, cx + 8, cy + 8, cx - 8, cy - 8);
