        private void DrawPowerPointTabPictureFormat(Graphics g, int width, SlidesView slidesView)
        {
            if (slidesView == null || slidesView.SelectedShape == null) return;
            ShapeNode shape = slidesView.SelectedShape;

            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.2f, FontStyle.Bold))
            using (Font valFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            {
                int curX = 14;

                // ==================== Group 1: Điều chỉnh (Adjust) ====================
                // 1. Xóa nền (Remove Background - Chuyển sang Tab Loại bỏ nền)
                Rectangle rmBgBtn = new Rectangle(curX, 68, 68, 54);
                DrawInteractiveButton(g, rmBgBtn, false, 4);
                DrawRemoveBgVector(g, rmBgBtn.X + 22, rmBgBtn.Y + 6, 24, 24);
                g.DrawString("Xóa nền", boldFont, Brushes.Black, rmBgBtn.X + 11, rmBgBtn.Y + 34);
                curX += 72;

                // 2. Chỉnh sửa ▾ (Corrections ▾)
                Rectangle corrBtn = new Rectangle(curX, 68, 72, 54);
                DrawInteractiveButton(g, corrBtn, false, 4);
                DrawSunVector(g, corrBtn.X + 36, corrBtn.Y + 18, 22, Color.FromArgb(234, 88, 12));
                g.DrawString("Chỉnh sửa ▾", btnFont, Brushes.Black, corrBtn.X + 4, corrBtn.Y + 34);
                curX += 76;

                // 3. Mini Stack Column 1: Màu sắc ▾, Hiệu ứng vẽ ▾, Trong suốt ▾
                Rectangle colBtn = new Rectangle(curX, 68, 110, 24);
                DrawInteractiveButton(g, colBtn, false, 3);
                DrawPaletteVector(g, colBtn.X + 6, colBtn.Y + 5, 14, 14, Color.FromArgb(37, 99, 235));
                g.DrawString("Màu sắc ▾", btnFont, Brushes.Black, colBtn.X + 24, colBtn.Y + 3);

                Rectangle artBtn = new Rectangle(curX, 94, 110, 24);
                DrawInteractiveButton(g, artBtn, false, 3);
                DrawArtisticWandVector(g, artBtn.X + 6, artBtn.Y + 5, 14, 14, Color.FromArgb(147, 51, 234));
                g.DrawString("Hiệu ứng vẽ ▾", btnFont, Brushes.Black, artBtn.X + 24, artBtn.Y + 3);

                Rectangle transBtn = new Rectangle(curX, 120, 110, 24);
                DrawInteractiveButton(g, transBtn, false, 3);
                DrawTransparencyGridVector(g, transBtn.X + 6, transBtn.Y + 5, 14, 14);
                g.DrawString("Trong suốt ▾", btnFont, Brushes.Black, transBtn.X + 24, transBtn.Y + 3);
                curX += 114;

                // 6. Mini Stack Column 2: Nén ảnh, Đổi ảnh ▾, Đặt lại ảnh ▾
                Rectangle compBtn = new Rectangle(curX, 68, 108, 24);
                DrawInteractiveButton(g, compBtn, false, 3);
                DrawCompressVector(g, compBtn.X + 6, compBtn.Y + 5, 14, 14, Color.FromArgb(16, 185, 129));
                g.DrawString("Nén ảnh", btnFont, Brushes.Black, compBtn.X + 24, compBtn.Y + 3);

                Rectangle chgBtn = new Rectangle(curX, 94, 108, 24);
                DrawInteractiveButton(g, chgBtn, false, 3);
                DrawChangePicVector(g, chgBtn.X + 6, chgBtn.Y + 5, 14, 14, Color.FromArgb(217, 119, 6));
                g.DrawString("Đổi ảnh ▾", btnFont, Brushes.Black, chgBtn.X + 24, chgBtn.Y + 3);

                Rectangle rstBtn = new Rectangle(curX, 120, 108, 24);
                DrawInteractiveButton(g, rstBtn, false, 3);
                DrawResetVector(g, rstBtn.X + 10, rstBtn.Y + 12, 5, Color.FromArgb(239, 68, 68));
                g.DrawString("Đặt lại ảnh ▾", btnFont, Brushes.Black, rstBtn.X + 24, rstBtn.Y + 3);
                curX += 112;

                g.DrawString("Điều chỉnh", labelFont, Brushes.Gray, 12 + (curX - 12 - 60) / 2, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 2: Kiểu Hình ảnh (Picture Styles) ====================
                int fW = 32;
                for (int pIdx = 1; pIdx <= 7; pIdx++)
                {
                    Rectangle fBox = new Rectangle(curX + (pIdx - 1) * (fW + 3), 68, fW, 53);
                    DrawInteractiveButton(g, fBox, shape.PictureStyleIndex == pIdx, 4);
                    DrawPictureStyleThumbnail(g, fBox, pIdx, shape.CachedImage);
                }
                curX += 7 * (fW + 3) + 4;

                // Stack: Viền ảnh ▾, Hiệu ứng ảnh ▾, Bố cục ảnh ▾
                Rectangle pBorderBtn = new Rectangle(curX, 68, 110, 24);
                DrawInteractiveButton(g, pBorderBtn, false, 3);
                DrawBorderVector(g, pBorderBtn.X + 6, pBorderBtn.Y + 5, 14, 14, Color.FromArgb(37, 99, 235));
                g.DrawString("Viền ảnh ▾", btnFont, Brushes.Black, pBorderBtn.X + 24, pBorderBtn.Y + 3);

                Rectangle pFxBtn = new Rectangle(curX, 94, 110, 24);
                DrawInteractiveButton(g, pFxBtn, false, 3);
                DrawStarVector(g, pFxBtn.X + 11, pFxBtn.Y + 12, 4, Color.FromArgb(245, 158, 11));
                g.DrawString("Hiệu ứng ▾", btnFont, Brushes.Black, pFxBtn.X + 24, pFxBtn.Y + 3);

                Rectangle pLayoutBtn = new Rectangle(curX, 120, 110, 24);
                DrawInteractiveButton(g, pLayoutBtn, false, 3);
                DrawLayoutGridVector(g, pLayoutBtn.X + 6, pLayoutBtn.Y + 5, 14, 14, Color.FromArgb(16, 185, 129));
                g.DrawString("Bố cục ảnh ▾", btnFont, Brushes.Black, pLayoutBtn.X + 24, pLayoutBtn.Y + 3);
                curX += 116;

                g.DrawString("Kiểu Hình ảnh", labelFont, Brushes.Gray, curX - 220, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 3: Khả năng truy cập (Accessibility) ====================
                Rectangle altBtn = new Rectangle(curX, 68, 68, 54);
                DrawInteractiveButton(g, altBtn, false, 4);
                DrawAltTextVector(g, altBtn.X + 22, altBtn.Y + 6, 24, 24);
                g.DrawString("Văn bản Alt", btnFont, Brushes.Black, altBtn.X + 4, altBtn.Y + 34);
                curX += 74;

                g.DrawString("Truy cập", labelFont, Brushes.Gray, curX - 60, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 4: Sắp xếp (Arrange) ====================
                Rectangle bFwdBtn = new Rectangle(curX, 68, 88, 24);
                DrawInteractiveButton(g, bFwdBtn, false, 3);
                WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.BringForward, bFwdBtn.X + 4, bFwdBtn.Y + 4, 16, 16, Color.FromArgb(55, 65, 81), Color.FromArgb(16, 185, 129));
                g.DrawString("Lên trước", btnFont, Brushes.Black, bFwdBtn.X + 22, bFwdBtn.Y + 3);

                Rectangle sBwdBtn = new Rectangle(curX, 94, 88, 24);
                DrawInteractiveButton(g, sBwdBtn, false, 3);
                WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.SendBackward, sBwdBtn.X + 4, sBwdBtn.Y + 4, 16, 16, Color.FromArgb(55, 65, 81), Color.FromArgb(239, 68, 68));
                g.DrawString("Ra sau", btnFont, Brushes.Black, sBwdBtn.X + 22, sBwdBtn.Y + 3);

                Rectangle alignBtn = new Rectangle(curX, 120, 88, 24);
                DrawInteractiveButton(g, alignBtn, false, 3);
                WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.AlignObjects, alignBtn.X + 4, alignBtn.Y + 4, 16, 16, Color.FromArgb(55, 65, 81), Color.FromArgb(37, 99, 235));
                g.DrawString("Căn chỉnh ▾", btnFont, Brushes.Black, alignBtn.X + 18, alignBtn.Y + 3);
                curX += 92;

                Rectangle rotBtn = new Rectangle(curX, 68, 84, 24);
                DrawInteractiveButton(g, rotBtn, false, 3);
                WpfSlideIconRenderer.DrawIcon(g, SlideIconKind.ResetSlide, rotBtn.X + 4, rotBtn.Y + 4, 16, 16, Color.FromArgb(217, 119, 6));
                g.DrawString("Xoay 90°", btnFont, Brushes.Black, rotBtn.X + 18, rotBtn.Y + 3);

                Rectangle flipHBtn = new Rectangle(curX, 94, 84, 24);
                DrawInteractiveButton(g, flipHBtn, false, 3);
                g.DrawString("⇄", boldFont, Brushes.DarkBlue, flipHBtn.X + 4, flipHBtn.Y + 2);
                g.DrawString("Lật ngang", btnFont, Brushes.Black, flipHBtn.X + 20, flipHBtn.Y + 3);

                Rectangle flipVBtn = new Rectangle(curX, 120, 84, 24);
                DrawInteractiveButton(g, flipVBtn, false, 3);
                g.DrawString("⇅", boldFont, Brushes.DarkBlue, flipVBtn.X + 4, flipVBtn.Y + 2);
                g.DrawString("Lật dọc", btnFont, Brushes.Black, flipVBtn.X + 20, flipVBtn.Y + 3);
                curX += 88;

                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 5: Kích thước & Cắt ảnh (Size & Crop) ====================
                bool isCroppingActive = (slidesView != null && slidesView.IsCropping);
                Rectangle cropTopBtn = new Rectangle(curX, 68, 62, 38);
                Rectangle cropArrowBtn = new Rectangle(curX, 106, 62, 16);
                Rectangle fullCropBtn = new Rectangle(curX, 68, 62, 54);

                DrawInteractiveButton(g, fullCropBtn, isCroppingActive, 4);
                DrawCropVector(g, cropTopBtn.X + 31, cropTopBtn.Y + 16, 20, isCroppingActive ? Color.FromArgb(218, 59, 1) : Color.FromArgb(15, 23, 42));
                g.DrawString("Cắt ảnh", btnFont, isCroppingActive ? Brushes.DarkRed : Brushes.Black, cropTopBtn.X + 11, cropTopBtn.Y + 23);
                
                // Divider line & dropdown arrow
                g.DrawLine(Pens.LightGray, curX + 6, 105, curX + 56, 105);
                g.DrawString("▾", boldFont, Brushes.DimGray, cropArrowBtn.X + 26, cropArrowBtn.Y - 1);
                curX += 68;

                // Height Spin Box
                Rectangle hLabel = new Rectangle(curX, 68, 124, 25);
                DrawInteractiveButton(g, hLabel, false, 3);
                g.DrawString("↕ Cao:", btnFont, Brushes.DimGray, hLabel.X + 4, hLabel.Y + 4);
                string hStr = (shape.Transform.Height * 0.0264583f).ToString("0.00") + " cm";
                g.DrawString(hStr, valFont, Brushes.Navy, hLabel.X + 38, hLabel.Y + 3);
                Rectangle hUp = new Rectangle(hLabel.Right - 20, hLabel.Y + 1, 18, 11);
                Rectangle hDn = new Rectangle(hLabel.Right - 20, hLabel.Y + 12, 18, 11);
                DrawInteractiveButton(g, hUp, false, 1);
                DrawInteractiveButton(g, hDn, false, 1);
                g.DrawString("▲", labelFont, Brushes.Black, hUp.X + 3, hUp.Y - 2);
                g.DrawString("▼", labelFont, Brushes.Black, hDn.X + 3, hDn.Y - 2);

                // Width Spin Box
                Rectangle wLabel = new Rectangle(curX, 96, 124, 25);
                DrawInteractiveButton(g, wLabel, false, 3);
                g.DrawString("↔ Rộng:", btnFont, Brushes.DimGray, wLabel.X + 4, wLabel.Y + 4);
                string wStr = (shape.Transform.Width * 0.0264583f).ToString("0.00") + " cm";
                g.DrawString(wStr, valFont, Brushes.Navy, wLabel.X + 42, wLabel.Y + 3);
                Rectangle wUp = new Rectangle(wLabel.Right - 20, wLabel.Y + 1, 18, 11);
                Rectangle wDn = new Rectangle(wLabel.Right - 20, wLabel.Y + 12, 18, 11);
                DrawInteractiveButton(g, wUp, false, 1);
                DrawInteractiveButton(g, wDn, false, 1);
                g.DrawString("▲", labelFont, Brushes.Black, wUp.X + 3, wUp.Y - 2);
                g.DrawString("▼", labelFont, Brushes.Black, wDn.X + 3, wDn.Y - 2);
                curX += 130;

                g.DrawString("Kích thước", labelFont, Brushes.Gray, curX - 110, 137);
            }
        }

