                g.DrawString("Xoay 90°", btnFont, Brushes.Black, rotBtn.X + 22, rotBtn.Y + 3);

                Rectangle flipHBtn = new Rectangle(curX, 94, 84, 24);
                DrawInteractiveButton(g, flipHBtn, false, 3);
                g.DrawString("⇄", boldFont, Brushes.DarkBlue, flipHBtn.X + 4, flipHBtn.Y + 2);
                g.DrawString("Lật ngang", btnFont, Brushes.Black, flipHBtn.X + 20, flipHBtn.Y + 3);

                Rectangle flipVBtn = new Rectangle(curX, 120, 84, 24);
                DrawInteractiveButton(g, flipVBtn, false, 3);
                g.DrawString("⇅", boldFont, Brushes.DarkBlue, flipVBtn.X + 4, flipVBtn.Y + 2);
                g.DrawString("Lật dọc", btnFont, Brushes.Black, flipVBtn.X + 20, flipVBtn.Y + 3);

                curX += 88;
                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 5: Kích thước (Size) ====================
                // Height Spin Box
                Rectangle hLabel = new Rectangle(curX, 68, 130, 34);
                DrawInteractiveButton(g, hLabel, false, 3);
                g.DrawString("↕ Cao:", btnFont, Brushes.DimGray, hLabel.X + 4, hLabel.Y + 8);
                string hStr = (shape.Transform.Height * 0.0264583f).ToString("0.00") + " cm";
                g.DrawString(hStr, valFont, Brushes.Navy, hLabel.X + 42, hLabel.Y + 7);
                // Spin buttons ▲ ▼
                Rectangle hUp = new Rectangle(hLabel.Right - 22, hLabel.Y + 2, 20, 14);
                Rectangle hDn = new Rectangle(hLabel.Right - 22, hLabel.Y + 18, 20, 14);
                DrawInteractiveButton(g, hUp, false, 2);
                DrawInteractiveButton(g, hDn, false, 2);
                g.DrawString("▲", labelFont, Brushes.Black, hUp.X + 4, hUp.Y - 1);
                g.DrawString("▼", labelFont, Brushes.Black, hDn.X + 4, hDn.Y - 1);

                // Width Spin Box
                Rectangle wLabel = new Rectangle(curX, 106, 130, 34);
                DrawInteractiveButton(g, wLabel, false, 3);
                g.DrawString("↔ Rộng:", btnFont, Brushes.DimGray, wLabel.X + 4, wLabel.Y + 8);
                string wStr = (shape.Transform.Width * 0.0264583f).ToString("0.00") + " cm";
                g.DrawString(wStr, valFont, Brushes.Navy, wLabel.X + 46, wLabel.Y + 7);
                Rectangle wUp = new Rectangle(wLabel.Right - 22, wLabel.Y + 2, 20, 14);
                Rectangle wDn = new Rectangle(wLabel.Right - 22, wLabel.Y + 18, 20, 14);
                DrawInteractiveButton(g, wUp, false, 2);
                DrawInteractiveButton(g, wDn, false, 2);
                g.DrawString("▲", labelFont, Brushes.Black, wUp.X + 4, wUp.Y - 1);
                g.DrawString("▼", labelFont, Brushes.Black, wDn.X + 4, wDn.Y - 1);

                curX += 134;
                g.DrawString("Kích thước", labelFont, Brushes.Gray, curX - 85, 137);
            }
        }

        private void DrawPowerPointTabVideoFormat(Graphics g, int width, SlidesView slidesView)
        {
            using (Font btnFont = new Font("Segoe UI", 9f))
            using (Font labelFont = new Font("Segoe UI", 8.25f))
            using (Font boldFont = new Font("Segoe UI", 9f, FontStyle.Bold))
            using (Font miniFont = new Font("Segoe UI", 7.5f))
            using (Font valFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                ShapeNode shape = (slidesView != null) ? slidesView.SelectedShape : null;
                if (shape == null) return;

                int curX = 14;

                // ==================== 1. Nhóm Xem trước (Preview) ====================
                Rectangle playBox = new Rectangle(curX, 68, 48, 54);
                DrawInteractiveButton(g, playBox, false, 3);
                using (SolidBrush playBrush = new SolidBrush(Color.FromArgb(16, 185, 129)))
                {
                    g.FillPolygon(playBrush, new PointF[] {
                        new PointF(playBox.X + 16, playBox.Y + 8),
                        new PointF(playBox.X + 34, playBox.Y + 19),
                        new PointF(playBox.X + 16, playBox.Y + 30)
                    });
                }
                g.DrawString("Phát", btnFont, Brushes.Black, playBox.X + 10, playBox.Y + 33);
                g.DrawString("Xem trước", labelFont, Brushes.Gray, curX - 2, 137);
                curX += 54;
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== 2. Nhóm Điều chỉnh (Adjust) ====================
                // Row 1: Hiệu chỉnh & Khung áp phích
                Rectangle corrBox = new Rectangle(curX, 68, 108, 24);
                DrawInteractiveButton(g, corrBox, false, 3);
                DrawSunVector(g, corrBox.X + 14, corrBox.Y + 12, 15, Color.FromArgb(234, 179, 8));
                g.DrawString("Hiệu chỉnh ▾", btnFont, Brushes.Black, corrBox.X + 26, corrBox.Y + 2);

                Rectangle posterBox = new Rectangle(curX + 112, 68, 122, 24);
                DrawInteractiveButton(g, posterBox, false, 3);
                DrawPosterFrameVector(g, posterBox.X + 6, posterBox.Y + 4, 15, Color.FromArgb(37, 99, 235));
                g.DrawString("Khung áp phích ▾", btnFont, Brushes.Black, posterBox.X + 24, posterBox.Y + 2);

                // Row 2: Màu sắc & Đặt lại Thiết kế
                Rectangle colBox = new Rectangle(curX, 96, 108, 24);
                DrawInteractiveButton(g, colBox, false, 3);
                DrawColorWashVector(g, colBox.X + 6, colBox.Y + 4, 15, Color.FromArgb(168, 85, 247));
                g.DrawString("Màu sắc ▾", btnFont, Brushes.Black, colBox.X + 26, colBox.Y + 2);

                Rectangle resetBox = new Rectangle(curX + 112, 96, 122, 24);
                DrawInteractiveButton(g, resetBox, false, 3);
                DrawResetVector(g, resetBox.X + 12, resetBox.Y + 12, 6, Color.FromArgb(220, 38, 38));
                g.DrawString("Đặt lại Thiết kế ▾", btnFont, Brushes.Black, resetBox.X + 24, resetBox.Y + 2);

                curX += 238;
                g.DrawString("Điều chỉnh", labelFont, Brushes.Gray, curX - 146, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== 3. Nhóm Kiểu Video (Video Styles) ====================
                int activeStyle = shape.VideoStyleIndex;
                for (int i = 0; i < 7; i++)
                {
                    Rectangle cardR = new Rectangle(curX + i * 42, 68, 38, 54);
                    bool isSelected = (activeStyle == i);
                    DrawVideoStyleThumbnail(g, cardR, i, isSelected);
                }
                curX += 7 * 42 + 6;

                // 3 Quick style menus
                Rectangle vShapeBox = new Rectangle(curX, 68, 116, 18);
                DrawInteractiveButton(g, vShapeBox, false, 2);
                DrawShapeIconMini(g, vShapeBox.X + 4, vShapeBox.Y + 3, Color.FromArgb(37, 99, 235));
                g.DrawString("Hình dạng Video ▾", miniFont, Brushes.Black, vShapeBox.X + 18, vShapeBox.Y + 1);

                Rectangle vBorderBox = new Rectangle(curX, 88, 116, 18);
                DrawInteractiveButton(g, vBorderBox, false, 2);
                DrawBorderVector(g, vBorderBox.X + 4, vBorderBox.Y + 3, 11, 11, Color.FromArgb(16, 185, 129));
                g.DrawString("Viền Video ▾", miniFont, Brushes.Black, vBorderBox.X + 18, vBorderBox.Y + 1);

                Rectangle vEffectBox = new Rectangle(curX, 108, 116, 18);
                DrawInteractiveButton(g, vEffectBox, false, 2);
                DrawSparkleVector(g, vEffectBox.X + 4, vEffectBox.Y + 3, 11, Color.FromArgb(234, 179, 8));
                g.DrawString("Hiệu ứng Video ▾", miniFont, Brushes.Black, vEffectBox.X + 18, vEffectBox.Y + 1);

                curX += 122;
                g.DrawString("Kiểu Video", labelFont, Brushes.Gray, curX - 220, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== 4. Khả năng truy cập (Accessibility) ====================
                Rectangle altBox = new Rectangle(curX, 68, 64, 54);
                DrawInteractiveButton(g, altBox, false, 3);
                DrawAltTextVector(g, altBox.X + 18, altBox.Y + 6, 26, 20);
                g.DrawString("Văn bản\nThay thế", miniFont, Brushes.Black, altBox.X + 8, altBox.Y + 28);

                curX += 70;
                g.DrawString("Truy cập", labelFont, Brushes.Gray, curX - 56, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== 5. Nhóm Sắp xếp (Arrange) ====================
                Rectangle bFwd = new Rectangle(curX, 68, 96, 18);
                DrawInteractiveButton(g, bFwd, false, 2);
                DrawLayerFwdVector(g, bFwd.X + 4, bFwd.Y + 3, Color.FromArgb(37, 99, 235));
                g.DrawString("Đưa lên trên ▾", miniFont, Brushes.Black, bFwd.X + 18, bFwd.Y + 1);

                Rectangle sBwd = new Rectangle(curX, 88, 96, 18);
                DrawInteractiveButton(g, sBwd, false, 2);
                DrawLayerBwdVector(g, sBwd.X + 4, sBwd.Y + 3, Color.FromArgb(75, 85, 99));
                g.DrawString("Đưa ra sau ▾", miniFont, Brushes.Black, sBwd.X + 18, sBwd.Y + 1);

                Rectangle selPane = new Rectangle(curX, 108, 96, 18);
                DrawInteractiveButton(g, selPane, false, 2);
                DrawSelectionPaneVector(g, selPane.X + 4, selPane.Y + 3, Color.FromArgb(16, 185, 129));
                g.DrawString("Ngăn Lựa chọn", miniFont, Brushes.Black, selPane.X + 18, selPane.Y + 1);

                Rectangle alignBox = new Rectangle(curX + 100, 68, 88, 18);
                DrawInteractiveButton(g, alignBox, false, 2);
                DrawAlignVector(g, alignBox.X + 4, alignBox.Y + 4, 12, 10, 0, Color.FromArgb(37, 99, 235));
                g.DrawString("Căn chỉnh ▾", miniFont, Brushes.Black, alignBox.X + 18, alignBox.Y + 1);

                Rectangle grpBox = new Rectangle(curX + 100, 88, 88, 18);
                DrawInteractiveButton(g, grpBox, false, 2);
                DrawGroupVector(g, grpBox.X + 4, grpBox.Y + 3, Color.FromArgb(75, 85, 99));
                g.DrawString("Nhóm ▾", miniFont, Brushes.Black, grpBox.X + 18, grpBox.Y + 1);

                Rectangle rotBox = new Rectangle(curX + 100, 108, 88, 18);
                DrawInteractiveButton(g, rotBox, false, 2);
                DrawRotateVector(g, rotBox.X + 4, rotBox.Y + 3, Color.FromArgb(234, 179, 8));
                g.DrawString("Xoay ▾", miniFont, Brushes.Black, rotBox.X + 18, rotBox.Y + 1);

                curX += 194;
                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, curX - 116, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== 6. Nhóm Kích cỡ (Size) ====================
                Rectangle cropBox = new Rectangle(curX, 68, 48, 54);
                DrawInteractiveButton(g, cropBox, false, 3);
                DrawCropVector(g, cropBox.X + 24, cropBox.Y + 16, 20, Color.FromArgb(37, 99, 235));
                g.DrawString("Cắt tỉa ▾", miniFont, Brushes.Black, cropBox.X + 4, cropBox.Y + 34);
                curX += 52;

                Rectangle hLabel = new Rectangle(curX, 68, 118, 25);
                DrawInteractiveButton(g, hLabel, false, 3);
                g.DrawString("↕ Cao:", btnFont, Brushes.DimGray, hLabel.X + 4, hLabel.Y + 4);
                string hStr = (shape.Transform.Height * 0.0264583f).ToString("0.00") + " cm";
                g.DrawString(hStr, valFont, Brushes.Navy, hLabel.X + 44, hLabel.Y + 3);
                Rectangle hUp = new Rectangle(hLabel.Right - 20, hLabel.Y + 1, 18, 11);
                Rectangle hDn = new Rectangle(hLabel.Right - 20, hLabel.Y + 13, 18, 11);
                DrawInteractiveButton(g, hUp, false, 2);
                DrawInteractiveButton(g, hDn, false, 2);
                g.DrawString("▲", miniFont, Brushes.Black, hUp.X + 3, hUp.Y - 2);
                g.DrawString("▼", miniFont, Brushes.Black, hDn.X + 3, hDn.Y - 2);

                Rectangle wLabel = new Rectangle(curX, 96, 118, 25);
                DrawInteractiveButton(g, wLabel, false, 3);
                g.DrawString("↔ Rộng:", btnFont, Brushes.DimGray, wLabel.X + 4, wLabel.Y + 4);
                string wStr = (shape.Transform.Width * 0.0264583f).ToString("0.00") + " cm";
                g.DrawString(wStr, valFont, Brushes.Navy, wLabel.X + 44, wLabel.Y + 3);
                Rectangle wUp = new Rectangle(wLabel.Right - 20, wLabel.Y + 1, 18, 11);
                Rectangle wDn = new Rectangle(wLabel.Right - 20, wLabel.Y + 13, 18, 11);
                DrawInteractiveButton(g, wUp, false, 2);
                DrawInteractiveButton(g, wDn, false, 2);
                g.DrawString("▲", miniFont, Brushes.Black, wUp.X + 3, wUp.Y - 2);
                g.DrawString("▼", miniFont, Brushes.Black, wDn.X + 3, wDn.Y - 2);

                curX += 124;
                g.DrawString("Kích cỡ", labelFont, Brushes.Gray, curX - 90, 137);
            }
