        private void DrawBookmarkVector(Graphics g, int x, int y, int size, bool isAdd)
        {
            using (SolidBrush ribbonBrush = new SolidBrush(Color.FromArgb(245, 158, 11)))
            {
                g.FillPolygon(ribbonBrush, new PointF[] {
                    new PointF(x + 1, y),
                    new PointF(x + 10, y),
                    new PointF(x + 10, y + size),
                    new PointF(x + 5.5f, y + size - 4),
                    new PointF(x + 1, y + size)
                });
            }
            if (isAdd)
            {
                using (SolidBrush greenBrush = new SolidBrush(Color.FromArgb(16, 185, 129)))
                using (Pen whitePen = new Pen(Color.White, 1.5f))
                {
                    g.FillEllipse(greenBrush, x + 8, y + 6, 8, 8);
                    g.DrawLine(whitePen, x + 12, y + 8, x + 12, y + 12);
                    g.DrawLine(whitePen, x + 10, y + 10, x + 14, y + 10);
                }
            }
            else
            {
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(239, 68, 68)))
                using (Pen whitePen = new Pen(Color.White, 1.5f))
                {
                    g.FillEllipse(redBrush, x + 8, y + 6, 8, 8);
                    g.DrawLine(whitePen, x + 10, y + 8, x + 14, y + 12);
                    g.DrawLine(whitePen, x + 14, y + 8, x + 10, y + 12);
                }
            }
        }

        private void DrawTrimVideoVector(Graphics g, int x, int y, int size, Color c)
        {
            using (Pen p = new Pen(c, 1.5f))
            using (Pen blackPen = new Pen(Color.FromArgb(30, 41, 59), 1.2f))
            using (SolidBrush b = new SolidBrush(Color.FromArgb(30, 41, 59)))
            {
                g.DrawRectangle(blackPen, x - 10, y + 4, size + 8, 12);
                for (int i = -8; i < size + 6; i += 5)
                {
                    g.FillRectangle(b, x + i, y + 5, 2, 2);
                    g.FillRectangle(b, x + i, y + 13, 2, 2);
                }
                g.DrawEllipse(p, x - 6, y + 10, 5, 5);
                g.DrawEllipse(p, x - 6, y + 16, 5, 5);
                g.DrawLine(p, x - 2, y + 12, x + 10, y + 2);
                g.DrawLine(p, x - 2, y + 18, x + 10, y + 8);
            }
        }

        private void DrawVolumeVector(Graphics g, int x, int y, int size, Color c)
        {
            using (SolidBrush b = new SolidBrush(c))
            using (Pen p = new Pen(c, 1.4f))
            {
                g.FillRectangle(b, x, y + 4, 3, 6);
                g.FillPolygon(b, new PointF[] {
                    new PointF(x + 3, y + 4),
                    new PointF(x + 7, y + 1),
                    new PointF(x + 7, y + 13),
                    new PointF(x + 3, y + 10)
                });
                g.DrawArc(p, x + 4, y + 3, 6, 8, -60, 120);
                g.DrawArc(p, x + 6, y + 1, 9, 12, -60, 120);
            }
        }

