            }
        }

        private void DrawVideoStyleThumbnail(Graphics g, Rectangle r, int styleIdx, bool isSelected)
        {
            DrawInteractiveButton(g, r, isSelected, 3);
            Rectangle inner = new Rectangle(r.X + 4, r.Y + 4, r.Width - 8, r.Height - 8);

            switch (styleIdx)
            {
                case 0: // Simple Frame
                    g.FillRectangle(Brushes.Black, inner);
                    using (Pen p = new Pen(Color.LightGray, 1.5f)) g.DrawRectangle(p, inner);
                    break;
                case 1: // Metal Bevel
                    using (LinearGradientBrush bg = new LinearGradientBrush(inner, Color.FromArgb(15, 23, 42), Color.FromArgb(51, 65, 85), 45f))
                    {
                        g.FillRectangle(bg, inner);
                    }
                    using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 2.5f)) g.DrawRectangle(p, inner);
                    break;
                case 2: // Drop Shadow
                    using (SolidBrush shB = new SolidBrush(Color.FromArgb(80, 0, 0, 0)))
                    {
                        g.FillRectangle(shB, inner.X + 2, inner.Y + 2, inner.Width, inner.Height);
                    }
                    g.FillRectangle(Brushes.SlateGray, inner);
                    g.DrawRectangle(Pens.White, inner);
                    break;
                case 3: // Soft Rounded
                    using (GraphicsPath gp = CreateRoundedRectPath(inner, 6))
                    {
                        g.FillPath(Brushes.DarkSlateBlue, gp);
                        using (Pen p = new Pen(Color.FromArgb(99, 102, 241), 1.5f)) g.DrawPath(p, gp);
                    }
                    break;
                case 4: // Oval Frame
                    g.FillEllipse(Brushes.DarkBlue, inner);
                    using (Pen p = new Pen(Color.FromArgb(234, 179, 8), 1.8f)) g.DrawEllipse(p, inner);
                    break;
                case 5: // Perspective 3D
                    PointF[] pts = new PointF[] {
                        new PointF(inner.X + 4, inner.Y + 3),
                        new PointF(inner.Right - 2, inner.Y),
                        new PointF(inner.Right - 2, inner.Bottom - 3),
                        new PointF(inner.X + 4, inner.Bottom)
                    };
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(30, 58, 138)))
                    {
                        g.FillPolygon(b, pts);
                    }
                    using (Pen p = new Pen(Color.White, 1.2f)) g.DrawPolygon(p, pts);
                    break;
                case 6: // Glowing Cyan
                default:
                    g.FillRectangle(Brushes.Black, inner);
                    using (Pen p = new Pen(Color.FromArgb(6, 182, 212), 2f)) g.DrawRectangle(p, inner);
                    break;
            }

            using (SolidBrush pb = new SolidBrush(Color.FromArgb(200, 255, 255, 255)))
            {
                g.FillPolygon(pb, new PointF[] {
                    new PointF(inner.X + inner.Width / 2 - 3, inner.Y + inner.Height / 2 - 4),
                    new PointF(inner.X + inner.Width / 2 + 4, inner.Y + inner.Height / 2),
                    new PointF(inner.X + inner.Width / 2 - 3, inner.Y + inner.Height / 2 + 4)
                });
            }
        }

        public bool HandleClick(int x, int y, WriterView writerView = null, Form parentForm = null, SlidesView slidesView = null, CalcView calcView = null, PdfView pdfView = null, PhotoView photoView = null)
        {
            UpdateHover(x, y);
            if (ActiveOpenMenu != null && !ActiveDropdownBounds.Contains(x, y))
            {
                try { ActiveOpenMenu.Close(); } catch { }
                ActiveOpenMenu = null;
                ActiveDropdownBounds = Rectangle.Empty;
            }
            int rTop = (RibbonTopHeight > 0) ? RibbonTopHeight : 36;
            int maxTopY = rTop + 2;
            if (y >= 0 && y <= maxTopY)
            {
                if ((!CaptionCloseBounds.IsEmpty && CaptionCloseBounds.Contains(x, y)) ||
                    (!CaptionMaxBounds.IsEmpty && CaptionMaxBounds.Contains(x, y)) ||
                    (!CaptionMinBounds.IsEmpty && CaptionMinBounds.Contains(x, y)) ||
                    (!CaptionTouchModeBounds.IsEmpty && CaptionTouchModeBounds.Contains(x, y)) ||
                    (!CaptionPeripheralsBounds.IsEmpty && CaptionPeripheralsBounds.Contains(x, y)) ||
                    (!CaptionMobileConnectBounds.IsEmpty && CaptionMobileConnectBounds.Contains(x, y)))
                {
                    return true;
                }

                if (StandaloneMode)
                {
                    AppForm appForm = parentForm as AppForm;
                    if (!QuickSaveBounds.IsEmpty && QuickSaveBounds.Contains(x, y))
                    {
                        if (appForm != null) appForm.PerformQuickSave();
                        return true;
                    }
                    if (!QuickUndoBounds.IsEmpty && QuickUndoBounds.Contains(x, y))
                    {
                        if (appForm != null) appForm.PerformQuickUndo();
                        return true;
                    }
                    if (!QuickRedoBounds.IsEmpty && QuickRedoBounds.Contains(x, y))
                    {
                        if (appForm != null) appForm.PerformQuickRedo();
                        return true;
                    }
                    return true;
                }

                // 0. Check Document Tab Scroll Left / Right Arrows (< / >)
                if (!DocTabScrollLeftBounds.IsEmpty && DocTabScrollLeftBounds.Contains(x, y))
                {
                    ScrollDocTabsLeft(slidesView, writerView, calcView, pdfView, photoView);
                    if (parentForm != null) parentForm.Invalidate();
                    if (Parent != null) Parent.Invalidate();
                    return true;
                }
                if (!DocTabScrollRightBounds.IsEmpty && DocTabScrollRightBounds.Contains(x, y))
                {
                    ScrollDocTabsRight(slidesView, writerView, calcView, pdfView, photoView);
                    if (parentForm != null) parentForm.Invalidate();
                    if (Parent != null) Parent.Invalidate();
                    return true;
                }

                int formW = (parentForm != null) ? parentForm.ClientSize.Width : ((Parent != null) ? Parent.ClientSize.Width : 1366);
                int docAreaX = (_lastDocAreaX > 0) ? _lastDocAreaX : 120;
                int docAreaW = (_lastDocAreaW > 20) ? _lastDocAreaW : Math.Max(10, formW - docAreaX - (int)Math.Round(214f * (CurrentDpiScale > 0 ? CurrentDpiScale : 1.0f)) - 10);
                Rectangle docClipRect = new Rectangle(docAreaX, 0, docAreaW, maxTopY);

                // 1. Check Home Tab (Luôn cố định ở vị trí đầu tiên index 0)
                if (DocTabBounds.Count > 0 && DocTabBounds[0].Contains(x, y))
                {
                    SwitchDocTab(0, slidesView, writerView, calcView, pdfView, photoView);
                    if (parentForm != null) parentForm.Invalidate();
                    if (Parent != null) Parent.Invalidate();
                    return true;
                }

                // 2. Check Add Tab Button (Luôn nhận click kể cả khi ghim ngoài docClipRect)
                if (!DocTabPlusBounds.IsEmpty && DocTabPlusBounds.Contains(x, y))
                {
                    AppForm app = (parentForm as AppForm) ?? (Parent as AppForm) ?? HostAppForm;
                    if (app != null)
                    {
                        if (app.BackstageView != null && app.BackstageView.IsOpen)
                        {
                            app.CloseBackstageView();
                        }
                        Point plusCenter = new Point((DocTabPlusBounds.Left + DocTabPlusBounds.Right) / 2, DocTabPlusBounds.Bottom + 4);
                        NewTabRadialLauncher.Toggle(plusCenter, app);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    if (Parent != null) Parent.Invalidate();
                    return true;
                }

                // 3. Check Document Tabs (Chỉ nhận click khi nằm trong vùng hiển thị docClipRect)
                if (docClipRect.Contains(x, y))
                {
                    for (int i = 1; i < DocTabs.Count; i++)
                    {
                        // Close Button
                        if (i < DocTabCloseBounds.Count && !DocTabCloseBounds[i].IsEmpty && DocTabCloseBounds[i].Contains(x, y))
                        {
                            CloseDocTab(i, slidesView, writerView, calcView, pdfView, photoView);
                            if (parentForm != null) parentForm.Invalidate();
                            if (Parent != null) Parent.Invalidate();
                            return true;
                        }

                        // Switch Tab
                        if (i < DocTabBounds.Count && !DocTabBounds[i].IsEmpty && DocTabBounds[i].Contains(x, y))
                        {
                            SwitchDocTab(i, slidesView, writerView, calcView, pdfView, photoView);
                            if (parentForm != null) parentForm.Invalidate();
                            if (Parent != null) Parent.Invalidate();
                            return true;
                        }
                    }
                }
            }
            else if (y > rTop && y <= 66 && CurrentMode != OfficeAppMode.Home)
            {
                // 1. Kiểm tra click nút Hoàn tác (Undo) và Làm lại (Redo)
                if (!RibbonUndoButtonBounds.IsEmpty && RibbonUndoButtonBounds.Contains(x, y))
                {
                    AppForm app = (parentForm as AppForm) ?? (Parent as AppForm) ?? HostAppForm;
                    if (app != null)
                    {
                        app.PerformQuickUndo();
                        if (parentForm != null) parentForm.Invalidate();
                        if (Parent != null) Parent.Invalidate();
                    }
                    return true;
                }
                if (!RibbonRedoButtonBounds.IsEmpty && RibbonRedoButtonBounds.Contains(x, y))
                {
                    AppForm app = (parentForm as AppForm) ?? (Parent as AppForm) ?? HostAppForm;
                    if (app != null)
                    {
                        app.PerformQuickRedo();
                        if (parentForm != null) parentForm.Invalidate();
                        if (Parent != null) Parent.Invalidate();
                    }
                    return true;
                }

                // 2. Kiểm tra click nút "Tệp" (Mở Office Backstage View)
                if (!RibbonFileBtnBounds.IsEmpty && RibbonFileBtnBounds.Contains(x, y))
                {
                    AppForm appForm = parentForm as AppForm;
                    if (appForm != null)
                    {
                        appForm.OpenBackstageView();
                        return true;
                    }

                    SwitchDocTab(0, slidesView, writerView, calcView, pdfView);
                    if (parentForm != null) parentForm.Invalidate();
                    if (Parent != null) Parent.Invalidate();
                    return true;
                }

                // 3. Kiểm tra click các Ribbon Tabs
                if (RibbonTabBounds.Count == RibbonTabs.Length)
                {
                    for (int i = 0; i < RibbonTabs.Length; i++)
                    {
                        if (RibbonTabBounds[i].Contains(x, y))
                        {
                            ActiveRibbonTab = i;
                            if (parentForm != null) parentForm.Invalidate();
                            if (Parent != null) Parent.Invalidate();
                            return true;
                        }
                    }
                }
                else
                {
                    int rTabX = RibbonFileBtnBounds.Width > 0 ? (RibbonFileBtnBounds.Right + 8) : ((AppSettings.Instance.RibbonStyle == RibbonStyle.Island) ? 64 : 72);
                    float fSize = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island) ? 9.0f : 9.5f;
                    int minW = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island) ? 64 : 72;
                    using (Font rFont = new Font("Segoe UI", fSize, FontStyle.Regular))
                    using (Bitmap tmpBmp = new Bitmap(1, 1))
                    using (Graphics gTmp = Graphics.FromImage(tmpBmp))
                    {
                        for (int i = 0; i < RibbonTabs.Length; i++)
                        {
                            int rWidth = Math.Max(minW, (int)gTmp.MeasureString(RibbonTabs[i], rFont).Width + 24);
                            if (x >= rTabX && x <= rTabX + rWidth)
                            {
                                ActiveRibbonTab = i;
                                if (parentForm != null) parentForm.Invalidate();
                                if (Parent != null) Parent.Invalidate();
                                return true;
                            }
                            rTabX += rWidth + 4;
                        }
                    }
                }
            }
            else if (y > 64 && y <= 155 && CurrentMode == OfficeAppMode.Writer)
            {
                string curTab = (RibbonTabs != null && ActiveRibbonTab >= 0 && ActiveRibbonTab < RibbonTabs.Length) ? RibbonTabs[ActiveRibbonTab] : "";

                if (curTab == "Trang đầu" || (ActiveRibbonTab == 0 && string.IsNullOrEmpty(curTab)))
                {
                    if (writerView != null)
                    {
                        // Clipboard Buttons
                        if (x >= 14 && x <= 68 && y >= 68 && y <= 130) { writerView.Paste(); return true; }
                        if (x >= 72 && x <= 238 && y >= 68 && y <= 88) { writerView.Cut(); return true; }
                        if (x >= 72 && x <= 238 && y >= 89 && y <= 109) { writerView.Copy(); return true; }
                        if (x >= 72 && x <= 238 && y >= 110 && y <= 130)
                        {
                            writerView.ToggleFormatPainter(false, this);
                            IsFormatPainterActive = writerView.IsFormatPainterActive;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Clipboard Dialog Box Launcher (X: 218..236, Y: 130..148)
                        if (x >= 218 && x <= 236 && y >= 130 && y <= 148)
                        {
                            ContextMenuStrip clipMenu = new ContextMenuStrip();
                            clipMenu.Items.Add("Dán (Paste)", null, (s, e) => { writerView.Paste(); if (parentForm != null) parentForm.Invalidate(); });
                            clipMenu.Items.Add("Sao chép (Copy)", null, (s, e) => { writerView.Copy(); });
                            clipMenu.Items.Add("Cắt (Cut)", null, (s, e) => { writerView.Cut(); if (parentForm != null) parentForm.Invalidate(); });
                            clipMenu.Items.Add(new ToolStripSeparator());
                            clipMenu.Items.Add("Xóa sạch Bảng tạm (Clear Clipboard)", null, (s, e) => { try { Clipboard.Clear(); } catch { } });
                            clipMenu.Show(parentForm ?? Form.ActiveForm, new Point(x, y));
                            return true;
                        }

                        // Font Family Dropdown Popup (X: 248 to 368)
                        if (x >= 248 && x <= 368 && y >= 68 && y <= 92)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(248, 96)) : new Point(248, 96);
                            FontDropDownForm fontDlg = new FontDropDownForm(SelectedFont, pt, AvailableSystemFonts, Color.FromArgb(16, 110, 190));
                            fontDlg.OnFontSelected += (font) =>
                            {
                                SelectedFont = font;
                                writerView.ApplyFontToSelectionOrTyping(font);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            fontDlg.Show();
                            return true;
                        }

                        // Font Size Dropdown Popup (X: 372 to 414)
                        if (x >= 372 && x <= 414 && y >= 68 && y <= 92)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(372, 96)) : new Point(372, 96);
                            SizeDropDownForm sizeDlg = new SizeDropDownForm(FontSize, pt, Color.FromArgb(16, 110, 190));
                            sizeDlg.OnSizeSelected += (sz) =>
                            {
                                FontSize = sz;
                                writerView.ApplyFontSizeToSelectionOrTyping(sz);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            sizeDlg.Show();
                            return true;
                        }

                        // A^ / Av Font Size Adjustment Buttons
                        if (x >= 418 && x <= 440 && y >= 68 && y <= 92)
                        {
                            FontSize += 2.0f;
                            writerView.ApplyFontSizeToSelectionOrTyping(FontSize);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 442 && x <= 464 && y >= 68 && y <= 92)
                        {
                            if (FontSize > 6.0f) FontSize -= 2.0f;
                            writerView.ApplyFontSizeToSelectionOrTyping(FontSize);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Aa▾ Case Conversion Button (X: 466 to 488)
                        if (x >= 466 && x <= 488 && y >= 68 && y <= 92)
                        {
                            ContextMenuStrip caseMenu = new ContextMenuStrip();
                            caseMenu.RenderMode = ToolStripRenderMode.System;
                            string[] caseLabels = new string[] {
                                "Chữ đầu câu hoa (Sentence case)",
                                "chữ thường (lowercase)",
                                "CHỮ HOA (UPPERCASE)",
                                "Viết Hoa Từng Từ (Capitalize Each Word)",
                                "đỔI kIỂU hOA tHƯỜNG (tOGGLE cASE)"
                            };
                            for (int mi = 0; mi < caseLabels.Length; mi++)
                            {
                                int mode = mi;
                                caseMenu.Items.Add(caseLabels[mi], null, (s, e) => {
                                    writerView.ApplyCase(mode);
                                    writerView.UpdateRibbonState(this);
                                    if (parentForm != null) parentForm.Invalidate();
                                });
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(466, 92)) : new Point(466, 92);
                            ShowRibbonDropdown(caseMenu, parentForm, pt, new Rectangle(466, 68, 22, 24));
                            return true;
                        }

                        // Clear Formatting Button (X: 490 to 512)
                        if (x >= 490 && x <= 512 && y >= 68 && y <= 92)
                        {
                            IsBold = false;
                            IsItalic = false;
                            IsUnderline = false;
                            IsStrikethrough = false;
                            IsSubscript = false;
                            IsSuperscript = false;
                            FontSize = 11.0f;
                            SelectedFont = "Times New Roman";
                            writerView.ClearFormatting();
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Formatting Toggles Row 2 (Y: 96..120)
                        if (x >= 248 && x <= 270 && y >= 96 && y <= 120)
                        {
                            IsBold = !IsBold;
                            writerView.ApplyBoldToSelectionOrTyping(IsBold);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 272 && x <= 294 && y >= 96 && y <= 120)
                        {
                            IsItalic = !IsItalic;
                            writerView.ApplyItalicToSelectionOrTyping(IsItalic);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 296 && x <= 322 && y >= 96 && y <= 120)
                        {
                            IsUnderline = !IsUnderline;
                            writerView.ApplyUnderlineToSelectionOrTyping(IsUnderline);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 324 && x <= 346 && y >= 96 && y <= 120)
                        {
                            IsStrikethrough = !IsStrikethrough;
                            writerView.ApplyStrikeToSelectionOrTyping(IsStrikethrough);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Subscript (X_2) (X: 348 to 370)
                        if (x >= 348 && x <= 370 && y >= 96 && y <= 120)
                        {
                            IsSubscript = !IsSubscript;
                            if (IsSubscript) IsSuperscript = false;
                            writerView.ApplySubscriptToSelectionOrTyping(IsSubscript);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Superscript (X^2) (X: 372 to 394)
                        if (x >= 372 && x <= 394 && y >= 96 && y <= 120)
                        {
                            IsSuperscript = !IsSuperscript;
                            if (IsSuperscript) IsSubscript = false;
                            writerView.ApplySuperscriptToSelectionOrTyping(IsSuperscript);
                            writerView.UpdateRibbonState(this);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Text Effects (A▾) (X: 396 to 422)
                        if (x >= 396 && x <= 422 && y >= 96 && y <= 120)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(396, 122)) : new Point(396, 122);
                            TextEffectsDropDownForm fxDlg = new TextEffectsDropDownForm(pt, (preset, isClear) =>
                            {
                                if (isClear || preset == null)
                                {
                                    writerView.ClearTextEffectsFromSelectionOrTyping();
                                }
                                else
                                {
                                    writerView.ApplyTextEffectToSelectionOrTyping(preset.Color, preset.Bold, preset.Italic, preset.Underline, preset.Highlight);
                                }
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            fxDlg.Show();
                            return true;
                        }

                        // Highlight Color Button (🖍) (X: 424 to 452)
                        if (x >= 424 && x <= 452 && y >= 96 && y <= 120)
                        {
                            if (x <= 441 && CurrentHighlightColor != Color.Transparent && CurrentHighlightColor != Color.Empty)
                            {
                                writerView.ApplyHighlightToSelectionOrTyping(CurrentHighlightColor);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(424, 122)) : new Point(424, 122);
                            ColorPaletteForm hlDlg = new ColorPaletteForm(pt, true);
                            hlDlg.OnColorSelected += (col) =>
                            {
                                CurrentHighlightColor = col;
                                writerView.ApplyHighlightToSelectionOrTyping(col);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            hlDlg.Show();
                            return true;
                        }

                        // Font Color Button (A) (X: 454 to 482)
                        if (x >= 454 && x <= 482 && y >= 96 && y <= 120)
                        {
                            if (x <= 470)
                            {
                                Color col = (CurrentFontColor != Color.Transparent && CurrentFontColor != Color.Empty) ? CurrentFontColor : Color.FromArgb(220, 38, 38);
                                CurrentFontColor = col;
                                writerView.ApplyFontColorToSelectionOrTyping(col);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(454, 122)) : new Point(454, 122);
                            ColorPaletteForm fcDlg = new ColorPaletteForm(pt, false);
                            fcDlg.OnColorSelected += (col) =>
                            {
                                CurrentFontColor = col;
                                writerView.ApplyFontColorToSelectionOrTyping(col);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            fcDlg.Show();
                            return true;
                        }

                        // Font Dialog Box Launcher (X: 498..516, Y: 130..148)
                        if (x >= 498 && x <= 516 && y >= 130 && y <= 148)
                        {
                            using (OfficeFontDialogForm fontDlg = new OfficeFontDialogForm(SelectedFont, FontSize, IsBold, IsItalic, IsUnderline, IsStrikethrough, CurrentFontColor))
                            {
                                if (fontDlg.ShowDialog(parentForm) == DialogResult.OK)
                                {
                                    SelectedFont = fontDlg.FontNameResult;
                                    FontSize = fontDlg.FontSizeResult;
                                    IsBold = fontDlg.BoldResult;
                                    IsItalic = fontDlg.ItalicResult;
                                    IsUnderline = fontDlg.UnderlineResult;
                                    IsStrikethrough = fontDlg.StrikethroughResult;
                                    CurrentFontColor = fontDlg.TextColorResult;
                                    writerView.ApplyFormatToSelection(fontDlg.FontNameResult, fontDlg.FontSizeResult, fontDlg.BoldResult, fontDlg.ItalicResult, fontDlg.UnderlineResult, fontDlg.StrikethroughResult, fontDlg.TextColorResult, null, fontDlg.SubscriptResult, fontDlg.SuperscriptResult);
                                    writerView.UpdateRibbonState(this);
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                            return true;
                        }

                        // Bullets ▾ (X: 528 to 556)
                        if (x >= 528 && x <= 556 && y >= 68 && y <= 92)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(528, 96)) : new Point(528, 96);
                            BulletDropDownForm bDlg = new BulletDropDownForm(pt, (b) =>
                            {
                                writerView.ApplyBulletStyle(b);
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            bDlg.Show();
                            return true;
                        }

                        // Numbering ▾ (X: 558 to 586)
                        if (x >= 558 && x <= 586 && y >= 68 && y <= 92)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(558, 96)) : new Point(558, 96);
                            NumberingDropDownForm nDlg = new NumberingDropDownForm(pt, (fmt) =>
                            {
                                writerView.ApplyNumberingStyle(fmt);
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            nDlg.Show();
                            return true;
                        }

                        // Multilevel List ▾ (X: 588 to 616)
                        if (x >= 588 && x <= 616 && y >= 68 && y <= 92)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(588, 96)) : new Point(588, 96);
                            MultilevelListDropDownForm mDlg = new MultilevelListDropDownForm(pt, (fmt) =>
                            {
                                writerView.ApplyMultilevelStyle(fmt);
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            mDlg.Show();
                            return true;
                        }

                        // Decrease Indent (X: 618 to 640)
                        if (x >= 618 && x <= 640 && y >= 68 && y <= 92)
                        {
                            writerView.IndentLeft();
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Increase Indent (X: 642 to 664)
                        if (x >= 642 && x <= 664 && y >= 68 && y <= 92)
                        {
                            writerView.IndentRight();
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Sort A->Z ↓ (X: 666 to 688)
                        if (x >= 666 && x <= 688 && y >= 68 && y <= 92)
                        {
                            SortDialogForm sortDlg = new SortDialogForm();
                            sortDlg.OnSortExecute += (asc, stype, hasHdr) =>
                            {
                                writerView.SortSelectedParagraphs(asc, stype, hasHdr);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            sortDlg.ShowDialog(parentForm);
                            return true;
                        }

                        // Show/Hide Formatting Marks Button (¶) (X: 690 to 712, Y: 68 to 92)
                        if (x >= 690 && x <= 712 && y >= 68 && y <= 92)
                        {
                            writerView.ShowFormattingMarks = !writerView.ShowFormattingMarks;
                            ShowFormattingMarks = writerView.ShowFormattingMarks;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Paragraph Alignments (Left, Center, Right, Justify) (X: 528..622)
                        int alignX = 528;
                        for (int a = 0; a < 4; a++)
                        {
                            if (x >= alignX && x <= alignX + 22 && y >= 96 && y <= 120)
                            {
                                Alignment = a;
                                writerView.ApplyAlignmentToSelectionOrParagraph(a);
                                writerView.UpdateRibbonState(this);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            alignX += 24;
                        }

                        // Line Spacing ↕≡▾ (X: 626 to 654)
                        if (x >= 626 && x <= 654 && y >= 96 && y <= 120)
