                        // Shading (X: 656 to 684)
                        if (x >= 656 && x <= 684 && y >= 96 && y <= 120)
                        {
                            Point pLoc = parentForm != null ? parentForm.PointToScreen(new Point(656, 122)) : new Point(656, 122);
                            ColorPaletteForm colDlg = new ColorPaletteForm(pLoc, false);
