                                    else if (chosen == 1) // Chọn đối tượng
                                    {
                                        writerView.IsSelectObjectsMode = !writerView.IsSelectObjectsMode;
                                    }
                                    else if (chosen == 2) // Chọn tất cả văn bản có định dạng tương tự
                                    {
                                        writerView.SelectAllTextWithSimilarFormatting();
                                    }
                                    else if (chosen == 3) // Ngăn chọn...
                                    {
                                        writerView.ShowSelectionPane = !writerView.ShowSelectionPane;
                                    }
                                    if (parentForm != null) parentForm.Invalidate();
                                });
                                selDlg.Show();
                                return true;
                            }
