                            int sIdx = StyleGalleryCardIndices[c];
                            ActiveStyleSetIndex = sIdx;
                            if (writerView != null)
                            {
                                writerView.ApplyStyleSetToDocument(sIdx, this);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                    }

                    // Style Gallery Up Button
                    if (BtnStyleGalleryUpBounds.Contains(x, y))
                    {
                        if (StyleSetScrollOffset > 0)
                        {
                            StyleSetScrollOffset--;
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }

                    // Style Gallery Down Button
                    if (BtnStyleGalleryDownBounds.Contains(x, y))
                    {
                        StyleSetScrollOffset++;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }

                    // Style Gallery More Button ▾ -> opens StyleSetsGalleryDropDownForm
                    if (BtnStyleGalleryMoreBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnStyleGalleryMoreBounds.Right - 540, BtnStyleGalleryMoreBounds.Bottom + 4)) : new Point(100, 132);
                        if (pt.X < 10) pt.X = 10;
                        Color thAccent = (ThemeColorPalette != null && ThemeColorPalette.Length > 0) ? ThemeColorPalette[0] : Color.FromArgb(68, 114, 196);
                        StyleSetsGalleryDropDownForm sDlg = new StyleSetsGalleryDropDownForm(pt, ActiveStyleSetIndex, thAccent);
                        sDlg.OnStyleSetSelected = (sIdx) =>
                        {
                            ActiveStyleSetIndex = sIdx;
                            if (writerView != null)
                            {
                                writerView.ApplyStyleSetToDocument(sIdx, this);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        sDlg.Show();
                        return true;
                    }

                    // Colors ▾
                    if (BtnColorsBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnColorsBounds.X, BtnColorsBounds.Bottom)) : new Point(BtnColorsBounds.X, 132);
                        ThemeColorsDropDownForm cDlg = new ThemeColorsDropDownForm(pt, ThemeColorPaletteName);
                        cDlg.OnPaletteSelected = (pItem) =>
                        {
                            if (writerView != null)
                            {
                                writerView.ApplyColorPaletteToDocument(pItem, this);
                            }
                            else
                            {
                                ThemeColorPalette = pItem.Colors;
                                ThemeColorPaletteName = pItem.Name;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        cDlg.OnCustomizeColorsClicked = () =>
                        {
                            using (ColorDialog cd = new ColorDialog())
                            {
                                if (cd.ShowDialog(parentForm) == DialogResult.OK)
                                {
                                    Color c = cd.Color;
                                    Color[] custColors = new Color[] {
                                        c,
                                        Color.FromArgb(Math.Min(255, (int)(c.R * 1.2f)), Math.Min(255, (int)(c.G * 1.2f)), Math.Min(255, (int)(c.B * 1.2f))),
                                        Color.FromArgb(Math.Max(0, (int)(c.R * 0.7f)), Math.Max(0, (int)(c.G * 0.7f)), Math.Max(0, (int)(c.B * 0.7f))),
                                        Color.FromArgb(255, 192, 0)
                                    };
                                    ThemeColorPaletteItem custPal = new ThemeColorPaletteItem("Tùy chỉnh", custColors);
                                    if (writerView != null)
                                    {
                                        writerView.ApplyColorPaletteToDocument(custPal, this);
                                    }
                                    else
                                    {
                                        ThemeColorPalette = custColors;
                                        ThemeColorPaletteName = "Tùy chỉnh";
                                    }
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                        };
                        cDlg.Show();
                        return true;
                    }

                    // Fonts ▾
                    if (BtnFontsBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnFontsBounds.X, BtnFontsBounds.Bottom)) : new Point(BtnFontsBounds.X, 132);
                        ThemeFontsDropDownForm fDlg = new ThemeFontsDropDownForm(pt, ThemeFontHeading);
                        fDlg.OnFontPairSelected = (fPair) =>
                        {
                            if (writerView != null)
                            {
                                writerView.ApplyFontPairToDocument(fPair, this);
                            }
                            else
                            {
                                ThemeFontHeading = fPair.HeadingFont;
                                ThemeFontBody = fPair.BodyFont;
                                SelectedFont = fPair.BodyFont;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        fDlg.OnCustomizeFontsClicked = () =>
                        {
                            Point fPt = parentForm != null ? parentForm.PointToScreen(new Point(BtnFontsBounds.X, BtnFontsBounds.Bottom)) : new Point(BtnFontsBounds.X, 132);
                            FontDropDownForm fontListDlg = new FontDropDownForm(SelectedFont, fPt, AvailableSystemFonts, Color.FromArgb(16, 110, 190));
                            fontListDlg.OnFontSelected += (fName) =>
                            {
                                ThemeFontPairItem custPair = new ThemeFontPairItem("Tùy chỉnh (" + fName + ")", fName, fName);
                                if (writerView != null)
                                {
                                    writerView.ApplyFontPairToDocument(custPair, this);
                                }
                                else
                                {
                                    ThemeFontHeading = fName;
                                    ThemeFontBody = fName;
                                    SelectedFont = fName;
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            fontListDlg.Show();
                        };
                        fDlg.Show();
                        return true;
                    }

                    // Paragraph Spacing ▾
                    if (BtnParagraphSpacingBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnParagraphSpacingBounds.X, BtnParagraphSpacingBounds.Bottom)) : new Point(BtnParagraphSpacingBounds.X, 132);
                        ParagraphSpacingDropDownForm spDlg = new ParagraphSpacingDropDownForm(pt, ParagraphSpacingPreset);
                        spDlg.OnSpacingSelected = (sp) =>
                        {
                            if (writerView != null)
                            {
                                writerView.ApplyParagraphSpacingPreset(sp, this);
                            }
                            else
                            {
                                ParagraphSpacingPreset = sp.Name;
                                LineSpacingFactor = sp.LineSpacingFactor;
                                ParagraphSpacingBefore = sp.BeforePt;
                                ParagraphSpacingAfter = sp.AfterPt;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        spDlg.OnCustomSpacingClicked = () =>
                        {
                            using (ManageStylesForm msDlg = new ManageStylesForm(
                                SelectedFont ?? ThemeFontBody,
                                FontSize,
                                CurrentFontColor,
                                LineSpacingFactor,
                                ParagraphSpacingBefore,
                                ParagraphSpacingAfter,
                                writerView != null ? writerView.CurrentAlignment : 0,
                                AvailableSystemFonts))
                            {
                                msDlg.OnApplyDefaults = (fName, fSize, fCol, lIndent, rIndent, align, beforePt, afterPt, lsFactor, spMode, isGlobal) =>
                                {
                                    SelectedFont = fName;
                                    FontSize = fSize;
                                    CurrentFontColor = fCol;
                                    LineSpacingFactor = lsFactor;
                                    ParagraphSpacingBefore = beforePt;
                                    ParagraphSpacingAfter = afterPt;

                                    if (writerView != null)
                                    {
                                        writerView.ApplyCustomParagraphDefaults(fName, fSize, fCol, align, beforePt, afterPt, lsFactor, this);
                                    }

                                    if (isGlobal)
                                    {
                                        MessageBox.Show("Đã lưu các thiết lập làm mặc định cho tất cả tài liệu mới!", "ZenQ Writer", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                    }

                                    if (parentForm != null) parentForm.Invalidate();
                                };
                                msDlg.ShowDialog(parentForm);
                            }
                        };
                        spDlg.Show();
                        return true;
                    }

                    // Effects ▾
                    if (BtnEffectsBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnEffectsBounds.X, BtnEffectsBounds.Bottom)) : new Point(BtnEffectsBounds.X, 132);
                        ThemeEffectsDropDownForm eDlg = new ThemeEffectsDropDownForm(pt, ActiveThemeEffectIndex);
                        eDlg.OnEffectSelected = (eff) =>
                        {
                            ActiveThemeEffectIndex = eff.EffectIndex;
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        eDlg.Show();
                        return true;
                    }

                    // Set as Default
                    if (BtnSetAsDefaultBounds.Contains(x, y))
                    {
                        DialogResult dr = MessageBox.Show(
                            "Bạn có muốn lưu các thiết lập Chủ đề (" + (ActiveTheme ?? "Office") + "), Phông chữ (" + (ThemeFontBody ?? SelectedFont) + "), Bảng màu (" + (ThemeColorPaletteName ?? "Office") + ") và Giãn cách đoạn hiện tại làm mẫu mặc định cho tất cả tài liệu mới không?",
                            "ZenQ Writer - Đặt làm mặc định",
                            MessageBoxButtons.YesNo,
                            MessageBoxIcon.Question);

                        if (dr == DialogResult.Yes)
                        {
                            MessageBox.Show("Đã lưu thành công bộ thiết lập làm mặc định cho các tài liệu mới!", "ZenQ Writer", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }

                    // Watermark ▾
                    if (BtnWatermarkBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnWatermarkBounds.X, BtnWatermarkBounds.Bottom)) : new Point(BtnWatermarkBounds.X, 132);
                        WatermarkDropDownForm wmDlg = new WatermarkDropDownForm(pt);
                        wmDlg.Owner = parentForm;
                        wmDlg.OnWatermarkSelected = (wmTxt, isDiag) =>
                        {
                            WatermarkText = wmTxt;
                            WatermarkIsDiagonal = isDiag;
                            if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                        };
                        wmDlg.OnCustomWatermarkClicked = () =>
                        {
                            if (parentForm != null && !parentForm.IsDisposed) { parentForm.Activate(); parentForm.BringToFront(); }
                            using (CustomWatermarkDialogForm custDlg = new CustomWatermarkDialogForm(WatermarkText, WatermarkIsDiagonal))
                            {
                                custDlg.ShowInTaskbar = false;
                                custDlg.StartPosition = FormStartPosition.CenterParent;
                                custDlg.OnApplyTextWatermark = (txt, isDiag, col, isSemi) =>
                                {
                                    WatermarkText = txt;
                                    WatermarkIsDiagonal = isDiag;
                                    WatermarkImage = null;
                                    if (writerView != null)
                                    {
                                        writerView.WatermarkImage = null;
                                    }
                                    if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                                };
                                custDlg.OnApplyPictureWatermark = (img, scale, washout) =>
                                {
                                    WatermarkText = "";
                                    WatermarkImage = img;
                                    WatermarkImageScale = scale;
                                    WatermarkWashout = washout;
                                    if (writerView != null)
                                    {
                                        writerView.WatermarkImage = img;
                                        writerView.WatermarkImageScale = scale;
                                        writerView.WatermarkWashout = washout;
                                    }
                                    if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                                };
                                custDlg.OnRemoveWatermark = () =>
                                {
                                    WatermarkText = "";
                                    WatermarkImage = null;
                                    if (writerView != null)
                                    {
                                        writerView.WatermarkImage = null;
                                    }
                                    if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                                };
                                custDlg.ShowDialog(parentForm);
                            }
                            if (parentForm != null && !parentForm.IsDisposed) { parentForm.Activate(); parentForm.BringToFront(); }
                        };
                        wmDlg.OnRemoveWatermarkClicked = () =>
                        {
                            WatermarkText = "";
                            WatermarkImage = null;
                            if (writerView != null)
                            {
                                writerView.WatermarkImage = null;
                            }
                            if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                        };
                        if (parentForm != null && !parentForm.IsDisposed) wmDlg.Show(parentForm); else wmDlg.Show();
                        return true;
                    }

                    // Page Color ▾
                    if (BtnPageColorBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnPageColorBounds.X, BtnPageColorBounds.Bottom)) : new Point(BtnPageColorBounds.X, 132);
                        PageColorDropDownForm colDlg = new PageColorDropDownForm(pt);
                        colDlg.OnColorSelected = (c) =>
                        {
                            PageBgColor = c;
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        colDlg.OnNoColorSelected = () =>
                        {
                            PageBgColor = Color.White;
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        colDlg.OnMoreColorsClicked = () =>
                        {
                            using (ColorDialog cd = new ColorDialog())
                            {
                                cd.Color = PageBgColor;
                                if (cd.ShowDialog(parentForm) == DialogResult.OK)
                                {
                                    PageBgColor = cd.Color;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                        };
                        colDlg.Show();
                        return true;
                    }

                    // Page Borders
                    if (BtnPageBordersBounds.Contains(x, y))
                    {
                        using (PageBordersForm pbDlg = new PageBordersForm(HasPageBorder, PageBorderColor, PageBorderWidth))
                        {
                            if (pbDlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                HasPageBorder = pbDlg.HasBorder;
                                PageBorderColor = pbDlg.BorderColor;
                                PageBorderWidth = pbDlg.BorderWidth;
                                PageBorderStyleType = pbDlg.BorderStyleType;
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                        return true;
                    }

                    return true;
                }
                else if (curTab == "Bố trí") // Bố trí (Layout)
                {
                    // 1. Nhóm Thiết lập trang
                    if (BtnMarginsBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnMarginsBounds.X, BtnMarginsBounds.Bottom)) : new Point(BtnMarginsBounds.X, 130);
                        MarginsDropDownForm dropDlg = new MarginsDropDownForm(pt, MarginMode);
                        dropDlg.OnMarginPresetSelected += (mode) =>
                        {
                            MarginMode = mode;
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        dropDlg.OnCustomMarginsClicked += () =>
                        {
                            float top = GetEffectiveTopMarginInches();
                            float bottom = top;
                            float left = GetEffectiveLeftMarginInches();
                            float right = left;

                            using (PageSetupForm pageSetupDlg = new PageSetupForm(top, bottom, left, right, IsLandscape))
                            {
                                pageSetupDlg.OnApply += () =>
                                {
                                    CustomTopMargin = pageSetupDlg.TopMargin;
                                    CustomBottomMargin = pageSetupDlg.BottomMargin;
                                    CustomLeftMargin = pageSetupDlg.LeftMargin;
                                    CustomRightMargin = pageSetupDlg.RightMargin;
                                    MarginMode = 4; // Custom
                                    IsLandscape = pageSetupDlg.IsLandscape;
                                    if (parentForm != null) parentForm.Invalidate();
                                };

                                if (pageSetupDlg.ShowDialog(parentForm) == DialogResult.OK)
                                {
                                    CustomTopMargin = pageSetupDlg.TopMargin;
                                    CustomBottomMargin = pageSetupDlg.BottomMargin;
                                    CustomLeftMargin = pageSetupDlg.LeftMargin;
                                    CustomRightMargin = pageSetupDlg.RightMargin;
                                    MarginMode = 4; // Custom
                                    IsLandscape = pageSetupDlg.IsLandscape;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                        };
                        dropDlg.Show();
                        return true;
                    }

                    if (BtnOrientationBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnOrientationBounds.X, BtnOrientationBounds.Bottom)) : new Point(BtnOrientationBounds.X, 130);
                        ShowOrientationPopupMenu(pt, parentForm);
                        return true;
                    }

                    if (BtnPageSizeBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnPageSizeBounds.X, BtnPageSizeBounds.Bottom)) : new Point(BtnPageSizeBounds.X, 130);
                        ShowPageSizePopupMenu(pt, parentForm);
                        return true;
                    }

                    if (BtnPageSetupLauncherBounds.Contains(x, y))
                    {
                        float top = GetEffectiveTopMarginInches();
                        using (PageSetupForm pageSetupDlg = new PageSetupForm(top, top, GetEffectiveLeftMarginInches(), GetEffectiveRightMarginInches(), IsLandscape))
                        {
                            if (pageSetupDlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                IsLandscape = pageSetupDlg.IsLandscape;
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                        return true;
                    }

                    if (BtnColumnsBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnColumnsBounds.X, BtnColumnsBounds.Bottom)) : new Point(BtnColumnsBounds.X, 130);
                        ShowColumnsPopupMenu(pt, parentForm);
                        return true;
                    }

                    if (BtnBreaksBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnBreaksBounds.X, BtnBreaksBounds.Bottom)) : new Point(BtnBreaksBounds.X, 90);
                        ShowBreaksPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnLineNumbersBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnLineNumbersBounds.X, BtnLineNumbersBounds.Bottom)) : new Point(BtnLineNumbersBounds.X, 110);
                        ShowLineNumbersPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnHyphenationBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnHyphenationBounds.X, BtnHyphenationBounds.Bottom)) : new Point(BtnHyphenationBounds.X, 130);
                        ShowHyphenationPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    // 2. Nhóm Đoạn văn (Paragraph)
                    if (SpinIndentLeftUpBounds.Contains(x, y)) { ParagraphIndentLeft = (float)Math.Round(Math.Min(5.0f, ParagraphIndentLeft + 0.1f), 1); if (parentForm != null) parentForm.Invalidate(); return true; }
                    if (SpinIndentLeftDownBounds.Contains(x, y)) { ParagraphIndentLeft = (float)Math.Round(Math.Max(0.0f, ParagraphIndentLeft - 0.1f), 1); if (parentForm != null) parentForm.Invalidate(); return true; }

                    if (SpinIndentRightUpBounds.Contains(x, y)) { ParagraphIndentRight = (float)Math.Round(Math.Min(5.0f, ParagraphIndentRight + 0.1f), 1); if (parentForm != null) parentForm.Invalidate(); return true; }
                    if (SpinIndentRightDownBounds.Contains(x, y)) { ParagraphIndentRight = (float)Math.Round(Math.Max(0.0f, ParagraphIndentRight - 0.1f), 1); if (parentForm != null) parentForm.Invalidate(); return true; }

                    if (SpinSpacingBeforeUpBounds.Contains(x, y)) { ParagraphSpacingBefore = Math.Min(72f, ParagraphSpacingBefore + 6f); if (parentForm != null) parentForm.Invalidate(); return true; }
                    if (SpinSpacingBeforeDownBounds.Contains(x, y)) { ParagraphSpacingBefore = Math.Max(0f, ParagraphSpacingBefore - 6f); if (parentForm != null) parentForm.Invalidate(); return true; }

                    if (SpinSpacingAfterUpBounds.Contains(x, y)) { ParagraphSpacingAfter = Math.Min(72f, ParagraphSpacingAfter + 6f); if (parentForm != null) parentForm.Invalidate(); return true; }
                    if (SpinSpacingAfterDownBounds.Contains(x, y)) { ParagraphSpacingAfter = Math.Max(0f, ParagraphSpacingAfter - 6f); if (parentForm != null) parentForm.Invalidate(); return true; }

                    if (BtnParagraphLauncherBounds.Contains(x, y))
                    {
                        float curLineSp = writerView != null ? writerView.GetCurrentParagraphLineSpacing() : 1.15f;
                        int curAlign = Alignment;
                        int pStart = writerView != null ? writerView.GetCurrentParagraphStart() : 0;
                        float curLeft = writerView != null ? writerView.GetLeftIndent(pStart) : 0f;
                        float curRight = writerView != null ? writerView.GetRightIndent(pStart) : 0f;
                        float curFirst = writerView != null ? writerView.GetFirstLineIndent(pStart) : 0f;
                        float curHang = writerView != null ? writerView.GetHangingIndent(pStart) : 0f;
                        using (OfficeParagraphDialogForm paraDlg = new OfficeParagraphDialogForm(curAlign, curLineSp, ParagraphSpacingBefore, ParagraphSpacingAfter, curLeft, curRight, curFirst, curHang))
                        {
                            if (paraDlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                Alignment = paraDlg.AlignmentResult;
                                ParagraphSpacingBefore = paraDlg.SpaceBeforeResult;
                                ParagraphSpacingAfter = paraDlg.SpaceAfterResult;
                                if (writerView != null)
                                {
                                    writerView.SetParagraphAlignment(paraDlg.AlignmentResult);
                                    writerView.SetLineSpacing(paraDlg.LineSpacingResult);
                                    writerView.ApplyParagraphIndents(paraDlg.LeftIndentResult, paraDlg.RightIndentResult, paraDlg.FirstLineIndentResult, paraDlg.HangingIndentResult);
                                    writerView.UpdateRibbonState(this);
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                        return true;
                    }

                    // 3. Nhóm Sắp xếp (Arrange)
                    if (BtnPositionBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnPositionBounds.X, BtnPositionBounds.Bottom)) : new Point(BtnPositionBounds.X, 130);
                        ShowPositionPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnWrapTextBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnWrapTextBounds.X, BtnWrapTextBounds.Bottom)) : new Point(BtnWrapTextBounds.X, 130);
                        ShowWrapTextPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnBringForwardBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnBringForwardBounds.X, BtnBringForwardBounds.Bottom)) : new Point(BtnBringForwardBounds.X, 130);
                        ShowBringForwardPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnSendBackwardBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnSendBackwardBounds.X, BtnSendBackwardBounds.Bottom)) : new Point(BtnSendBackwardBounds.X, 130);
                        ShowSendBackwardPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    // Ngăn Lựa chọn (Selection Pane) -> Toggle Hiện/Ẩn bảng bên phải chuẩn Microsoft Word
                    if (BtnSelectionPaneBounds.Contains(x, y))
                    {
                        if (writerView != null)
                        {
                            writerView.ShowSelectionPane = !writerView.ShowSelectionPane;
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }

                    if (BtnAlignBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnAlignBounds.X, BtnAlignBounds.Bottom)) : new Point(BtnAlignBounds.X, 90);
                        ShowAlignPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnGroupBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnGroupBounds.X, BtnGroupBounds.Bottom)) : new Point(BtnGroupBounds.X, 110);
                        ShowGroupPopupMenu(pt, writerView, parentForm);
                        return true;
                    }

                    if (BtnRotateBounds.Contains(x, y))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(BtnRotateBounds.X, BtnRotateBounds.Bottom)) : new Point(BtnRotateBounds.X, 130);
                        ShowRotatePopupMenu(pt, writerView, parentForm);
                        return true;
                    }
                }
                else if (curTab == "Tham chiếu") // Tham chiếu (References)
                {
                    if (writerView != null)
                    {
                        // 1. Nhóm Mục lục (Table of Contents)
                        if (x >= 14 && x <= 82) // Mục lục tự động ▾
                        {
                            using (TableOfContentsForm tocDlg = new TableOfContentsForm(writerView))
                            {
                                if (tocDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(tocDlg.GeneratedTOC))
                                {
                                    writerView.InsertText(tocDlg.GeneratedTOC);
                                }
                            }
                        }
                        else if (x >= 86 && x <= 214 && y >= 68 && y <= 96) // Thêm văn bản ▾ (Heading Levels Popup)
                        {
                            ContextMenuStrip addTxtMenu = new ContextMenuStrip();
                            ToolStripMenuItem miL1 = new ToolStripMenuItem("Mức 1 (Heading 1)");
                            miL1.Click += (s, ev) => { writerView.ApplyHeadingStyle(1); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miL2 = new ToolStripMenuItem("Mức 2 (Heading 2)");
                            miL2.Click += (s, ev) => { writerView.ApplyHeadingStyle(2); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miL3 = new ToolStripMenuItem("Mức 3 (Heading 3)");
                            miL3.Click += (s, ev) => { writerView.ApplyHeadingStyle(3); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miNorm = new ToolStripMenuItem("Không hiển thị trong Mục lục (Văn bản thường)");
                            miNorm.Click += (s, ev) => { writerView.ApplyHeadingStyle(0); if (parentForm != null) parentForm.Invalidate(); };
                            addTxtMenu.Items.AddRange(new ToolStripItem[] { miL1, miL2, miL3, new ToolStripSeparator(), miNorm });
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(86, 96)) : new Point(86, 96);
                            addTxtMenu.Show(pt);
                            return true;
                        }
                        else if (x >= 86 && x <= 214 && y > 96 && y <= 128) // Cập nhật bảng (Update TOC)
                        {
                            writerView.UpdateTableOfContents();
                        }
                        // 2. Nhóm Chú thích (Footnotes & Endnotes)
                        else if (x >= 232 && x <= 304) // Chèn Footnote (AB¹)
                        {
                            writerView.InsertFootnote(null, true);
                        }
                        else if (x >= 308 && x <= 432 && y >= 68 && y <= 96) // Chèn Endnote ([i])
                        {
                            writerView.InsertEndnote(null, true);
                        }
                        else if (x >= 308 && x <= 432 && y > 96 && y <= 128) // Chú thích tiếp theo ▾
                        {
                            ContextMenuStrip fnNavMenu = new ContextMenuStrip();
                            ToolStripMenuItem miNextFn = new ToolStripMenuItem("Chú thích chân trang tiếp theo (Next Footnote)");
                            miNextFn.Click += (s, ev) => { writerView.GoToNextFootnote(false, false); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miPrevFn = new ToolStripMenuItem("Chú thích chân trang trước đó (Previous Footnote)");
                            miPrevFn.Click += (s, ev) => { writerView.GoToNextFootnote(false, true); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miNextEn = new ToolStripMenuItem("Chú thích cuối tài liệu tiếp theo (Next Endnote)");
                            miNextEn.Click += (s, ev) => { writerView.GoToNextFootnote(true, false); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miPrevEn = new ToolStripMenuItem("Chú thích cuối tài liệu trước đó (Previous Endnote)");
                            miPrevEn.Click += (s, ev) => { writerView.GoToNextFootnote(true, true); if (parentForm != null) parentForm.Invalidate(); };
                            ToolStripMenuItem miManage = new ToolStripMenuItem("📋 Danh sách & Quản lý chú thích...");
                            miManage.Click += (s, ev) => { writerView.ShowFootnotesList(); if (parentForm != null) parentForm.Invalidate(); };

                            fnNavMenu.Items.AddRange(new ToolStripItem[] { miNextFn, miPrevFn, new ToolStripSeparator(), miNextEn, miPrevEn, new ToolStripSeparator(), miManage });
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(308, 128)) : new Point(308, 128);
                            fnNavMenu.Show(pt);
                            return true;
                        }
                        else if (x >= 436 && x <= 504) // Hiện chú thích
                        {
                            writerView.ShowFootnotesList();
                        }
                        // 3. Nhóm Trích dẫn & Nguồn (Citations & Bibliography)
                        else if (x >= 522 && x <= 596) // Chèn Trích dẫn ▾
                        {
                            ContextMenuStrip citMenu = new ContextMenuStrip();
                            if (writerView.CitationSources != null && writerView.CitationSources.Count > 0)
                            {
                                foreach (var src in writerView.CitationSources)
                                {
                                    var itemSrc = src;
                                    ToolStripMenuItem miSrc = new ToolStripMenuItem(string.Format("({0}, {1}) - {2}", itemSrc.Author, itemSrc.Year, itemSrc.Title));
                                    miSrc.Click += (s, ev) => {
                                        writerView.InsertCitationFromSource(itemSrc);
                                        if (parentForm != null) parentForm.Invalidate();
                                    };
                                    citMenu.Items.Add(miSrc);
                                }
                                citMenu.Items.Add(new ToolStripSeparator());
                            }
                            ToolStripMenuItem miAddSrc = new ToolStripMenuItem("➕ Quản lý & Thêm nguồn trích dẫn...");
                            miAddSrc.Click += (s, ev) => {
                                using (ManageSourcesForm srcDlg = new ManageSourcesForm(writerView))
                                {
                                    srcDlg.ShowDialog(parentForm);
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            citMenu.Items.Add(miAddSrc);
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(522, 128)) : new Point(522, 128);
                            citMenu.Show(pt);
                            return true;
                        }
                        else if (x >= 600 && x <= 728 && y >= 68 && y <= 96) // Quản lý nguồn
                        {
                            using (ManageSourcesForm srcDlg = new ManageSourcesForm(writerView))
                            {
                                srcDlg.ShowDialog(parentForm);
                            }
                        }
                        else if (x >= 600 && x <= 728 && y > 96 && y <= 128) // Kiểu trích dẫn ▾
                        {
                            ContextMenuStrip styleMenu = new ContextMenuStrip();
                            string[] styles = new string[] { "APA (Tái bản lần 7)", "MLA (Tái bản lần 9)", "Chicago (Tái bản lần 17)", "IEEE", "Harvard" };
                            string[] shortCodes = new string[] { "APA", "MLA", "Chicago", "IEEE", "Harvard" };
                            for (int i = 0; i < styles.Length; i++)
                            {
                                string sCode = shortCodes[i];
                                ToolStripMenuItem miSt = new ToolStripMenuItem(styles[i]);
                                miSt.Checked = (writerView.CurrentCitationStyle == sCode);
                                miSt.Click += (s, ev) => {
                                    writerView.CurrentCitationStyle = sCode;
                                    if (parentForm != null) parentForm.Invalidate();
                                };
                                styleMenu.Items.Add(miSt);
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(600, 128)) : new Point(600, 128);
                            styleMenu.Show(pt);
                            return true;
                        }
                        else if (x >= 734 && x <= 804) // Thư mục tài liệu tham khảo ▾
                        {
                            writerView.InsertBibliography();
                        }
                        // 4. Nhóm Phụ đề & Bảng biểu (Captions)
                        else if (x >= 822 && x <= 892) // Chèn Phụ đề
                        {
                            using (InsertCaptionForm capDlg = new InsertCaptionForm(writerView))
                            {
                                if (capDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(capDlg.GeneratedCaption))
                                {
                                    writerView.InsertText("\n" + capDlg.GeneratedCaption + "\n");
                                }
                            }
                        }
                        else if (x >= 896 && x <= 1028 && y >= 68 && y <= 96) // Chèn bảng hình ảnh
                        {
                            writerView.InsertTableOfFigures();
                        }
                        else if (x >= 896 && x <= 1028 && y > 96 && y <= 128) // Cập nhật bảng hình ảnh
                        {
                            writerView.InsertTableOfFigures();
                        }
                        else if (x >= 1034 && x <= 1106) // Tham chiếu chéo
                        {
                            using (CrossReferenceForm crDlg = new CrossReferenceForm(writerView))
                            {
                                if (crDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(crDlg.ReferenceText))
                                {
                                    writerView.InsertText(crDlg.ReferenceText);
                                }
                            }
                        }
                        // 5. Nhóm Chỉ mục (Index)
                        else if (x >= 1124 && x <= 1246 && y >= 68 && y <= 96) // Đánh dấu mục
                        {
                            using (MarkIndexEntryForm idxDlg = new MarkIndexEntryForm(writerView))
                            {
                                if (idxDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(idxDlg.MarkedEntryField))
                                {
                                    writerView.InsertText(idxDlg.MarkedEntryField);
                                }
                            }
                        }
                        else if (x >= 1124 && x <= 1246 && y > 96 && y <= 128) // Chèn chỉ mục
                        {
                            writerView.InsertIndexTable();
                        }
                        else if (x >= 1250 && x <= 1326) // Cập nhật chỉ mục (Vẽ tại curX = 1250, rộng 76 -> 1250..1326)
                        {
                            writerView.InsertIndexTable();
                        }

                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                else if (curTab == "Gửi thư")
                {
                    return HandleTabGuiThuClick(x, y, writerView, parentForm);
                }
                else if (curTab == "Xem lại")
                {
                    return HandleTabXemLaiClick(x, y, writerView, parentForm);
                }
                else if (curTab == "Hiển thị") // Hiển thị (View)
                {
                    if (writerView != null)
                    {
                        // 1. Nhóm Chế độ xem
                        if (x >= 14 && x <= 80) // Bố trí In
                        {
                            writerView.ViewMode = 1;
                        }
                        else if (x >= 84 && x <= 150) // Chế độ Đọc
                        {
                            writerView.ViewMode = 0;
                            writerView.ScrollY = 0;
                            writerView.TargetScrollY = 0;
                            writerView.ReadModePageIndex = Math.Max(0, Math.Min(writerView.TotalPageCount - 1, writerView.CurrentActivePage - 1));
                        }
                        else if (x >= 154 && x <= 220) // Bố trí Web
                        {
                            writerView.ViewMode = 2;
                        }
                        else if (x >= 224 && x <= 330 && y >= 68 && y <= 96) // Đề cương
                        {
                            writerView.ViewMode = 1;
                            writerView.ShowNavigationPane = true;
                            writerView.NavActiveTab = 0;
                            writerView.PerformNavSearch();
                        }
                        else if (x >= 224 && x <= 330 && y > 96 && y <= 128) // Bản nháp
                        {
                            writerView.ViewMode = 1;
                        }
                        else if (x >= 334 && x <= 400) // Tập trung (Focus Mode)
                        {
                            if (parentForm != null)
                            {
                                if (parentForm.FormBorderStyle == FormBorderStyle.None)
                                {
                                    parentForm.FormBorderStyle = FormBorderStyle.Sizable;
                                    parentForm.WindowState = FormWindowState.Normal;
                                }
                                else
                                {
                                    parentForm.FormBorderStyle = FormBorderStyle.None;
                                    parentForm.WindowState = FormWindowState.Maximized;
                                }
                            }
                        }
                        // 2. Nhóm Hiển thị
                        else if (x >= 418 && x <= 482) // Thước kẻ (Ruler)
                        {
                            ShowRuler = !ShowRuler;
                        }
                        else if (x >= 486 && x <= 604 && y >= 68 && y <= 96) // Đơn vị đo (cm / inch)
                        {
                            writerView.CurrentRulerUnit = (writerView.CurrentRulerUnit == RulerUnit.Centimeters) ? RulerUnit.Inches : RulerUnit.Centimeters;
                        }
                        else if (x >= 486 && x <= 604 && y > 96 && y <= 128) // Đường lưới (Gridlines)
                        {
                            ShowGridlines = !ShowGridlines;
                            if (writerView != null) writerView.ShowDocumentGridlines = ShowGridlines;
                        }
                        else if (x >= 608 && x <= 676) // Ngăn điều hướng (Navigation Pane)
                        {
                            writerView.ShowNavigationPane = !writerView.ShowNavigationPane;
                            if (writerView.ShowNavigationPane)
                            {
                                if (string.IsNullOrEmpty(writerView.NavSearchQuery))
                                    writerView.NavActiveTab = 0;
                                writerView.PerformNavSearch();
                            }
                        }
                        // 3. Nhóm Thu phóng
                        else if (x >= 692 && x <= 754) // 100% Zoom
                        {
                            writerView.ZoomLevel = 1.0f;
                        }
                        else if (x >= 758 && x <= 870 && y >= 68 && y <= 96) // Một trang
                        {
                            writerView.ZoomLevel = 0.85f;
                        }
                        else if (x >= 758 && x <= 870 && y > 96 && y <= 128) // Nhiều trang
                        {
                            writerView.ZoomLevel = 0.65f;
                        }
                        else if (x >= 874 && x <= 990 && y >= 68 && y <= 96) // Độ rộng trang
                        {
                            writerView.ZoomLevel = 1.35f;
                        }
                        else if (x >= 874 && x <= 990 && y > 96 && y <= 128) // Thu phóng ▾
                        {
                            ContextMenuStrip zoomMenu = new ContextMenuStrip();
                            float[] zoomLevels = new float[] { 0.5f, 0.75f, 1.0f, 1.25f, 1.5f, 2.0f };
                            string[] zoomNames = new string[] { "50%", "75%", "100%", "125%", "150%", "200%" };
                            for (int i = 0; i < zoomLevels.Length; i++)
                            {
                                float zVal = zoomLevels[i];
                                ToolStripMenuItem miZ = new ToolStripMenuItem(zoomNames[i]);
                                miZ.Checked = (Math.Abs(writerView.ZoomLevel - zVal) < 0.05f);
                                miZ.Click += (s, ev) => {
                                    writerView.ZoomLevel = zVal;
                                    if (parentForm != null) parentForm.Invalidate();
                                };
                                zoomMenu.Items.Add(miZ);
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(874, 128)) : new Point(874, 128);
                            zoomMenu.Show(pt);
                            return true;
                        }
                        // 4. Nhóm Nền & Màu trang
                        else if (x >= 1008 && x <= 1080) // Màu trang ▾
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(1008, 132)) : new Point(1008, 132);
                            PageColorDropDownForm colDlg = new PageColorDropDownForm(pt);
                            colDlg.OnColorSelected = (c) =>
                            {
                                PageBgColor = c;
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            colDlg.OnNoColorSelected = () =>
                            {
                                PageBgColor = Color.White;
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            colDlg.OnMoreColorsClicked = () =>
                            {
                                using (ColorDialog cd = new ColorDialog())
                                {
                                    cd.Color = PageBgColor;
                                    if (cd.ShowDialog(parentForm) == DialogResult.OK)
                                    {
                                        PageBgColor = cd.Color;
                                        if (parentForm != null) parentForm.Invalidate();
                                    }
                                }
                            };
                            colDlg.Show();
                            return true;
                        }
                        // 5. Nhóm Cửa sổ & Ngăn
                        else if (x >= 1096 && x <= 1164) // Ngăn Lựa chọn (Selection Pane)
                        {
                            writerView.ShowSelectionPane = !writerView.ShowSelectionPane;
                        }
                        else if (x >= 1168 && x <= 1278 && y >= 68 && y <= 96) // Cửa sổ mới
                        {
                            DocTabs.Add(new DocTab("Tài liệu " + (DocTabs.Count + 1), OfficeAppMode.Writer, true));
                        }
                        else if (x >= 1168 && x <= 1278 && y > 96 && y <= 128) // Chia tách
                        {
                            MessageBox.Show("Chế độ chia tách cửa sổ (Split View) đã được kích hoạt!", "ZenQ Writer", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }

                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                else if (curTab == "Thiết kế Bảng")
                {
                    return HandleTabTableDesignClick(x, y, writerView, parentForm);
                }
                else if (curTab == "Bố trí Bảng")
                {
                    return HandleTabTableLayoutClick(x, y, writerView, parentForm);
                }
                else if (curTab == "Thiết kế SmartArt")
                {
                    return HandleSmartArtDesignClick(x, y, writerView, parentForm);
                }
                else if (curTab == "Định dạng")
                {
                    return HandleSmartArtFormatClick(x, y, writerView, parentForm);
                }
                else if (ActiveRibbonTab >= 6 || !string.IsNullOrEmpty(curTab))
                {
                    if (writerView != null && writerView.ActiveShape != null && (writerView.ActiveShape.ShapeType == "SmartArt" || !string.IsNullOrEmpty(writerView.ActiveShape.SmartArtType)))
                    {
                        return HandleSmartArtDesignClick(x, y, writerView, parentForm);
                    }
                    else if (writerView != null && writerView.IsChartSelected)
                    {
                        if (x >= 16 && x <= 88) { writerView.ActiveChart.ShowElementsMenu = !writerView.ActiveChart.ShowElementsMenu; if (parentForm != null) parentForm.Invalidate(); return true; }
                        else if (x >= 94 && x <= 166) { writerView.ActiveChart.ShowElementsMenu = true; if (parentForm != null) parentForm.Invalidate(); return true; }
                        else if (x >= 172 && x <= 244) { writerView.ActiveChart.ColorPaletteIndex = (writerView.ActiveChart.ColorPaletteIndex + 1) % 3; if (parentForm != null) parentForm.Invalidate(); return true; }
                        else if (x >= 256 && x <= 460) { int sIdx = (x - 256) / 68; writerView.ActiveChart.StyleThemeIndex = Math.Max(0, Math.Min(2, sIdx)); if (parentForm != null) parentForm.Invalidate(); return true; }
                        else if (x >= 472 && x <= 554)
                        {
                            if (writerView.ActiveChart != null && writerView.ActiveChart.Data != null)
                            {
                                writerView.SaveUndoState();
                                writerView.ActiveChart.Data.SwitchRowColumn();
                                writerView.InvalidateLayoutAndTextCache();
                                if (parentForm != null) parentForm.Invalidate();
                            }
                            return true;
                        }
                        else if (x >= 560 && x <= 652) { writerView.OpenChartExcelEditor(writerView.ActiveChart); return true; }
                        else if (x >= 658 && x <= 732)
                        {
                            writerView.InvalidateLayoutAndTextCache();
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        else if (x >= 744 && x <= 836)
                        {
                            using (InsertChartForm chartDlg = new InsertChartForm())
                            {
                                if (chartDlg.ShowDialog(parentForm) == DialogResult.OK)
                                {
                                    writerView.ActiveChart.Data.ChartType = chartDlg.SelectedChartType;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                            return true;
                        }
                        else if (x >= 852)
                        {
                            writerView.ActiveChart.IsSelected = false;
                            writerView.ActiveChart = null;
                            ActiveRibbonTab = 0;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        return true;
                    }
                    else if (writerView != null && writerView.ActiveShape != null && writerView.ActiveShape.ShapeType == "Image")
                    {
                        var sh = writerView.ActiveShape;

                        // 1. Nhóm Điều chỉnh (Adjust) (X: 14 -> 264)
                        if (x >= 14 && x <= 78) // Xóa nền (Remove Background)
                        {
                            sh.FillColor = Color.Transparent;
                            sh.PictureStylePreset = 0;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 82 && x <= 168)
                        {
                            if (y >= 68 && y <= 88) // Chỉnh sửa (Corrections)
                            {
                                sh.PictureBrightness = (sh.PictureBrightness + 0.2f) > 0.6f ? -0.2f : sh.PictureBrightness + 0.2f;
                            }
                            else if (y >= 89 && y <= 108) // Màu sắc (Color)
                            {
                                sh.PictureGrayscale = !sh.PictureGrayscale;
                            }
                            else if (y >= 109 && y <= 128) // Hiệu ứng nghệ thuật (Artistic)
                            {
                                sh.PictureSepia = !sh.PictureSepia;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 172 && x <= 258)
                        {
                            if (y >= 68 && y <= 88) // Độ trong suốt (Transparency)
                            {
                                sh.PictureTransparency = (sh.PictureTransparency + 0.25f) > 0.75f ? 0f : sh.PictureTransparency + 0.25f;
                            }
                            else if (y >= 89 && y <= 108) // Đổi ảnh (Change Picture)
                            {
                                using (OpenFileDialog ofd = new OpenFileDialog())
                                {
                                    ofd.Filter = "Hình ảnh (*.png;*.jpg;*.jpeg;*.bmp;*.gif)|*.png;*.jpg;*.jpeg;*.bmp;*.gif|Tất cả tệp (*.*)|*.*";
                                    ofd.Title = "Chọn hình ảnh thay thế";
                                    if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                                    {
                                        sh.ImagePath = ofd.FileName;
                                        try
                                        {
                                            using (var temp = Image.FromFile(ofd.FileName))
                                            {
                                                sh.CachedImage = new Bitmap(temp);
                                                float ratio = (float)temp.Width / Math.Max(1, temp.Height);
                                                if (ratio >= 1.0f)
                                                {
                                                    sh.BaseWidth = Math.Min(480, Math.Max(120, temp.Width));
                                                    sh.BaseHeight = (int)(sh.BaseWidth / ratio);
                                                }
                                                else
                                                {
                                                    sh.BaseHeight = Math.Min(380, Math.Max(120, temp.Height));
                                                    sh.BaseWidth = (int)(sh.BaseHeight * ratio);
                                                }
                                            }
                                        }
                                        catch { }
                                    }
                                }
                            }
                            else if (y >= 109 && y <= 128) // Đặt lại ảnh (Reset Picture)
                            {
                                sh.PictureStylePreset = 0;
                                sh.PictureBrightness = 0;
                                sh.PictureContrast = 0;
                                sh.PictureGrayscale = false;
                                sh.PictureSepia = false;
                                sh.PictureTransparency = 0;
                                sh.OutlineWidth = 0;
                                sh.OutlineColor = Color.Transparent;
                                sh.HasShadow = false;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // 2. Nhóm Kiểu hình ảnh (Picture Styles) (X: 276 -> 646)
                        if (x >= 276 && x <= 552)
                        {
                            int pIdx = (x - 276) / 46 + 1;
                            if (pIdx >= 1 && pIdx <= 6)
                            {
                                sh.PictureStylePreset = (sh.PictureStylePreset == pIdx) ? 0 : pIdx;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        if (x >= 556 && x <= 648)
                        {
                            if (y >= 68 && y <= 88) // Viền ảnh (Picture Border)
                            {
                                if (sh.OutlineWidth == 0) { sh.OutlineWidth = 2.0f; sh.OutlineColor = Color.FromArgb(0, 120, 215); }
                                else if (sh.OutlineColor == Color.FromArgb(0, 120, 215)) { sh.OutlineColor = Color.Black; sh.OutlineWidth = 3.0f; }
                                else if (sh.OutlineColor == Color.Black) { sh.OutlineColor = Color.FromArgb(217, 119, 6); }
                                else { sh.OutlineWidth = 0; sh.OutlineColor = Color.Transparent; }
                            }
                            else if (y >= 89 && y <= 108) // Hiệu ứng ảnh (Picture Effects)
                            {
                                sh.HasShadow = !sh.HasShadow;
                            }
                            else if (y >= 109 && y <= 128) // Bố cục ảnh (Picture Layout)
                            {
                                sh.WrapMode = (sh.WrapMode + 1) % 7;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // 3. Nhóm Tiếp cận (Alt Text) (X: 660 -> 742)
                        if (x >= 660 && x <= 742)
                        {
                            using (Form altDlg = new Form())
                            {
                                altDlg.Text = "Văn bản thay thế (Alt Text)";
                                altDlg.Size = new Size(440, 260);
                                altDlg.StartPosition = FormStartPosition.CenterParent;
                                altDlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                                altDlg.MaximizeBox = false;
                                altDlg.MinimizeBox = false;

                                Label lbl = new Label { Text = "Mô tả văn bản thay thế cho hình ảnh (hỗ trợ đọc màn hình):", Location = new Point(14, 14), AutoSize = true };
                                TextBox txt = new TextBox { Multiline = true, Text = sh.AltText ?? "", Location = new Point(16, 38), Size = new Size(390, 110), ScrollBars = ScrollBars.Vertical };
                                Button btnSave = new Button { Text = "Lưu lại", DialogResult = DialogResult.OK, Location = new Point(236, 168), Size = new Size(84, 28) };
                                Button btnCancel = new Button { Text = "Hủy bỏ", DialogResult = DialogResult.Cancel, Location = new Point(326, 168), Size = new Size(80, 28) };

                                altDlg.Controls.AddRange(new Control[] { lbl, txt, btnSave, btnCancel });
                                altDlg.AcceptButton = btnSave;
                                altDlg.CancelButton = btnCancel;

                                if (altDlg.ShowDialog(parentForm) == DialogResult.OK)
                                {
                                    writerView.SaveUndoState();
                                    sh.AltText = txt.Text.Trim();
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                            return true;
                        }

                        // 4. Nhóm Sắp xếp (Arrange) (X: 754 -> 950)
                        if (x >= 754 && x <= 824) // Ngắt dòng
                        {
                            sh.WrapMode = (sh.WrapMode + 1) % 7;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        if (x >= 828 && x <= 950)
                        {
                            if (y >= 68 && y <= 88) // Lên trước
                            {
                                int idx = writerView.DocumentShapes.IndexOf(sh);
                                if (idx >= 0 && idx < writerView.DocumentShapes.Count - 1)
                                {
                                    writerView.DocumentShapes.RemoveAt(idx);
                                    writerView.DocumentShapes.Add(sh);
                                }
                            }
                            else if (y >= 89 && y <= 108) // Về sau
                            {
                                int idx = writerView.DocumentShapes.IndexOf(sh);
                                if (idx > 0)
                                {
                                    writerView.DocumentShapes.RemoveAt(idx);
                                    writerView.DocumentShapes.Insert(0, sh);
                                }
                            }
                            else if (y >= 109 && y <= 128) // Xoay hình
                            {
                                sh.RotationAngle = (sh.RotationAngle + 90f) % 360f;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // 5. Nhóm Kích cỡ (Size) (X: 960 -> 1130)
                        if (x >= 960 && x <= 1022) // Cắt ảnh (Crop)
                        {
                            MessageBox.Show("Chế độ Cắt ảnh (Crop) đã sẵn sàng! Bạn có thể kéo các điểm neo để điều chỉnh khung ảnh.", "ZENQ OFFICE", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            return true;
                        }
                        if (x >= 1026 && x <= 1130)
                        {
                            if (y >= 68 && y <= 95) // Height +/-
                            {
                                if (x >= 1100) sh.HeightDelta = Math.Max(-sh.BaseHeight + 20, sh.HeightDelta - 15);
                                else sh.HeightDelta += 15;
                            }
                            else if (y >= 96 && y <= 128) // Width +/-
                            {
                                if (x >= 1100) sh.WidthDelta = Math.Max(-sh.BaseWidth + 20, sh.WidthDelta - 15);
                                else sh.WidthDelta += 15;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Close button (X: 1140..1232)
                        if (x >= 1140)
                        {
                            sh.IsSelected = false;
                            writerView.ActiveShape = null;
                            ActiveRibbonTab = 0;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        return true;
                    }
                    else if (writerView != null && writerView.IsShapeSelected)
                    {
                        var sh = writerView.ActiveShape;
                        // 1. Nhóm Chèn hình dạng
                        if (x >= 16 && x <= 95) // Quick palette click
                        {
                            int qi = ((x - 22) / 22) + ((y - 70) / 18) * 3;
                            string[] qTypes = new string[] { "TextBox", "Line", "ArrowLine", "Rectangle", "Oval", "Triangle", "RightArrow", "Star5", "Cloud" };
                            if (qi >= 0 && qi < qTypes.Length)
                            {
                                writerView.InsertShape(qTypes[qi]);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        else if (x >= 96 && x <= 180) // Đổi hình dạng
                        {
                            Point menuPt = parentForm != null ? parentForm.PointToScreen(new Point(96, 130)) : new Point(96, 130);
                            ShapeGalleryPopup popup = new ShapeGalleryPopup();
                            popup.Location = menuPt;
                            popup.OnShapeSelected = (sType) =>
                            {
                                if (writerView.ActiveShape != null)
                                {
                                    writerView.ActiveShape.ShapeType = sType;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            };
                            popup.Show();
                            return true;
                        }
                        // 2. Nhóm Kiểu hình dạng
                        else if (x >= 195 && x <= 450) // 6 Presets
                        {
                            int spIdx = (x - 195) / 42;
                            Color[] pFills = new Color[] { Color.FromArgb(43, 87, 154), Color.FromArgb(31, 41, 55), Color.White, Color.FromArgb(5, 150, 105), Color.FromArgb(217, 119, 6), Color.FromArgb(124, 58, 237) };
                            Color[] pLines = new Color[] { Color.FromArgb(30, 60, 110), Color.FromArgb(17, 24, 39), Color.FromArgb(55, 65, 81), Color.FromArgb(4, 120, 87), Color.FromArgb(180, 83, 9), Color.FromArgb(109, 40, 217) };
                            if (spIdx >= 0 && spIdx < 6)
                            {
                                sh.FillColor = pFills[spIdx];
                                sh.OutlineColor = pLines[spIdx];
                                sh.TextColor = (spIdx == 2) ? Color.Black : Color.White;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        else if (x >= 455 && x <= 570)
                        {
                            if (y >= 68 && y <= 88) // Đổ màu nền
                            {
                                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(455, 130)) : new Point(455, 130);
                                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                                colDlg.OnColorSelected += (col) => { sh.FillColor = col; if (parentForm != null) parentForm.Invalidate(); };
                                colDlg.Show();
                                return true;
                            }
                            else if (y >= 88 && y <= 108) // Viền hình
                            {
                                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(455, 130)) : new Point(455, 130);
                                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                                colDlg.OnColorSelected += (col) => { sh.OutlineColor = col; sh.OutlineWidth = 2.0f; if (parentForm != null) parentForm.Invalidate(); };
                                colDlg.Show();
                                return true;
                            }
                            else if (y >= 108 && y <= 128) // Hiệu ứng
                            {
                                sh.HasShadow = !sh.HasShadow;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        // 3. Nhóm Sắp xếp
                        else if (x >= 580 && x <= 660) // Ngắt dòng
                        {
                            sh.ShowLayoutOptions = !sh.ShowLayoutOptions;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        else if (x >= 665 && x <= 785)
                        {
                            if (y >= 68 && y <= 88) { sh.WrapMode = 6; if (parentForm != null) parentForm.Invalidate(); return true; } // Lên trước (In front)
                            else if (y >= 88 && y <= 108) { sh.WrapMode = 5; if (parentForm != null) parentForm.Invalidate(); return true; } // Về sau (Behind)
                            else if (y >= 108 && y <= 128) { sh.RotationAngle = (sh.RotationAngle + 90f) % 360f; if (parentForm != null) parentForm.Invalidate(); return true; }
                        }
                        // 4. Nhóm Kích cỡ
                        else if (x >= 795 && x <= 910)
                        {
                            if (y >= 68 && y <= 90) { sh.HeightDelta += 10; if (parentForm != null) parentForm.Invalidate(); return true; }
                            else if (y >= 90 && y <= 125) { sh.WidthDelta += 10; if (parentForm != null) parentForm.Invalidate(); return true; }
                        }
                        // 5. Đóng / Bỏ chọn
                        else if (x >= 920)
                        {
                            sh.IsSelected = false;
                            writerView.ActiveShape = null;
                            ActiveRibbonTab = 0;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        return true;
                    }
                    else if (writerView != null && writerView.IsEditingEquation)
                    {
                        // 1. Nhóm Công cụ (X: 14..140)
                        if (x >= 14 && x <= 78) // Công thức ▾
                        {
                            Point eqPt = parentForm != null ? parentForm.PointToScreen(new Point(14, 132)) : new Point(14, 132);
                            QuickEquationDropDownForm eqDlg = new QuickEquationDropDownForm(eqPt);
                            eqDlg.OnEquationSelected = (formula) =>
                            {
                                writerView.InsertEquation(formula);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            eqDlg.OnInsertNewEquationClicked = () =>
                            {
                                writerView.InsertEquation();
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            eqDlg.Show();
                            return true;
                        }
                        else if (x >= 80 && x <= 142) // Viết công thức tay / Nhập Equation
                        {
                            using (Form inkDlg = new Form())
                            {
                                inkDlg.Text = "Nhập Công thức Toán học (Equation / LaTeX)";
                                inkDlg.Size = new Size(460, 210);
                                inkDlg.StartPosition = FormStartPosition.CenterParent;
                                inkDlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                                inkDlg.MaximizeBox = false;
                                inkDlg.MinimizeBox = false;

                                Label lbl = new Label { Text = "Nhập công thức toán học hoặc mã LaTeX (ví dụ: E = mc^2, \\int_0^1 x dx):", Location = new Point(14, 14), AutoSize = true };
                                TextBox txt = new TextBox { Text = "\\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}", Location = new Point(16, 42), Size = new Size(410, 26) };
                                Button btnOk = new Button { Text = "Chèn công thức", DialogResult = DialogResult.OK, Location = new Point(226, 115), Size = new Size(116, 30) };
                                Button btnCancel = new Button { Text = "Hủy bỏ", DialogResult = DialogResult.Cancel, Location = new Point(350, 115), Size = new Size(76, 30) };

                                inkDlg.Controls.AddRange(new Control[] { lbl, txt, btnOk, btnCancel });
                                inkDlg.AcceptButton = btnOk;
                                inkDlg.CancelButton = btnCancel;

                                if (inkDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrWhiteSpace(txt.Text))
                                {
                                    writerView.InsertEquation(txt.Text.Trim());
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                            return true;
                        }

                        // 2. Nhóm Ký hiệu toán học (X: 160..512)
                        if (x >= 160 && x <= 512 && y >= 68 && y <= 130)
                        {
                            string[] mSymbols = new string[] {
                                "±", "∞", "=", "≠", "~", "×", "÷", "!", "∝", "<", "≪", ">", "≫", "≤", "≥", "∓",
                                "≅", "≈", "≡", "∀", "∂", "∃", "∇", "∈", "∉", "∋", "∏", "∑", "√", "∛", "∫", "π"
                            };
                            int c = (x - 160) / 22;
                            int r = (y - 70) / 28;
                            int idx = r * 16 + c;
                            if (idx >= 0 && idx < mSymbols.Length)
                            {
                                writerView.InsertSymbol(mSymbols[idx]);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }

                        // 3. Nhóm Cấu trúc công thức (X: 528..1100)
                        if (x >= 528 && x <= 1100 && y >= 68 && y <= 130)
                        {
                            int stIdx = (x - 528) / 58;
                            switch (stIdx)
                            {
                                case 0: writerView.InsertSymbol("(a / b)"); break;
                                case 1: writerView.InsertSymbol("x²"); break;
                                case 2: writerView.InsertSymbol("√(x)"); break;
                                case 3: writerView.InsertSymbol("∫ f(x) dx"); break;
                                case 4: writerView.InsertSymbol("∑(i=1..n)"); break;
                                case 5: writerView.InsertSymbol("(x)"); break;
                                case 6: writerView.InsertSymbol("sin(x)"); break;
                                case 7: writerView.InsertSymbol("ẋ"); break;
                                case 8: writerView.InsertSymbol("lim(x→0)"); break;
                                case 9: writerView.InsertSymbol("[a, b; c, d]"); break;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // 4. Nhóm Đóng Công thức (X >= 1110)
                        if (x >= 1110)
                        {
                            writerView.IsEditingEquation = false;
                            ActiveRibbonTab = 0;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        return true;
                    }
                    else if (writerView != null)
                    {
                        // 1. Nhóm Đầu trang & Chân trang (X: 16..220)
                        if (x >= 16 && x <= 78) // Đầu trang
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(16, 132)) : new Point(16, 132);
                            HeaderFooterDropDownForm dlg = new HeaderFooterDropDownForm(pt, true);
                            dlg.OnPresetSelected = (preset) => { writerView.CurrentHeaderPreset = preset; writerView.IsEditingHeaderFooter = true; writerView.IsEditingHeaderMode = true; ActiveRibbonTab = 9; if (parentForm != null) parentForm.Invalidate(); };
                            dlg.OnEditClicked = () => { writerView.IsEditingHeaderFooter = true; writerView.IsEditingHeaderMode = true; ActiveRibbonTab = 9; if (parentForm != null) parentForm.Invalidate(); };
                            dlg.OnRemoveClicked = () => { writerView.CurrentHeaderPreset = HeaderFooterPreset.None; writerView.HeaderText = ""; if (parentForm != null) parentForm.Invalidate(); };
                            dlg.Show();
                            return true;
                        }
                        else if (x >= 84 && x <= 146) // Chân trang
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(84, 132)) : new Point(84, 132);
                            HeaderFooterDropDownForm dlg = new HeaderFooterDropDownForm(pt, false);
                            dlg.OnPresetSelected = (preset) => { writerView.CurrentFooterPreset = preset; writerView.IsEditingHeaderFooter = true; writerView.IsEditingHeaderMode = false; ActiveRibbonTab = 9; if (parentForm != null) parentForm.Invalidate(); };
                            dlg.OnEditClicked = () => { writerView.IsEditingHeaderFooter = true; writerView.IsEditingHeaderMode = false; ActiveRibbonTab = 9; if (parentForm != null) parentForm.Invalidate(); };
                            dlg.OnRemoveClicked = () => { writerView.CurrentFooterPreset = HeaderFooterPreset.None; writerView.FooterText = ""; if (parentForm != null) parentForm.Invalidate(); };
                            dlg.Show();
                            return true;
                        }
                        else if (x >= 152 && x <= 214) // Số trang
                        {
                            Point mPt = parentForm != null ? parentForm.PointToScreen(new Point(x, 132)) : new Point(x, 132);
                            ShowPageNumberMenu(mPt, writerView, parentForm);
                            return true;
                        }
                        // 2. Nhóm Chèn (X: 226..470)
                        else if (x >= 226 && x <= 351)
                        {
                            if (y >= 68 && y <= 88) // Ngày & Giờ
                            {
                                string dtStr = DateTime.Now.ToString("dd/MM/yyyy HH:mm");
                                if (writerView.IsEditingHeaderMode)
                                    writerView.HeaderTitleText = dtStr;
                                else
                                    writerView.InsertText(dtStr);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 88 && y <= 108) // Thông tin tài liệu
                            {
                                string infoStr = "Tài liệu ZENQ OFFICE - Tác giả: Người dùng";
                                if (writerView.IsEditingHeaderMode)
                                    writerView.HeaderTitleText = infoStr;
                                else
                                    writerView.InsertText(infoStr);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 108 && y <= 128) // Phần nhanh
                            {
                                writerView.InsertText("[Trường Thông Tin Nhanh]");
                                if (parentForm != null) parentForm.Invalidate();
                            if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        else if (x >= 358 && x <= 468)
                        {
                            if (y >= 68 && y <= 88) // Hình ảnh
                            {
                                using (OpenFileDialog ofd = new OpenFileDialog())
                                {
                                    ofd.Filter = "Hình ảnh (*.png;*.jpg;*.jpeg;*.bmp;*.gif)|*.png;*.jpg;*.jpeg;*.bmp;*.gif|Tất cả tệp (*.*)|*.*";
                                    ofd.Title = "Chọn hình ảnh chèn vào văn bản";
                                    if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                                    {
                                        writerView.InsertImage(ofd.FileName);
                                        if (parentForm != null) parentForm.Invalidate();
                                    }
                                }
                                return true;
                            }
                            else if (y >= 88 && y <= 108) // Ảnh trực tuyến
                            {
                                writerView.InsertText("\n![IMAGE:ONLINE:https://placehold.co/400x200]\n");
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        // 3. Nhóm Điều hướng (X: 480..608)
                        else if (x >= 480 && x <= 608)
                        {
                            if (y >= 68 && y <= 88) // Đến Đầu trang
                            {
                                writerView.IsEditingHeaderFooter = true;
                                writerView.IsEditingHeaderMode = true;
                                writerView.ScrollY = 0;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 88 && y <= 108) // Đến Chân trang
                            {
                                writerView.IsEditingHeaderFooter = true;
                                writerView.IsEditingHeaderMode = false;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 108 && y <= 128) // Liên kết Trước
                            {
                                MessageBox.Show("Đã liên kết với phần đầu trang/chân trang trước!", "ZENQ OFFICE", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                return true;
                            }
                        }
                        // 4. Nhóm Tùy chọn (X: 620..795)
                        else if (x >= 620 && x <= 795)
                        {
                            if (y >= 68 && y <= 88) // Trang đầu khác biệt
                            {
                                DifferentFirstPage = !DifferentFirstPage;
                                if (writerView != null) writerView.DifferentFirstPage = DifferentFirstPage;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 88 && y <= 108) // Trang chẵn & lẻ khác nhau
                            {
                                DifferentOddEven = !DifferentOddEven;
                                if (writerView != null)
                                {
                                    writerView.DifferentOddEvenPages = DifferentOddEven;
                                    if (DifferentOddEven)
                                    {
                                        writerView.FooterAlignment = 2; // Trang lẻ bên phải
                                        writerView.FooterEvenAlignment = 0; // Trang chẵn bên trái ("2 bên")
                                    }
                                }
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                        // 6. Nhóm Đóng (X >= 950)
                        else if (x >= 950)
                        {
                            writerView.IsEditingHeaderFooter = false;
                            ActiveRibbonTab = 0;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        return true;
                    }
                }
                else if (ActiveRibbonTab == 7 || curTab == "Định dạng")
                {
                    if (writerView != null && writerView.ActiveShape != null && (writerView.ActiveShape.ShapeType == "SmartArt" || !string.IsNullOrEmpty(writerView.ActiveShape.SmartArtType)))
                    {
                        return HandleSmartArtFormatClick(x, y, writerView, parentForm);
                    }
                    return true;
                }
            }
            else if (y > 64 && y <= 155 && CurrentMode == OfficeAppMode.Calc && calcView != null)
            {
                return HandleExcelRibbonClick(x, y, calcView, parentForm);
            }
            else if (y > 64 && y <= 155 && CurrentMode == OfficeAppMode.Slides && slidesView != null)
            {
                return HandlePowerPointRibbonClick(x, y, slidesView, parentForm);
            }
            else if (y > 64 && y <= 155 && CurrentMode == OfficeAppMode.Pdf && pdfView != null)
            {
                return HandlePdfRibbonClick(x, y, pdfView, parentForm);
            }
            else if (y > 64 && y <= 155 && CurrentMode == OfficeAppMode.Photo && photoView != null)
            {
                return HandlePhotoRibbonClick(x, y, photoView, parentForm);
            }
            return false;
        }

        private bool HandleSmartArtDesignClick(int x, int y, WriterView writerView, Form parentForm)
        {
            if (writerView == null || writerView.ActiveShape == null) return false;
            var sh = writerView.ActiveShape;

            // 1. Nhóm Tạo Đồ họa (Create Graphic) (X: 14 -> 306)
            // Cột 1 (X: 14..114)
            if (x >= 14 && x <= 114)
            {
                if (y >= 68 && y <= 88) // Thêm hình (Add Shape)
                {
                    writerView.AddSmartArtNode(sh);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 89 && y <= 109) // Thêm Đầu dòng (Add Bullet)
                {
                    string[] curNodes = SmartArtRenderer.GetSmartArtNodeList(sh.SmartArtType, sh.TextContent);
                    List<string> list = new List<string>(curNodes);
                    int idx = (sh.SelectedNodeIndex >= 0 && sh.SelectedNodeIndex < list.Count) ? sh.SelectedNodeIndex : (list.Count > 0 ? list.Count - 1 : 0);
                    if (idx < list.Count)
                    {
                        list[idx] = list[idx] + "\n• Đầu dòng con";
                        sh.TextContent = string.Join("|", list.ToArray());
                        sh.CachedImage = null;
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                else if (y >= 110 && y <= 130) // Ngăn Văn bản (Text Pane)
                {
                    writerView.OpenSmartArtEditor(sh);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            // Cột 2 (X: 118..214)
            else if (x >= 118 && x <= 214)
            {
                if (y >= 68 && y <= 88) // Nâng cấp (Promote)
                {
                    if (sh.SelectedNodeIndex > 0)
                    {
                        string[] curNodes = SmartArtRenderer.GetSmartArtNodeList(sh.SmartArtType, sh.TextContent);
                        List<string> list = new List<string>(curNodes);
                        if (sh.SelectedNodeIndex < list.Count)
                        {
                            string temp = list[sh.SelectedNodeIndex];
                            list[sh.SelectedNodeIndex] = list[sh.SelectedNodeIndex - 1];
                            list[sh.SelectedNodeIndex - 1] = temp;
                            sh.TextContent = string.Join("|", list.ToArray());
                            sh.SelectedNodeIndex--;
                            sh.SubShapeRelativeBounds.Clear();
                            sh.CachedImage = null;
                            writerView.SyncShapeTagInDocument(sh);
                            writerView.SaveUndoState();
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                else if (y >= 89 && y <= 109) // Hạ cấp (Demote)
                {
                    string[] curNodes = SmartArtRenderer.GetSmartArtNodeList(sh.SmartArtType, sh.TextContent);
                    List<string> list = new List<string>(curNodes);
                    if (sh.SelectedNodeIndex >= 0 && sh.SelectedNodeIndex < list.Count - 1)
                    {
                        string temp = list[sh.SelectedNodeIndex];
                        list[sh.SelectedNodeIndex] = list[sh.SelectedNodeIndex + 1];
                        list[sh.SelectedNodeIndex + 1] = temp;
                        sh.TextContent = string.Join("|", list.ToArray());
                        sh.SelectedNodeIndex++;
                        sh.SubShapeRelativeBounds.Clear();
                        sh.CachedImage = null;
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                else if (y >= 110 && y <= 130) // Phải sang Trái (Right to Left)
                {
                    string[] curNodes = SmartArtRenderer.GetSmartArtNodeList(sh.SmartArtType, sh.TextContent);
                    Array.Reverse(curNodes);
                    sh.TextContent = string.Join("|", curNodes);
                    sh.SubShapeRelativeBounds.Clear();
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            // Cột 3 (X: 218..306)
            else if (x >= 218 && x <= 306)
            {
                if (y >= 68 && y <= 88) // Lên (Move Up)
                {
                    if (sh.SelectedNodeIndex > 0)
                    {
                        string[] curNodes = SmartArtRenderer.GetSmartArtNodeList(sh.SmartArtType, sh.TextContent);
                        List<string> list = new List<string>(curNodes);
                        if (sh.SelectedNodeIndex < list.Count)
                        {
                            string temp = list[sh.SelectedNodeIndex];
                            list[sh.SelectedNodeIndex] = list[sh.SelectedNodeIndex - 1];
                            list[sh.SelectedNodeIndex - 1] = temp;
                            sh.TextContent = string.Join("|", list.ToArray());
                            sh.SelectedNodeIndex--;
                            sh.SubShapeRelativeBounds.Clear();
                            sh.CachedImage = null;
                            writerView.SyncShapeTagInDocument(sh);
                            writerView.SaveUndoState();
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                else if (y >= 89 && y <= 109) // Xuống (Move Down)
                {
                    string[] curNodes = SmartArtRenderer.GetSmartArtNodeList(sh.SmartArtType, sh.TextContent);
                    List<string> list = new List<string>(curNodes);
                    if (sh.SelectedNodeIndex >= 0 && sh.SelectedNodeIndex < list.Count - 1)
                    {
                        string temp = list[sh.SelectedNodeIndex];
                        list[sh.SelectedNodeIndex] = list[sh.SelectedNodeIndex + 1];
                        list[sh.SelectedNodeIndex + 1] = temp;
                        sh.TextContent = string.Join("|", list.ToArray());
                        sh.SelectedNodeIndex++;
                        sh.SubShapeRelativeBounds.Clear();
                        sh.CachedImage = null;
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                else if (y >= 110 && y <= 130) // Bố cục nhánh
                {
                    MessageBox.Show("Đã áp dụng định dạng nhánh cân bằng cho các nút cấp dưới!", "ZENQ OFFICE SmartArt", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return true;
                }
            }

            // 2. Nhóm Bố cục (Layouts) (X: 318 -> 666)
            else if (x >= 318 && x < 582 && y >= 68 && y <= 128)
            {
                int lIdx = (x - 318) / 44;
                string[] sampleLayouts = new string[] { "Cycle_Radial", "Cycle_Basic", "Process_BasicChevron", "List_BasicBlock", "Hierarchy_Tree", "Matrix_Grid" };
                if (lIdx >= 0 && lIdx < sampleLayouts.Length)
                {
                    Rectangle curBounds = new Rectangle(sh.PageX, sh.PageY, Math.Max(100, sh.BaseWidth + sh.WidthDelta), Math.Max(60, sh.BaseHeight + sh.HeightDelta));
                    var model = ZenQOffice.Format.OpenXmlSmartArtModel.FromDocShapeObject(sh);
                    model.SwitchLayout(sampleLayouts[lIdx], sh, curBounds);
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (x >= 582 && x <= 666 && y >= 68 && y <= 128) // Bố cục khác...
            {
                using (SmartArtGalleryForm saDlg = new SmartArtGalleryForm())
                {
                    if (saDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(saDlg.SelectedSmartArtType))
                    {
                        Rectangle curBounds = new Rectangle(sh.PageX, sh.PageY, Math.Max(100, sh.BaseWidth + sh.WidthDelta), Math.Max(60, sh.BaseHeight + sh.HeightDelta));
                        var model = ZenQOffice.Format.OpenXmlSmartArtModel.FromDocShapeObject(sh);
                        model.Title = saDlg.SelectedSmartArtName;
                        model.SwitchLayout(saDlg.SelectedSmartArtType, sh, curBounds);
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                }
                return true;
            }

            // 3. Nhóm Kiểu SmartArt (SmartArt Styles) (X: 678 -> 990)
            else if (x >= 678 && x <= 746 && y >= 68 && y <= 128) // Đổi Màu ▾
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(678, 132)) : new Point(678, 132);
                SmartArtColorGalleryPopup popup = new SmartArtColorGalleryPopup();
                popup.Location = pt;
                popup.OnPaletteSelected = (colors, isOutline) =>
                {
                    if (colors != null && colors.Length > 0)
                    {
                        Rectangle curBounds = new Rectangle(sh.PageX, sh.PageY, Math.Max(100, sh.BaseWidth + sh.WidthDelta), Math.Max(60, sh.BaseHeight + sh.HeightDelta));
                        var model = ZenQOffice.Format.OpenXmlSmartArtModel.FromDocShapeObject(sh);
                        model.ApplyPalette(colors, isOutline, sh, curBounds);
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                };
                popup.Show();
                return true;
            }
            else if (x >= 750 && x <= 990 && y >= 68 && y <= 128) // 5 Style presets (Phẳng, Dải màu, Nổi 3D, Thủy tinh, Viền)
            {
                int stIdx = (x - 750) / 48;
                if (stIdx >= 0 && stIdx < 5)
                {
                    Rectangle curBounds = new Rectangle(sh.PageX, sh.PageY, Math.Max(100, sh.BaseWidth + sh.WidthDelta), Math.Max(60, sh.BaseHeight + sh.HeightDelta));
                    var model = ZenQOffice.Format.OpenXmlSmartArtModel.FromDocShapeObject(sh);
                    model.ApplyVisualStyle(stIdx, sh, curBounds);
                    if (stIdx == 0) { sh.HasShadow = false; sh.OutlineWidth = 1.0f; }
                    else if (stIdx == 1) { sh.HasShadow = false; sh.OutlineWidth = 1.2f; }
                    else if (stIdx == 2) { sh.HasShadow = true; sh.OutlineWidth = 1.5f; }
                    else if (stIdx == 3) { sh.HasShadow = true; sh.OutlineWidth = 1.2f; }
                    else if (stIdx == 4) { sh.HasShadow = false; sh.OutlineWidth = 2.2f; }
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // 4. Nhóm Đặt lại (Reset) (X: 1002 -> 1082)
            else if (x >= 1002 && x <= 1082 && y >= 68 && y <= 128)
            {
                sh.StylePresetIndex = 1;
                sh.VisualStylePreset = 0;
                if (sh.NodeColors != null) sh.NodeColors.Clear();
                if (sh.NodeShapeTypes != null) sh.NodeShapeTypes.Clear();
                if (sh.NodeOutlineColors != null) sh.NodeOutlineColors.Clear();
                if (sh.NodeTextColors != null) sh.NodeTextColors.Clear();
                if (sh.NodeScaleDeltas != null) sh.NodeScaleDeltas.Clear();
                if (sh.ModifiedNodes != null) sh.ModifiedNodes.Clear();
                sh.SelectedNodeIndex = -1;
                sh.SubShapeRelativeBounds.Clear();
                sh.WidthDelta = 0;
                sh.HeightDelta = 0;
                sh.HasShadow = false;
                sh.ImagePath = null;
                sh.CachedImage = null;
                Rectangle curBounds = new Rectangle(sh.PageX, sh.PageY, sh.BaseWidth, sh.BaseHeight);
                SmartArtRenderer.PopulateSubShapeBounds(curBounds, sh.SmartArtType, 4, sh);
                writerView.SyncShapeTagInDocument(sh);
                writerView.SaveUndoState();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // 5. Nhóm Đóng (X >= 1094)
            else if (x >= 1094 && y >= 68 && y <= 128)
            {
                sh.IsSelected = false;
                sh.SelectedNodeIndex = -1;
                writerView.ActiveShape = null;
                ActiveRibbonTab = 0;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            return false;
        }

        private void ShowPageNumberMenu(Point screenPt, WriterView writerView, Form parentForm)
        {
            if (writerView == null) return;
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.Font = new Font("Segoe UI", 9.0f, FontStyle.Regular);

            ToolStripMenuItem itemTwoSides = new ToolStripMenuItem("Hai bên (Trang chẵn bên trái, trang lẻ bên phải)");
            itemTwoSides.Click += (s, e) =>
            {
                writerView.ShowPageNumbers = true;
                writerView.DifferentOddEvenPages = true;
                writerView.FooterAlignment = 2; // Right for odd
                writerView.FooterEvenAlignment = 0; // Left for even
                DifferentOddEven = true;
                if (parentForm != null) parentForm.Invalidate();
            };
            menu.Items.Add(itemTwoSides);

            ToolStripMenuItem itemCenter = new ToolStripMenuItem("Ở giữa (Căn giữa)");
            itemCenter.Click += (s, e) =>
            {
                writerView.ShowPageNumbers = true;
                writerView.DifferentOddEvenPages = false;
                writerView.FooterAlignment = 1;
                DifferentOddEven = false;
                if (parentForm != null) parentForm.Invalidate();
            };
            menu.Items.Add(itemCenter);

            ToolStripMenuItem itemRight = new ToolStripMenuItem("Bên phải (Căn phải)");
            itemRight.Click += (s, e) =>
            {
                writerView.ShowPageNumbers = true;
                writerView.DifferentOddEvenPages = false;
                writerView.FooterAlignment = 2;
                DifferentOddEven = false;
                if (parentForm != null) parentForm.Invalidate();
            };
            menu.Items.Add(itemRight);

            ToolStripMenuItem itemLeft = new ToolStripMenuItem("Bên trái (Căn trái)");
            itemLeft.Click += (s, e) =>
            {
                writerView.ShowPageNumbers = true;
                writerView.DifferentOddEvenPages = false;
                writerView.FooterAlignment = 0;
                DifferentOddEven = false;
                if (parentForm != null) parentForm.Invalidate();
            };
            menu.Items.Add(itemLeft);

            menu.Items.Add(new ToolStripSeparator());

            ToolStripMenuItem itemRemove = new ToolStripMenuItem("Gỡ bỏ số trang (Remove Page Numbers)");
            itemRemove.Click += (s, e) =>
            {
                writerView.ShowPageNumbers = false;
                if (parentForm != null) parentForm.Invalidate();
            };
            menu.Items.Add(itemRemove);

            menu.Show(screenPt);
        }

        private bool HandleSmartArtFormatClick(int x, int y, WriterView writerView, Form parentForm)
        {
            if (writerView == null || writerView.ActiveShape == null) return false;
            var sh = writerView.ActiveShape;

            // 1. Nhóm Hình dạng (X: 14 -> 119)
            if (x >= 14 && x <= 119)
            {
                if (y >= 68 && y <= 88) // Đổi hình dạng
                {
                    Point menuPt = parentForm != null ? parentForm.PointToScreen(new Point(14, 130)) : new Point(14, 130);
                    ShapeGalleryPopup popup = new ShapeGalleryPopup();
                    popup.Location = menuPt;
                    popup.OnShapeSelected = (sType) =>
                    {
                        if (sh.SelectedNodeIndex >= 0)
                        {
                            if (sh.NodeShapeTypes == null) sh.NodeShapeTypes = new Dictionary<int, string>();
                            sh.NodeShapeTypes[sh.SelectedNodeIndex] = sType;
                        }
                        else
                        {
                            if (sh.NodeShapeTypes == null) sh.NodeShapeTypes = new Dictionary<int, string>();
                            int count = (sh.SubShapeRelativeBounds != null && sh.SubShapeRelativeBounds.Count > 0) ? sh.SubShapeRelativeBounds.Count : 5;
                            for (int i = 0; i < count; i++)
                            {
                                sh.NodeShapeTypes[i] = sType;
                            }
                        }
                        sh.ImagePath = null;
                        sh.CachedImage = null;
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    popup.Show();
                    return true;
                }
                else if (y >= 89 && y <= 109) // Lớn hơn
                {
                    if (sh.SelectedNodeIndex >= 0)
                    {
                        if (sh.NodeScaleDeltas == null) sh.NodeScaleDeltas = new Dictionary<int, float>();
                        float cur = 0f;
                        if (sh.NodeScaleDeltas.ContainsKey(sh.SelectedNodeIndex)) cur = sh.NodeScaleDeltas[sh.SelectedNodeIndex];
                        sh.NodeScaleDeltas[sh.SelectedNodeIndex] = cur + 0.15f;
                    }
                    else
                    {
                        sh.WidthDelta += 20;
                        sh.HeightDelta += 15;
                        sh.SubShapeRelativeBounds.Clear();
                    }
                    sh.ImagePath = null;
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 110 && y <= 130) // Nhỏ hơn
                {
                    if (sh.SelectedNodeIndex >= 0)
                    {
                        if (sh.NodeScaleDeltas == null) sh.NodeScaleDeltas = new Dictionary<int, float>();
                        float cur = 0f;
                        if (sh.NodeScaleDeltas.ContainsKey(sh.SelectedNodeIndex)) cur = sh.NodeScaleDeltas[sh.SelectedNodeIndex];
                        sh.NodeScaleDeltas[sh.SelectedNodeIndex] = Math.Max(-0.6f, cur - 0.15f);
                    }
                    else
                    {
                        sh.WidthDelta = Math.Max(-sh.BaseWidth + 60, sh.WidthDelta - 20);
                        sh.HeightDelta = Math.Max(-sh.BaseHeight + 40, sh.HeightDelta - 15);
                        sh.SubShapeRelativeBounds.Clear();
                    }
                    sh.ImagePath = null;
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // 2. Nhóm Kiểu Hình dạng (Shape Styles) (X: 131 -> 525)
            // 6 Preset Boxes (X: 131 -> 395, Y: 68..128)
            else if (x >= 131 && x < 395 && y >= 68 && y <= 128)
            {
                int pIdx = (x - 131) / 44;
                Color[] pColors = new Color[] {
                    Color.FromArgb(43, 87, 154),  // Theme Blue
                    Color.FromArgb(31, 41, 55),   // Slate/Dark
                    Color.White,                  // Minimalist White
                    Color.FromArgb(5, 150, 105),  // Emerald Green
                    Color.FromArgb(217, 119, 6),  // Amber / Orange
                    Color.FromArgb(124, 58, 237)  // Violet / Purple
                };
                if (pIdx >= 0 && pIdx < pColors.Length)
                {
                    writerView.SetSelectedNodeColor(pColors[pIdx]);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            // Cột nút Tô Hình dạng, Viền ngoài, Hiệu ứng (X: 395..525)
            else if (x >= 395 && x <= 525)
            {
                if (y >= 68 && y <= 88) // Tô Hình dạng
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(395, 130)) : new Point(395, 130);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                    colDlg.OnColorSelected += (col) =>
                    {
                        writerView.SetSelectedNodeColor(col);
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                else if (y >= 89 && y <= 109) // Viền ngoài
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(395, 130)) : new Point(395, 130);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                    colDlg.OnColorSelected += (col) =>
                    {
                        if (sh.SelectedNodeIndex >= 0)
                        {
                            if (sh.NodeOutlineColors == null) sh.NodeOutlineColors = new Dictionary<int, Color>();
                            sh.NodeOutlineColors[sh.SelectedNodeIndex] = col;
                        }
                        else
                        {
                            sh.OutlineColor = col;
                            sh.OutlineWidth = 2.0f;
                        }
                        sh.ImagePath = null;
                        sh.CachedImage = null;
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                else if (y >= 110 && y <= 130) // Hiệu ứng ✨
                {
                    sh.HasShadow = !sh.HasShadow;
                    if (sh.VisualStylePreset == 0 && sh.HasShadow)
                    {
                        sh.VisualStylePreset = 2; // Switch to 3D
                    }
                    else if (sh.VisualStylePreset == 2 && !sh.HasShadow)
                    {
                        sh.VisualStylePreset = 0;
                    }
                    sh.ImagePath = null;
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // 3. Nhóm Kiểu WordArt (WordArt Styles) (X: 537 -> 783)
            else if (x >= 537 && x < 669 && y >= 68 && y <= 128) // 3 WordArt boxes
            {
                int waIdx = (x - 537) / 44;
                Color[] textColors = new Color[] { Color.Black, Color.FromArgb(43, 87, 154), Color.FromArgb(217, 119, 6) };
                if (waIdx >= 0 && waIdx < textColors.Length)
                {
                    if (sh.SelectedNodeIndex >= 0)
                    {
                        if (sh.NodeTextColors == null) sh.NodeTextColors = new Dictionary<int, Color>();
                        sh.NodeTextColors[sh.SelectedNodeIndex] = textColors[waIdx];
                    }
                    else
                    {
                        sh.TextColor = textColors[waIdx];
                    }
                    sh.ImagePath = null;
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (x >= 669 && x <= 783)
            {
                if (y >= 68 && y <= 88) // Tô Màu Chữ
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(669, 130)) : new Point(669, 130);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                    colDlg.OnColorSelected += (col) =>
                    {
                        if (sh.SelectedNodeIndex >= 0)
                        {
                            if (sh.NodeTextColors == null) sh.NodeTextColors = new Dictionary<int, Color>();
                            sh.NodeTextColors[sh.SelectedNodeIndex] = col;
                        }
                        else
                        {
                            sh.TextColor = col;
                        }
                        sh.ImagePath = null;
                        sh.CachedImage = null;
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                else if (y >= 89 && y <= 109) // Viền Chữ (Bold toggle)
                {
                    sh.Bold = !sh.Bold;
                    sh.ImagePath = null;
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 110 && y <= 130) // Hiệu ứng Chữ (Italic toggle)
                {
                    sh.Italic = !sh.Italic;
                    sh.ImagePath = null;
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // 4. Nhóm Sắp xếp (Arrange) (X: 795 -> 900)
            else if (x >= 795 && x <= 900)
            {
                if (y >= 68 && y <= 88) // Ngắt dòng
                {
                    sh.WrapMode = (sh.WrapMode + 1) % 7;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 89 && y <= 109) // Lên trước
                {
                    int idx = writerView.DocumentShapes.IndexOf(sh);
                    if (idx >= 0 && idx < writerView.DocumentShapes.Count - 1)
                    {
                        writerView.DocumentShapes.RemoveAt(idx);
                        writerView.DocumentShapes.Add(sh);
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                else if (y >= 110 && y <= 130) // Về sau
                {
                    int idx = writerView.DocumentShapes.IndexOf(sh);
                    if (idx > 0)
                    {
                        writerView.DocumentShapes.RemoveAt(idx);
                        writerView.DocumentShapes.Insert(0, sh);
                        writerView.SyncShapeTagInDocument(sh);
                        writerView.SaveUndoState();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
            }

            // 5. Nhóm Kích cỡ (Size) (X: 912 -> 1017)
            else if (x >= 912 && x <= 1017)
            {
                if (y >= 68 && y <= 95) // Height +/-
                {
                    if (x >= 980) sh.HeightDelta = Math.Max(-sh.BaseHeight + 20, sh.HeightDelta - 15);
                    else sh.HeightDelta += 15;
                    sh.SubShapeRelativeBounds.Clear();
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (y >= 96 && y <= 128) // Width +/-
                {
                    if (x >= 980) sh.WidthDelta = Math.Max(-sh.BaseWidth + 20, sh.WidthDelta - 15);
                    else sh.WidthDelta += 15;
                    sh.SubShapeRelativeBounds.Clear();
                    sh.CachedImage = null;
                    writerView.SyncShapeTagInDocument(sh);
                    writerView.SaveUndoState();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // 6. Nhóm Đóng / Bỏ chọn (X >= 1029)
            else if (x >= 1029 && y >= 68 && y <= 128)
            {
                sh.IsSelected = false;
                sh.SelectedNodeIndex = -1;
                writerView.ActiveShape = null;
                ActiveRibbonTab = 0;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            return false;
        }

        private bool HandleExcelRibbonClick(int x, int y, CalcView calcView, Form parentForm)
        {
            if (ActiveRibbonTab == 0) // Trang đầu (Home)
            {
                // ==================== Group 1: Bảng tạm (X: 14 to 238) ====================
                // Dán Paste (X: 14..68, Y: 68..130)
                if (x >= 14 && x <= 68 && y >= 68 && y <= 130)
                {
                    if (Clipboard.ContainsText())
                    {
                        calcView.SaveUndoState();
                        calcView.CurrentSheet.SetCellText(calcView.SelectedRow, calcView.SelectedCol, Clipboard.GetText());
                        FormulaEngine.EvaluateSheet(calcView.CurrentSheet);
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                // Cắt Cut (X: 72..238, Y: 68..88)
                else if (x >= 72 && x <= 238 && y >= 68 && y <= 88)
                {
                    CellData cd = calcView.CurrentSheet.GetCell(calcView.SelectedRow, calcView.SelectedCol);
                    if (cd != null && !string.IsNullOrEmpty(cd.RawValue))
                    {
                        calcView.SaveUndoState();
                        Clipboard.SetText(cd.RawValue);
                        calcView.CurrentSheet.ClearCell(calcView.SelectedRow, calcView.SelectedCol);
                        FormulaEngine.EvaluateSheet(calcView.CurrentSheet);
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                // Sao chép Copy (X: 72..238, Y: 89..109)
                else if (x >= 72 && x <= 238 && y >= 89 && y <= 109)
                {
                    CellData cd = calcView.CurrentSheet.GetCell(calcView.SelectedRow, calcView.SelectedCol);
                    if (cd != null && !string.IsNullOrEmpty(cd.EvaluatedStr ?? cd.RawValue))
                    {
                        Clipboard.SetText(cd.EvaluatedStr ?? cd.RawValue);
                    }
                    return true;
                }
                // Sao chép định dạng Format Painter (X: 72..238, Y: 110..130)
                else if (x >= 72 && x <= 238 && y >= 110 && y <= 130)
                {
                    if (calcView.IsFormatPainterActive)
                    {
                        calcView.PasteFormat();
                    }
                    else
                    {
                        calcView.CopyFormat();
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }

                // Group 1: Bảng tạm Dialog Launcher (X: 218..236, Y: 130..148)
                else if (x >= 218 && x <= 236 && y >= 130 && y <= 148)
                {
                    ContextMenuStrip clipMenu = new ContextMenuStrip();
                    clipMenu.Items.Add("Dán (Paste)", null, (s, e) => {
                        if (Clipboard.ContainsText()) {
                            calcView.SaveUndoState();
                            calcView.CurrentSheet.SetCellText(calcView.SelectedRow, calcView.SelectedCol, Clipboard.GetText());
                            FormulaEngine.EvaluateSheet(calcView.CurrentSheet);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    });
                    clipMenu.Items.Add("Sao chép (Copy)", null, (s, e) => {
                        CellData cd = calcView.CurrentSheet.GetCell(calcView.SelectedRow, calcView.SelectedCol);
                        if (cd != null && !string.IsNullOrEmpty(cd.EvaluatedStr ?? cd.RawValue)) Clipboard.SetText(cd.EvaluatedStr ?? cd.RawValue);
                    });
                    clipMenu.Items.Add("Cắt (Cut)", null, (s, e) => {
                        CellData cd = calcView.CurrentSheet.GetCell(calcView.SelectedRow, calcView.SelectedCol);
                        if (cd != null && !string.IsNullOrEmpty(cd.RawValue)) {
                            calcView.SaveUndoState();
                            Clipboard.SetText(cd.RawValue);
                            calcView.CurrentSheet.ClearCell(calcView.SelectedRow, calcView.SelectedCol);
                            FormulaEngine.EvaluateSheet(calcView.CurrentSheet);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    });
                    clipMenu.Items.Add(new ToolStripSeparator());
                    clipMenu.Items.Add("Xóa bảng tạm (Clear Clipboard)", null, (s, e) => { try { Clipboard.Clear(); } catch { } });
                    clipMenu.Show(parentForm ?? Form.ActiveForm, new Point(x, y));
                    return true;
                }

                // ==================== Group 2: Phông chữ (X: 248 to 462) ====================
