                }
            }
            else if (ActiveRibbonTab == 5) // Soát lỗi (Review)
            {
                // Spelling (X: 14..72)
                if (x >= 14 && x <= 72 && y >= 66 && y <= 124)
                {
                    calcView.RunSpellCheck(parentForm);
