                }
                // Protect Sheet (X: 84..162)
                else if (x >= 84 && x <= 162 && y >= 66 && y <= 124)
                {
                    calcView.ToggleProtectSheet(parentForm);
                    return true;
                }
            }
            else if (ActiveRibbonTab == 6) // Hiển thị (View)
            {
                // Normal View (X: 14..74)
                if (x >= 14 && x <= 74 && y >= 68 && y <= 124)
