                {
                    calcView.ShowGridlines = !calcView.ShowGridlines;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Headings Checkbox (X: 86..212, Y: 106..124)
                else if (x >= 86 && x <= 212 && y >= 106 && y <= 124)
                {
                    calcView.ShowHeadings = !calcView.ShowHeadings;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Freeze Panes (X: 224..300, Y: 68..124)
                else if (x >= 224 && x <= 300 && y >= 68 && y <= 124)
                {
                    calcView.IsFreezeTopRow = !calcView.IsFreezeTopRow;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Zoom 100% (X: 312..368, Y: 68..124)
                else if (x >= 312 && x <= 368 && y >= 68 && y <= 124)
                {
                    calcView.ZoomFactor = 1.0f;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Zoom In (+) (X: 372..452, Y: 68..94)
                else if (x >= 372 && x <= 452 && y >= 68 && y <= 94)
                {
                    calcView.ZoomFactor = Math.Min(4.0f, calcView.ZoomFactor + 0.15f);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Zoom Out (-) (X: 372..452, Y: 96..124)
                else if (x >= 372 && x <= 452 && y >= 96 && y <= 124)
                {
                    calcView.ZoomFactor = Math.Max(0.2f, calcView.ZoomFactor - 0.15f);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (ActiveRibbonTab == 7) // Thiết kế Bảng (Table Design)
            {
                ExcelTableInfo activeTbl;
                if (calcView != null && calcView.IsSelectionInsideTable(out activeTbl) && activeTbl != null)
                {
                    return HandleTableDesignRibbonClick(x, y, calcView, activeTbl, parentForm);
                }
            }
            return false;
        }

        private bool HandleTableDesignRibbonClick(int x, int y, CalcView calcView, ExcelTableInfo tbl, Form parentForm)
        {
            if (tbl == null || calcView == null) return false;

            // Group 1: Thuộc tính (X: 14..104)
            if (x >= 14 && x <= 104)
            {
                // Table Name box
                if (y >= 85 && y <= 107)
                {
                    using (Form dlg = new Form())
                    {
                        dlg.Text = "Đổi tên Bảng (Rename Table)";
                        dlg.Size = new Size(320, 160);
                        dlg.StartPosition = FormStartPosition.CenterParent;
                        dlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                        dlg.MaximizeBox = false;
                        dlg.MinimizeBox = false;
                        dlg.Font = new Font("Segoe UI", 9f);

                        Label lbl = new Label { Text = "Tên bảng mới (Table Name):", Location = new Point(16, 16), AutoSize = true };
                        TextBox txt = new TextBox { Text = tbl.Name, Location = new Point(18, 42), Width = 268 };
                        Button btnOk = new Button { Text = "Đồng ý", DialogResult = DialogResult.OK, Location = new Point(120, 80), Width = 80, Height = 28 };
                        Button btnCancel = new Button { Text = "Hủy bỏ", DialogResult = DialogResult.Cancel, Location = new Point(206, 80), Width = 80, Height = 28 };

                        dlg.Controls.AddRange(new Control[] { lbl, txt, btnOk, btnCancel });
                        dlg.AcceptButton = btnOk;
                        dlg.CancelButton = btnCancel;

                        if (dlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(txt.Text.Trim()))
                        {
                            tbl.Name = txt.Text.Trim();
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                // Resize Table button
                else if (y >= 110 && y <= 132)
                {
                    new CreateTableDialogForm(calcView).ShowDialog(parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 2: Công cụ (X: 112..264)
            if (x >= 112 && x <= 264)
            {
                // Summarize with PivotTable
                if (y >= 68 && y <= 88)
                {
                    new CreatePivotTableDialogForm(calcView).ShowDialog(parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Remove Duplicates
                else if (y >= 90 && y <= 110)
                {
                    calcView.RemoveTableDuplicates(tbl);
                    MessageBox.Show("Đã quét và làm sạch các dòng dữ liệu trùng lặp trong bảng " + tbl.Name + "!", "ZenQ Calc", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Convert to Range
                else if (y >= 112 && y <= 134)
                {
                    if (MessageBox.Show("Bạn có muốn chuyển đổi bảng này thành vùng dữ liệu thông thường không?", "ZenQ Calc", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
                    {
                        calcView.ConvertTableToRange(tbl);
                        ActiveRibbonTab = 0;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
            }

            // Group 3: Dữ liệu ngoài (X: 268..376)
            if (x >= 268 && x <= 376)
            {
                // Export (Xuất bảng dữ liệu ra CSV / Text)
                if (x <= 320 && y >= 70 && y <= 128)
                {
                    using (SaveFileDialog sfd = new SaveFileDialog())
                    {
                        sfd.Title = "Xuất dữ liệu bảng ra CSV / Tệp văn bản";
                        sfd.Filter = "Tệp CSV (phân cách bằng dấu phẩy) (*.csv)|*.csv|Tệp văn bản (*.txt)|*.txt";
                        sfd.FileName = (tbl != null && !string.IsNullOrEmpty(tbl.Name) ? tbl.Name : "BangDuLieu") + ".csv";
                        if (sfd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            try
                            {
                                var sb = new System.Text.StringBuilder();
                                if (tbl != null && calcView != null && calcView.CurrentSheet != null)
                                {
                                    for (uint r = tbl.StartRow; r <= tbl.EndRow; r++)
                                    {
                                        var rowCells = new List<string>();
                                        for (uint c = tbl.StartCol; c <= tbl.EndCol; c++)
                                        {
                                            var cell = calcView.CurrentSheet.GetCell(r, c);
                                            string cellVal = cell != null ? (cell.EvaluatedStr ?? cell.RawValue ?? "") : "";
                                            if (cellVal.Contains(",") || cellVal.Contains("\"") || cellVal.Contains("\n"))
                                            {
                                                cellVal = "\"" + cellVal.Replace("\"", "\"\"") + "\"";
                                            }
                                            rowCells.Add(cellVal);
                                        }
                                        sb.AppendLine(string.Join(",", rowCells));
                                    }
                                    System.IO.File.WriteAllText(sfd.FileName, sb.ToString(), System.Text.Encoding.UTF8);
                                    MessageBox.Show("Đã xuất thành công bảng '" + tbl.Name + "' ra tệp:\n" + sfd.FileName, "ZenQ Calc", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                }
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Lỗi xuất bảng: " + ex.Message, "ZenQ Calc", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    return true;
                }
                // Refresh
                else if (x >= 321 && y >= 70 && y <= 128)
                {
                    FormulaEngine.EvaluateSheet(calcView.CurrentSheet);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 4: Tùy chọn Kiểu Bảng (X: 380..700)
            if (x >= 380 && x <= 700)
            {
                // Col 1 (X: 380..485)
                if (x >= 380 && x <= 485)
                {
                    if (y >= 70 && y <= 90) // Dòng tiêu đề
                    {
                        tbl.HasHeaders = !tbl.HasHeaders;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 91 && y <= 111) // Dòng tổng cộng
                    {
                        calcView.ToggleTableTotalRow(tbl);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 112 && y <= 132) // Dòng xen kẽ
                    {
                        tbl.BandedRows = !tbl.BandedRows;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                // Col 2 (X: 486..590)
                else if (x >= 486 && x <= 590)
                {
                    if (y >= 70 && y <= 90) // Cột đầu tiên
                    {
                        tbl.FirstColumn = !tbl.FirstColumn;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 91 && y <= 111) // Cột cuối cùng
                    {
                        tbl.LastColumn = !tbl.LastColumn;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 112 && y <= 132) // Cột xen kẽ
                    {
                        tbl.BandedColumns = !tbl.BandedColumns;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                // Col 3 (X: 591..700)
                else if (x >= 591 && x <= 700)
                {
                    if (y >= 70 && y <= 90) // Nút lọc
                    {
                        tbl.ShowFilterButtons = !tbl.ShowFilterButtons;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
            }

            // Group 5: Kiểu Bảng Gallery (X: 710..1085, Y: 70..118)
            if (x >= 710 && x <= 1085 && y >= 70 && y <= 118)
            {
                int clickedStyle = (x - 710) / 62;
                if (clickedStyle >= 0 && clickedStyle < 6)
                {
                    calcView.ApplyTableStyle(tbl, clickedStyle);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            return false;
        }

        private bool HandlePowerPointTabExtensionsClick(int x, int y, SlidesView slidesView, Form parentForm)
        {
            if (slidesView == null) return false;

            // Group 1: Mẫu slide (X: 14..82)
            if (x >= 14 && x <= 82 && y >= 68 && y <= 130)
            {
                slidesView.ToggleElementsDrawer(0);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 2: Hình dạng (X: 90..162)
            if (x >= 90 && x <= 162 && y >= 68 && y <= 130)
            {
                slidesView.OpenShapesDrawer();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 3: Đồ họa (X: 170..238)
            if (x >= 170 && x <= 238 && y >= 68 && y <= 130)
            {
                slidesView.OpenGraphicsDrawer();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 4: Font chữ (X: 246..434)
            // Nút lớn: Font chữ ▾ (Mở Drawer Quản lý font chữ)
            if (x >= 246 && x <= 313 && y >= 68 && y <= 130)
            {
                slidesView.ToggleElementsDrawer(2);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // Nút trên: 📥 Nhập font...
            if (x >= 306 && x <= 425 && y >= 68 && y <= 98)
            {
                using (OpenFileDialog ofd = new OpenFileDialog())
                {
                    ofd.Filter = "Tệp phông chữ (*.ttf;*.otf)|*.ttf;*.otf|Tất cả tệp (*.*)|*.*";
                    ofd.Title = "Nhập phông chữ nội bộ vào ZenQOffice";
                    if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        string importedFont;
                        string errMsg;
                        if (SlideFontManager.ImportCustomFont(ofd.FileName, out importedFont, out errMsg))
                        {
                            LoadSystemFonts();
                            if (slidesView.SelectedShape != null)
                            {
                                slidesView.SelectedShape.FontName = importedFont;
                            }
                            SelectedFont = importedFont;
                            MessageBox.Show(parentForm, $"Đã nhập và kích hoạt thành công phông chữ '{importedFont}' vào ứng dụng!", "Nhập Font Thành Công", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        else
                        {
                            MessageBox.Show(parentForm, "Không thể nhập phông chữ: " + (errMsg ?? "Lỗi không xác định"), "Lỗi nhập font", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        }
                    }
                }
                return true;
            }
            // Nút dưới: 🔤 Font nội bộ ▾ (Danh sách phông chữ nội bộ)
            if (x >= 314 && x <= 433 && y >= 99 && y <= 130)
            {
                ContextMenuStrip fontMenu = new ContextMenuStrip();
                var customFonts = SlideFontManager.GetCustomFontNames();
                if (customFonts != null && customFonts.Count > 0)
                {
                    foreach (var fn in customFonts)
                    {
                        string fName = fn;
                        ToolStripMenuItem item = new ToolStripMenuItem(fName, null, (s, e) => {
                            SelectedFont = fName;
                            if (slidesView.SelectedShape != null)
                            {
                                slidesView.SelectedShape.FontName = fName;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        fontMenu.Items.Add(item);
                    }
                    fontMenu.Items.Add(new ToolStripSeparator());
                }
                else
                {
                    ToolStripMenuItem emptyItem = new ToolStripMenuItem("(Chưa có font nội bộ nào)");
                    emptyItem.Enabled = false;
                    fontMenu.Items.Add(emptyItem);
                }

                fontMenu.Items.Add("📥 Nhập phông chữ mới (.ttf, .otf)...", null, (s, e) => {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Filter = "Tệp phông chữ (*.ttf;*.otf)|*.ttf;*.otf|Tất cả tệp (*.*)|*.*";
                        ofd.Title = "Nhập phông chữ nội bộ vào ZenQOffice";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            string importedFont;
                            string errMsg;
                            if (SlideFontManager.ImportCustomFont(ofd.FileName, out importedFont, out errMsg))
                            {
                                LoadSystemFonts();
                                if (slidesView.SelectedShape != null)
                                {
                                    slidesView.SelectedShape.FontName = importedFont;
                                }
                                SelectedFont = importedFont;
                                MessageBox.Show(parentForm, $"Đã nhập và kích hoạt thành công phông chữ '{importedFont}' vào ứng dụng!", "Nhập Font Thành Công", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                if (parentForm != null) parentForm.Invalidate();
                            }
                            else
                            {
                                MessageBox.Show(parentForm, "Không thể nhập phông chữ: " + (errMsg ?? "Lỗi không xác định"), "Lỗi nhập font", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            }
                        }
                    }
                });

                fontMenu.Items.Add(new ToolStripSeparator());
                fontMenu.Items.Add("🇻🇳 Sửa lỗi Tiếng Việt & Trích xuất Font...", null, (s, e) => {
                    OpenVietnameseFontToolkit(parentForm);
                });

                fontMenu.Show(parentForm ?? Form.ActiveForm, new Point(x, y));
                return true;
            }

            // Group 4: Thương hiệu / Bảng màu (X: 434..506)
            if (x >= 442 && x <= 514 && y >= 68 && y <= 130)
            {
                slidesView.ToggleElementsDrawer(3);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 5: Phần bổ trợ (X: 514..662)
            if (x >= 522 && x <= 589 && y >= 68 && y <= 130)
            {
                slidesView.ToggleElementsDrawer(7);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 590 && x <= 670 && y >= 68 && y <= 130)
            {
                using (CreateQrCodeDialogForm dlg = new CreateQrCodeDialogForm())
                {
                    if (dlg.ShowDialog(parentForm) == DialogResult.OK && dlg.GeneratedQrBitmap != null)
                    {
                        slidesView.InsertQrCodeBitmap(dlg.GeneratedQrBitmap);
                        if (parentForm != null) parentForm.Invalidate();
                    }
                }
                return true;
            }

            return false;
        }

        private bool HandlePowerPointTabDrawClick(int x, int y, SlidesView slidesView, Form parentForm)
        {
            if (slidesView == null) return false;

            // Group 1: Công cụ (Tools)
            if (x >= 14 && x <= 66)
            {
                ActiveDrawTool = 0;
                slidesView.CancelShapeDrawMode();
                if (parentForm != null) { parentForm.Cursor = Cursors.Default; parentForm.Invalidate(); }
                return true;
            }
            if (x >= 68 && x <= 120)
            {
                ActiveDrawTool = 6;
                slidesView.CancelShapeDrawMode();
                if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetEraserCursor(); parentForm.Invalidate(); }
                return true;
            }

            // Group 2: Bút vẽ (Pens)
            if (x >= 134 && x <= 184)
            {
                ActiveDrawTool = 1;
                CustomPenIsHighlighter = false;
                slidesView.StartFreeformScribbleMode(Color.Black, 2.5f);
                if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetPenCursor(Color.Black); parentForm.Invalidate(); }
                return true;
            }
            if (x >= 186 && x <= 234)
            {
                ActiveDrawTool = 2;
                CustomPenIsHighlighter = false;
                slidesView.StartFreeformScribbleMode(Color.FromArgb(220, 38, 38), 2.5f);
                if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetPenCursor(Color.FromArgb(220, 38, 38)); parentForm.Invalidate(); }
                return true;
            }
            if (x >= 236 && x <= 284)
            {
                ActiveDrawTool = 3;
                CustomPenIsHighlighter = false;
                slidesView.StartFreeformScribbleMode(Color.FromArgb(37, 99, 235), 2.5f);
                if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetPenCursor(Color.FromArgb(37, 99, 235)); parentForm.Invalidate(); }
                return true;
            }
            if (x >= 286 && x <= 342)
            {
                ActiveDrawTool = 4;
                CustomPenIsHighlighter = true;
                slidesView.StartFreeformScribbleMode(Color.FromArgb(200, 250, 204, 21), 6.0f);
                if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetHighlighterCursor(Color.FromArgb(250, 204, 21)); parentForm.Invalidate(); }
                return true;
            }
            if (x >= 344 && x <= 400)
            {
                ActiveDrawTool = 5;
                CustomPenIsHighlighter = true;
                slidesView.StartFreeformScribbleMode(Color.FromArgb(200, 34, 197, 94), 6.0f);
                if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetHighlighterCursor(Color.FromArgb(34, 197, 94)); parentForm.Invalidate(); }
                return true;
            }
            if (x >= 402 && x <= 454)
            {
                ActiveDrawTool = 7;
                using (ColorDialog cd = new ColorDialog())
                {
                    cd.Color = CustomPenColor;
                    if (cd.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        CustomPenColor = cd.Color;
                        slidesView.StartFreeformScribbleMode(CustomPenColor, CustomPenIsHighlighter ? 6.0f : 2.5f);
                        if (parentForm != null)
                        {
                            parentForm.Cursor = CustomPenIsHighlighter
                                ? OfficeDrawingCursorHelper.GetHighlighterCursor(cd.Color)
                                : OfficeDrawingCursorHelper.GetPenCursor(cd.Color);
                            parentForm.Invalidate();
                        }
                    }
                }
                return true;
            }
            if (x >= 456 && x <= 512)
            {
                ContextMenuStrip penMenu = new ContextMenuStrip();
                penMenu.Items.Add("🖊️ Thêm Bút thường...", null, (s, e) => {
                    using (ColorDialog cd = new ColorDialog()) {
                        if (cd.ShowDialog(parentForm) == DialogResult.OK) {
                            CustomPenColor = cd.Color;
                            CustomPenIsHighlighter = false;
                            ActiveDrawTool = 7;
                            slidesView.StartFreeformScribbleMode(CustomPenColor, 2.5f);
                            if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetPenCursor(cd.Color); parentForm.Invalidate(); }
                        }
                    }
                });
                penMenu.Items.Add("🖍️ Thêm Bút dạ quang...", null, (s, e) => {
                    using (ColorDialog cd = new ColorDialog()) {
                        if (cd.ShowDialog(parentForm) == DialogResult.OK) {
                            CustomPenColor = cd.Color;
                            CustomPenIsHighlighter = true;
                            ActiveDrawTool = 7;
                            slidesView.StartFreeformScribbleMode(Color.FromArgb(200, cd.Color.R, cd.Color.G, cd.Color.B), 6.0f);
                            if (parentForm != null) { parentForm.Cursor = OfficeDrawingCursorHelper.GetHighlighterCursor(cd.Color); parentForm.Invalidate(); }
                        }
                    }
                });
                penMenu.Show(parentForm ?? Form.ActiveForm, new Point(x, y));
                return true;
            }
            return false;
        }

        private bool HandlePowerPointTabReviewClick(int x, int y, SlidesView slidesView, Form parentForm)
        {
            if (slidesView == null) return false;

            // Group 1: Kiểm tra
            if (x >= 14 && x <= 78) // Chính tả
            {
                MessageBox.Show(parentForm, "Kiểm tra chính tả hoàn tất! Không phát hiện lỗi chính tả trên trang slide hiện tại.", "Soát lỗi chính tả", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return true;
            }
            if (x >= 80 && x <= 154) // Đồng nghĩa
            {
                string selWord = slidesView.SelectedShape?.Text ?? "";
                using (ThesaurusDialogForm tDlg = new ThesaurusDialogForm(selWord, null))
                {
                    tDlg.ShowDialog(parentForm);
                }
                return true;
            }
            if (x >= 156 && x <= 224) // Đếm từ
            {
                int slideCount = slidesView.Presentation?.Slides.Count ?? 1;
                int wordCount = 0;
                int charCount = 0;
                if (slidesView.Presentation != null)
                {
                    foreach (var sl in slidesView.Presentation.Slides)
                    {
                        foreach (var sh in sl.Shapes)
                        {
                            if (!string.IsNullOrEmpty(sh.Text))
                            {
                                charCount += sh.Text.Length;
                                wordCount += sh.Text.Split(new char[] { ' ', '\r', '\n', '\t' }, StringSplitOptions.RemoveEmptyEntries).Length;
                            }
                        }
                    }
                }
                using (WordCountForm wcDlg = new WordCountForm(slideCount, wordCount, charCount, charCount, slideCount, slideCount))
                {
                    wcDlg.ShowDialog(parentForm);
                }
                return true;
            }
            // Group 2: Ngôn ngữ
            if (x >= 238 && x <= 298) // Đọc to
            {
                string textToRead = slidesView.SelectedShape?.Text ?? "";
                if (!string.IsNullOrEmpty(textToRead))
                {
                    ZenQOffice.Core.SpeechHelper.ToggleSpeech(textToRead);
                }
                return true;
            }
            if (x >= 300 && x <= 358) // Dịch
            {
                string textToTr = slidesView.SelectedShape?.Text ?? "";
                using (TranslationDialogForm dlg = new TranslationDialogForm(textToTr, null))
                {
                    dlg.ShowDialog(parentForm);
                }
                return true;
            }

            // Group 6: Font & Tiếng Việt
            if (x >= 970 && x <= 1076)
            {
                OpenVietnameseFontToolkit(parentForm);
                return true;
            }

            return false;
        }

        private void ShowShapeEffectsMenu(SlidesView slidesView, ShapeNode shape, Form parentForm, Point pt)
        {
            if (slidesView == null || shape == null) return;
            ContextMenuStrip fxMenu = new ContextMenuStrip();
            fxMenu.Font = new Font("Segoe UI", 9f);
            fxMenu.ShowImageMargin = true;

            // 1. Soft Shadows
            ToolStripMenuItem miShadow = new ToolStripMenuItem("🌟 Đổ bóng mềm (Gaussian Soft Shadow)");
            miShadow.DropDownItems.Add(new ToolStripMenuItem("❌ Tắt đổ bóng", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasShadow = false;
                shape.InvalidateShadowCache();
                if (parentForm != null) parentForm.Invalidate();
            }));
            miShadow.DropDownItems.Add(new ToolStripMenuItem("☁️ Bóng đổ mềm nhẹ (Subtle Soft)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasShadow = true;
                shape.ShadowOffsetX = 0f;
                shape.ShadowOffsetY = 8f;
                shape.ShadowBlur = 16f;
                shape.ShadowOpacity = 0.28f;
                shape.ShadowColor = 0x000000;
                shape.InvalidateShadowCache();
                if (parentForm != null) parentForm.Invalidate();
            }));
            miShadow.DropDownItems.Add(new ToolStripMenuItem("🏢 Bóng nổi 3D (Elevated 3D)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasShadow = true;
                shape.ShadowOffsetX = 0f;
                shape.ShadowOffsetY = 16f;
                shape.ShadowBlur = 32f;
                shape.ShadowOpacity = 0.35f;
                shape.ShadowColor = 0x000000;
                shape.InvalidateShadowCache();
                if (parentForm != null) parentForm.Invalidate();
            }));
            miShadow.DropDownItems.Add(new ToolStripMenuItem("✨ Hào quang phát sáng (Soft Glow)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasShadow = true;
                shape.ShadowOffsetX = 0f;
                shape.ShadowOffsetY = 0f;
                shape.ShadowBlur = 24f;
                shape.ShadowOpacity = 0.50f;
                shape.ShadowColor = (shape.FillColor != 0 && shape.FillColor != 0x00FFFFFF) ? shape.FillColor : 0x2563EB;
                shape.InvalidateShadowCache();
                if (parentForm != null) parentForm.Invalidate();
            }));
            miShadow.DropDownItems.Add(new ToolStripMenuItem("🌑 Đổ bóng sâu cổ điển (Deep Drop)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasShadow = true;
                shape.ShadowOffsetX = 6f;
                shape.ShadowOffsetY = 12f;
                shape.ShadowBlur = 20f;
                shape.ShadowOpacity = 0.45f;
                shape.ShadowColor = 0x000000;
                shape.InvalidateShadowCache();
                if (parentForm != null) parentForm.Invalidate();
            }));
            fxMenu.Items.Add(miShadow);

            // 2. Glassmorphism
            ToolStripMenuItem miGlass = new ToolStripMenuItem("🪟 Hiệu ứng Kính mờ (Glassmorphism Acrylic)");
            miGlass.DropDownItems.Add(new ToolStripMenuItem("❌ Tắt hiệu ứng kính", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasGlassmorphism = false;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miGlass.DropDownItems.Add(new ToolStripMenuItem("❄️ Kính mờ tuyết trắng (Frosted White)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasGlassmorphism = true;
                shape.GlassTintColor = 0xFFFFFF;
                shape.GlassTintOpacity = 0.35f;
                shape.GlassBorderOpacity = 0.55f;
                shape.GlassBlurRadius = 15f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miGlass.DropDownItems.Add(new ToolStripMenuItem("🕶️ Kính mờ Acrylic tối (Dark Acrylic)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasGlassmorphism = true;
                shape.GlassTintColor = 0x1E293B;
                shape.GlassTintOpacity = 0.55f;
                shape.GlassBorderOpacity = 0.30f;
                shape.GlassBlurRadius = 18f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miGlass.DropDownItems.Add(new ToolStripMenuItem("🎨 Kính mờ theo màu hình (Tinted Glass)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasGlassmorphism = true;
                shape.GlassTintColor = shape.FillColor;
                shape.GlassTintOpacity = 0.40f;
                shape.GlassBorderOpacity = 0.45f;
                shape.GlassBlurRadius = 16f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            fxMenu.Items.Add(miGlass);

            // 3. Radial Gradient
            ToolStripMenuItem miGrad = new ToolStripMenuItem("🌈 Kiểu dải màu (Linear / Radial Gradient)");
            miGrad.DropDownItems.Add(new ToolStripMenuItem("➡️ Chuyển màu thẳng (Linear Gradient)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.GradientType = GradientType.Linear;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miGrad.DropDownItems.Add(new ToolStripMenuItem("🎯 Chuyển màu tâm tỏa tròn (Radial Gradient)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.GradientType = GradientType.Radial;
                if (parentForm != null) parentForm.Invalidate();
            }));
            fxMenu.Items.Add(miGrad);

            // 4. Text Warp
            ToolStripMenuItem miWarp = new ToolStripMenuItem("🌀 Uốn cong chữ nghệ thuật (Text Warp)");
            miWarp.DropDownItems.Add(new ToolStripMenuItem("Chữ thẳng bình thường (None)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.TextWarpType = TextWarpType.None;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miWarp.DropDownItems.Add(new ToolStripMenuItem("Uốn cong vòm lên (Arc Up ⏜)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.TextWarpType = TextWarpType.ArcUp;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miWarp.DropDownItems.Add(new ToolStripMenuItem("Uốn cong vòm xuống (Arc Down ⏝)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.TextWarpType = TextWarpType.ArcDown;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miWarp.DropDownItems.Add(new ToolStripMenuItem("Uốn lượn sóng (Wave 〰)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.TextWarpType = TextWarpType.Wave;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miWarp.DropDownItems.Add(new ToolStripMenuItem("Uốn tròn 360° (Circle ◯)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.TextWarpType = TextWarpType.Circle;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miWarp.DropDownItems.Add(new ToolStripMenuItem("Cổng vòm (Arch ⛩)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.TextWarpType = TextWarpType.Arch;
                if (parentForm != null) parentForm.Invalidate();
            }));
            fxMenu.Items.Add(miWarp);

            fxMenu.Items.Add(new ToolStripSeparator());
            fxMenu.Items.Add("✨ Phát sáng viền vàng (Gold Outline)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.StrokeWidth = 4f;
                shape.StrokeColor = Color.FromArgb(250, 204, 21).ToArgb();
                if (parentForm != null) parentForm.Invalidate();
            });
            fxMenu.Items.Add("❌ Tắt toàn bộ hiệu ứng (Reset)", null, (s, e) => {
                slidesView.SaveUndoState();
                shape.HasShadow = false;
                shape.HasGlassmorphism = false;
                shape.TextWarpType = TextWarpType.None;
                shape.GradientType = GradientType.Linear;
                shape.InvalidateShadowCache();
                if (parentForm != null) parentForm.Invalidate();
            });

            Point screenPt = parentForm != null ? parentForm.PointToScreen(pt) : pt;
            fxMenu.Show(screenPt);
        }

        private bool HandlePowerPointTabGraphicsFormatClick(int x, int y, SlidesView slidesView, Form parentForm)
        {
            if (slidesView == null || slidesView.SelectedShape == null) return false;
            ShapeNode shape = slidesView.SelectedShape;

            // Group 1: Thay đổi Đồ họa (Change Graphic)
            if (x >= 14 && x <= 90 && y >= 68 && y <= 122)
            {
                ContextMenuStrip chgMenu = new ContextMenuStrip();
                chgMenu.RenderMode = ToolStripRenderMode.System;
                chgMenu.Items.Add("📁 Từ tệp (File)...", null, (s, e) =>
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Filter = "Tệp Đồ họa (*.svg;*.png;*.jpg;*.jpeg;*.emf)|*.svg;*.png;*.jpg;*.jpeg;*.emf|Tất cả tệp (*.*)|*.*";
                        ofd.Title = "Chọn tệp đồ họa mới";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            slidesView.SaveUndoState();
                            try
                            {
                                if (ofd.FileName.EndsWith(".svg", StringComparison.OrdinalIgnoreCase))
                                {
                                    shape.ImagePath = ofd.FileName;
                                    shape.IsSvg = true;
                                    shape.IsGraphic = true;
                                    shape.CachedImage = ZenQOffice.Core.SvgRasterizer.RenderSvgToBitmap(ofd.FileName, 1600, 1600);
                                }
                                else
                                {
                                    shape.ImagePath = ofd.FileName;
                                    shape.CachedImage = Image.FromFile(ofd.FileName);
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Không thể nạp tệp: " + ex.Message, "Lỗi Nạp Tệp", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                });
                chgMenu.Items.Add("🎨 Từ kho Đồ họa & Biểu tượng...", null, (s, e) =>
                {
                    slidesView.OpenGraphicsDrawer();
                    if (parentForm != null) parentForm.Invalidate();
                });
                chgMenu.Items.Add("📋 Từ Bảng tạm (Clipboard)", null, (s, e) =>
                {
                    if (Clipboard.ContainsImage())
                    {
                        slidesView.SaveUndoState();
                        shape.CachedImage = Clipboard.GetImage();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                });
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(14, 124)) : new Point(14, 124);
                chgMenu.Show(pt);
                return true;
            }
            if (x >= 94 && x <= 188 && y >= 68 && y <= 122)
            {
                slidesView.SaveUndoState();
                shape.IsGraphic = false;
                shape.IsSvg = false;
                if (shape.Type == ShapeType.Image) shape.Type = ShapeType.Rectangle;
                MessageBox.Show(parentForm, "Đã chuyển đổi đồ họa sang hình khối vector độc lập có thể tùy biến đường viền và tô màu toàn diện!", "Chuyển Đổi Thành Hình Dạng", MessageBoxButtons.OK, MessageBoxIcon.Information);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Group 2: Kiểu Đồ họa
            Color[] styleColors = new Color[] {
                Color.FromArgb(37, 99, 235),
                Color.FromArgb(220, 38, 38),
                Color.FromArgb(16, 185, 129),
                Color.FromArgb(245, 158, 11),
                Color.FromArgb(107, 114, 128)
            };
            for (int i = 0; i < styleColors.Length; i++)
            {
                int bx = 196 + i * 36;
                if (x >= bx && x <= bx + 32 && y >= 68 && y <= 122)
                {
                    slidesView.SaveUndoState();
                    shape.FillColor = styleColors[i].ToArgb();
                    shape.StrokeColor = Color.White.ToArgb();
                    shape.StrokeWidth = 1.5f;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            if (x >= 380 && x <= 500 && y >= 68 && y <= 92)
            {
                using (ColorDialog cd = new ColorDialog())
                {
                    cd.Color = Color.FromArgb(shape.FillColor);
                    if (cd.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        slidesView.SaveUndoState();
                        shape.FillColor = cd.Color.ToArgb();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                }
                return true;
            }
            if (x >= 380 && x <= 500 && y >= 94 && y <= 118)
            {
                using (ColorDialog cd = new ColorDialog())
                {
                    cd.Color = Color.FromArgb(shape.StrokeColor);
                    if (cd.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        slidesView.SaveUndoState();
                        shape.StrokeColor = cd.Color.ToArgb();
                        if (shape.StrokeWidth <= 0) shape.StrokeWidth = 2f;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                }
                return true;
            }
            if (x >= 380 && x <= 500 && y >= 120 && y <= 144)
            {
                ShowShapeEffectsMenu(slidesView, shape, parentForm, new Point(380, 144));
                return true;
            }

            // Group 3: Sắp xếp (Arrange)
            if (x >= 512 && x <= 608 && y >= 68 && y <= 86)
            {
                if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex < slidesView.ActiveSlide.Shapes.Count - 1)
                {
                    slidesView.SaveUndoState();
                    int idx = slidesView.SelectedShapeIndex;
                    ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                    slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx + 1];
                    slidesView.ActiveSlide.Shapes[idx + 1] = s1;
                    slidesView.SelectedShapeIndex = idx + 1;
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 512 && x <= 608 && y >= 88 && y <= 106)
            {
                if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex > 0)
                {
                    slidesView.SaveUndoState();
                    int idx = slidesView.SelectedShapeIndex;
                    ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                    slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx - 1];
                    slidesView.ActiveSlide.Shapes[idx - 1] = s1;
                    slidesView.SelectedShapeIndex = idx - 1;
                }
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 512 && x <= 608 && y >= 108 && y <= 126)
            {
                slidesView.SidebarPanel = SidebarPanelType.SelectionPane;
                slidesView.IsSidebarOpen = true;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 612 && x <= 700 && y >= 68 && y <= 86)
            {
                ContextMenuStrip alignMenu = new ContextMenuStrip();
                alignMenu.RenderMode = ToolStripRenderMode.System;
                alignMenu.Items.Add("Căn Trái", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.X = 0; if (parentForm != null) parentForm.Invalidate(); });
                alignMenu.Items.Add("Căn Giữa ngang", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.X = (slidesView.Presentation.CanvasWidth - shape.Transform.Width) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                alignMenu.Items.Add("Căn Phải", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.X = slidesView.Presentation.CanvasWidth - shape.Transform.Width; if (parentForm != null) parentForm.Invalidate(); });
                alignMenu.Items.Add(new ToolStripSeparator());
                alignMenu.Items.Add("Căn Trên", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.Y = 0; if (parentForm != null) parentForm.Invalidate(); });
                alignMenu.Items.Add("Căn Giữa dọc", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.Y = (slidesView.Presentation.CanvasHeight - shape.Transform.Height) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                alignMenu.Items.Add("Căn Dưới", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.Y = slidesView.Presentation.CanvasHeight - shape.Transform.Height; if (parentForm != null) parentForm.Invalidate(); });
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(612, 86)) : new Point(612, 86);
                alignMenu.Show(pt);
                return true;
            }
            if (x >= 612 && x <= 700 && y >= 108 && y <= 126)
            {
                ContextMenuStrip rotMenu = new ContextMenuStrip();
                rotMenu.RenderMode = ToolStripRenderMode.System;
                rotMenu.Items.Add("Xoay phải 90°", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.Rotation = (shape.Transform.Rotation + 90f) % 360f; if (parentForm != null) parentForm.Invalidate(); });
                rotMenu.Items.Add("Xoay trái 90°", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.Rotation = (shape.Transform.Rotation + 270f) % 360f; if (parentForm != null) parentForm.Invalidate(); });
                rotMenu.Items.Add("Lật dọc", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.FlipVertical = !shape.Transform.FlipVertical; if (parentForm != null) parentForm.Invalidate(); });
                rotMenu.Items.Add("Lật ngang", null, (s, e) => { slidesView.SaveUndoState(); shape.Transform.FlipHorizontal = !shape.Transform.FlipHorizontal; if (parentForm != null) parentForm.Invalidate(); });
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(612, 126)) : new Point(612, 126);
                rotMenu.Show(pt);
                return true;
            }

            // Group 4: Kích thước & Cắt
            if (x >= 708 && x <= 772 && y >= 68 && y <= 122)
            {
                slidesView.ToggleCropMode();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 776 && x <= 906 && y >= 68 && y <= 92)
            {
                slidesView.SaveUndoState();
                shape.Transform.Height = Math.Max(20f, shape.Transform.Height + 25f);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            if (x >= 776 && x <= 906 && y >= 94 && y <= 118)
            {
                slidesView.SaveUndoState();
                shape.Transform.Width = Math.Max(20f, shape.Transform.Width + 25f);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            return false;
        }

        private bool HandlePowerPointRibbonClick(int x, int y, SlidesView slidesView, Form parentForm)
        {
            if (slidesView != null && slidesView.IsRemovingBackground)
            {
                if (y >= 68 && y <= 122)
                {
                    // 1. Xóa tự động (Auto Remove) (X: 12..98)
                    if (x >= 12 && x <= 98)
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.AutoRemoveBackgroundDirect(slidesView.SelectedShape);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // 2. Chọn màu xóa (Chroma Key CapCut) (X: 104..196)
                    else if (x >= 104 && x <= 196)
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.StartColorPickMode(slidesView.SelectedShape);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // 3. Giữ vùng (+) (X: 208..304)
                    else if (x >= 208 && x <= 304)
                    {
                        slidesView.IsColorPickingMode = false;
                        slidesView.BgRemovalTool = "Keep";
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 4. Xóa vùng (-) (X: 310..406)
                    else if (x >= 310 && x <= 406)
                    {
                        slidesView.IsColorPickingMode = false;
                        slidesView.BgRemovalTool = "Remove";
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 5. Xóa dấu (Delete Mark) (X: 412..490)
                    else if (x >= 412 && x <= 490)
                    {
                        slidesView.DeleteLastBgMark();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 6. Hủy thay đổi (Discard All Changes) (X: 502..596)
                    else if (x >= 502 && x <= 596)
                    {
                        slidesView.EndBackgroundRemoval(false);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 7. Giữ thay đổi (Keep Changes) (X: 602..696)
                    else if (x >= 602 && x <= 696)
                    {
                        slidesView.EndBackgroundRemoval(true);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                return true;
            }

            string curTab = (RibbonTabs != null && ActiveRibbonTab >= 0 && ActiveRibbonTab < RibbonTabs.Length) ? RibbonTabs[ActiveRibbonTab] : "";

            if (curTab == "Mở rộng")
            {
                return HandlePowerPointTabExtensionsClick(x, y, slidesView, parentForm);
            }
            if (curTab == "Vẽ")
            {
                return HandlePowerPointTabDrawClick(x, y, slidesView, parentForm);
            }
            if (curTab == "Xem lại")
            {
                return HandlePowerPointTabReviewClick(x, y, slidesView, parentForm);
            }
            if (curTab == "Định dạng Đồ họa")
            {
                return HandlePowerPointTabGraphicsFormatClick(x, y, slidesView, parentForm);
            }

            if (curTab == "Trang đầu" || (ActiveRibbonTab == 0 && string.IsNullOrEmpty(curTab))) // Trang đầu (Home)
            {
                // Dialog Launchers
                if (BtnSlidesClipboardLauncherBounds.Contains(x, y))
                {
                    ContextMenuStrip clipMenu = new ContextMenuStrip();
                    clipMenu.Items.Add("Dán (Paste)", null, (s, e) => { slidesView.Paste(); if (parentForm != null) parentForm.Invalidate(); });
                    clipMenu.Items.Add("Sao chép (Copy)", null, (s, e) => { slidesView.Copy(); });
                    clipMenu.Items.Add("Cắt (Cut)", null, (s, e) => { slidesView.Cut(); if (parentForm != null) parentForm.Invalidate(); });
                    clipMenu.Show(parentForm ?? Form.ActiveForm, new Point(x, y));
                    return true;
                }
                else if (BtnSlidesFontLauncherBounds.Contains(x, y))
                {
                    ShapeNode targetShape = slidesView.SelectedShape;
                    using (SlideFontDialogForm dlg = new SlideFontDialogForm(targetShape))
                    {
                        if (dlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (targetShape != null)
                            {
                                dlg.ApplyToShape(targetShape);
                            }
                            else
                            {
                                SelectedFont = dlg.FontNameResult;
                                FontSize = dlg.FontSizeResult;
                                IsBold = dlg.BoldResult;
                                IsItalic = dlg.ItalicResult;
                                IsUnderline = dlg.UnderlineResult;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                else if (BtnSlidesParaLauncherBounds.Contains(x, y))
                {
                    ShapeNode targetShape = slidesView.SelectedShape;
                    using (SlideParagraphDialogForm dlg = new SlideParagraphDialogForm(targetShape))
                    {
                        if (dlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (targetShape != null)
                            {
                                dlg.ApplyToShape(targetShape);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                else if (BtnSlidesDrawingLauncherBounds.Contains(x, y))
                {
                    ShapeNode targetShape = slidesView.SelectedShape;
                    using (SlideFormatShapeForm dlg = new SlideFormatShapeForm(targetShape))
                    {
                        if (dlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (targetShape != null)
                            {
                                dlg.ApplyToShape(targetShape);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }

                // Dán (Paste) (X: 14..68, Y: 68..130)
                if (x >= 14 && x <= 68 && y >= 68 && y <= 130)
                {
                    slidesView.Paste();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Cắt (Cut) (X: 72..204, Y: 68..88)
                else if (x >= 72 && x <= 204 && y >= 68 && y <= 88)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.Cut();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                // Chép (Copy) (X: 72..204, Y: 89..109)
                else if (x >= 72 && x <= 204 && y >= 89 && y <= 109)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.Copy();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                // Slide Mới
                else if (x >= 212 && x <= 276 && y >= 68 && y <= 130)
                {
                    slidesView.AddSlide();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Bố cục Layout (Mở SlideLayoutGalleryDropDownForm với thumbnail đầy đủ)
                else if (x >= 280 && x <= 372 && y >= 68 && y <= 88)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(280, 88)) : new Point(280, 88);
                    SlideLayoutType curL = (slidesView.ActiveSlide != null) ? slidesView.ActiveSlide.Layout : SlideLayoutType.TitleAndContent;
                    SlideLayoutGalleryDropDownForm dlg = new SlideLayoutGalleryDropDownForm(pt, curL, (chosenLayout) =>
                    {
                        slidesView.SetLayout(chosenLayout);
                        if (parentForm != null) parentForm.Invalidate();
                        if (Parent != null) Parent.Invalidate();
                    });
                    dlg.Show(parentForm);
                    return true;
                }
                // Đặt lại Reset
                else if (x >= 280 && x <= 372 && y >= 89 && y <= 109)
                {
                    if (slidesView.ActiveSlide != null)
                    {
                        slidesView.ApplySlideLayoutTemplate(slidesView.ActiveSlide, slidesView.ActiveSlide.Layout);
                        if (parentForm != null) parentForm.Invalidate();
                        if (Parent != null) Parent.Invalidate();
                    }
                    return true;
                }
                // Nhân bản Duplicate
                else if (x >= 280 && x <= 372 && y >= 110 && y <= 130)
                {
                    slidesView.DuplicateActiveSlide();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Phông chữ (Font Family Dropdown) (X: 384 to 504, Y: 68 to 92)
                else if (x >= 384 && x <= 504 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape == null) return true;
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(384, 96)) : new Point(384, 96);
                    string curF = slidesView.SelectedShape.FontName;
                    FontDropDownForm fontDlg = new FontDropDownForm(curF, pt, AvailableSystemFonts, Color.FromArgb(210, 71, 38));
                    fontDlg.OnFontSelected += (font) =>
                    {
                        SelectedFont = font;
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.SelectedShape.FontName = font;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    fontDlg.Show();
                    return true;
                }
                // Cỡ chữ (Font Size Dropdown) (X: 508 to 552, Y: 68 to 92)
                else if (x >= 508 && x <= 552 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape == null) return true;
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(508, 96)) : new Point(508, 96);
                    float curSz = slidesView.SelectedShape.FontSize;
                    SizeDropDownForm sizeDlg = new SizeDropDownForm(curSz, pt, Color.FromArgb(210, 71, 38));
                    sizeDlg.OnSizeSelected += (sz) =>
                    {
                        FontSize = sz;
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.SelectedShape.FontSize = sz;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    sizeDlg.Show();
                    return true;
                }
                // Tăng cỡ chữ A^
                else if (x >= 556 && x <= 580 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape == null) return true;
                    slidesView.SelectedShape.FontSize = Math.Min(96f, slidesView.SelectedShape.FontSize + 4f);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Giảm cỡ chữ Av
                else if (x >= 582 && x <= 606 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape == null) return true;
                    slidesView.SelectedShape.FontSize = Math.Max(8f, slidesView.SelectedShape.FontSize - 4f);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Xóa định dạng (Clear All Formatting)
                else if (x >= 608 && x <= 634 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.FontSize = 18f;
                        slidesView.SelectedShape.Bold = false;
                        slidesView.SelectedShape.Italic = false;
                        slidesView.SelectedShape.Underline = false;
                        slidesView.SelectedShape.Strikethrough = false;
                        slidesView.SelectedShape.HasTextShadow = false;
                        slidesView.SelectedShape.TextColor = (slidesView.SelectedShape.Type == ShapeType.TextBox) ? 0x0F172A : 0xFFFFFF;
                        slidesView.SelectedShape.HasHighlight = false;
                        slidesView.SelectedShape.HighlightColor = 0;
                        slidesView.SelectedShape.CharacterSpacing = 0f;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                // Đậm Bold
                else if (x >= 384 && x <= 406 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        if (slidesView.SelectedShape.Type == ShapeType.Table)
                        {
                            ShapeNode tShape = slidesView.SelectedShape;
                            string cellKey = (tShape.TableSelectedCellRow >= 0 ? tShape.TableSelectedCellRow : 0) + "," + (tShape.TableSelectedCellCol >= 0 ? tShape.TableSelectedCellCol : 0);
                            bool isCurrentlyBold = (tShape.TableCellBolds != null && tShape.TableCellBolds.ContainsKey(cellKey) && tShape.TableCellBolds[cellKey]);
                            slidesView.SetSelectedTableCellBold(!isCurrentlyBold);
                        }
                        else
                        {
                            slidesView.SelectedShape.Bold = !slidesView.SelectedShape.Bold;
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nghiêng Italic
                else if (x >= 407 && x <= 429 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Italic = !slidesView.SelectedShape.Italic;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Gạch dưới Underline
                else if (x >= 430 && x <= 452 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Underline = !slidesView.SelectedShape.Underline;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Bóng chữ Text Shadow (S)
                else if (x >= 453 && x <= 475 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.HasTextShadow = !slidesView.SelectedShape.HasTextShadow;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Gạch ngang chữ Strikethrough (ab)
                else if (x >= 476 && x <= 499 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Strikethrough = !slidesView.SelectedShape.Strikethrough;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Khoảng cách ký tự Character Spacing (AV ▾)
                else if (x >= 501 && x <= 530 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        ContextMenuStrip menu = new ContextMenuStrip();
                        menu.RenderMode = ToolStripRenderMode.System;
                        float[] spacings = new float[] { -2f, -1f, 0f, 3f, 6f };
                        string[] labels = new string[] {
                            "Rất chặt (Very Tight)",
                            "Chặt (Tight)",
                            "Bình thường (Normal)",
                            "Rộng (Loose)",
                            "Rất rộng (Very Loose)"
                        };
                        for (int mi = 0; mi < labels.Length; mi++)
                        {
                            float spVal = spacings[mi];
                            var item = menu.Items.Add(labels[mi], null, (s, e) => {
                                if (slidesView.SelectedShape != null)
                                {
                                    slidesView.SelectedShape.CharacterSpacing = spVal;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            });
                            if (Math.Abs(slidesView.SelectedShape.CharacterSpacing - spVal) < 0.1f)
                            {
                                ((ToolStripMenuItem)item).Checked = true;
                            }
                        }
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(501, 120)) : new Point(501, 120);
                        ShowRibbonDropdown(menu, parentForm, pt, new Rectangle(501, 96, 29, 24));
                    }
                    return true;
                }
                // Đổi kiểu chữ Change Case (Aa ▾)
                else if (x >= 531 && x <= 559 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        ContextMenuStrip menu = new ContextMenuStrip();
                        menu.RenderMode = ToolStripRenderMode.System;
                        string[] caseLabels = new string[] {
                            "Chữ đầu câu hoa (Sentence case)",
                            "chữ thường (lowercase)",
                            "CHỮ HOA (UPPERCASE)",
                            "Viết Hoa Từng Từ (Capitalize Each Word)",
                            "đỔI cỠ cHỮ (tOGGLE cASE)"
                        };
                        for (int mi = 0; mi < caseLabels.Length; mi++)
                        {
                            int mode = mi;
                            menu.Items.Add(caseLabels[mi], null, (s, e) => {
                                if (slidesView.SelectedShape != null && !string.IsNullOrEmpty(slidesView.SelectedShape.Text))
                                {
                                    slidesView.SelectedShape.Text = TransformCase(slidesView.SelectedShape.Text, mode);
                                    if (slidesView.SelectedShape.TextRuns != null)
                                    {
                                        foreach (var tr in slidesView.SelectedShape.TextRuns)
                                        {
                                            if (!string.IsNullOrEmpty(tr.Text))
                                                tr.Text = TransformCase(tr.Text, mode);
                                        }
                                    }
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            });
                        }
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(531, 120)) : new Point(531, 120);
                        ShowRibbonDropdown(menu, parentForm, pt, new Rectangle(531, 96, 28, 24));
                    }
                    return true;
                }
                // Màu dạ quang Highlighter ▾
                else if (x >= 568 && x <= 601 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape == null) return true;
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(568, 120)) : new Point(568, 120);
                    Color curHl = (slidesView.SelectedShape.HasHighlight && slidesView.SelectedShape.HighlightColor != 0)
                        ? Color.FromArgb(slidesView.SelectedShape.HighlightColor)
                        : Color.FromArgb(255, 235, 59);
                    ColorPaletteForm hlDlg = new ColorPaletteForm(pt, curHl, false);
                    hlDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.SelectedShape.HasHighlight = true;
                            slidesView.SelectedShape.HighlightColor = c.ToArgb();
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    hlDlg.Show();
                    return true;
                }
                // Màu phông chữ Font Color (A ▾)
                else if (x >= 603 && x <= 636 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape == null) return true;
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(603, 120)) : new Point(603, 120);
                    int tc = slidesView.SelectedShape.TextColor;
                    Color curC = Color.FromArgb((tc >> 16) & 0xFF, (tc >> 8) & 0xFF, tc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            if (slidesView.SelectedShape.Type == ShapeType.Table)
                            {
                                slidesView.SetSelectedTableCellTextColor(c.ToArgb());
                            }
                            else
                            {
                                slidesView.SelectedShape.TextColor = c.ToArgb() & 0xFFFFFF;
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Bullets (X: 648..680, Y: 68..92)
                else if (x >= 648 && x <= 680 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null && !string.IsNullOrEmpty(slidesView.SelectedShape.Text))
                    {
                        if (slidesView.SelectedShape.Text.StartsWith("• "))
                            slidesView.SelectedShape.Text = slidesView.SelectedShape.Text.Substring(2);
                        else
                            slidesView.SelectedShape.Text = "• " + slidesView.SelectedShape.Text.Replace("\n", "\n• ");
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Numbering (X: 682..714, Y: 68..92)
                else if (x >= 682 && x <= 714 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null && !string.IsNullOrEmpty(slidesView.SelectedShape.Text))
                    {
                        string[] lines = slidesView.SelectedShape.Text.Split('\n');
                        for (int li = 0; li < lines.Length; li++)
                        {
                            string trimmed = lines[li].TrimStart();
                            if (trimmed.Length > 2 && char.IsDigit(trimmed[0]) && trimmed[1] == '.')
                                lines[li] = trimmed.Substring(2).TrimStart();
                            else
                                lines[li] = $"{li + 1}. {lines[li]}";
                        }
                        slidesView.SelectedShape.Text = string.Join("\n", lines);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Decrease Indent (X: 720..744, Y: 68..92)
                else if (x >= 720 && x <= 744 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.MarginLeft = Math.Max(0f, (slidesView.SelectedShape.MarginLeft ?? 10f) - 10f);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Increase Indent (X: 746..770, Y: 68..92)
                else if (x >= 746 && x <= 770 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.MarginLeft = (slidesView.SelectedShape.MarginLeft ?? 10f) + 10f;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Line Spacing (X: 776..806, Y: 68..92)
                else if (x >= 776 && x <= 806 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        float curLs = slidesView.SelectedShape.LineSpacing;
                        slidesView.SelectedShape.LineSpacing = (curLs >= 2.0f) ? 1.0f : (curLs <= 0 ? 1.25f : curLs + 0.25f);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn trái Align Left (X: 648..672, Y: 96..120)
                else if (x >= 648 && x <= 672 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Alignment = TextAlignment.Left;
                        if (slidesView.SelectedShape.TextRuns != null)
                        {
                            foreach (var r in slidesView.SelectedShape.TextRuns) r.ParaAlignment = TextAlignment.Left;
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn giữa Align Center (X: 674..698, Y: 96..120)
                else if (x >= 674 && x <= 698 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Alignment = TextAlignment.Center;
                        if (slidesView.SelectedShape.TextRuns != null)
                        {
                            foreach (var r in slidesView.SelectedShape.TextRuns) r.ParaAlignment = TextAlignment.Center;
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn phải Align Right (X: 700..724, Y: 96..120)
                else if (x >= 700 && x <= 724 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Alignment = TextAlignment.Right;
                        if (slidesView.SelectedShape.TextRuns != null)
                        {
                            foreach (var r in slidesView.SelectedShape.TextRuns) r.ParaAlignment = TextAlignment.Right;
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn đều hai lề Justify (X: 726..750, Y: 96..120)
                else if (x >= 726 && x <= 750 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Alignment = TextAlignment.Justify;
                        if (slidesView.SelectedShape.TextRuns != null)
                        {
                            foreach (var r in slidesView.SelectedShape.TextRuns) r.ParaAlignment = TextAlignment.Justify;
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Columns (X: 756..786, Y: 96..120)
                else if (x >= 756 && x <= 786 && y >= 96 && y <= 120)
                {
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Text Direction (X: 810..914, Y: 68..88)
                else if (x >= 810 && x <= 914 && y >= 68 && y <= 88)
                {
                    if (slidesView.SelectedShape != null && slidesView.SelectedShape.Transform != null)
                    {
                        slidesView.SelectedShape.Transform.Rotation = (slidesView.SelectedShape.Transform.Rotation == 0) ? 90f : (slidesView.SelectedShape.Transform.Rotation == 90f ? 270f : 0f);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Align Text Vertical (X: 810..914, Y: 89..109)
                else if (x >= 810 && x <= 914 && y >= 89 && y <= 109)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        if (slidesView.SelectedShape.VerticalAlignment == VerticalTextAlignment.Top)
                            slidesView.SelectedShape.VerticalAlignment = VerticalTextAlignment.Middle;
                        else if (slidesView.SelectedShape.VerticalAlignment == VerticalTextAlignment.Middle)
                            slidesView.SelectedShape.VerticalAlignment = VerticalTextAlignment.Bottom;
                        else
                            slidesView.SelectedShape.VerticalAlignment = VerticalTextAlignment.Top;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Convert to SmartArt (X: 810..914, Y: 110..130)
                else if (slidesView.SelectedShape != null && x >= 810 && x <= 914 && y >= 110 && y <= 130)
                {
                    using (SmartArtGalleryForm saDlg = new SmartArtGalleryForm())
                    {
                        if (saDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(saDlg.SelectedSmartArtType))
                        {
                            string textToUse = (slidesView.SelectedShape != null && !string.IsNullOrEmpty(slidesView.SelectedShape.Text))
                                ? slidesView.SelectedShape.Text
                                : "";
                            slidesView.InsertSmartArt(saDlg.SelectedSmartArtType, saDlg.SelectedSmartArtName);
                            if (!string.IsNullOrEmpty(textToUse) && slidesView.SelectedShape != null)
                            {
                                slidesView.SelectedShape.Text = textToUse;
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Quick Shapes 3x6 Grid (X: 922..1041, Y: 68..124)
                else if (x >= 922 && x < 1042 && y >= 68 && y <= 124)
                {
                    int col = (x - 922) / 20;
                    int r = (y < 86) ? 0 : ((y < 104) ? 1 : 2);
                    ShapeType[][] allShapeRows = new ShapeType[][] {
                        new ShapeType[] { ShapeType.TextBox, ShapeType.Line, ShapeType.Arrow, ShapeType.CustomPath, ShapeType.Rectangle, ShapeType.Ellipse },
                        new ShapeType[] { ShapeType.RoundedRectangle, ShapeType.Triangle, ShapeType.Diamond, ShapeType.RightTriangle, ShapeType.BlockArrowRight, ShapeType.Callout },
                        new ShapeType[] { ShapeType.Lightning, ShapeType.Heart, ShapeType.Star, ShapeType.Cloud, ShapeType.Sun, ShapeType.Moon },
                        new ShapeType[] { ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.Chevron, ShapeType.Cube, ShapeType.Can, ShapeType.Donut },
                        new ShapeType[] { ShapeType.Hexagon, ShapeType.Octagon, ShapeType.Pentagon, ShapeType.Cross, ShapeType.Shield, ShapeType.Banner },
                        new ShapeType[] { ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Smiley, ShapeType.Starburst, ShapeType.Arch, ShapeType.Flower }
                    };
                    int sRow = Math.Max(0, Math.Min(allShapeRows.Length - 3, slidesView.ShapeGalleryScrollRow));
                    if (r >= 0 && r < 3 && col >= 0 && col < 6)
                    {
                        int actualRow = sRow + r;
                        if (actualRow >= 0 && actualRow < allShapeRows.Length)
                        {
                            ShapeType selShape = allShapeRows[actualRow][col];
                            slidesView.StartShapeDrawMode(selShape);
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Gallery Up/Down/More Buttons (X: 1042..1058, Y: 68..124)
                else if (x >= 1042 && x <= 1058 && y >= 68 && y <= 124)
                {
                    ShapeType[][] allShapeRows = new ShapeType[][] {
                        new ShapeType[] { ShapeType.TextBox, ShapeType.Line, ShapeType.Arrow, ShapeType.CustomPath, ShapeType.Rectangle, ShapeType.Ellipse },
                        new ShapeType[] { ShapeType.RoundedRectangle, ShapeType.Triangle, ShapeType.Diamond, ShapeType.RightTriangle, ShapeType.BlockArrowRight, ShapeType.Callout },
                        new ShapeType[] { ShapeType.Lightning, ShapeType.Heart, ShapeType.Star, ShapeType.Cloud, ShapeType.Sun, ShapeType.Moon },
                        new ShapeType[] { ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.Chevron, ShapeType.Cube, ShapeType.Can, ShapeType.Donut },
                        new ShapeType[] { ShapeType.Hexagon, ShapeType.Octagon, ShapeType.Pentagon, ShapeType.Cross, ShapeType.Shield, ShapeType.Banner },
                        new ShapeType[] { ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Smiley, ShapeType.Starburst, ShapeType.Arch, ShapeType.Flower }
                    };
                    // Up button ▲ (Y: 68..85)
                    if (y < 86)
                    {
                        slidesView.ShapeGalleryScrollRow = Math.Max(0, slidesView.ShapeGalleryScrollRow - 1);
                    }
                    // Down button ▼ (Y: 86..103)
                    else if (y < 104)
                    {
                        slidesView.ShapeGalleryScrollRow = Math.Min(allShapeRows.Length - 3, slidesView.ShapeGalleryScrollRow + 1);
                    }
                    // More button ⤓ (Xổ bảng) (Y: 104..124)
                    else
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(922, 126)) : new Point(922, 126);
                        ShapeGalleryPopup drop = new ShapeGalleryPopup();
                        drop.Location = pt;
                        drop.OnShapeSelected = (sType) =>
                        {
                            if (sType.Equals("FreeformShape", StringComparison.OrdinalIgnoreCase))
                            {
                                slidesView.StartFreeformShapeMode();
                            }
                            else if (sType.Equals("FreeformScribble", StringComparison.OrdinalIgnoreCase))
                            {
                                slidesView.StartFreeformScribbleMode();
                            }
                            else
                            {
                                ShapeType st = ParseShapeTypeForSlides(sType);
                                slidesView.StartShapeDrawMode(st);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        drop.Show();
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Arrange Button (Sắp xếp ▾) (X: 1062..1108, Y: 68..122)
                else if (x >= 1062 && x <= 1108 && y >= 68 && y <= 122)
                {
                    if (slidesView.SelectedShape == null) return true;
                    ShowArrangeMenu(parentForm, new Point(1062, 126), slidesView);
                    return true;
                }
                // Quick Styles (Kiểu nhanh ▾) (X: 1110..1156, Y: 68..122)
                else if (x >= 1110 && x <= 1156 && y >= 68 && y <= 122)
                {
                    if (slidesView.SelectedShape == null) return true;
                    slidesView.SelectedShape.FillColor = 0x2563EB;
                    slidesView.SelectedShape.StrokeColor = 0x1D4ED8;
                    slidesView.SelectedShape.TextColor = 0xFFFFFF;
                    slidesView.SelectedShape.StrokeWidth = 1.5f;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Màu tô hình (Shape Fill) (X: 1158..1252, Y: 68..88)
                else if (x >= 1158 && x <= 1252 && y >= 68 && y <= 88)
                {
                    if (slidesView.SelectedShape == null) return true;
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(1158, 92)) : new Point(1158, 92);
                    int fc = slidesView.SelectedShape.FillColor;
                    Color curC = Color.FromArgb((fc >> 16) & 0xFF, (fc >> 8) & 0xFF, fc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            if (slidesView.SelectedShape.Type == ShapeType.Table)
                            {
                                slidesView.SetSelectedTableCellFillColor(c.ToArgb());
                            }
                            else
                            {
                                if (c == Color.Transparent)
                                {
                                    slidesView.SelectedShape.FillOpacity = 0.0f;
                                }
                                else
                                {
                                    slidesView.SelectedShape.FillColor = c.ToArgb() & 0xFFFFFF;
                                    slidesView.SelectedShape.FillOpacity = 1.0f;
                                }
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Màu viền hình (Shape Outline) (X: 1158..1252, Y: 89..109)
                else if (x >= 1158 && x <= 1252 && y >= 89 && y <= 109)
                {
                    if (slidesView.SelectedShape == null) return true;
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(1158, 114)) : new Point(1158, 114);
                    int sc = slidesView.SelectedShape.StrokeColor;
                    Color curC = Color.FromArgb((sc >> 16) & 0xFF, (sc >> 8) & 0xFF, sc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            if (c == Color.Transparent)
                            {
                                slidesView.SelectedShape.StrokeWidth = 0.0f;
                            }
                            else
                            {
                                slidesView.SelectedShape.StrokeColor = c.ToArgb() & 0xFFFFFF;
                                if (slidesView.SelectedShape.StrokeWidth <= 0) slidesView.SelectedShape.StrokeWidth = 1.5f;
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Hiệu ứng hình khối (Shape Effects) (X: 1158..1252, Y: 110..130)
                else if (x >= 1158 && x <= 1252 && y >= 110 && y <= 130)
                {
                    if (slidesView.SelectedShape == null) return true;
                    ShowShapeEffectsMenu(slidesView, slidesView.SelectedShape, parentForm, new Point(1158, 130));
                    return true;
                }
                // F5 Trình Chiếu Fullscreen (X: 1262..1340, Y: 68..130)
                else if (x >= 1262 && x <= 1340 && y >= 68 && y <= 130)
                {
                    AppForm af = parentForm as AppForm;
                    if (af != null) af.StartSlideShow(true);
                    else slidesView.StartPresenting(true);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (curTab == "Chèn" || (ActiveRibbonTab == 1 && string.IsNullOrEmpty(curTab))) // Chèn (Insert)
            {
                // ==================== Group 1: Trang chiếu (Slides) (X: 14..72, Y: 68..124) ====================
                if (x >= 14 && x <= 72 && y >= 68 && y <= 124)
                {
                    slidesView.AddSlide();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // ==================== Group 2: Bảng (Tables) (X: 84..136, Y: 68..124) ====================
                else if (x >= 84 && x <= 136 && y >= 68 && y <= 124)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(84, 130)) : new Point(84, 130);
                    TablePickerForm pickerDlg = new TablePickerForm(pt);
                    pickerDlg.OnTableHovered += (cols, rows) =>
                    {
                        slidesView.SetTableInsertPreview(cols, rows);
                    };
                    pickerDlg.OnTableHoverLeave += () =>
                    {
                        slidesView.ClearTableInsertPreview();
                    };
                    pickerDlg.OnTableSelected += (cols, rows) =>
                    {
                        slidesView.InsertTable(cols, rows);
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    pickerDlg.OnCustomInsertClicked += () =>
                    {
                        using (CustomTableForm customDlg = new CustomTableForm())
                        {
                            if (customDlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                slidesView.InsertTable(customDlg.Columns, customDlg.Rows);
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                    };
                    pickerDlg.OnDrawTableClicked += () =>
                    {
                        slidesView.InsertTable(4, 3);
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    pickerDlg.OnExcelTableClicked += () =>
                    {
                        slidesView.InsertTable(5, 5);
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    pickerDlg.Show();
                    return true;
                }
                // ==================== Group 3: Hình ảnh (Images) (X: 148..284) ====================
                else if (x >= 148 && x <= 204 && y >= 68 && y <= 124) // Hình ảnh ▾
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.webp)|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.webp|Tất cả tệp (*.*)|*.*";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK && slidesView.ActiveSlide != null)
                        {
                            try
                            {
                                Image loadedImg = Image.FromFile(ofd.FileName);
                                float origW = Math.Max(1f, (float)loadedImg.Width);
                                float origH = Math.Max(1f, (float)loadedImg.Height);
                                float canvasW = (slidesView.Presentation != null) ? slidesView.Presentation.CanvasWidth : 1920f;
                                float canvasH = (slidesView.Presentation != null) ? slidesView.Presentation.CanvasHeight : 1080f;

                                float maxW = canvasW * 0.70f;
                                float maxH = canvasH * 0.70f;
                                float scaleFactor = Math.Min(maxW / origW, maxH / origH);
                                if (scaleFactor > 1.0f && origW > 120f && origH > 120f) scaleFactor = 1.0f;

                                float fitW = (float)Math.Round(origW * scaleFactor);
                                float fitH = (float)Math.Round(origH * scaleFactor);
                                float posX = (canvasW - fitW) / 2f;
                                float posY = (canvasH - fitH) / 2f;

                                ShapeNode imgShape = new ShapeNode
                                {
                                    Name = "Hình ảnh " + (slidesView.ActiveSlide.Shapes.Count + 1),
                                    Type = ShapeType.Image,
                                    ImagePath = ofd.FileName,
                                    CachedImage = loadedImg,
                                    Transform = new Transform2D(posX, posY, fitW, fitH),
                                    OriginalWidth = origW,
                                    OriginalHeight = origH,
                                    Text = "",
                                    FillColor = 0x00FFFFFF,
                                    StrokeWidth = 0f
                                };
                                slidesView.SaveUndoState();
                                slidesView.ActiveSlide.AddShape(imgShape);
                                slidesView.SelectedShapeIndex = slidesView.ActiveSlide.Shapes.Count - 1;
                                slidesView.SelectedShapeIndices.Clear();
                                slidesView.SelectedShapeIndices.Add(slidesView.SelectedShapeIndex);
                                if (slidesView.ActiveSlide != null) slidesView.ActiveSlide.IsThumbnailDirty = true;
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Không thể tải hình ảnh: " + ex.Message, "Lỗi Chèn Ảnh", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (x >= 208 && x <= 284 && y >= 68 && y <= 94) // Ảnh chụp màn hình ▾ (Chụp cắt màn hình trực tiếp - Screen Snip)
                {
                    using (ScreenSnippingForm snipDlg = new ScreenSnippingForm())
                    {
                        if (snipDlg.ShowDialog(parentForm) == DialogResult.OK && snipDlg.CapturedBitmap != null && slidesView.ActiveSlide != null)
                        {
                            try
                            {
                                string tempPath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "SlideScreenClip_" + DateTime.Now.Ticks + ".png");
                                snipDlg.CapturedBitmap.Save(tempPath, System.Drawing.Imaging.ImageFormat.Png);

                                Image loadedImg = (Image)snipDlg.CapturedBitmap.Clone();
                                float origW = Math.Max(1f, (float)loadedImg.Width);
                                float origH = Math.Max(1f, (float)loadedImg.Height);
                                float canvasW = (slidesView.Presentation != null) ? slidesView.Presentation.CanvasWidth : 1920f;
                                float canvasH = (slidesView.Presentation != null) ? slidesView.Presentation.CanvasHeight : 1080f;

                                float maxW = canvasW * 0.70f;
                                float maxH = canvasH * 0.70f;
                                float scaleFactor = Math.Min(maxW / origW, maxH / origH);
                                if (scaleFactor > 1.0f && origW > 120f && origH > 120f) scaleFactor = 1.0f;

                                float fitW = (float)Math.Round(origW * scaleFactor);
                                float fitH = (float)Math.Round(origH * scaleFactor);
                                float posX = (canvasW - fitW) / 2f;
                                float posY = (canvasH - fitH) / 2f;

                                ShapeNode imgShape = new ShapeNode
                                {
                                    Name = "Ảnh chụp " + (slidesView.ActiveSlide.Shapes.Count + 1),
                                    Type = ShapeType.Image,
                                    ImagePath = tempPath,
                                    CachedImage = loadedImg,
                                    Transform = new Transform2D(posX, posY, fitW, fitH),
                                    OriginalWidth = origW,
                                    OriginalHeight = origH,
                                    Text = "",
                                    FillColor = 0x00FFFFFF,
                                    StrokeWidth = 0f
                                };
                                slidesView.SaveUndoState();
                                slidesView.ActiveSlide.AddShape(imgShape);
                                slidesView.SelectedShapeIndex = slidesView.ActiveSlide.Shapes.Count - 1;
                                slidesView.SelectedShapeIndices.Clear();
                                slidesView.SelectedShapeIndices.Add(slidesView.SelectedShapeIndex);
                                if (slidesView.ActiveSlide != null) slidesView.ActiveSlide.IsThumbnailDirty = true;
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Không thể chèn ảnh chụp màn hình: " + ex.Message, "Lỗi Chụp Màn Hình", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (x >= 208 && x <= 284 && y >= 95 && y <= 124) // Album ảnh
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Multiselect = true;
                        ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg)|*.png;*.jpg;*.jpeg";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            foreach (var fn in ofd.FileNames)
                            {
                                slidesView.AddSlide();
                                Image loadedImg = Image.FromFile(fn);
                                float origW = Math.Max(1f, (float)loadedImg.Width);
                                float origH = Math.Max(1f, (float)loadedImg.Height);
                                float canvasW = (slidesView.Presentation != null) ? slidesView.Presentation.CanvasWidth : 1920f;
                                float canvasH = (slidesView.Presentation != null) ? slidesView.Presentation.CanvasHeight : 1080f;

                                float maxW = canvasW * 0.75f;
                                float maxH = canvasH * 0.75f;
                                float scaleFactor = Math.Min(maxW / origW, maxH / origH);
                                if (scaleFactor > 1.0f && origW > 120f && origH > 120f) scaleFactor = 1.0f;

                                float fitW = (float)Math.Round(origW * scaleFactor);
                                float fitH = (float)Math.Round(origH * scaleFactor);
                                float posX = (canvasW - fitW) / 2f;
                                float posY = (canvasH - fitH) / 2f;

                                ShapeNode imgShape = new ShapeNode
                                {
                                    Name = "Ảnh Album " + (slidesView.ActiveSlide.Shapes.Count + 1),
                                    Type = ShapeType.Image,
                                    ImagePath = fn,
                                    CachedImage = loadedImg,
                                    Transform = new Transform2D(posX, posY, fitW, fitH),
                                    OriginalWidth = origW,
                                    OriginalHeight = origH,
                                    Text = "",
                                    FillColor = 0x00FFFFFF,
                                    StrokeWidth = 0f
                                };
                                slidesView.ActiveSlide.AddShape(imgShape);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // ==================== Group 4: Minh họa (Illustrations) ====================
                else if (x >= 296 && x <= 352 && y >= 68 && y <= 124) // Hình khối ▾
                {
                    Point ptShape = parentForm != null ? parentForm.PointToScreen(new Point(296, 130)) : new Point(296, 130);
                    ShapeGalleryPopup popup = new ShapeGalleryPopup();
                    popup.Location = ptShape;
                    popup.OnShapeSelected = (sType) =>
                    {
                        if (sType.Equals("FreeformShape", StringComparison.OrdinalIgnoreCase))
                        {
                            slidesView.StartFreeformShapeMode();
                        }
                        else if (sType.Equals("FreeformScribble", StringComparison.OrdinalIgnoreCase))
                        {
                            slidesView.StartFreeformScribbleMode();
                        }
                        else
                        {
                            ShapeType st = ParseShapeTypeForSlides(sType);
                            slidesView.StartShapeDrawMode(st);
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    popup.Show();
                    return true;
                }
                else if (x >= 356 && x <= 412 && y >= 68 && y <= 124) // SmartArt
