            }
            else if (curTab == "Thiết kế" || (ActiveRibbonTab == 2 && string.IsNullOrEmpty(curTab))) // Thiết kế (Design)
            {
                int width = (parentForm != null) ? parentForm.ClientSize.Width : 1200;
                if (slidesView.Presentation != null)
                {
                    int startX = 12;
                    int cardW = 86;
                    int cardH = 62;
                    int btnStackW = 20;

                    int availW = width - 260 - startX;
                    int maxVisibleCards = Math.Max(2, (availW - btnStackW - 12) / (cardW + 6));
                    int totalThemes = slidesView.Presentation.Themes.Count;
                    int offset = Math.Max(0, Math.Min(slidesView.ThemeGalleryScrollOffset, totalThemes - maxVisibleCards));
                    int renderCount = Math.Min(maxVisibleCards, totalThemes - offset);

                    // 1. Check clicking on Theme Cards
                    if (x >= startX && x < startX + renderCount * (cardW + 6) && y >= 68 && y <= 68 + cardH)
                    {
                        int cardIdx = (x - startX) / (cardW + 6);
                        if (cardIdx >= 0 && cardIdx < renderCount)
                        {
                            int targetIdx = offset + cardIdx;
                            if (targetIdx >= 0 && targetIdx < totalThemes)
                            {
                                slidesView.ApplyTheme(slidesView.Presentation.Themes[targetIdx].Name);
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                        }
                    }

                    // 2. Check 3-Button Stack (▲, ▼, ⮛ More)
                    int stackX = startX + renderCount * (cardW + 6) + 2;
                    if (x >= stackX && x <= stackX + btnStackW)
                    {
                        // ▲ Button (Scroll left / up)
                        if (y >= 68 && y <= 88)
                        {
                            slidesView.ThemeGalleryScrollOffset = Math.Max(0, slidesView.ThemeGalleryScrollOffset - 1);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        // ▼ Button (Scroll right / down)
                        else if (y >= 89 && y <= 109)
                        {
                            slidesView.ThemeGalleryScrollOffset = Math.Min(totalThemes - maxVisibleCards, slidesView.ThemeGalleryScrollOffset + 1);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        // ⮛ More Button (Open ThemeGalleryDropDownForm)
                        else if (y >= 110 && y <= 130)
                        {
                            Point screenPt = parentForm != null ? parentForm.PointToScreen(new Point(startX, 134)) : new Point(startX, 134);
                            ThemeGalleryDropDownForm dropDown = new ThemeGalleryDropDownForm(screenPt, slidesView.Presentation);
                            dropDown.OnThemeSelected += (selectedThemeName) =>
                            {
                                slidesView.ApplyTheme(selectedThemeName);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            dropDown.Show();
                            return true;
                        }
                    }

                    int customX = stackX + btnStackW + 10 + 12;
                    // 16:9 button
                    if (x >= customX && x <= customX + 92 && y >= 68 && y <= 87)
                    {
                        slidesView.SetSlideSize(true);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 4:3 button
                    else if (x >= customX && x <= customX + 92 && y >= 88 && y <= 107)
                    {
                        slidesView.SetSlideSize(false);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Custom size button
                    else if (x >= customX && x <= customX + 92 && y >= 108 && y <= 128)
                    {
                        using (var dlg = new SlideDimensionsDialog(slidesView.Presentation.CanvasWidth, slidesView.Presentation.CanvasHeight))
                        {
                            if (dlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                slidesView.SetCustomSlideSize(dlg.TargetCanvasWidth, dlg.TargetCanvasHeight);
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                        return true;
                    }

                    int fmtBgX = customX + 94 + 10;
                    // Format Background button ("Định dạng Nền")
                    if (x >= fmtBgX && x <= fmtBgX + 84 && y >= 68 && y <= 124)
                    {
                        slidesView.ToggleFormatBackgroundPane();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }

                    int designerX = fmtBgX + 84 + 10;
                    // PowerPoint 365 Designer button ("Ý tưởng Thiết kế")
                    if (x >= designerX && x <= designerX + 88 && y >= 68 && y <= 124)
