                        slidesView.ToggleDesignerPane();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
            }
            else if (curTab == "Chuyển tiếp" || (ActiveRibbonTab == 3 && string.IsNullOrEmpty(curTab))) // Chuyển tiếp (Transitions)
            {
                // ⭐ Xem trước Preview
                if (x >= 12 && x <= 72 && y >= 68 && y <= 130)
                {
                    slidesView.PlayTransitionPreview();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Transition Quick Tiles (X: 88 to 606)
                else if (x >= 88 && x <= 606)
                {
                    int transIdx = (x - 88) / 74;
                    TransitionType[] transTypes = new TransitionType[] {
                        TransitionType.None, TransitionType.Morph, TransitionType.Fade, TransitionType.Push,
                        TransitionType.Wipe, TransitionType.Split, TransitionType.Reveal
                    };
                    if (transIdx >= 0 && transIdx < transTypes.Length)
                    {
                        slidesView.SetTransition(transTypes[transIdx]);
                        slidesView.PlayTransitionPreview();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                // Transitions 3-Button Stack (X: 606..628, Y: 68..126)
                else if (x >= 606 && x <= 628 && y >= 68 && y <= 126)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(88, 128)) : new Point(88, 128);
                    TransitionType curr = (slidesView.ActiveSlide != null) ? slidesView.ActiveSlide.Transition : TransitionType.None;
                    TransitionsGalleryDropDownForm drop = new TransitionsGalleryDropDownForm(pt, curr);
                    drop.OnTransitionSelected += (tt) =>
                    {
                        slidesView.SetTransition(tt);
                        slidesView.PlayTransitionPreview();
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    drop.Show();
                    return true;
                }
                // Tùy chọn hiệu ứng đa chiều (Effect Options ▾) (X: 636..722, Y: 68..126)
                else if (x >= 636 && x <= 722 && y >= 68 && y <= 126)
                {
                    if (slidesView.ActiveSlide != null)
                    {
                        TransitionType currTrans = slidesView.ActiveSlide.Transition;
                        bool hasOpts = (currTrans == TransitionType.Push || currTrans == TransitionType.Wipe ||
                                         currTrans == TransitionType.Split || currTrans == TransitionType.Reveal ||
                                         currTrans == TransitionType.Cover || currTrans == TransitionType.Uncover ||
                                         currTrans == TransitionType.Pan || currTrans == TransitionType.Blinds ||
                                         currTrans == TransitionType.Comb || currTrans == TransitionType.FlyThrough ||
                                         currTrans == TransitionType.Cube || currTrans == TransitionType.Box ||
                                         currTrans == TransitionType.Zoom || currTrans == TransitionType.GenOffice_SmoothFlow ||
                                         currTrans == TransitionType.Morph);
                        if (hasOpts)
                        {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(636, 128)) : new Point(636, 128);
                            TransitionDirection currDir = slidesView.ActiveSlide.TransitionDirection;
                            MorphType currMorph = slidesView.ActiveSlide.MorphMode;
                            TransitionEffectOptionsDropDownForm drop = new TransitionEffectOptionsDropDownForm(pt, currTrans, currDir, currMorph);
                            drop.OnDirectionSelected += (dir) =>
                            {
                                slidesView.SetTransitionDirection(dir);
                                slidesView.PlayTransitionPreview();
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            drop.OnMorphModeSelected += (mm) =>
                            {
                                slidesView.SetMorphMode(mm);
                                slidesView.PlayTransitionPreview();
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            drop.Show();
                            return true;
                        }
                    }
                }
                // Tùy chỉnh Thời lượng (Duration) (X: 734..864, Y: 68..92)
                else if (x >= 734 && x <= 864 && y >= 68 && y <= 92)
                {
                    if (slidesView.ActiveSlide != null)
                    {
                        if (x >= 840)
                        {
                            if (y <= 80)
                            {
                                slidesView.SetTransitionDuration((float)Math.Round(slidesView.ActiveSlide.TransitionDuration + 0.25f, 2));
                            }
                            else
                            {
                                slidesView.SetTransitionDuration((float)Math.Round(Math.Max(0.1f, slidesView.ActiveSlide.TransitionDuration - 0.25f), 2));
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        else
                        {
                            ContextMenuStrip durMenu = new ContextMenuStrip();
                            durMenu.RenderMode = ToolStripRenderMode.System;
                            float[] presets = new float[] { 0.25f, 0.50f, 0.75f, 1.00f, 1.25f, 1.50f, 2.00f, 2.20f, 2.50f, 3.00f, 5.00f };
                            foreach (float pVal in presets)
                            {
                                float captureVal = pVal;
                                ToolStripMenuItem mi = new ToolStripMenuItem(captureVal.ToString("0.00") + " giây", null, (s, e) =>
                                {
                                    slidesView.SetTransitionDuration(captureVal);
                                    if (parentForm != null) parentForm.Invalidate();
                                });
                                if (Math.Abs(slidesView.ActiveSlide.TransitionDuration - captureVal) < 0.05f) mi.Checked = true;
                                durMenu.Items.Add(mi);
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(734, 94)) : new Point(734, 94);
                            durMenu.Show(pt);
                            return true;
                        }
                    }
                }
                // Áp dụng cho tất cả Slide (Apply to All) (X: 734..864, Y: 98..126)
                else if (x >= 734 && x <= 864 && y >= 98 && y <= 126)
                {
                    slidesView.ApplyTransitionToAll();
                    MessageBox.Show("Đã áp dụng hiệu ứng chuyển cảnh, thời lượng và hướng cho toàn bộ trang chiếu!", "ZenQ Slides", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    if (parentForm != null) parentForm.Invalidate();
                }
            }
            else if (curTab == "Hoạt họa" || (ActiveRibbonTab == 4 && string.IsNullOrEmpty(curTab))) // Hoạt họa (Animations)
            {
                bool hasSelectedShape = (slidesView != null && (slidesView.SelectedShape != null || (slidesView.SelectedShapeIndices != null && slidesView.SelectedShapeIndices.Count > 0)));
                bool hasAnimations = (slidesView != null && slidesView.ActiveSlide != null && slidesView.ActiveSlide.Animations.Count > 0);

                // 1. Preview button (X: 12..74, Y: 68..130)
                if (x >= 12 && x <= 74 && y >= 68 && y <= 130)
                {
                    if (hasAnimations)
                    {
                        slidesView.PlayAnimationPreview();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }

                // 2. Quick Gallery Tiles (7 tiles: X: 88, Step: 74, Y: 68..126)
                AnimationType[] quickAnims = new AnimationType[] {
                    AnimationType.Appear,
                    AnimationType.FadeIn,
                    AnimationType.FlyIn,
                    AnimationType.FloatIn,
                    AnimationType.ZoomIn,
                    AnimationType.Bounce,
                    AnimationType.Pulse
                };

                int ax = 88;
                for (int i = 0; i < quickAnims.Length; i++)
                {
                    if (x >= ax && x <= ax + 70 && y >= 68 && y <= 126)
                    {
                        if (hasSelectedShape)
                        {
                            slidesView.AddShapeAnimation(quickAnims[i]);
                            slidesView.PlayAnimationPreview();
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    ax += 74;
                }

                // 3. 3-Button Stack (X: ax, Y: 68..126)
                if (x >= ax && x <= ax + 18 && y >= 68 && y <= 126)
                {
                    if (hasSelectedShape)
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(88, 130)) : new Point(88, 130);
                        AnimationType curAnim = AnimationType.None;
                        if (slidesView.ActiveSlide != null && slidesView.SelectedShape != null)
                        {
                            foreach (var a in slidesView.ActiveSlide.Animations)
                            {
                                if (a.ShapeId == slidesView.SelectedShape.Id) { curAnim = a.Type; break; }
                            }
                        }
                        AnimationsGalleryDropDownForm drop = new AnimationsGalleryDropDownForm(pt, curAnim);
                        drop.OnAnimationSelected += (aType) =>
                        {
                            if (aType == AnimationType.None)
                            {
                                if (slidesView.ActiveSlide != null && slidesView.SelectedShape != null)
                                {
                                    slidesView.ActiveSlide.Animations.RemoveAll(a => a.ShapeId == slidesView.SelectedShape.Id);
                                }
                            }
                            else if (aType == AnimationType.MotionCustom)
                            {
                                slidesView.StartFreehandMotionPathDrawing(slidesView.SelectedShape);
                            }
                            else
                            {
                                slidesView.AddShapeAnimation(aType);
                                slidesView.PlayAnimationPreview();
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        drop.OnOpenMoreEffects += (catKey) =>
                        {
                            MoreAnimationsModalForm modal = new MoreAnimationsModalForm(slidesView, catKey);
                            modal.OnAnimationSelected += (aType) =>
                            {
                                if (aType == AnimationType.MotionCustom)
                                {
                                    slidesView.StartFreehandMotionPathDrawing(slidesView.SelectedShape);
                                }
                                else if (aType != AnimationType.None)
                                {
                                    slidesView.AddShapeAnimation(aType);
                                    slidesView.PlayAnimationPreview();
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            modal.ShowDialog(parentForm);
                        };
                        drop.Show();
                    }
                    return true;
                }
                ax += 24;

                // 3b. Tùy chọn hiệu ứng ▾ (Effect Options ▾) (X: ax..ax + 92, Y: 68..130)
                if (x >= ax && x <= ax + 92 && y >= 68 && y <= 130)
                {
                    if (hasSelectedShape && slidesView.SelectedAnimation != null && ShapeAnimation.HasEffectOptions(slidesView.SelectedAnimation.Type))
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(ax, 130)) : new Point(ax, 130);
                        ShapeAnimation currentSa = slidesView.SelectedAnimation;
                        AnimationEffectOptionsDropDownForm drop = new AnimationEffectOptionsDropDownForm(pt, currentSa, slidesView.SelectedShape);
                        drop.OnDirectionSelected += (dir) =>
                        {
                            slidesView.SetSelectedAnimationDirection(dir);
                            slidesView.PlayAnimationPreview();
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        drop.OnAnimationUpdated += (anim) =>
                        {
                            slidesView.PlayAnimationPreview();
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        drop.OnOpenAdvancedNeonDialog += () =>
                        {
                            NeonEffectOptionsDialogForm modal = new NeonEffectOptionsDialogForm(currentSa, slidesView.SelectedShape, () =>
                            {
                                slidesView.PlayAnimationPreview();
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            modal.ShowDialog(parentForm);
                        };
                        drop.Show();
                    }
                    return true;
                }
                ax += 98 + 14;

