                        colMenu.Items.Add("Tông Xanh Dương (Blue)", null, (s, e) => { shape.VideoColorFilter = "Blue"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add("Tông Cam Nắng (Orange)", null, (s, e) => { shape.VideoColorFilter = "Orange"; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(74, 120)) : new Point(74, 120);
