                            shape.ImageContrast = 1.0f;
                            shape.ImageSaturation = 1.0f;
                            shape.ImageRecolor = "None";
                            shape.FillOpacity = 1.0f;
                            shape.PictureStyleIndex = 0;
                            shape.CropLeft = 0f; shape.CropTop = 0f; shape.CropRight = 0f; shape.CropBottom = 0f;
