                        alignMenu.Items.Add("Căn Giữa dọc", null, (s, e) => { shape.Transform.Y = (slidesView.Presentation.CanvasHeight - shape.Transform.Height) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Dưới", null, (s, e) => { shape.Transform.Y = slidesView.Presentation.CanvasHeight - shape.Transform.Height; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(853, 144)) : new Point(853, 144);
                        alignMenu.Show(pt);
