                        return true;
                    }
                    // Lật ngang (X: 945..1029, Y: 94..118)
                    else if (x >= 945 && x <= 1029 && y >= 94 && y <= 118)
                    {
                        shape.Transform.FlipHorizontal = !shape.Transform.FlipHorizontal;
