                    }
                    // Lật dọc (X: 945..1029, Y: 120..144)
                    else if (x >= 945 && x <= 1029 && y >= 120 && y <= 144)
                    {
                        shape.Transform.FlipVertical = !shape.Transform.FlipVertical;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 15. Cắt ảnh (Crop Split Button) (X: 1041..1103, Y: 68..122)
                    else if (x >= 1041 && x <= 1103 && y >= 68 && y <= 122)
                    {
                        if (y <= 104)
                        {
                            // Nhấp nút Cắt ảnh ở trên (không nhấp mũi tên): Bật/Tắt chế độ Cắt ảnh tương tác
                            slidesView.ToggleCropMode();
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        else
                        {
                            // Nhấp vào mũi tên ▾ ở dưới: Mở Menu Cắt ảnh đầy đủ chức năng Crop to Shape & Aspect Ratio
                            ContextMenuStrip cropMenu = new ContextMenuStrip();
