                            // 1. Cắt theo Hình dạng (Crop to Shape)
                            ToolStripMenuItem cropToShapeItem = new ToolStripMenuItem("🔷 Cắt theo Hình dạng (Crop to Shape)");

                            ToolStripMenuItem rectsGroup = new ToolStripMenuItem("Hình chữ nhật (Rectangles)");
