                            arrowGroup.DropDownItems.Add("Mũi tên Chữ V (Chevron)", null, (s, e) => { slidesView.SetCropShape("Chevron"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(arrowGroup);

                            ToolStripMenuItem starGroup = new ToolStripMenuItem("Sao & Biểu ngữ (Stars & Banners)");
                            starGroup.DropDownItems.Add("Ngôi sao (Star)", null, (s, e) => { slidesView.SetCropShape("Star"); if (parentForm != null) parentForm.Invalidate(); });
                            starGroup.DropDownItems.Add("Dải ruy băng (Banner)", null, (s, e) => { slidesView.SetCropShape("Banner"); if (parentForm != null) parentForm.Invalidate(); });
                            starGroup.DropDownItems.Add("Sao bừng sáng (Starburst)", null, (s, e) => { slidesView.SetCropShape("Starburst"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(starGroup);

                            ToolStripMenuItem natureGroup = new ToolStripMenuItem("Hình độc quyền & Tự nhiên (Special Shapes)");
                            natureGroup.DropDownItems.Add("Bong bóng thoại (Callout)", null, (s, e) => { slidesView.SetCropShape("Callout"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Chiếc lá (Leaf)", null, (s, e) => { slidesView.SetCropShape("Leaf"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Cỏ 4 lá (Clover)", null, (s, e) => { slidesView.SetCropShape("Clover"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Bông hoa (Flower)", null, (s, e) => { slidesView.SetCropShape("Flower"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Viên ngọc (Gem)", null, (s, e) => { slidesView.SetCropShape("Gem"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Khiên bảo vệ (Shield)", null, (s, e) => { slidesView.SetCropShape("Shield"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Vòm cung (Arch)", null, (s, e) => { slidesView.SetCropShape("Arch"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(natureGroup);

                            cropMenu.Items.Add(cropToShapeItem);

                            // 2. Tỉ lệ Khung hình (Aspect Ratio)
                            ToolStripMenuItem ratioItem = new ToolStripMenuItem("📐 Tỉ lệ Khung hình (Aspect Ratio)");

                            ToolStripMenuItem sqGroup = new ToolStripMenuItem("Vuông (Square)");
                            sqGroup.DropDownItems.Add("1:1", null, (s, e) => { slidesView.SetCropAspectRatio(1f, 1f); if (parentForm != null) parentForm.Invalidate(); });
                            ratioItem.DropDownItems.Add(sqGroup);

                            ToolStripMenuItem portraitGroup = new ToolStripMenuItem("Dọc (Portrait)");
                            portraitGroup.DropDownItems.Add("2:3", null, (s, e) => { slidesView.SetCropAspectRatio(2f, 3f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("3:4", null, (s, e) => { slidesView.SetCropAspectRatio(3f, 4f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("3:5", null, (s, e) => { slidesView.SetCropAspectRatio(3f, 5f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("4:5", null, (s, e) => { slidesView.SetCropAspectRatio(4f, 5f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("9:16", null, (s, e) => { slidesView.SetCropAspectRatio(9f, 16f); if (parentForm != null) parentForm.Invalidate(); });
                            ratioItem.DropDownItems.Add(portraitGroup);

                            ToolStripMenuItem landscapeGroup = new ToolStripMenuItem("Ngang (Landscape)");
                            landscapeGroup.DropDownItems.Add("16:9 (Chuẩn Màn ảnh rộng)", null, (s, e) => { slidesView.SetCropAspectRatio(16f, 9f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("16:10", null, (s, e) => { slidesView.SetCropAspectRatio(16f, 10f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("4:3 (Truyền thống)", null, (s, e) => { slidesView.SetCropAspectRatio(4f, 3f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("3:2", null, (s, e) => { slidesView.SetCropAspectRatio(3f, 2f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("5:4", null, (s, e) => { slidesView.SetCropAspectRatio(5f, 4f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("5:3", null, (s, e) => { slidesView.SetCropAspectRatio(5f, 3f); if (parentForm != null) parentForm.Invalidate(); });
                            ratioItem.DropDownItems.Add(landscapeGroup);

                            cropMenu.Items.Add(ratioItem);

                            // 3. Lấp đầy & Vừa vặn (Fill & Fit)
                            cropMenu.Items.Add("🖼️ Lấp đầy (Fill)", null, (s, e) => {
                                slidesView.FillCrop();
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            cropMenu.Items.Add("🎯 Vừa vặn (Fit)", null, (s, e) => {
                                slidesView.FitCrop();
                                if (parentForm != null) parentForm.Invalidate();
                            });

                            cropMenu.Items.Add(new ToolStripSeparator());
                            cropMenu.Items.Add("↩️ Bỏ cắt ảnh (Reset Crop)", null, (s, e) => {
                                slidesView.ResetCrop();
                                if (parentForm != null) parentForm.Invalidate();
