                    {
                        slidesView.SaveUndoState();
                        if (slidesView.SelectedShapeIndices != null && slidesView.SelectedShapeIndices.Count > 1 && slidesView.ActiveSlide != null)
                        {
                            float minX = float.MaxValue;
                            foreach (int idx in slidesView.SelectedShapeIndices)
                                if (idx >= 0 && idx < slidesView.ActiveSlide.Shapes.Count)
                                    minX = Math.Min(minX, slidesView.ActiveSlide.Shapes[idx].Transform.X);
                            foreach (int idx in slidesView.SelectedShapeIndices)
                                if (idx >= 0 && idx < slidesView.ActiveSlide.Shapes.Count)
                                    slidesView.ActiveSlide.Shapes[idx].Transform.X = minX;
