                        {
                            float minX = float.MaxValue, maxX = float.MinValue;
                            foreach (int idx in slidesView.SelectedShapeIndices)
                            {
                                if (idx >= 0 && idx < slidesView.ActiveSlide.Shapes.Count)
                                {
                                    var sh = slidesView.ActiveSlide.Shapes[idx];
                                    minX = Math.Min(minX, sh.Transform.X);
                                    maxX = Math.Max(maxX, sh.Transform.X + sh.Transform.Width);
                                }
                            }
                            float center = (minX + maxX) / 2f;
                            foreach (int idx in slidesView.SelectedShapeIndices)
                                if (idx >= 0 && idx < slidesView.ActiveSlide.Shapes.Count)
                                {
                                    var sh = slidesView.ActiveSlide.Shapes[idx];
                                    sh.Transform.X = center - sh.Transform.Width / 2f;
