                shape.AudioFadeInDuration = (float)Math.Max(0.0, Math.Round(shape.AudioFadeInDuration + (isUp ? 0.25 : -0.25), 2));
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // Mờ dần ra ▲ / ▼ (X: 270..404, Y: 96..121)
            else if (x >= 270 && x <= 404 && y >= 96 && y <= 121)
