                bool isUp = (y <= 108);
                slidesView.SaveUndoState();
                shape.AudioFadeOutDuration = (float)Math.Max(0.0, Math.Round(shape.AudioFadeOutDuration + (isUp ? 0.25 : -0.25), 2));
                if (parentForm != null) parentForm.Invalidate();
