            {
                slidesView.SaveUndoState();
                shape.AudioHideDuringShow = !shape.AudioHideDuringShow;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // Checkbox 3: Lặp lại cho đến dừng (X: 418..552, Y: 118..136)
            else if (x >= 418 && x <= 552 && y >= 118 && y <= 136)
            {
                slidesView.SaveUndoState();
                shape.AudioLoopUntilStopped = !shape.AudioLoopUntilStopped;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // Checkbox 4: Tua lại sau khi phát (X: 558..696, Y: 118..136)
            else if (x >= 558 && x <= 696 && y >= 118 && y <= 136)
            {
                slidesView.SaveUndoState();
                shape.AudioRewindAfterPlaying = !shape.AudioRewindAfterPlaying;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // 5. Nhóm Phát trong Nền: Phát trong Nền (X: 706..798, Y: 68..122)
            else if (x >= 706 && x <= 798 && y >= 68 && y <= 122)
            {
                slidesView.SaveUndoState();
                SlideAudioPlayerManager.Instance.SetPlayInBackground(shape, true, parentForm);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
            // Không phát nền (X: 802..894, Y: 68..122)
            else if (x >= 802 && x <= 894 && y >= 68 && y <= 122)
            {
                slidesView.SaveUndoState();
                SlideAudioPlayerManager.Instance.SetPlayInBackground(shape, false, parentForm);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
        }
        else if ((curTab == "Phát lại" || (ActiveRibbonTab >= 8 && curTab != "Định dạng Hình dạng" && curTab != "Định dạng Hình ảnh" && curTab != "Thiết kế Bảng")) && slidesView != null && slidesView.SelectedShape != null && (slidesView.SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(slidesView.SelectedShape.VideoPath)))
        {
            ShapeNode shape = slidesView.SelectedShape;
            // Nhóm Xem trước (Preview): Phát (X: 12..60, Y: 68..122)
            if (x >= 12 && x <= 60 && y >= 68 && y <= 122)
                {
                    slidesView.PlayVideoPreview(shape, parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Dấu trang (Bookmarks): Thêm Dấu trang (X: 74..186, Y: 68..92)
                else if (x >= 74 && x <= 186 && y >= 68 && y <= 92)
                {
                    slidesView.AddVideoBookmark(shape);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Dấu trang: Xóa Dấu trang (X: 74..186, Y: 96..120)
                else if (x >= 74 && x <= 186 && y >= 96 && y <= 120)
                {
                    slidesView.RemoveVideoBookmark(shape);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Chỉnh sửa (Editing): Cắt Video (X: 200..260, Y: 68..122)
                else if (x >= 200 && x <= 260 && y >= 68 && y <= 122)
                {
                    slidesView.ShowTrimVideoDialog(shape);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Chỉnh sửa: Mờ dần vào ▲ / ▼ (X: 266..400, Y: 68..93)
                else if (x >= 266 && x <= 400 && y >= 68 && y <= 93)
                {
                    bool isUp = (y <= 80);
                    slidesView.SaveUndoState();
                    shape.VideoFadeInDuration = (float)Math.Max(0.0, Math.Round(shape.VideoFadeInDuration + (isUp ? 0.25 : -0.25), 2));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Chỉnh sửa: Mờ dần ra ▲ / ▼ (X: 266..400, Y: 96..121)
                else if (x >= 266 && x <= 400 && y >= 96 && y <= 121)
                {
                    bool isUp = (y <= 108);
                    slidesView.SaveUndoState();
                    shape.VideoFadeOutDuration = (float)Math.Max(0.0, Math.Round(shape.VideoFadeOutDuration + (isUp ? 0.25 : -0.25), 2));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Tùy chọn Video: Âm lượng ▾ (X: 414..500, Y: 68..92)
                else if (x >= 414 && x <= 500 && y >= 68 && y <= 92)
                {
                    ContextMenuStrip menu = new ContextMenuStrip();
                    ToolStripMenuItem miMute = new ToolStripMenuItem("Tắt tiếng (Mute)");
                    ToolStripMenuItem miLow = new ToolStripMenuItem("Nhỏ (Low - 25%)");
                    ToolStripMenuItem miMed = new ToolStripMenuItem("Trung bình (Medium - 50%)");
                    ToolStripMenuItem miHigh = new ToolStripMenuItem("Lớn (High - 100%)");

                    miMute.Checked = (shape.VideoVolume == VideoVolumeLevel.Mute);
                    miLow.Checked = (shape.VideoVolume == VideoVolumeLevel.Low);
                    miMed.Checked = (shape.VideoVolume == VideoVolumeLevel.Medium);
                    miHigh.Checked = (shape.VideoVolume == VideoVolumeLevel.High);

                    miMute.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.Mute; if (parentForm != null) parentForm.Invalidate(); };
                    miLow.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.Low; if (parentForm != null) parentForm.Invalidate(); };
                    miMed.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.Medium; if (parentForm != null) parentForm.Invalidate(); };
                    miHigh.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.High; if (parentForm != null) parentForm.Invalidate(); };

                    menu.Items.AddRange(new ToolStripItem[] { miMute, miLow, miMed, miHigh });
                    if (parentForm != null) menu.Show(parentForm, new Point(x, y + 10));
                    return true;
                }
                // Nhóm Tùy chọn Video: Bắt đầu: [ ... ▾ ] (X: 506..692, Y: 68..92)
                else if (x >= 506 && x <= 692 && y >= 68 && y <= 92)
                {
                    ContextMenuStrip menu = new ContextMenuStrip();
                    ToolStripMenuItem miClickSeq = new ToolStripMenuItem("Theo trình tự nhấp (In Click Sequence)");
                    ToolStripMenuItem miAuto = new ToolStripMenuItem("Tự động");
                    ToolStripMenuItem miWhenClicked = new ToolStripMenuItem("Khi nhấp vào (When Clicked On)");

                    miClickSeq.Checked = (shape.VideoStartMode == VideoStartMode.InClickSequence);
                    miAuto.Checked = (shape.VideoStartMode == VideoStartMode.Automatically);
                    miWhenClicked.Checked = (shape.VideoStartMode == VideoStartMode.WhenClickedOn);

                    miClickSeq.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoStartMode = VideoStartMode.InClickSequence; if (parentForm != null) parentForm.Invalidate(); };
                    miAuto.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoStartMode = VideoStartMode.Automatically; if (parentForm != null) parentForm.Invalidate(); };
                    miWhenClicked.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoStartMode = VideoStartMode.WhenClickedOn; if (parentForm != null) parentForm.Invalidate(); };

                    menu.Items.AddRange(new ToolStripItem[] { miClickSeq, miAuto, miWhenClicked });
                    if (parentForm != null) menu.Show(parentForm, new Point(x, y + 10));
                    return true;
                }
                // Checkbox: Phát toàn màn hình (X: 414..548, Y: 97..115)
                else if (x >= 414 && x <= 548 && y >= 97 && y <= 115)
                {
                    slidesView.SaveUndoState();
                    shape.VideoPlayFullScreen = !shape.VideoPlayFullScreen;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Checkbox: Ẩn khi không phát (X: 554..692, Y: 97..115)
                else if (x >= 554 && x <= 692 && y >= 97 && y <= 115)
                {
                    slidesView.SaveUndoState();
                    shape.VideoHideWhileNotPlaying = !shape.VideoHideWhileNotPlaying;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Checkbox: Lặp lại cho đến khi dừng (X: 414..548, Y: 118..136)
                else if (x >= 414 && x <= 548 && y >= 118 && y <= 136)
                {
                    slidesView.SaveUndoState();
                    shape.VideoLoopUntilStopped = !shape.VideoLoopUntilStopped;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Checkbox: Tua lại sau khi phát (X: 554..692, Y: 118..136)
                else if (x >= 554 && x <= 692 && y >= 118 && y <= 136)
                {
                    slidesView.SaveUndoState();
                    shape.VideoRewindAfterPlaying = !shape.VideoRewindAfterPlaying;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Tùy chọn Phụ đề (Caption Options): Chèn Phụ đề ▾ (X: 706..796, Y: 68..122)
                else if (x >= 706 && x <= 796 && y >= 68 && y <= 122)
                {
                    ContextMenuStrip menu = new ContextMenuStrip();
                    ToolStripMenuItem miAddCap = new ToolStripMenuItem("Chèn Phụ đề WebVTT (*.vtt, *.srt)...");
                    ToolStripMenuItem miRemCap = new ToolStripMenuItem("Xóa Phụ đề Đã chèn");

                    miAddCap.Click += (s, ev) =>
                    {
                        using (OpenFileDialog ofd = new OpenFileDialog())
                        {
                            ofd.Title = "Chọn tệp Phụ đề cho Video";
                            ofd.Filter = "Tệp Phụ đề (*.vtt;*.srt)|*.vtt;*.srt|Tất cả tệp (*.*)|*.*";
                            if (ofd.ShowDialog() == DialogResult.OK)
                            {
                                slidesView.SaveUndoState();
                                shape.VideoCaptionPath = ofd.FileName;
                                if (parentForm != null) parentForm.Invalidate();
                                MessageBox.Show("Đã chèn phụ đề:\n" + ofd.FileName, "Chèn Phụ đề Video", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            }
                        }
                    };

                    miRemCap.Click += (s, ev) =>
                    {
                        slidesView.SaveUndoState();
                        shape.VideoCaptionPath = null;
                        if (parentForm != null) parentForm.Invalidate();
                        MessageBox.Show("Đã xóa phụ đề khỏi video.", "Phụ đề Video", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    };

                    menu.Items.AddRange(new ToolStripItem[] { miAddCap, miRemCap });
                    if (parentForm != null) menu.Show(parentForm, new Point(x, y + 10));
                    return true;
                }
            }
            return false;
        }

        #region PDF Editor Ribbon Toolbar & Click Handling
    private void DrawPdfRibbonToolbar(Graphics g, int width, PdfView pdfView)
    {
        if (pdfView == null) return;
        switch (ActiveRibbonTab)
        {
            case 0: DrawPdfTabTrangDau(g, width, pdfView); break;
            case 1: DrawPdfTabChuThich(g, width, pdfView); break;
            case 2: DrawPdfTabChinhSua(g, width, pdfView); break;
            case 3: DrawPdfTabTrang(g, width, pdfView); break;
            case 4: DrawPdfTabKyBaoMat(g, width, pdfView); break;
            case 5: DrawPdfTabHienThi(g, width, pdfView); break;
            case 6: DrawPdfTabDinhDangHopChu(g, width, pdfView); break;
            default: DrawPdfTabTrangDau(g, width, pdfView); break;
        }
    }

    private void DrawPdfTabTrangDau(Graphics g, int width, PdfView pdfView)
    {
        int curX = 14;
        using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
        using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
        using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
        {
            // 1. Nhóm Tệp (File)
            DrawVectorToolBtnLarge(g, curX, 68, 36, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.8f))
                {
                    g1.DrawRectangle(p, x1 - 1, y1 + 5, 16, 12);
                    g1.DrawLine(p, x1 - 1, y1 + 5, x1 + 4, y1 + 2);
                    g1.DrawLine(p, x1 + 4, y1 + 2, x1 + 9, y1 + 2);
                }
            }, "Mở");
            curX += 38;

            DrawVectorToolBtnLarge(g, curX, 68, 36, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.8f))
                {
                    g1.DrawRectangle(p, x1 - 1, y1 + 2, 16, 16);
                    g1.DrawRectangle(p, x1 + 2, y1 + 2, 10, 6);
                }
            }, "Lưu");
            curX += 38;

            g.DrawString("Tệp", labelFont, Brushes.Gray, curX - 52, 137);
            g.DrawLine(Pens.LightGray, curX + 4, 68, curX + 4, 148);
            curX += 14;

            // 2. Nhóm Công cụ Chọn & Soạn thảo (Tools)
            bool isSelect = (pdfView.SelectedTool == 0);
            DrawVectorToolBtnLarge(g, curX, 68, 54, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isSelect ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.8f))
                {
                    g1.DrawLine(p, x1 + 4, y1 + 3, x1 + 4, y1 + 17);
                    g1.DrawLine(p, x1 + 4, y1 + 3, x1 + 14, y1 + 12);
                    g1.DrawLine(p, x1 + 14, y1 + 12, x1 + 9, y1 + 12);
                    g1.DrawLine(p, x1 + 9, y1 + 12, x1 + 13, y1 + 18);
                }
            }, "Con trỏ", isSelect);
            curX += 58;

            bool isAddText = (pdfView.SelectedTool == 1);
            DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                using (Font tf = new Font("Segoe UI", 12f, FontStyle.Bold))
                using (SolidBrush tb = new SolidBrush(isAddText ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105)))
                {
                    g1.DrawString("T", tf, tb, x1 + 3, y1 + 1);
                    g1.DrawString("+", new Font("Segoe UI", 8.5f, FontStyle.Bold), Brushes.Green, x1 + 13, y1);
                }
            }, "Thêm chữ", isAddText);
            curX += 66;

            bool isEdit = (pdfView.SelectedTool == 2);
            DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isEdit ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.6f))
                {
                    g1.DrawLine(p, x1 + 3, y1 + 16, x1 + 16, y1 + 3);
                    g1.DrawLine(p, x1 + 13, y1 + 3, x1 + 16, y1 + 6);
                }
            }, "Sửa chữ", isEdit);
            curX += 62;

            g.DrawString("Công cụ", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 3. Nhóm Phông chữ & Định dạng (Font Family & Size Picker like Writer)
            PdfTextElement selTxt = pdfView.SelectedText ?? pdfView.EditingText;
            string curF = (selTxt != null && !string.IsNullOrEmpty(selTxt.FontName)) ? selTxt.FontName : (pdfView.ActiveFontName ?? "Segoe UI");
            float curSz = (selTxt != null) ? selTxt.FontSize : (pdfView.ActiveFontSize > 0 ? pdfView.ActiveFontSize : 12f);
            bool isB = (selTxt != null && selTxt.IsBold);
            bool isI = (selTxt != null && selTxt.IsItalic);
            bool isU = (selTxt != null && selTxt.IsUnderline);

            // Font Combo (X: curX, W: 110, H: 22)
            Rectangle fontBox = new Rectangle(curX, 70, 110, 22);
            DrawInteractiveButton(g, fontBox, false, 3);
            g.DrawString(curF, btnFont, Brushes.Black, fontBox.X + 4, fontBox.Y + 3);
            g.DrawString("▾", btnFont, Brushes.Gray, fontBox.Right - 14, fontBox.Y + 3);

            // Size Combo (X: curX + 114, W: 45, H: 22)
            Rectangle sizeBox = new Rectangle(curX + 114, 70, 45, 22);
            DrawInteractiveButton(g, sizeBox, false, 3);
            g.DrawString(curSz.ToString("0.#"), btnFont, Brushes.Black, sizeBox.X + 4, sizeBox.Y + 3);
            g.DrawString("▾", btnFont, Brushes.Gray, sizeBox.Right - 14, sizeBox.Y + 3);

            // A ▲ / A ▼ (X: curX + 162, W: 24 each)
            Rectangle aUpBox = new Rectangle(curX + 162, 70, 24, 22);
            DrawInteractiveButton(g, aUpBox, false, 3);
            g.DrawString("A▲", labelFont, Brushes.Black, aUpBox.X + 2, aUpBox.Y + 4);

            Rectangle aDownBox = new Rectangle(curX + 188, 70, 24, 22);
            DrawInteractiveButton(g, aDownBox, false, 3);
            g.DrawString("A▼", labelFont, Brushes.Black, aDownBox.X + 2, aDownBox.Y + 4);

            // Row 2: B, I, U, Color
            DrawVectorBtn(g, curX, 96, 26, 22, (g1, x1, y1) => {
                g1.DrawString("B", boldFont, isB ? Brushes.Blue : Brushes.Black, x1 + 6, y1 + 2);
            }, "", isB);
            DrawVectorBtn(g, curX + 29, 96, 26, 22, (g1, x1, y1) => {
                using (Font itF = new Font("Segoe UI", 8.5f, FontStyle.Italic))
                    g1.DrawString("I", itF, isI ? Brushes.Blue : Brushes.Black, x1 + 8, y1 + 2);
            }, "", isI);
            DrawVectorBtn(g, curX + 58, 96, 26, 22, (g1, x1, y1) => {
                using (Font unF = new Font("Segoe UI", 8.5f, FontStyle.Underline))
                    g1.DrawString("U", unF, isU ? Brushes.Blue : Brushes.Black, x1 + 7, y1 + 2);
            }, "", isU);

            Rectangle clrBox = new Rectangle(curX + 87, 96, 45, 22);
            DrawInteractiveButton(g, clrBox, false, 3);
            using (Font af = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (SolidBrush ab = new SolidBrush(selTxt != null ? selTxt.TextColor : Color.Black))
            {
                g.DrawString("A", af, ab, clrBox.X + 6, clrBox.Y + 2);
                using (Pen ap = new Pen(ab.Color, 2.5f)) g.DrawLine(ap, clrBox.X + 5, clrBox.Y + 16, clrBox.X + 17, clrBox.Y + 16);
                g.DrawString("▾", btnFont, Brushes.Gray, clrBox.Right - 14, clrBox.Y + 3);
            }

            curX += 216;
            g.DrawString("Phông chữ", labelFont, Brushes.Gray, curX - 140, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 4. Nhóm Thu phóng & Khớp trang (Zoom & Fit)
            Rectangle zInBtn = new Rectangle(curX, 68, 70, 24);
            DrawInteractiveButton(g, zInBtn, false, 3);
            g.DrawString("🔍+", boldFont, Brushes.Black, zInBtn.X + 4, zInBtn.Y + 3);
            g.DrawString("Phóng to", btnFont, Brushes.Black, zInBtn.X + 22, zInBtn.Y + 3);

            Rectangle zOutBtn = new Rectangle(curX, 94, 70, 24);
            DrawInteractiveButton(g, zOutBtn, false, 3);
            g.DrawString("🔍-", boldFont, Brushes.Black, zOutBtn.X + 4, zOutBtn.Y + 3);
            g.DrawString("Thu nhỏ", btnFont, Brushes.Black, zOutBtn.X + 22, zOutBtn.Y + 3);

            Rectangle zResetBtn = new Rectangle(curX, 120, 70, 24);
            DrawInteractiveButton(g, zResetBtn, false, 3);
            string zPct = (int)(pdfView.ZoomLevel * 100) + "%";
            g.DrawString(zPct, btnFont, Brushes.DarkBlue, zResetBtn.X + 4, zResetBtn.Y + 3);

            curX += 76;

            Rectangle fitWBtn = new Rectangle(curX, 68, 88, 24);
            DrawInteractiveButton(g, fitWBtn, false, 3);
            g.DrawString("↔ Vừa rộng", btnFont, Brushes.Black, fitWBtn.X + 4, fitWBtn.Y + 3);

            Rectangle fitPBtn = new Rectangle(curX, 94, 88, 24);
            DrawInteractiveButton(g, fitPBtn, false, 3);
            g.DrawString("↕ Vừa trang", btnFont, Brushes.Black, fitPBtn.X + 4, fitPBtn.Y + 3);

            curX += 94;
            g.DrawString("Thu phóng", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 5. Nhóm Tìm kiếm (Find)
            bool isSearchActive = pdfView.ShowSearchBar;
            DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isSearchActive ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.8f))
                {
                    g1.DrawEllipse(p, x1 + 2, y1 + 2, 11, 11);
                    g1.DrawLine(p, x1 + 10, y1 + 10, x1 + 17, y1 + 17);
                }
            }, "Tìm kiếm", isSearchActive);
            curX += 66;

            g.DrawString("Tìm kiếm", labelFont, Brushes.Gray, curX - 54, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 6. Nhóm AI OCR Văn Bản
            bool isOcrActive = pdfView.IsOcrScanning;
            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Font sf = new Font("Segoe UI", 11.5f, FontStyle.Bold))
                {
                    g1.DrawString("✨", sf, Brushes.MediumPurple, x1 + 4, y1 + 1);
                }
            }, "Quét AI OCR", isOcrActive);
            curX += 80;

            g.DrawString("AI OCR", labelFont, Brushes.Gray, curX - 58, 137);
        }
    }

    private void DrawPdfTabChuThich(Graphics g, int width, PdfView pdfView)
    {
        int curX = 14;
        using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
        using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
        using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
        {
            // 1. Nhóm Bút Dạ Quang Highlight (Tool 3)
            bool isHl = (pdfView.SelectedTool == 3);
            DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                using (SolidBrush hb = new SolidBrush(Color.FromArgb(250, 204, 21)))
                {
                    g1.FillRectangle(hb, x1 + 2, y1 + 4, 16, 12);
                }
                using (Pen hp = new Pen(Color.FromArgb(202, 138, 4), 1.5f))
                {
                    g1.DrawRectangle(hp, x1 + 2, y1 + 4, 16, 12);
                }
            }, "Dạ quang", isHl);
            curX += 72;

            // Màu Highlight (Vàng, Xanh lá, Xanh dương, Hồng)
            Rectangle yBtn = new Rectangle(curX, 72, 18, 18);
            Rectangle gBtn = new Rectangle(curX + 22, 72, 18, 18);
            Rectangle bBtn = new Rectangle(curX, 96, 18, 18);
            Rectangle pBtn = new Rectangle(curX + 22, 96, 18, 18);

            using (SolidBrush yb = new SolidBrush(Color.FromArgb(250, 204, 21))) g.FillRectangle(yb, yBtn);
            using (SolidBrush gb = new SolidBrush(Color.FromArgb(74, 222, 128))) g.FillRectangle(gb, gBtn);
            using (SolidBrush bb = new SolidBrush(Color.FromArgb(96, 165, 250))) g.FillRectangle(bb, bBtn);
            using (SolidBrush pb = new SolidBrush(Color.FromArgb(244, 114, 182))) g.FillRectangle(pb, pBtn);

            g.DrawRectangle(Pens.Gray, yBtn);
            g.DrawRectangle(Pens.Gray, gBtn);
            g.DrawRectangle(Pens.Gray, bBtn);
            g.DrawRectangle(Pens.Gray, pBtn);

            curX += 48;
            g.DrawString("Tô màu", labelFont, Brushes.Gray, curX - 70, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 2. Nhóm Gạch Chân & Gạch Bỏ
            bool isUnder = (pdfView.SelectedTool == 4);
            DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                using (Font uf = new Font("Segoe UI", 11f, FontStyle.Underline | FontStyle.Bold))
                {
                    g1.DrawString("U", uf, Brushes.Black, x1 + 5, y1 + 1);
                }
            }, "Gạch chân", isUnder);
            curX += 66;

            bool isStrike = (pdfView.SelectedTool == 5);
            DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => {
                using (Font sf = new Font("Segoe UI", 11f, FontStyle.Strikeout | FontStyle.Bold))
                {
                    g1.DrawString("S", sf, Brushes.Black, x1 + 5, y1 + 1);
                }
            }, "Gạch bỏ", isStrike);
            curX += 64;

            bool isNote = (pdfView.SelectedTool == 6);
            DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => {
                using (SolidBrush nb = new SolidBrush(Color.FromArgb(250, 204, 21)))
                {
                    g1.FillRectangle(nb, x1 + 2, y1 + 3, 16, 14);
                    g1.DrawString("✎", new Font("Segoe UI", 9f, FontStyle.Bold), Brushes.Brown, x1 + 4, y1 + 2);
                }
            }, "Ghi chú", isNote);
            curX += 64;

            g.DrawString("Đánh dấu", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 3. Nhóm Bút Vẽ Tay Tự Do (Freehand Ink)
            bool isInk = (pdfView.SelectedTool == 7);
            DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 2.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                {
                    g1.DrawLine(p, x1 + 2, y1 + 16, x1 + 8, y1 + 10);
                    g1.DrawLine(p, x1 + 8, y1 + 10, x1 + 14, y1 + 14);
                    g1.DrawLine(p, x1 + 14, y1 + 14, x1 + 18, y1 + 4);
                }
            }, "Bút vẽ tay", isInk);
            curX += 70;

            // 4. Nhóm Hình khối (Shapes)
            bool isRect = (pdfView.SelectedTool == 8);
            Color rectCol = pdfView.ActiveColor != Color.Empty ? pdfView.ActiveColor : Color.FromArgb(239, 68, 68);
            DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(rectCol, 2.0f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 2, 16, 12);
                }
                using (SolidBrush cBar = new SolidBrush(rectCol))
                {
                    g1.FillRectangle(cBar, x1, y1 + 17, 20, 3);
                }
            }, "Khung vuông", isRect);
            curX += 66;

            // Dãy chấm màu tròn phổ biến chọn nhanh cho Khung vuông
            Color[] shapeSwatches = new Color[] {
                Color.FromArgb(239, 68, 68),  // Đỏ
                Color.FromArgb(59, 130, 246),  // Xanh dương
                Color.FromArgb(16, 185, 129),  // Xanh lá
                Color.FromArgb(245, 158, 11),  // Vàng
                Color.FromArgb(139, 92, 246),  // Tím
                Color.FromArgb(15, 23, 42)     // Đen
            };

            // Hàng 1 (y: 74..88): Đỏ, Xanh dương, Xanh lá
            for (int k = 0; k < 3; k++)
            {
                int sx = curX + (k * 18);
                int sy = 74;
                using (SolidBrush sb = new SolidBrush(shapeSwatches[k]))
                {
                    g.FillEllipse(sb, sx, sy, 14, 14);
                }
                if (pdfView.ActiveColor.ToArgb() == shapeSwatches[k].ToArgb())
                {
                    g.DrawEllipse(Pens.Black, sx - 1, sy - 1, 16, 16);
                }
            }

            // Hàng 2 (y: 96..110): Vàng, Tím, Đen
            for (int k = 3; k < 6; k++)
            {
                int sx = curX + ((k - 3) * 18);
                int sy = 96;
                using (SolidBrush sb = new SolidBrush(shapeSwatches[k]))
                {
                    g.FillEllipse(sb, sx, sy, 14, 14);
                }
                if (pdfView.ActiveColor.ToArgb() == shapeSwatches[k].ToArgb())
                {
                    g.DrawEllipse(Pens.Black, sx - 1, sy - 1, 16, 16);
                }
            }

            // Nút mở Bảng màu đầy đủ giống Writer (Biểu tượng bảng màu 4 chấm + mũi tên dropdown)
            int paletteBtnX = curX + 56;
            using (SolidBrush pBg = new SolidBrush(Color.FromArgb(241, 245, 249)))
            using (Pen pBorder = new Pen(Color.FromArgb(203, 213, 225)))
            {
                g.FillRectangle(pBg, paletteBtnX, 74, 24, 36);
                g.DrawRectangle(pBorder, paletteBtnX, 74, 24, 36);

                g.FillEllipse(Brushes.Crimson, paletteBtnX + 4, 78, 6, 6);
                g.FillEllipse(Brushes.DodgerBlue, paletteBtnX + 13, 78, 6, 6);
                g.FillEllipse(Brushes.Goldenrod, paletteBtnX + 4, 88, 6, 6);
                g.FillEllipse(Brushes.MediumPurple, paletteBtnX + 13, 88, 6, 6);

                using (Font arrFont = new Font("Segoe UI", 6f, FontStyle.Bold))
                {
                    g.DrawString("▼", arrFont, Brushes.DimGray, paletteBtnX + 6, 97);
                }
            }
            curX += 86;

            g.DrawString("Vẽ hình", labelFont, Brushes.Gray, curX - 105, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 5. Nhóm Con Dấu (Stamps)
            bool isStamp = (pdfView.SelectedTool == 10);
            Color stampC = pdfView.ActiveStampColor != Color.Empty ? pdfView.ActiveStampColor : Color.FromArgb(16, 185, 129);
            DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                using (Pen sp = new Pen(stampC, 1.8f))
                {
                    g1.DrawRectangle(sp, x1 + 2, y1 + 3, 18, 14);
                    g1.DrawString("✓", new Font("Segoe UI", 9f, FontStyle.Bold), new SolidBrush(stampC), x1 + 4, y1 + 2);
                }
            }, "Con dấu ▾", isStamp);
            curX += 72;

            g.DrawString("Con dấu", labelFont, Brushes.Gray, curX - 55, 137);
        }
    }

