            DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                using (Font f = new Font("Segoe UI", 10.5f, FontStyle.Bold))
                {
                    g1.DrawString("📊X", f, Brushes.ForestGreen, x1, y1 + 1);
                }
            }, "Xuất Excel");
            curX += 68;

