            DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                using (Font f = new Font("Segoe UI", 10.5f, FontStyle.Bold))
                {
                    g1.DrawString("🗜️", f, Brushes.Purple, x1 + 2, y1 + 1);
                }
            }, "Nén PDF");
            curX += 68;

            g.DrawString("Chuyển đổi & Nén", labelFont, Brushes.Gray, curX - 180, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 5. Nhóm Đánh Số Bates Pháp Lý
            bool hasBates = (pdfView.Document != null && pdfView.Document.ActiveBatesConfig != null);
            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Font f = new Font("Courier New", 9f, FontStyle.Bold))
                {
                    g1.DrawString("#001", f, Brushes.DarkBlue, x1 - 1, y1 + 3);
                }
            }, "Số Bates", hasBates);
            curX += 80;

            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(239, 68, 68), 1.8f))
                {
                    g1.DrawLine(p, x1 + 2, y1 + 3, x1 + 18, y1 + 17);
                    g1.DrawString("#", new Font("Segoe UI", 9.5f, FontStyle.Bold), Brushes.DarkRed, x1 + 4, y1 + 2);
                }
            }, "Gỡ số Bates");
            curX += 80;

            g.DrawString("Đánh số Bates", labelFont, Brushes.Gray, curX - 110, 137);
        }
    }

    private void DrawPdfTabKyBaoMat(Graphics g, int width, PdfView pdfView)
    {
        int curX = 14;
        using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
        {
            // 1. Nhóm 3 Phương Thức Ký Tên Điện Tử (E-Sign: Type, Draw, Upload)
            bool isSign = (pdfView.SelectedTool == 11);
            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(30, 58, 138), 1.8f))
                {
                    g1.DrawLine(p, x1 + 2, y1 + 15, x1 + 18, y1 + 15);
                    g1.DrawString("✍", new Font("Segoe UI", 11f, FontStyle.Bold), Brushes.Navy, x1 + 3, y1);
                }
            }, "Ký điện tử", isSign);
            curX += 80;

            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(16, 185, 129), 1.8f))
                {
                    g1.DrawString("🖋", new Font("Segoe UI", 11f, FontStyle.Bold), Brushes.DarkGreen, x1 + 3, y1);
                }
            }, "Vẽ chữ ký");
            curX += 80;

            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.8f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 3, 18, 14);
                    g1.DrawString("🖼", new Font("Segoe UI", 10f, FontStyle.Bold), Brushes.Blue, x1 + 4, y1 + 2);
                }
            }, "Tải ảnh ký");
            curX += 80;

            g.DrawString("3 Phương thức ký", labelFont, Brushes.Gray, curX - 145, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 2. Nhóm Hình Mờ Bảo Mật (Watermark)
            bool isWmOn = (pdfView.Document != null && pdfView.Document.GlobalWatermark != null && pdfView.Document.GlobalWatermark.IsEnabled);
            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isWmOn ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.8f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 3, 18, 14);
                    g1.DrawLine(p, x1 + 4, y1 + 14, x1 + 16, y1 + 6);
                }
