    private void DrawColorTile(Graphics g, int x, int y, int w, int h, Color col, string label)
    {
        Rectangle r = new Rectangle(x, y, w, h);
        if (col == Color.Transparent)
        {
            using (SolidBrush b = new SolidBrush(Color.White)) g.FillRectangle(b, r);
            using (Pen p = new Pen(Color.Red, 1.2f)) g.DrawLine(p, x, y + h, x + w, y);
        }
        else
        {
            using (SolidBrush b = new SolidBrush(col)) g.FillRectangle(b, r);
        }
        using (Pen border = new Pen(Color.FromArgb(203, 213, 225), 1f))
        {
            g.DrawRectangle(border, r);
        }
    }

    private void DrawPdfTabDinhDangHopChu(Graphics g, int width, PdfView pdfView)
    {
        int curX = 14;
        using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
        using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
        using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
        {
            PdfTextElement txt = pdfView.SelectedText ?? pdfView.EditingText;

            // 1. Nhóm Màu Nền Ô (Fill Color) (X: 10..150)
            DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(196, 43, 28), 1.8f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 3, 16, 14);
                    Color fillCol = (txt != null && txt.BackgroundColor != Color.Transparent) ? txt.BackgroundColor : Color.LightBlue;
                    using (SolidBrush sb = new SolidBrush(fillCol))
                    {
                        g1.FillRectangle(sb, x1 + 4, y1 + 5, 12, 10);
                    }
                }
            }, "Màu nền");
            curX += 68;

            // Bảng màu nhanh cho Màu Nền (X: 78..146)
            int palX = curX;
            DrawColorTile(g, palX, 72, 18, 18, Color.Transparent, "X");
            DrawColorTile(g, palX + 22, 72, 18, 18, Color.White, "");
            DrawColorTile(g, palX + 44, 72, 18, 18, Color.FromArgb(254, 240, 138), "");
            DrawColorTile(g, palX, 98, 18, 18, Color.FromArgb(191, 219, 254), "");
            DrawColorTile(g, palX + 22, 98, 18, 18, Color.FromArgb(251, 207, 232), "");
            DrawColorTile(g, palX + 44, 98, 18, 18, Color.FromArgb(241, 245, 249), "");
            curX += 74;

            g.DrawString("Màu nền ô", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 2. Nhóm Viền Khung (Border Color & Width) (X: 160..300)
            DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                Color borderCol = (txt != null && txt.BorderColor != Color.Transparent) ? txt.BorderColor : Color.FromArgb(196, 43, 28);
