                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 3, 16, 14);
                }
            }, "Màu viền");
            curX += 68;

            // Bảng màu nhanh cho Viền Khung (X: 228..296)
            int bPalX = curX;
            DrawColorTile(g, bPalX, 72, 18, 18, Color.Transparent, "X");
            DrawColorTile(g, bPalX + 22, 72, 18, 18, Color.FromArgb(37, 99, 235), "");
            DrawColorTile(g, bPalX + 44, 72, 18, 18, Color.FromArgb(220, 38, 38), "");
            DrawColorTile(g, bPalX, 98, 18, 18, Color.FromArgb(15, 23, 42), "");
            DrawColorTile(g, bPalX + 22, 98, 18, 18, Color.FromArgb(16, 185, 129), "");
            DrawColorTile(g, bPalX + 44, 98, 18, 18, Color.FromArgb(148, 163, 184), "");
            curX += 74;

            g.DrawString("Viền khung", labelFont, Brushes.Gray, curX - 115, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 3. Nhóm Phông Chữ & Định Dạng Chữ (Font Family, Size, B, I, U, Color like Writer)
            string curFont = (txt != null && !string.IsNullOrEmpty(txt.FontName)) ? txt.FontName : (pdfView.ActiveFontName ?? "Segoe UI");
            float curFontSize = (txt != null) ? txt.FontSize : (pdfView.ActiveFontSize > 0 ? pdfView.ActiveFontSize : 12f);
            bool isB = (txt != null && txt.IsBold);
            bool isI = (txt != null && txt.IsItalic);
            bool isU = (txt != null && txt.IsUnderline);

            // Font Combo (X: curX, W: 115, H: 22)
            Rectangle fontBox = new Rectangle(curX, 70, 115, 22);
            DrawInteractiveButton(g, fontBox, false, 3);
            g.DrawString(curFont, btnFont, Brushes.Black, fontBox.X + 4, fontBox.Y + 3);
            g.DrawString("▾", btnFont, Brushes.Gray, fontBox.Right - 14, fontBox.Y + 3);

            // Size Combo (X: curX + 119, W: 45, H: 22)
            Rectangle sizeBox = new Rectangle(curX + 119, 70, 45, 22);
            DrawInteractiveButton(g, sizeBox, false, 3);
            g.DrawString(curFontSize.ToString("0.#"), btnFont, Brushes.Black, sizeBox.X + 4, sizeBox.Y + 3);
            g.DrawString("▾", btnFont, Brushes.Gray, sizeBox.Right - 14, sizeBox.Y + 3);

            // A ▲ / A ▼ (X: curX + 168, W: 24 each)
            Rectangle aUpBox = new Rectangle(curX + 168, 70, 24, 22);
            DrawInteractiveButton(g, aUpBox, false, 3);
            g.DrawString("A▲", labelFont, Brushes.Black, aUpBox.X + 2, aUpBox.Y + 4);

            Rectangle aDownBox = new Rectangle(curX + 194, 70, 24, 22);
            DrawInteractiveButton(g, aDownBox, false, 3);
            g.DrawString("A▼", labelFont, Brushes.Black, aDownBox.X + 2, aDownBox.Y + 4);

            // Căn lề: Trái, Giữa, Phải (X: curX + 222..294, Y: 70)
            bool isLeft = (txt == null || txt.Alignment == StringAlignment.Near);
            bool isCenter = (txt != null && txt.Alignment == StringAlignment.Center);
            bool isRight = (txt != null && txt.Alignment == StringAlignment.Far);

            DrawVectorBtn(g, curX + 222, 70, 24, 22, (g1, x1, y1) => {
                DrawAlignmentIcon(g1, x1, y1 + 1, 0, isLeft ? Color.FromArgb(196, 43, 28) : Color.Black);
            }, "", isLeft);
            DrawVectorBtn(g, curX + 248, 70, 24, 22, (g1, x1, y1) => {
                DrawAlignmentIcon(g1, x1, y1 + 1, 1, isCenter ? Color.FromArgb(196, 43, 28) : Color.Black);
            }, "", isCenter);
            DrawVectorBtn(g, curX + 274, 70, 24, 22, (g1, x1, y1) => {
                DrawAlignmentIcon(g1, x1, y1 + 1, 2, isRight ? Color.FromArgb(196, 43, 28) : Color.Black);
            }, "", isRight);

            // Hàng 2 (Y: 96): B, I, U, Màu chữ, Palette & Nút Thao tác
            DrawVectorBtn(g, curX, 96, 24, 22, (g1, x1, y1) => {
                using (SolidBrush bBrush = new SolidBrush(isB ? Color.FromArgb(196, 43, 28) : Color.Black))
                    g1.DrawString("B", boldFont, bBrush, x1 + 5, y1 + 2);
            }, "", isB);
            DrawVectorBtn(g, curX + 26, 96, 24, 22, (g1, x1, y1) => {
                using (Font itF = new Font("Segoe UI", 8.5f, FontStyle.Italic))
                using (SolidBrush iBrush = new SolidBrush(isI ? Color.FromArgb(196, 43, 28) : Color.Black))
                    g1.DrawString("I", itF, iBrush, x1 + 7, y1 + 2);
