            DrawColorTile(g, tPalX, 98, 18, 18, Color.Black, "");
            DrawColorTile(g, tPalX + 20, 98, 18, 18, Color.FromArgb(220, 38, 38), "");
            DrawColorTile(g, tPalX + 40, 98, 18, 18, Color.FromArgb(37, 99, 235), "");
            DrawColorTile(g, tPalX + 60, 98, 18, 18, Color.FromArgb(16, 185, 129), "");
            DrawColorTile(g, tPalX + 80, 98, 18, 18, Color.FromArgb(147, 51, 234), "");

            // Nút Nhân bản & Xóa
            DrawVectorBtn(g, curX + 222, 96, 36, 22, (g1, x1, y1) => {
                g1.DrawString("Nhân", labelFont, Brushes.DarkBlue, x1, y1 + 4);
            }, "");
            DrawVectorBtn(g, curX + 260, 96, 38, 22, (g1, x1, y1) => {
                g1.DrawString("Xóa", labelFont, Brushes.DarkRed, x1 + 5, y1 + 4);
            }, "");
            curX += 302;

            g.DrawString("Phông chữ & Thao tác", labelFont, Brushes.Gray, curX - 180, 137);
        }
    }

    public bool HandlePdfRibbonClick(int x, int y, PdfView pdfView, Form parentForm)
    {
        if (pdfView == null) return false;

        int formW = parentForm != null ? parentForm.ClientSize.Width : 1200;
        int formH = parentForm != null ? parentForm.ClientSize.Height : 800;

        if (ActiveRibbonTab == 0) // Trang đầu
        {
            // Mở file PDF (x: 14..50)
            if (x >= 14 && x <= 50 && y >= 68 && y <= 130)
            {
                using (OpenFileDialog ofd = new OpenFileDialog())
                {
                    ofd.Title = "Mở tệp PDF";
                    ofd.Filter = "Tệp PDF (*.pdf)|*.pdf|Tất cả tệp (*.*)|*.*";
                    if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        var loadedDoc = PdfHandler.LoadPdf(ofd.FileName);
                        pdfView.Document = loadedDoc;
                        pdfView.ActivePageIndex = 0;
                        DocTabs[ActiveDocIndex].Title = System.IO.Path.GetFileName(ofd.FileName);
                        DocTabs[ActiveDocIndex].PdfData = loadedDoc;
                        DocTabs[ActiveDocIndex].IsModified = false;
                        pdfView.InvalidateAllCaches();
                        if (parentForm != null) parentForm.Invalidate();
                        MessageBox.Show("Đã mở tệp PDF '" + ofd.FileName + "' thành công!", "ZenQ PDF Editor", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
                return true;
            }

            // Lưu file PDF (x: 52..88)
            if (x >= 52 && x <= 88 && y >= 68 && y <= 130)
            {
                using (SaveFileDialog sfd = new SaveFileDialog())
                {
                    sfd.Title = "Lưu tệp PDF chuẩn 1.7";
                    sfd.Filter = "Tệp PDF (*.pdf)|*.pdf";
                    sfd.DefaultExt = "pdf";
                    sfd.FileName = DocTabs[ActiveDocIndex].Title.Replace(" *", "");
                    if (sfd.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        bool ok = PdfHandler.SavePdf(pdfView.Document, sfd.FileName);
                        if (ok)
                        {
                            DocTabs[ActiveDocIndex].Title = System.IO.Path.GetFileName(sfd.FileName);
                            DocTabs[ActiveDocIndex].IsModified = false;
                            if (parentForm != null) parentForm.Invalidate();
                            MessageBox.Show("Đã lưu tệp PDF '" + sfd.FileName + "' thành công!", "Tài liệu PDF", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                    }
                }
                return true;
            }

            // Con trỏ (x: 104..158)
            if (x >= 104 && x <= 158 && y >= 68 && y <= 130) { pdfView.SelectedTool = 0; if (parentForm != null) parentForm.Invalidate(); return true; }

            // Thêm chữ (x: 162..224)
            if (x >= 162 && x <= 224 && y >= 68 && y <= 130) { pdfView.SelectedTool = 1; if (parentForm != null) parentForm.Invalidate(); return true; }

            // Sửa chữ (x: 228..286)
            if (x >= 228 && x <= 286 && y >= 68 && y <= 130)
            {
                pdfView.SelectedTool = 2;
                pdfView.AutoDetectTextForPage(pdfView.ActivePageIndex);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // === NHÓM PHÔNG CHỮ & ĐỊNH DẠNG (Tab 0) ===
            // Font Family Dropdown Popup (X: 300..410, Y: 70..92) - Khai thác toàn bộ font chữ của máy như Writer
            if (x >= 300 && x <= 410 && y >= 70 && y <= 92)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                string curFont = txtObj != null ? txtObj.FontName : pdfView.ActiveFontName;
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(300, 94)) : new Point(300, 94);
                FontDropDownForm fontDlg = new FontDropDownForm(curFont, pt, AvailableSystemFonts, Color.FromArgb(220, 38, 38));
                fontDlg.OnFontSelected += (font) =>
                {
                    pdfView.PushUndoState("Đổi phông chữ");
                    pdfView.ActiveFontName = font;
                    if (pdfView.SelectedText != null) pdfView.SelectedText.FontName = font;
                    if (pdfView.EditingText != null) pdfView.EditingText.FontName = font;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                fontDlg.Show();
                return true;
            }

            // Font Size Dropdown Popup (X: 414..459, Y: 70..92)
            if (x >= 414 && x <= 459 && y >= 70 && y <= 92)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                float curSize = txtObj != null ? txtObj.FontSize : pdfView.ActiveFontSize;
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(414, 94)) : new Point(414, 94);
                SizeDropDownForm sizeDlg = new SizeDropDownForm(curSize, pt, Color.FromArgb(220, 38, 38));
                sizeDlg.OnSizeSelected += (sz) =>
                {
                    pdfView.PushUndoState("Đổi cỡ chữ");
                    pdfView.ActiveFontSize = sz;
                    if (pdfView.SelectedText != null) pdfView.SelectedText.FontSize = sz;
                    if (pdfView.EditingText != null) pdfView.EditingText.FontSize = sz;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                sizeDlg.Show();
                return true;
            }

            // A▲ (X: 462..486, Y: 70..92)
            if (x >= 462 && x <= 486 && y >= 70 && y <= 92)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                if (txtObj != null)
                {
                    pdfView.PushUndoState("Tăng cỡ chữ");
                    txtObj.FontSize = Math.Min(72f, txtObj.FontSize + 2f);
                    pdfView.ActiveFontSize = txtObj.FontSize;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }

            // A▼ (X: 488..512, Y: 70..92)
            if (x >= 488 && x <= 512 && y >= 70 && y <= 92)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                if (txtObj != null)
                {
                    pdfView.PushUndoState("Giảm cỡ chữ");
                    txtObj.FontSize = Math.Max(6f, txtObj.FontSize - 2f);
                    pdfView.ActiveFontSize = txtObj.FontSize;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }

            // B (X: 300..326, Y: 96..118)
            if (x >= 300 && x <= 326 && y >= 96 && y <= 118)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                if (txtObj != null)
                {
                    txtObj.IsBold = !txtObj.IsBold;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }

            // I (X: 329..355, Y: 96..118)
            if (x >= 329 && x <= 355 && y >= 96 && y <= 118)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                if (txtObj != null)
                {
                    txtObj.IsItalic = !txtObj.IsItalic;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }

            // U (X: 358..384, Y: 96..118)
            if (x >= 358 && x <= 384 && y >= 96 && y <= 118)
            {
                var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                if (txtObj != null)
                {
                    txtObj.IsUnderline = !txtObj.IsUnderline;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }

            // Màu chữ (X: 387..432, Y: 96..118)
            if (x >= 387 && x <= 432 && y >= 96 && y <= 118)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(387, 120)) : new Point(387, 120);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    var txtObj = pdfView.SelectedText ?? pdfView.EditingText;
                    if (txtObj != null)
                    {
                        pdfView.PushUndoState("Đổi màu chữ");
                        txtObj.TextColor = c;
                        pdfView.ActiveColor = c;
                        if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
