                pdfView.PromptAddBookmark(parentForm);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
        }
        else if (ActiveRibbonTab == 6) // Định dạng Hộp chữ
        {
            PdfTextElement txt = pdfView.SelectedText ?? pdfView.EditingText;
            if (txt == null) return false;

            // Nút Màu Nền Ô (x: 14..78)
            if (x >= 14 && x <= 78 && y >= 68 && y <= 130)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(14, 132)) : new Point(14, 132);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    pdfView.PushUndoState("Đổi màu nền ô");
                    txt.BackgroundColor = c;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Bảng màu nhanh Màu Nền (x: 82..144)
            if (x >= 82 && x <= 100 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.Transparent; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 104 && x <= 122 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.White; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 126 && x <= 144 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(254, 240, 138); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 82 && x <= 100 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(191, 219, 254); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 104 && x <= 122 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(251, 207, 232); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 126 && x <= 144 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(241, 245, 249); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // Nút Màu Viền Khung (x: 166..230)
            if (x >= 166 && x <= 230 && y >= 68 && y <= 130)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(166, 132)) : new Point(166, 132);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    pdfView.PushUndoState("Đổi màu viền");
                    txt.BorderColor = c;
                    txt.BorderWidth = Math.Max(1.5f, txt.BorderWidth);
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Bảng màu nhanh Viền Khung (x: 234..296)
            if (x >= 234 && x <= 252 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.Transparent; txt.BorderWidth = 0f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 256 && x <= 274 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(37, 99, 235); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 278 && x <= 296 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(220, 38, 38); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 234 && x <= 252 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(15, 23, 42); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 256 && x <= 274 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(16, 185, 129); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 278 && x <= 296 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(148, 163, 184); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // === NHÓM PHÔNG CHỮ & ĐỊNH DẠNG (Tab 6) ===
            // Font Family Dropdown Popup (X: 318..433, Y: 70..92) - Khai thác toàn bộ font chữ của máy như Writer
            if (x >= 318 && x <= 433 && y >= 70 && y <= 92)
            {
                string curFont = txt != null ? txt.FontName : pdfView.ActiveFontName;
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(318, 94)) : new Point(318, 94);
                FontDropDownForm fontDlg = new FontDropDownForm(curFont, pt, AvailableSystemFonts, Color.FromArgb(220, 38, 38));
                fontDlg.OnFontSelected += (font) =>
                {
                    pdfView.PushUndoState("Đổi phông chữ");
                    txt.FontName = font;
                    pdfView.ActiveFontName = font;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                fontDlg.Show();
                return true;
            }

            // Font Size Dropdown Popup (X: 437..482, Y: 70..92)
            if (x >= 437 && x <= 482 && y >= 70 && y <= 92)
            {
                float curSize = txt != null ? txt.FontSize : pdfView.ActiveFontSize;
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(437, 94)) : new Point(437, 94);
                SizeDropDownForm sizeDlg = new SizeDropDownForm(curSize, pt, Color.FromArgb(220, 38, 38));
                sizeDlg.OnSizeSelected += (sz) =>
                {
                    pdfView.PushUndoState("Đổi cỡ chữ");
                    txt.FontSize = sz;
                    pdfView.ActiveFontSize = sz;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                sizeDlg.Show();
                return true;
            }

            // A▲ (X: 486..510, Y: 70..92)
            if (x >= 486 && x <= 510 && y >= 70 && y <= 92)
            {
                pdfView.PushUndoState("Tăng cỡ chữ");
                txt.FontSize = Math.Min(72f, txt.FontSize + 2f);
                pdfView.ActiveFontSize = txt.FontSize;
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                pdfView.Document.IsModified = true;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // A▼ (X: 512..536, Y: 70..92)
            if (x >= 512 && x <= 536 && y >= 70 && y <= 92)
            {
                pdfView.PushUndoState("Giảm cỡ chữ");
                txt.FontSize = Math.Max(6f, txt.FontSize - 2f);
                pdfView.ActiveFontSize = txt.FontSize;
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                pdfView.Document.IsModified = true;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Căn lề Trái, Giữa, Phải (X: 540..616, Y: 70..92)
            if (x >= 540 && x <= 564 && y >= 70 && y <= 92) { txt.Alignment = StringAlignment.Near; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 566 && x <= 590 && y >= 70 && y <= 92) { txt.Alignment = StringAlignment.Center; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 592 && x <= 616 && y >= 70 && y <= 92) { txt.Alignment = StringAlignment.Far; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // B (X: 318..342, Y: 96..118)
            if (x >= 318 && x <= 342 && y >= 96 && y <= 118) { txt.IsBold = !txt.IsBold; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            // I (X: 344..368, Y: 96..118)
            if (x >= 344 && x <= 368 && y >= 96 && y <= 118) { txt.IsItalic = !txt.IsItalic; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            // U (X: 370..394, Y: 96..118)
            if (x >= 370 && x <= 394 && y >= 96 && y <= 118) { txt.IsUnderline = !txt.IsUnderline; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // Nút Màu Chữ (x: 396..434, y: 96..118)
            if (x >= 396 && x <= 434 && y >= 96 && y <= 118)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(396, 120)) : new Point(396, 120);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    pdfView.PushUndoState("Đổi màu chữ");
                    txt.TextColor = c;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Bảng màu nhanh Màu Chữ (X: 436..534, Y: 96..118)
            if (x >= 436 && x <= 454 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.Black; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 456 && x <= 474 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(220, 38, 38); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 476 && x <= 494 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(37, 99, 235); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 496 && x <= 514 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(16, 185, 129); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 516 && x <= 534 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(147, 51, 234); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // Nhân bản & Xóa (x: 540..616, y: 96..118)
            if (x >= 540 && x <= 576 && y >= 96 && y <= 118)
            {
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                {
                    pdfView.PushUndoState("Nhân bản");
                    var dup = txt.Clone();
                    dup.Bounds = new RectangleF(dup.Bounds.X + 20, dup.Bounds.Y + 20, dup.Bounds.Width, dup.Bounds.Height);
                    pdfView.Document.Pages[pdfView.ActivePageIndex].TextElements.Add(dup);
                    pdfView.SelectedText = dup;
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }
            if (x >= 578 && x <= 616 && y >= 96 && y <= 118)
            {
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                {
                    pdfView.PushUndoState("Xóa");
                    pdfView.Document.Pages[pdfView.ActivePageIndex].TextElements.Remove(txt);
                    pdfView.SelectedText = null;
                    pdfView.EditingText = null;
                    ActiveRibbonTab = 0;
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }
        }

        return false;
    }
    #endregion

    public static Bitmap CreateExcelBorderIcon(int preset)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.None;
            using (Pen gridPen = new Pen(Color.FromArgb(210, 215, 220), 1f))
            {
                gridPen.DashStyle = DashStyle.Dot;
                g.DrawRectangle(gridPen, 2, 2, 11, 11);
                g.DrawLine(gridPen, 7, 2, 7, 13);
                g.DrawLine(gridPen, 2, 7, 13, 7);
            }

            using (Pen activePen = new Pen(Color.FromArgb(15, 23, 42), 2f))
            using (Pen thinPen = new Pen(Color.FromArgb(15, 23, 42), 1f))
            {
                switch (preset)
                {
                    case 0: // Bottom
                        g.DrawLine(activePen, 2, 13, 13, 13);
                        break;
                    case 1: // Top
                        g.DrawLine(activePen, 2, 2, 13, 2);
                        break;
                    case 2: // Left
                        g.DrawLine(activePen, 2, 2, 2, 13);
                        break;
                    case 3: // Right
                        g.DrawLine(activePen, 13, 2, 13, 13);
                        break;
                    case 4: // No border
                        using (Pen redX = new Pen(Color.FromArgb(239, 68, 68), 1.5f))
                        {
                            g.DrawLine(redX, 4, 4, 11, 11);
                            g.DrawLine(redX, 11, 4, 4, 11);
                        }
                        break;
                    case 5: // All borders
                        g.DrawRectangle(thinPen, 2, 2, 11, 11);
                        g.DrawLine(thinPen, 7, 2, 7, 13);
                        g.DrawLine(thinPen, 2, 7, 13, 7);
                        break;
                    case 6: // Outside borders
                        g.DrawRectangle(thinPen, 2, 2, 11, 11);
                        break;
                    case 7: // Thick outside border
                        g.DrawRectangle(activePen, 2, 2, 11, 11);
                        break;
                    case 8: // Bottom double border
                        g.DrawLine(thinPen, 2, 12, 13, 12);
                        g.DrawLine(thinPen, 2, 14, 13, 14);
                        break;
                    case 9: // Thick bottom border
                        using (Pen thick = new Pen(Color.FromArgb(15, 23, 42), 3f))
                        {
                            g.DrawLine(thick, 2, 13, 13, 13);
                        }
                        break;
                    case 10: // Top and bottom
                        g.DrawLine(thinPen, 2, 2, 13, 2);
                        g.DrawLine(thinPen, 2, 13, 13, 13);
                        break;
                    case 11: // Top and thick bottom
                        g.DrawLine(thinPen, 2, 2, 13, 2);
                        using (Pen thick = new Pen(Color.FromArgb(15, 23, 42), 3f))
                        {
                            g.DrawLine(thick, 2, 13, 13, 13);
                        }
                        break;
                    case 12: // Top and double bottom
                        g.DrawLine(thinPen, 2, 2, 13, 2);
                        g.DrawLine(thinPen, 2, 12, 13, 12);
                        g.DrawLine(thinPen, 2, 14, 13, 14);
                        break;
                }
            }
        }
        return bmp;
    }

    public static Bitmap CreateConditionalFormatIcon(int type)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            switch (type)
            {
                case 0: // Above Average (Green cell with up arrow)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(220, 252, 231)))
                    using (Pen border = new Pen(Color.FromArgb(22, 101, 52), 1f))
                    using (Pen arrow = new Pen(Color.FromArgb(22, 101, 52), 1.6f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        g.FillRectangle(bg, 1, 1, 13, 13);
                        g.DrawRectangle(border, 1, 1, 13, 13);
                        g.DrawLine(arrow, 5, 8, 8, 4);
                        g.DrawLine(arrow, 8, 4, 11, 8);
                        g.DrawLine(arrow, 8, 4, 8, 11);
                    }
                    break;
                case 1: // Below Average (Red cell with down arrow)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(254, 226, 226)))
                    using (Pen border = new Pen(Color.FromArgb(153, 27, 27), 1f))
                    using (Pen arrow = new Pen(Color.FromArgb(153, 27, 27), 1.6f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        g.FillRectangle(bg, 1, 1, 13, 13);
                        g.DrawRectangle(border, 1, 1, 13, 13);
                        g.DrawLine(arrow, 5, 7, 8, 11);
                        g.DrawLine(arrow, 8, 11, 11, 7);
                        g.DrawLine(arrow, 8, 4, 8, 11);
                    }
                    break;
                case 2: // Color Scale Heatmap (Green, Yellow, Red horizontal gradient bands)
                    using (SolidBrush bgG = new SolidBrush(Color.FromArgb(34, 197, 94)))
                    using (SolidBrush bgY = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    using (SolidBrush bgR = new SolidBrush(Color.FromArgb(239, 68, 68)))
                    using (Pen border = new Pen(Color.FromArgb(203, 213, 225), 1f))
                    {
                        g.FillRectangle(bgG, 2, 2, 12, 4);
                        g.FillRectangle(bgY, 2, 6, 12, 4);
                        g.FillRectangle(bgR, 2, 10, 12, 4);
                        g.DrawRectangle(border, 2, 2, 12, 12);
                    }
                    break;
                case 3: // Data Bars (Blue gradient fill inside cell)
                    using (Pen border = new Pen(Color.FromArgb(148, 163, 184), 1f))
                    using (LinearGradientBrush lgb = new LinearGradientBrush(new Rectangle(2, 3, 9, 10), Color.FromArgb(59, 130, 246), Color.FromArgb(147, 197, 253), LinearGradientMode.Horizontal))
                    {
                        g.FillRectangle(Brushes.White, 2, 3, 12, 10);
                        g.FillRectangle(lgb, 2, 3, 9, 10);
                        g.DrawRectangle(border, 2, 3, 12, 10);
                    }
                    break;
                case 4: // Duplicate Values (Two overlapping yellow squares)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(254, 240, 138)))
                    using (Pen border = new Pen(Color.FromArgb(202, 138, 4), 1f))
                    {
                        g.FillRectangle(bg, 1, 1, 9, 9);
                        g.DrawRectangle(border, 1, 1, 9, 9);
                        g.FillRectangle(bg, 5, 5, 9, 9);
                        g.DrawRectangle(border, 5, 5, 9, 9);
                    }
                    break;
                case 5: // Clear Rules (Eraser / Slash)
                    using (Pen border = new Pen(Color.FromArgb(148, 163, 184), 1f))
                    using (Pen slash = new Pen(Color.FromArgb(239, 68, 68), 2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                    {
                        g.DrawRectangle(border, 2, 2, 11, 11);
                        g.DrawLine(border, 2, 7, 13, 7);
                        g.DrawLine(border, 7, 2, 7, 13);
                        g.DrawLine(slash, 3, 13, 13, 3);
                    }
                    break;
            }
        }
        return bmp;
    }

    public static Bitmap CreateTableStyleIcon(int type)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            Color hdrCol, r1Col, r2Col, bdrCol;
            switch (type)
            {
                case 0: // Green
                    hdrCol = Color.FromArgb(16, 124, 65);
                    r1Col = Color.FromArgb(220, 252, 231);
                    r2Col = Color.White;
                    bdrCol = Color.FromArgb(22, 101, 52);
                    break;
                case 1: // Blue
                    hdrCol = Color.FromArgb(2, 132, 199);
                    r1Col = Color.FromArgb(224, 242, 254);
                    r2Col = Color.White;
                    bdrCol = Color.FromArgb(3, 105, 161);
                    break;
                case 2: // Orange
                    hdrCol = Color.FromArgb(234, 88, 12);
                    r1Col = Color.FromArgb(255, 237, 213);
                    r2Col = Color.White;
                    bdrCol = Color.FromArgb(194, 65, 12);
                    break;
                default: // Slate
                    hdrCol = Color.FromArgb(51, 65, 85);
                    r1Col = Color.FromArgb(241, 245, 249);
                    r2Col = Color.White;
                    bdrCol = Color.FromArgb(71, 85, 105);
                    break;
            }

            using (SolidBrush bHdr = new SolidBrush(hdrCol))
            using (SolidBrush bR1 = new SolidBrush(r1Col))
            using (SolidBrush bR2 = new SolidBrush(r2Col))
            using (Pen pBdr = new Pen(bdrCol, 1f))
            {
                g.FillRectangle(bHdr, 1, 1, 14, 4);
                g.FillRectangle(bR1, 1, 5, 14, 3);
                g.FillRectangle(bR2, 1, 8, 14, 3);
                g.FillRectangle(bR1, 1, 11, 14, 3);
                g.DrawRectangle(pBdr, 1, 1, 14, 13);
                g.DrawLine(pBdr, 8, 1, 8, 14);
            }
        }
        return bmp;
    }

    public static Bitmap CreateCellStyleIcon(int type)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            switch (type)
            {
                case 0: // Normal
                    using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(100, 116, 139), 1.5f))
                    {
                        g.FillRectangle(Brushes.White, 1, 2, 13, 11);
                        g.DrawRectangle(p, 1, 2, 13, 11);
                        g.DrawLine(txt, 4, 8, 11, 8);
                    }
                    break;
                case 1: // Good (Green)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(220, 252, 231)))
                    using (Pen p = new Pen(Color.FromArgb(22, 101, 52), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(22, 101, 52), 1.5f))
                    {
                        g.FillRectangle(bg, 1, 2, 13, 11);
                        g.DrawRectangle(p, 1, 2, 13, 11);
                        g.DrawLine(txt, 4, 8, 11, 8);
                    }
                    break;
                case 2: // Bad (Red)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(254, 226, 226)))
                    using (Pen p = new Pen(Color.FromArgb(153, 27, 27), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(153, 27, 27), 1.5f))
                    {
                        g.FillRectangle(bg, 1, 2, 13, 11);
                        g.DrawRectangle(p, 1, 2, 13, 11);
                        g.DrawLine(txt, 4, 8, 11, 8);
                    }
                    break;
                case 3: // Neutral (Yellow/Amber)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(254, 243, 199)))
                    using (Pen p = new Pen(Color.FromArgb(180, 83, 9), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(146, 64, 14), 1.5f))
                    {
                        g.FillRectangle(bg, 1, 2, 13, 11);
                        g.DrawRectangle(p, 1, 2, 13, 11);
                        g.DrawLine(txt, 4, 8, 11, 8);
                    }
                    break;
                case 4: // Heading 1 (Thick bottom blue line)
                    using (Pen line = new Pen(Color.FromArgb(37, 99, 235), 2.2f))
                    using (Pen txt = new Pen(Color.FromArgb(30, 41, 59), 2f))
                    {
                        g.FillRectangle(Brushes.White, 1, 2, 13, 11);
                        g.DrawLine(txt, 3, 6, 12, 6);
                        g.DrawLine(line, 1, 13, 14, 13);
                    }
                    break;
                case 5: // Heading 2 (Thin bottom blue line)
                    using (Pen line = new Pen(Color.FromArgb(59, 130, 246), 1.2f))
                    using (Pen txt = new Pen(Color.FromArgb(71, 85, 105), 1.5f))
                    {
                        g.FillRectangle(Brushes.White, 1, 2, 13, 11);
                        g.DrawLine(txt, 3, 6, 11, 6);
                        g.DrawLine(line, 1, 13, 14, 13);
                    }
                    break;
                case 6: // Total Row (Top single line, bottom double line)
                    using (Pen line = new Pen(Color.FromArgb(15, 23, 42), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(15, 23, 42), 1.5f))
                    {
                        g.FillRectangle(Brushes.White, 1, 2, 13, 11);
                        g.DrawLine(line, 1, 3, 14, 3);
                        g.DrawLine(txt, 4, 7, 11, 7);
                        g.DrawLine(line, 1, 11, 14, 11);
                        g.DrawLine(line, 1, 13, 14, 13);
                    }
                    break;
                case 7: // Accent 1 (Blue)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(219, 234, 254)))
                    using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(30, 64, 175), 1.5f))
                    {
                        g.FillRectangle(bg, 1, 2, 13, 11);
                        g.DrawRectangle(p, 1, 2, 13, 11);
                        g.DrawLine(txt, 4, 8, 11, 8);
                    }
                    break;
                default: // Accent 2 (Orange)
                    using (SolidBrush bg = new SolidBrush(Color.FromArgb(255, 237, 213)))
                    using (Pen p = new Pen(Color.FromArgb(234, 88, 12), 1f))
                    using (Pen txt = new Pen(Color.FromArgb(194, 65, 12), 1.5f))
                    {
                        g.FillRectangle(bg, 1, 2, 13, 11);
                        g.DrawRectangle(p, 1, 2, 13, 11);
                        g.DrawLine(txt, 4, 8, 11, 8);
                    }
                    break;
            }
        }
        return bmp;
    }

    public static Bitmap CreateCellInsertDeleteIcon(int type)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Pen grid = Pens.Silver;
            g.DrawRectangle(grid, 1, 1, 13, 13);

            switch (type)
            {
                case 0: // Insert Row (+ and green row highlight)
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(220, 252, 231)))
                    using (Pen p = new Pen(Color.FromArgb(22, 163, 74), 1.6f))
                    {
                        g.FillRectangle(sb, 2, 7, 12, 4);
                        g.DrawLine(p, 1, 3, 5, 3);
                        g.DrawLine(p, 3, 1, 3, 5);
                    }
                    break;
                case 1: // Insert Col (+ and green col highlight)
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(220, 252, 231)))
                    using (Pen p = new Pen(Color.FromArgb(22, 163, 74), 1.6f))
                    {
                        g.FillRectangle(sb, 7, 2, 4, 12);
                        g.DrawLine(p, 1, 3, 5, 3);
                        g.DrawLine(p, 3, 1, 3, 5);
                    }
                    break;
                case 2: // Insert Sheet
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(241, 245, 249)))
                    using (Pen p = new Pen(Color.FromArgb(22, 163, 74), 1.6f))
                    {
                        g.FillRectangle(sb, 2, 2, 11, 11);
                        g.DrawLine(p, 5, 8, 11, 8);
                        g.DrawLine(p, 8, 5, 8, 11);
                    }
                    break;
                case 3: // Delete Row (- and red row strike)
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(254, 226, 226)))
                    using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.6f))
                    {
                        g.FillRectangle(sb, 2, 7, 12, 4);
                        g.DrawLine(p, 1, 3, 5, 3);
                    }
                    break;
                case 4: // Delete Col (- and red col strike)
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(254, 226, 226)))
                    using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.6f))
                    {
                        g.FillRectangle(sb, 7, 2, 4, 12);
                        g.DrawLine(p, 1, 3, 5, 3);
                    }
                    break;
                case 5: // Delete Sheet
                    using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.6f))
                    {
                        g.DrawLine(p, 4, 4, 11, 11);
                        g.DrawLine(p, 11, 4, 4, 11);
                    }
                    break;
                case 6: // Clear Contents
                    using (Pen p = new Pen(Color.FromArgb(239, 68, 68), 1.5f))
                    {
                        g.DrawLine(p, 4, 4, 11, 11);
                        g.DrawLine(p, 11, 4, 4, 11);
                    }
                    break;
                case 7: // Clear Formats
                    using (Pen p = new Pen(Color.FromArgb(245, 158, 11), 1.5f))
                    {
                        g.DrawLine(p, 3, 12, 12, 3);
                    }
                    break;
                default: // Clear All
                    using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 2f))
                    {
                        g.DrawLine(p, 2, 2, 13, 13);
                        g.DrawLine(p, 13, 2, 2, 13);
                    }
                    break;
            }
        }
        return bmp;
    }

    public static Bitmap CreateCellFormatIcon(int type)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Pen p = new Pen(Color.FromArgb(16, 124, 65), 1.5f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                switch (type)
                {
                    case 0: // AutoFit Row Height (vertical arrows)
                        g.DrawLine(p, 8, 2, 8, 13);
                        g.DrawLine(p, 5, 5, 8, 2);
                        g.DrawLine(p, 11, 5, 8, 2);
                        g.DrawLine(p, 5, 10, 8, 13);
                        g.DrawLine(p, 11, 10, 8, 13);
                        break;
                    case 1: // AutoFit Col Width (horizontal arrows)
                        g.DrawLine(p, 2, 8, 13, 8);
                        g.DrawLine(p, 5, 5, 2, 8);
                        g.DrawLine(p, 5, 11, 2, 8);
                        g.DrawLine(p, 10, 5, 13, 8);
                        g.DrawLine(p, 10, 11, 13, 8);
                        break;
                    case 2: // Set Row Height (ruler vertical)
                        g.DrawRectangle(Pens.Gray, 3, 2, 10, 11);
                        g.DrawLine(p, 3, 6, 8, 6);
                        break;
                    case 3: // Set Col Width (ruler horizontal)
                        g.DrawRectangle(Pens.Gray, 2, 3, 11, 10);
                        g.DrawLine(p, 6, 3, 6, 8);
                        break;
                    case 4: // Hide Rows
                        using (Pen pRed = new Pen(Color.FromArgb(220, 38, 38), 1.5f))
                        {
                            g.DrawLine(pRed, 2, 8, 13, 8);
                            g.DrawLine(Pens.Gray, 2, 3, 13, 3);
                            g.DrawLine(Pens.Gray, 2, 12, 13, 12);
                        }
                        break;
                    case 5: // Unhide Rows
                        g.DrawLine(Pens.Gray, 2, 3, 13, 3);
                        g.DrawLine(Pens.Gray, 2, 12, 13, 12);
                        g.DrawLine(p, 8, 4, 8, 11);
                        break;
                    case 6: // Hide Cols
                        using (Pen pRed = new Pen(Color.FromArgb(220, 38, 38), 1.5f))
                        {
                            g.DrawLine(pRed, 8, 2, 8, 13);
                            g.DrawLine(Pens.Gray, 3, 2, 3, 13);
                            g.DrawLine(Pens.Gray, 12, 2, 12, 13);
                        }
                        break;
                    default: // Unhide Cols
                        g.DrawLine(Pens.Gray, 3, 2, 3, 13);
                        g.DrawLine(Pens.Gray, 12, 2, 12, 13);
                        g.DrawLine(p, 4, 8, 11, 8);
                        break;
                }
            }
        }
        return bmp;
    }

    public static Bitmap CreateAutoSumIcon(int type)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Pen p = new Pen(Color.FromArgb(16, 124, 65), 1.6f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
            {
                switch (type)
                {
                    case 0: // SUM Σ
                        g.DrawLine(p, 12, 3, 4, 3);
                        g.DrawLine(p, 4, 3, 9, 8);
                        g.DrawLine(p, 9, 8, 4, 13);
                        g.DrawLine(p, 4, 13, 12, 13);
                        break;
                    case 1: // AVERAGE x̄
                        using (Font f = new Font("Segoe UI", 8.5f, FontStyle.Bold))
                        {
                            g.DrawLine(p, 4, 3, 12, 3);
                            g.DrawString("x", f, new SolidBrush(Color.FromArgb(16, 124, 65)), 3, 2);
                        }
                        break;
                    case 2: // COUNT #
                        using (Font f = new Font("Segoe UI", 9f, FontStyle.Bold))
                        {
                            g.DrawString("#", f, new SolidBrush(Color.FromArgb(16, 124, 65)), 2, 1);
                        }
                        break;
                    case 3: // MAX ▲
                        g.DrawPolygon(p, new PointF[] { new PointF(8, 3), new PointF(13, 12), new PointF(3, 12) });
                        break;
                    default: // MIN ▼
                        g.DrawPolygon(p, new PointF[] { new PointF(3, 4), new PointF(13, 4), new PointF(8, 13) });
                        break;
                }
            }
        }
        return bmp;
    }

        #region Photo & Studio Ribbon Toolbar Implementation
        private void DrawPhotoRibbonToolbar(Graphics g, int width, PhotoView photoView)
        {
            if (photoView == null) return;

            int maxScroll = Math.Max(0, PhotoRibbonTotalContentWidth - width + 50);
            if (PhotoRibbonScrollX > maxScroll) PhotoRibbonScrollX = maxScroll;
            if (PhotoRibbonScrollX < 0) PhotoRibbonScrollX = 0;

            GraphicsState state = g.Save();
            Rectangle clipRect = new Rectangle(0, 56, width, RibbonHeight - 56);
            g.SetClip(clipRect);
            g.TranslateTransform(-PhotoRibbonScrollX, 0);

            switch (ActiveRibbonTab)
            {
                case 0: DrawPhotoTabTrangDau(g, width, photoView); break;
                case 1: DrawPhotoTabLop(g, width, photoView); break;
                case 2: DrawPhotoTabBoLoc(g, width, photoView); break;
                case 3: DrawPhotoTabVeVector(g, width, photoView); break;
                case 4: DrawPhotoTabVanBan(g, width, photoView); break;
                case 5: DrawPhotoTabSapXep(g, width, photoView); break;
                case 6: DrawPhotoTabXemThuoc(g, width, photoView); break;
                case 7: DrawPhotoTabXuatTep(g, width, photoView); break;
                default: DrawPhotoTabTrangDau(g, width, photoView); break;
            }

            g.Restore(state);

            // Draw scroll left/right navigation buttons if overflowing
            if (maxScroll > 0)
            {
                if (PhotoRibbonScrollX > 2)
                {
                    PhotoRibbonScrollLeftBounds = new Rectangle(2, 74, 20, 56);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 255, 255, 255)))
                    using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 1f))
                    {
                        g.FillRectangle(b, PhotoRibbonScrollLeftBounds);
                        g.DrawRectangle(p, PhotoRibbonScrollLeftBounds);
                        FluentIconRenderer.DrawGlyph(g, '\uE76B', new Rectangle(PhotoRibbonScrollLeftBounds.X + 2, PhotoRibbonScrollLeftBounds.Y + 20, 16, 16), Color.FromArgb(71, 85, 105), 12f);
                    }
                }
                else PhotoRibbonScrollLeftBounds = Rectangle.Empty;

                if (PhotoRibbonScrollX < maxScroll - 2)
                {
                    PhotoRibbonScrollRightBounds = new Rectangle(width - 22, 74, 20, 56);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 255, 255, 255)))
                    using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 1f))
                    {
                        g.FillRectangle(b, PhotoRibbonScrollRightBounds);
                        g.DrawRectangle(p, PhotoRibbonScrollRightBounds);
                        FluentIconRenderer.DrawGlyph(g, '\uE76C', new Rectangle(PhotoRibbonScrollRightBounds.X + 2, PhotoRibbonScrollRightBounds.Y + 20, 16, 16), Color.FromArgb(71, 85, 105), 12f);
                    }
                }
                else PhotoRibbonScrollRightBounds = Rectangle.Empty;
            }
            else
            {
                PhotoRibbonScrollLeftBounds = Rectangle.Empty;
                PhotoRibbonScrollRightBounds = Rectangle.Empty;
            }
        }

        private void DrawPhotoTabTrangDau(Graphics g, int width, PhotoView photoView)
        {
            int curX = 14;
            Color primary = Color.FromArgb(99, 102, 241); // Indigo Studio
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            {
                // 1. Nhóm Lịch sử & Bảng nhớ tạm (Undo, Redo, Copy, Cut, Paste)
                DrawVectorToolBtnLarge(g, curX, 68, 42, 60, (g1, x1, y1) => {
                    FluentIconRenderer.DrawGlyph(g1, '\uE7A7', new Rectangle(x1 - 2, y1, 20, 20), Color.FromArgb(71, 85, 105), 18f);
                }, "Hoàn tác");
                curX += 44;

                DrawVectorToolBtnLarge(g, curX, 68, 42, 60, (g1, x1, y1) => {
                    FluentIconRenderer.DrawGlyph(g1, '\uE7A6', new Rectangle(x1 - 2, y1, 20, 20), Color.FromArgb(71, 85, 105), 18f);
                }, "Làm lại");
                curX += 44;

                DrawVectorBtn(g, curX, 68, 64, 26, (g1, x1, y1) => {
                    FluentIconRenderer.DrawGlyph(g1, '\uE8C8', new Rectangle(x1, y1 + 1, 14, 14), Color.FromArgb(71, 85, 105), 11f);
                }, "Sao chép");
                DrawVectorBtn(g, curX, 98, 64, 26, (g1, x1, y1) => {
                    FluentIconRenderer.DrawGlyph(g1, '\uE8C6', new Rectangle(x1, y1 + 1, 14, 14), Color.FromArgb(71, 85, 105), 11f);
                }, "Cắt");
                curX += 68;

                DrawVectorToolBtnLarge(g, curX, 68, 44, 60, (g1, x1, y1) => {
                    FluentIconRenderer.DrawGlyph(g1, '\uE77F', new Rectangle(x1 - 1, y1, 20, 20), primary, 18f);
                }, "Dán");
                curX += 48;

                g.DrawString("Lịch sử & Tạm", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX + 2, 68, curX + 2, 148);
                curX += 12;

                // 2. Nhóm Công cụ Đồ họa (Tools)
                DrawVectorToolBtnLarge(g, curX, 68, 48, 60, (g1, x1, y1) => {
                    Color c = photoView.SelectedTool == PhotoTool.Move ? primary : Color.FromArgb(71, 85, 105);
                    FluentIconRenderer.DrawGlyph(g1, '\uE8B0', new Rectangle(x1 + 1, y1, 20, 20), c, 18f);
