                }, "Thu nhỏ");
                curX += 82;

                g.DrawString("Thu phóng (" + (int)(photoView.Zoom * 100) + "%)", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX + 2, 68, curX + 2, 148);
                curX += 14;

                // 4. Nhóm Cọ vẽ nhanh (Brush size)
