                    FluentIconRenderer.DrawGlyph(g1, '\uED63', new Rectangle(x1, y1 + 1, 14, 14), photoView.BrushSize == 8f ? primary : Color.FromArgb(71, 85, 105), 11f);
                }, "Nhỏ 8px", photoView.BrushSize == 8f);

                DrawVectorBtn(g, curX, 98, 78, 26, (g1, x1, y1) => {
